  void *array[100];
  size_t size;
  // get void*'s for all entries on the stack
  size = backtrace(array, 100);
  // print out all the frames to stderr
  fprintf(stderr, "Error: signal %d:\n", sig);
  backtrace_symbols_fd(array, size, STDERR_FILENO);
  exit(1);
}
