#define COLOR_CYAN      "\033[36m"
#define COLOR_RESET     "\033[0m"
#define COLOR_HIGH      "\033[1m"
#define LOG_WRITE(OUTPUT, COLOR, LEVEL, MSG) OUTPUT << COLOR << \
QTime::currentTime().toString("hh:mm:ss:zzz").toStdString() << \
" " LEVEL " " << COLOR_RESET << MSG << "\n"
static void EmsCustomLogWriter(QtMsgType type, const QMessageLogContext &context, const QString &msg)
{
   switch (type)
     {
      case QtWarningMsg:
         LOG_WRITE(std::cout, COLOR_YELLOW, "WARN", msg.toStdString());
         break;
      case QtCriticalMsg:
         LOG_WRITE(std::cout, COLOR_RED, "CRIT",  msg.toStdString());
         break;
      case QtFatalMsg:
         LOG_WRITE(std::cout, COLOR_ORANGE, "FATAL",  msg.toStdString());
         break;
      case QtDebugMsg:
         LOG_WRITE(std::cout, COLOR_CYAN, "DEBUG",  msg.toStdString());
         break;
      default:
         LOG_WRITE(std::cout, COLOR_CYAN, "DEBUG",  msg.toStdString());
         break;
     }
}
int main(int argc, char *argv[])
{
    qInstallMessageHandler(EmsCustomLogWriter);
    Application a(argc, argv);

    return a.exec();
}

#include "rapidcheck/detail/FrequencyMap.h"
#include <algorithm>
namespace rc {
namespace detail {
FrequencyMap::FrequencyMap(const std::vector<std::size_t> &frequencies)
    : m_sum(0) {
  m_table.reserve(frequencies.size());
  for (auto x : frequencies) {
    m_sum += x;
    m_table.push_back(m_sum);
  }
}
std::size_t FrequencyMap::lookup(std::size_t x) const {
  return std::upper_bound(begin(m_table), end(m_table), x) - begin(m_table);
}
std::size_t FrequencyMap::sum() const { return m_sum; }
} // namespace detail
} // namespace rc

