void *ThreadFunc(void *) { return nullptr; }
int main() {
  pthread_t t;
  const size_t sz = 1024 * 1024;
  void *p = malloc(sz);
  pthread_attr_t attr;
  pthread_attr_init(&attr);
  pthread_attr_setstack(&attr, p, sz);
  pthread_create(&t, &attr, ThreadFunc, nullptr);
  pthread_join(t, nullptr);
  free(p);
  return 0;
}

