    #if defined _WIN32 || defined WIN32 || defined WIN64
        out << "Windows";
    #elif defined __APPLE__ || defined __MACH__
        out << "Mac OS X";
    #elif defined __linux__
        out << "Linux";
    #elif defined __unix__ || defined __unix
        out << "Unix";
    #else
        out << "Unknown Platform";
