    ASSERT_NEAR(engine.m_understeer_effect, 0.6f, 0.01);
    ASSERT_EQ(engine.m_lockup_enabled, true);
    ASSERT_NEAR(engine.m_wheelbase_max_nm, 18.0f, 0.01);
