#include <sys/mman.h>
#include "syscall.h"
static void dummy(void) { }
weak_alias(dummy, __vm_wait);
int __munmap(void *start, size_t len)
{
	__vm_wait();
	return syscall(SYS_munmap, start, len);
}
weak_alias(__munmap, munmap);

#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"
#include "protocol_extracter/nprotocol_extracter.h"
#include <iomanip>
#include <iostream>
void printHexData(const std::string &data) {
  if (!data.empty()) {
    std::cout << "data received: ";
    for (int i = 0; i < data.size(); ++i) {
      std::cout << std::hex << std::setfill('0') << std::setw(2)
                << int(uint8_t(data.at(i))) << " ";
    }
    std::cout << std::endl;
  }
}
int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_parser");
  ros::NodeHandle nh;
  serial::Serial serial;
  initSerial(&serial);
  NProtocolExtracter protocol_extraction;
  linktrack::Init init(&protocol_extraction, &serial);
  ros::Rate loop_rate(1000);
  while (ros::ok()) {
    auto available_bytes = serial.available();
    std::string str_received;
    if (available_bytes) {
      serial.read(str_received, available_bytes);
      // printHexData(str_received);
      protocol_extraction.AddNewData(str_received);
    }
    ros::spinOnce();
    loop_rate.sleep();
  }
  return EXIT_SUCCESS;
}

#include <stdlib.h>
#include <stdio.h>
#include <blasfeo_target.h>
#include <blasfeo_common.h>
#include <blasfeo_d_aux.h>
#include <blasfeo_d_kernel.h>
#include <blasfeo_d_blas.h>
#if defined(FORTRAN_BLAS_API)
#define blas_dposv dposv_
#define blas_dpotrf dpotrf_
#define blas_dpotrs dpotrs_
#endif
void blas_dposv(char *uplo, int *pm, int *pn, double *A, int *plda, double *B, int *pldb, int *info)
	{
#if defined(PRINT_NAME)
	printf("\nblas_dposv %c %d %d %p %d %p %d %d\n", *uplo, *pm, *pn, A, *plda, B, *pldb, *info);
#endif
	*info = 0;
	blas_dpotrf(uplo, pm, A, plda, info);
	if(*info==0)
		{
		blas_dpotrs(uplo, pm, pn, A, plda, B, pldb, info);
		}
	return;
	}

#include "basics/attribute_name_parser.h"
