  ASSERT_FALSE(spec.empty());
  ASSERT_EQ(spec.rules().size(), 1u);
  EXPECT_EQ(spec.rules()[0].kind, PropertyKind::NoOverflow);
  EXPECT_TRUE(spec.rules()[0].negated);
}
