    u32 hid2 = PPCMfhid2();
    ASSERTMSGLINE(1319, !((u32)addr & 31), "LCAlloc(): addr must be 32 byte aligned");
    ASSERTMSGLINE(1321, !((u32)nBytes & 31), "LCAlloc(): nBytes must be 32 byte aligned");
    if ((hid2 & 0x10000000) == 0) {
        LCEnable();
    }
    LCAllocTags(TRUE, addr, numBlocks);
}
void LCAllocNoInvalidate(void* addr, u32 nBytes) {
    u32 numBlocks = nBytes >> 5;
    u32 hid2 = PPCMfhid2();
    ASSERTMSGLINE(1366, !((u32)addr & 31), "LCAllocNoFlush(): addr must be 32 byte aligned");
    ASSERTMSGLINE(1368, !((u32)nBytes & 31), "LCAllocNoFlush(): nBytes must be 32 byte aligned");
    if ((hid2 & 0x10000000) == 0) {
        LCEnable();
    }
    LCAllocTags(FALSE, addr, numBlocks);
}
u32 LCLoadData(void* destAddr, void* srcAddr, u32 nBytes) {
    u32 numBlocks = (nBytes + 31) / 32;
    u32 numTransactions = (numBlocks + 128 - 1) / 128;
    ASSERTMSGLINE(1426, !((u32)srcAddr & 31), "LCLoadData(): srcAddr not 32 byte aligned");
    ASSERTMSGLINE(1428, !((u32)destAddr & 31), "LCLoadData(): destAddr not 32 byte aligned");
    while (numBlocks > 0) {
        if (numBlocks < 128) {
            LCLoadBlocks(destAddr, srcAddr, numBlocks);
            numBlocks = 0;
        } else {
            LCLoadBlocks(destAddr, srcAddr, 0);
            numBlocks -= 128;
            destAddr = (void*)((u32)destAddr + 4096);
            srcAddr = (void*)((u32)srcAddr + 4096);
        }
    }
    return numTransactions;
}
u32 LCStoreData(void* destAddr, void* srcAddr, u32 nBytes) {
    u32 numBlocks = (nBytes + 31) / 32;
    u32 numTransactions = (numBlocks + 128 - 1) / 128;
    ASSERTMSGLINE(1494, !((u32)srcAddr & 31), "LCStoreData(): srcAddr not 32 byte aligned");
    ASSERTMSGLINE(1496, !((u32)destAddr & 31), "LCStoreData(): destAddr not 32 byte aligned");
    while (numBlocks > 0) {
        if (numBlocks < 128) {
            LCStoreBlocks(destAddr, srcAddr, numBlocks);
            numBlocks = 0;
        } else {
            LCStoreBlocks(destAddr, srcAddr, 0);
            numBlocks -= 128;
            destAddr = (void*)((u32)destAddr + 4096);
            srcAddr = (void*)((u32)srcAddr + 4096);
        }
    }
    return numTransactions;
}
#ifdef __GEKKO__
asm u32 LCQueueLength(void) {
    nofralloc
    mfspr   r4, HID2
    rlwinm  r3, r4, 8, 28, 31
    blr
}
asm void LCQueueWait(register u32 len) {
    nofralloc
@1
    mfspr r4, HID2
    rlwinm r4, r4, 8, 28, 31
    cmpw r4, r3
    bgt @1
    blr
}
#endif
void LCFlushQueue() {
    union {
        u32 val;
        struct {
            u32 lcAddr : 27;
            u32 dmaLd : 1;
            u32 dmaLenL : 2;
            u32 dmaTrigger : 1;
            u32 dmaFlush : 1;
        } f;
    } dmaL;
    dmaL.val = 0;
    dmaL.f.dmaFlush = 1;
    PPCMtdmaU(0);
    PPCMtdmaL(dmaL.val);
    PPCSync();
}
static void L2Init(void) {
    u32 oldMSR;
    oldMSR = PPCMfmsr();
    __sync();
    PPCMtmsr(MSR_IR | MSR_DR);
    __sync();
    L2Disable();
    L2GlobalInvalidate();
    PPCMtmsr(oldMSR);
}
void L2Enable(void) { 
    PPCMtl2cr((PPCMfl2cr() | L2CR_L2E) & ~L2CR_L2I);
}
void L2Disable(void) {
    __sync();
    PPCMtl2cr(PPCMfl2cr() & ~0x80000000);
    __sync();
}
void L2GlobalInvalidate(void) {
    L2Disable();
    PPCMtl2cr(PPCMfl2cr() | 0x00200000);
    while (PPCMfl2cr() & 0x00000001u);
    PPCMtl2cr(PPCMfl2cr() & ~0x00200000);
    while (PPCMfl2cr() & 0x00000001u) {
        DBPrintf(">>> L2 INVALIDATE : SHOULD NEVER HAPPEN\n");
    }
}
void L2SetDataOnly(BOOL dataOnly) {
    if (dataOnly) {
        PPCMtl2cr(PPCMfl2cr() | 0x400000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFBFFFFF);
}
void L2SetWriteThrough(BOOL writeThrough) {
    if (writeThrough) {
        PPCMtl2cr(PPCMfl2cr() | 0x80000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFF7FFFF);
}
void DMAErrorHandler(OSError error, OSContext* context, ...) {
    u32 hid2 = PPCMfhid2();
    OSReport("Machine check received\n");
    OSReport("HID2 = 0x%x   SRR1 = 0x%x\n", hid2, context->srr1);
    if (!(hid2 & (HID2_DCHERR | HID2_DNCERR | HID2_DCMERR | HID2_DQOERR)) || !(context->srr1 & SRR1_DMA_BIT)) {
        OSReport("Machine check was not DMA/locked cache related\n");
        OSDumpContext(context);
        PPCHalt();
    }
    OSReport("DMAErrorHandler(): An error occurred while processing DMA.\n");
    OSReport("The following errors have been detected and cleared :\n");
    if (hid2 & HID2_DCHERR) {
        OSReport("\t- Requested a locked cache tag that was already in the cache\n");
    }
    if (hid2 & HID2_DNCERR) {
        OSReport("\t- DMA attempted to access normal cache\n");
    }
    if (hid2 & HID2_DCMERR) {
        OSReport("\t- DMA missed in data cache\n");
    }
    if (hid2 & HID2_DQOERR) {
        OSReport("\t- DMA queue overflowed\n");
    }
    // write hid2 back to clear the error bits
    PPCMthid2(hid2);
}
void __OSCacheInit() {
    if (!(PPCMfhid0() & HID0_ICE)) {
        ICEnable();
        DBPrintf("L1 i-caches initialized\n");
    }
    if (!(PPCMfhid0() & HID0_DCE)) {
        DCEnable();
        DBPrintf("L1 d-caches initialized\n");
    }
    if (!(PPCMfl2cr() & L2CR_L2E)) {
        L2Init();
        L2Enable();
        DBPrintf("L2 cache initialized\n");
    }
    OSSetErrorHandler(OS_ERROR_MACHINE_CHECK, DMAErrorHandler);
    DBPrintf("Locked cache machine check handler installed\n");
}

#include "valdi_core/cpp/Utils/PathUtils.hpp"
#include "gtest/gtest.h"
#include <iostream>
using namespace Valdi;
namespace ValdiTest {
TEST(PathUtils, isAbsolutePathAcceptance) {
    ASSERT_EQ(Path("/").isAbsolute(), true);
    ASSERT_EQ(Path("").isAbsolute(), false);
    ASSERT_EQ(Path("/test/dir").isAbsolute(), true);
    ASSERT_EQ(Path("test/dir").isAbsolute(), false);
}
TEST(PathUtils, normalizePathAcceptance) {
    ASSERT_EQ(Path("").normalize().toString(), "");
    ASSERT_EQ(Path("/").normalize().toString(), "/");
    ASSERT_EQ(Path("/test/").normalize().toString(), "/test");
    ASSERT_EQ(Path("test").normalize().toString(), "test");
    ASSERT_EQ(Path("test///dir").normalize().toString(), "test/dir");
    // Single dots should always be ingored
    ASSERT_EQ(Path("./").normalize().toString(), "");
    ASSERT_EQ(Path("/./").normalize().toString(), "/");
    ASSERT_EQ(Path("././test").normalize().toString(), "test");
    ASSERT_EQ(Path("/test/./././dir/.").normalize().toString(), "/test/dir");
    // Double dots
    ASSERT_EQ(Path("/test/../dir").normalize().toString(), "/dir");
    ASSERT_EQ(Path("/test/../../dir").normalize().toString(), "/dir");
    ASSERT_EQ(Path("test/../../dir").normalize().toString(), "../dir");
    ASSERT_EQ(Path("/test/dir/..").normalize().toString(), "/test");
    ASSERT_EQ(Path("test/dir/../..").normalize().toString(), "");
    ASSERT_EQ(Path("/../../test/dir/../..").normalize().toString(), "/");
    ASSERT_EQ(Path("../test/dir/../..").normalize().toString(), "..");
    ASSERT_EQ(Path("../test/dir/..").normalize().toString(), "../test");
}
TEST(PathUtils, removeComponentAcceptance) {
    ASSERT_EQ(Path("").removeLastComponent().toString(), "");
    ASSERT_EQ(Path("/").removeLastComponent().toString(), "");
    ASSERT_EQ(Path("test").removeLastComponent().toString(), "");
    ASSERT_EQ(Path("/test").removeLastComponent().toString(), "/");
    ASSERT_EQ(Path("test/dir").removeLastComponent().toString(), "test");
    ASSERT_EQ(Path("/test/dir").removeLastComponent().toString(), "/test");
}
TEST(PathUtils, appendPathAcceptance) {
    ASSERT_EQ(Path("").append("").toString(), "");
    ASSERT_EQ(Path("/").append("").toString(), "/");
    ASSERT_EQ(Path("").append("/").toString(), "/");
    ASSERT_EQ(Path("/").append("test").toString(), "/test");
    ASSERT_EQ(Path("./").append("/test").normalize().toString(), "test");
    ASSERT_EQ(Path("test").append("dir").toString(), "test/dir");
    ASSERT_EQ(Path("/test").append("dir").toString(), "/test/dir");
    ASSERT_EQ(Path("/test/dir").append("/path").toString(), "/test/dir/path");
    ASSERT_EQ(Path("test/dir").append("/path").toString(), "test/dir/path");
    ASSERT_EQ(Path("test/dir").append("../path").normalize().toString(), "test/path");
}
TEST(PathUtils, removeFileExtensionAcceptance) {
    ASSERT_EQ(Path("").removeFileExtension().toString(), "");
    ASSERT_EQ(Path("/").removeFileExtension().toString(), "/");
    ASSERT_EQ(Path("/test").removeFileExtension().toString(), "/test");
    ASSERT_EQ(Path("./test").removeFileExtension().toString(), "./test");
    ASSERT_EQ(Path("/test/").removeFileExtension().toString(), "/test");
    ASSERT_EQ(Path("./test/").removeFileExtension().toString(), "./test");
    ASSERT_EQ(Path("/test.foo").removeFileExtension().toString(), "/test");
    ASSERT_EQ(Path("./test.foo").removeFileExtension().toString(), "./test");
}
TEST(PathUtils, appendFileExtensionAcceptance) {
    ASSERT_EQ(Path("").appendFileExtension("bar").toString(), "");
    ASSERT_EQ(Path("/").appendFileExtension("bar").toString(), "/.bar");
    ASSERT_EQ(Path("/test").appendFileExtension("bar").toString(), "/test.bar");
    ASSERT_EQ(Path("./test").appendFileExtension("bar").toString(), "./test.bar");
    ASSERT_EQ(Path("/test/").appendFileExtension("bar").toString(), "/test.bar");
    ASSERT_EQ(Path("./test/").appendFileExtension("bar").toString(), "./test.bar");
    ASSERT_EQ(Path("/test.foo").appendFileExtension("bar").toString(), "/test.foo.bar");
    ASSERT_EQ(Path("./test.foo").appendFileExtension("bar").toString(), "./test.foo.bar");
}
TEST(PathUtils, startsWithAcceptance) {
    ASSERT_TRUE(Path("").startsWith(Path("")));
    ASSERT_TRUE(Path("/").startsWith(Path("")));
    ASSERT_TRUE(Path("/").startsWith(Path("/")));
    ASSERT_FALSE(Path("/").startsWith(Path("/hello")));
    ASSERT_TRUE(Path("/hello").startsWith(Path("/")));
    ASSERT_FALSE(Path("hello").startsWith(Path("/")));
    ASSERT_FALSE(Path("hello/boy").startsWith(Path("/")));
    ASSERT_FALSE(Path("hello/boy").startsWith(Path("h")));
    ASSERT_TRUE(Path("hello/boy").startsWith(Path("hello")));
    ASSERT_TRUE(Path("hello/boy").startsWith(Path("hello/boy")));
    ASSERT_FALSE(Path("hello/boy").startsWith(Path("hello/boy/nein")));
}
TEST(PathUtils, getFileExtensionAcceptable) {
    ASSERT_EQ("", Path("").getFileExtension());
    ASSERT_EQ("", Path("hello").getFileExtension());
    ASSERT_EQ("txt", Path("hello.txt").getFileExtension());
    ASSERT_EQ("png", Path("nice/bro/hello.png").getFileExtension());
    ASSERT_EQ("jpg", Path("/nice/bro/hello.jpg").getFileExtension());
}
