              sdb::options::units_helper::ToNumber<uint32_t>(v));
  }
  const char* invalid[] = {"-1",    "-66666",     "-129", "-255", "-10000",
                           "4500m", "4294967296", "4GiB", "5g"};
  for (auto v : invalid) {
    try {
      sdb::options::units_helper::ToNumber<uint32_t>(v);
      ASSERT_FALSE(true);
    } catch (const std::out_of_range&) {
    }
  }
}
