using namespace caf;
using std::endl;

// Main function spawns 50 actors that print greetings and farewells
int main()
{
    // Seed random number generator with current time
    std::srand(static_cast<unsigned>(std::time(0)));

    // Spawn 50 actors
    for(int i=1; i<=50; ++i)
    {
        spawn<blocking_api>([i](blocking_actor* self) {
            // Print greeting
            aout(self) << "Hi there! This is actor nr. "
                       << i << "!" << endl;

            // Create random delay
            std::random_device rd;
            std::default_random_engine re(rd());
            std::chrono::milliseconds tout{re() % 10};

            // Send delayed message to self
            self->delayed_send(self, tout, atom("done"));

            // Wait for the message and print farewell
            self->receive(others() >> [i, self] {
                aout(self) << "Actor nr. "
                           << i << " says goodbye!" << endl;
            });
        });
    }

    // Wait until all spawned actors are done
    await_all_actors_done();

    // Shutdown CAF runtime
    shutdown();

    return 0;
}

