// Startup time measurement
double StartupTime;

int main(int argc, const char** argv)
{
    clock_t begin, end;

    // Record start time
    begin = clock();

    // Initialize runtime
    vz_bootstrap_runtime(argc, argv);

    // Record end time
    end = clock();

    // Calculate startup time in seconds
    StartupTime = (end - begin) / CLOCKS_PER_SEC;

