// Function to check cell finding around a point
void check (Triangulation<3> &tria)
{
  Point<3> p (0.75,0,0);

  Triangulation<3>::active_cell_iterator cell
    = GridTools::find_active_cell_around_point (tria, p);
  deallog << cell << std::endl;

  // Output vertices of the found cell
  for (unsigned int v=0; v<GeometryInfo<2>::vertices_per_cell; ++v)
    deallog << "<" << cell->vertex(v) << "> ";
  deallog << std::endl;

  // Verify that the point is close enough to the cell center
  Assert (p.distance (cell->center()) < cell->diameter()/2,
	  ExcInternalError());
}

int main () 
{
  // Set up output file
  std::ofstream logfile("find_cell_1/output");
  deallog.attach(logfile);
  deallog.depth_console(0);
  deallog.threshold_double(1.e-10);

  // Create and refine triangulation
  Triangulation<3> coarse_grid;
  GridGenerator::hyper_cube (coarse_grid);
  coarse_grid.refine_global (3);

  // Run the check
  check (coarse_grid);
}

