#include <stdio.h>
#include <Halide.h>

using namespace Halide;

int main(int argc, char **argv)
{
    Var x, y;

    // Predicate function: returns true if x < y
    Func pred("pred");
    pred(x, y) = x < y;

    // Selector function: returns 1 if pred is true, else 0
    Func selector("selector");
    selector(x, y) = select(pred(x, y), 1, 0);

    // Compute predicate at root level
    pred.compute_root();

    // Vectorize selector over x dimension with width 8
    selector.compute_root().vectorize(x, 8);

    // Define reduction domain
    RDom range(0, 100, 0, 100);

    // Evaluate the sum of selector over the domain
    int32_t result = evaluate<int32_t>(lambda(sum(selector(range.x, range.y))));

    // Verify result matches expected value
    assert(result == 4950);

    printf("Success!\n");
    return 0;
}

