using namespace llvm;

// Stores loaded plugins
static ManagedStatic<std::vector<std::string> > Plugins;

// Load a plugin from the given filename
void PluginLoader::operator=(const std::string &Filename)
{
    std::string Error;
    if (sys::DynamicLibrary::LoadLibraryPermanently(Filename.c_str(), &Error))
    {
        cerr << "Error opening '" << Filename << "': " << Error
             << "\n  -load request ignored.\n";
    }
    else
    {
        Plugins->push_back(Filename);
    }
}

// Returns the number of loaded plugins
unsigned PluginLoader::getNumPlugins()
{
    return Plugins.isConstructed() ? Plugins->size() : 0;
}

// Returns the plugin at the specified index
std::string &PluginLoader::getPlugin(unsigned num)
{
    assert(Plugins.isConstructed() && num < Plugins->size() &&
           "Asking for an out of bounds plugin");
    return (*Plugins)[num];
}

