// Power function using exponentiation by squaring
unsigned long long pow(unsigned long long x, unsigned long long n)
{
    unsigned long long result = 1;
    while (n > 0) {
        if ((n & 1) > 0) {
            result = result * x;
        }
        x = x * x;
        n >>= 1;
    }
    return result;
}

// Floor of log base 2
unsigned int log2_floor(unsigned long long x)
{
    unsigned int y(0);
    while (x > 0) {
        x >>= 1;
        ++y;
    }
    --y;
    return y;
}

