public:
    // Constructor initializes base class with document
    Parser(const std::string &document) : HtmlParser(document) { }

    // Override notify method to handle parsed chunks
    virtual void notify(const HtmlParser::Chunk &chunk);
};

// Implementation of notify: outputs chunk content
void Parser::notify(const HtmlParser::Chunk &chunk) {
    std::cout << chunk.toString() << '\n';
}

