    ::progname = argv[1];

    // Validate command-line arguments
    if (argc != 2)
        Usage();

    try {
        const std::string input_filename(argv[1]);
        std::string html_document;

        // Read HTML file content
        if (not FileUtil::ReadString(input_filename, &html_document))
            ERROR("failed to read an HTML document from \"" + input_filename + "\"!");

        // Parse the document
        Parser parser(html_document);
        parser.parse();

    } catch (const std::exception &x) {
        ERROR(x.what());
    }
}

#include <test.hpp>

// Test case for varint encoding/decoding
TEST_CASE("varint")
{
    std::string buffer;
    mapbox::util::pbf_writer pw(buffer);

    SECTION("encode/decode int32")
    {
        pw.add_int32(1, 17);
        mapbox::util::pbf item(buffer.data(), buffer.size());
        REQUIRE(item.next());
        REQUIRE(17 == item.get_int32());
    }

    SECTION("encode/decode uint32")
    {
        pw.add_uint32(1, 17U);
        mapbox::util::pbf item(buffer.data(), buffer.size());
        REQUIRE(item.next());
        REQUIRE(17U == item.get_uint32());
    }

    SECTION("encode/decode uint64")
    {
        pw.add_uint64(1, (1ULL << 40));
        mapbox::util::pbf item(buffer.data(), buffer.size());
        REQUIRE(item.next());
        REQUIRE((1ULL << 40) == item.get_uint64());
    }

    SECTION("short buffer while parsing varint")
    {
        pw.add_uint64(1, (1ULL << 40));
        buffer.resize(buffer.size() - 1); // "remove" last byte from buffer
        mapbox::util::pbf item(buffer.data(), buffer.size());
        REQUIRE(item.next());
        REQUIRE_THROWS_AS(item.get_uint64(), mapbox::util::pbf::end_of_buffer_exception);
    }

    SECTION("data corruption in buffer while parsing varint)")
    {
        pw.add_uint64(1, (1ULL << 20));
        buffer[buffer.size() - 1] += 0x80; // pretend the varint goes on
        mapbox::util::pbf item(buffer.data(), buffer.size());
        REQUIRE(item.next());
        REQUIRE_THROWS_AS(item.get_uint64(), mapbox::util::pbf::end_of_buffer_exception);
    }

    SECTION("data corruption in buffer while parsing varint (max length varint)")
    {
        pw.add_uint64(1, std::numeric_limits<uint64_t>::max());
        buffer[buffer.size() - 1] += 0x80; // pretend the varint goes on
        mapbox::util::pbf item(buffer.data(), buffer.size());
        REQUIRE(item.next());
        REQUIRE_THROWS_AS(item.get_uint64(), mapbox::util::pbf::varint_too_long_exception);
    }
}

#include "cell_refine.hpp"
#include <viennagrid/algorithm/refine.hpp>

/***************
 * CELL_REFINE *
 ***************/
// Triangular
tuple TriangularCartesian2D_Domain_cell_refine(
    TriangularCartesian2D_Domain domain_in,
    TriangularCartesian2D_Segmentation segmentation_in,
    bool (*predicate)(const TriangularCartesian2D_Cell &)
)
{
    TriangularCartesian2D_Domain          domain_out;
    TriangularCartesian2D_Segmentation    segmentation_out(domain_out);

    // Vector of marks/flags that indicate which cells should be refined
    CellRefinementFlagContainerType     cell_refinement_flag_container;

    viennagrid::result_of::field<CellRefinementFlagContainerType,
                                 TriangularCartesian2D_Cell_t>::type
        cell_refinement_flag_field(cell_refinement_flag_container);

    // Marks which edges should be refined
    TriangularCartesian2D_CellRange_t cells = viennagrid::elements(domain_in.get_domain());
    for (TriangularCartesian2D_CellRange_t::iterator it = cells.begin();
         it != cells.end();
         ++it)
    {
        if (predicate(TriangularCartesian2D_Cell(*it)))
            cell_refinement_flag_field(*it) = true;
    }

    // Refine marked edges
    viennagrid::cell_refine(domain_in.get_domain(),
                            segmentation_in.get_segmentation(),
                            domain_out.get_domain(),
                            segmentation_out.get_segmentation(),
                            cell_refinement_flag_field);

    // Return refined domain and segmentation as a tuple: (refined_domain, refined_segmentation)
    return make_tuple<TriangularCartesian2D_Domain, TriangularCartesian2D_Segmentation>(domain_out, segmentation_out);
}

