// Main write function for assembly file generation
void Main::write(AssemblyFileWriter& writer)
{
    // Write the text section and global symbol
    writer.stream() << ".text" << std::endl
                    << ".globl _start" << std::endl

                    // Start label for entry point
                    << "_start:" << std::endl
                    // Call main function
                    << "call main" << std::endl
                    // Set exit system call number
                    << "movl $1, %eax" << std::endl
                    // Clear ebx register for exit code 0
                    << "xorl %ebx, %ebx" << std::endl
                    // Invoke system call
                    << "int $0x80" << std::endl;
}

