int main(void)
{
    // Initialize system clocks
    DCO::init();
    ACLK::init();
    SMCLK::init();
    MCLK::init();

    // Initialize and enable watchdog timer with interrupt
    WDT::init();
    WDT::enable_irq();

    // Initialize GPIO ports
    PORT1::init();
    PORT2::init();

    // Indicate start-up by turning on red LED
    LED_RED::set_high();

#ifndef __MSP430_HAS_USCI__
    // Initialize timer if USCI is not available
    TIMER::init();
#endif

    // Initialize UART and SPI interfaces
    UART::init();
    printf<UART>("CC110X example start.\n");
    SPI::init();

    // Initialize CC1101 radio transceiver
    CC1101::reset();
    CC1101::init(cc110x_default_init_values, ARRAY_COUNT(cc110x_default_init_values));
    CC1101::start_rx();

    // Turn off red LED to indicate ready state
    LED_RED::set_low();

    // Main loop: continuously receive packets
    while (1) {
        // Receive packet with no timeout
        CC1101::rx_buffer<TIMEOUT_NEVER>(packet, sizeof(packet));

        // Indicate packet reception
        LED_RED::set_high();

        // Wait 50 units before next reception
        TIMEOUT::set_and_wait(50);

        // Turn off LED after delay
        LED_RED::set_low();
    }
}

