#include <assert.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

// Main function
int main()
{
    // Allocate memory
    void *p = malloc(1024 * 1024);

    // Free allocated memory
    free(p);

    // Map anonymous memory
    char *q = (char *)mmap(p, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, 0, 0);

    // Verify mapping succeeded and is within expected bounds
    assert(q);
    assert(q <= p);
    assert(q + 4096 > p);

    // Fill memory with value 42
    memset(q, 42, 4096);

    // Unmap the memory region
    munmap(q, 4096);

    return 0;
}

