    driver = &ics;

    // Create node handles and subscribers/publishers
    ros::NodeHandle n {};
    ros::Subscriber sub {n.subscribe("cmd_krs", 100, move)};
    pub = n.advertise<servo_msgs::IdBased>("pose_krs", 10);

    // Start ROS event loop
    ros::spin();

    return 0;
}

