#include <unistd.h>
#include <sys/wait.h>
#include <cstdlib>

// Namespace alias for filesystem operations
using namespace clt::filesystem::operations;

void ExecutableLauncherUnix::execute(const entities::Path & path)
{
    pid_t cpid;

    // Fork a new process
    cpid = fork();

    switch (cpid) 
    {
        case -1: 
            perror("fork");
            break;

        case 0:
            // Child process attempts to execute the binary
            execl(path.getValue().c_str(), path.getValue().c_str(), NULL, NULL);
            _exit(EXIT_FAILURE);
            break;

        default: 
            // Parent process waits for child completion
            waitpid(cpid, NULL, 0);
    }
}

