#include <Automaton.h>
#include "Atm_blink.h"

// Begin method to initialize the blink automaton
Atm_blink & Atm_blink::begin( int attached_pin, uint32_t blinkrate )
{
  // Define state table in program memory
  const static state_t state_table[] PROGMEM = {
    /*            ON_ENTER    ON_LOOP  ON_EXIT  EVT_TIMER   ELSE */
    /* LED_ON  */   ACT_ON,        -1,      -1,   LED_OFF,    -1,
    /* LED_OFF */  ACT_OFF,        -1,      -1,    LED_ON,    -1 
  };

  // Initialize the machine with the state table and default transition
  Machine::begin( state_table, ELSE );

  // Set pin and timer configuration
  pin = attached_pin; 
  timer.begin( this, blinkrate ); 

  // Configure pin as output
  pinMode( pin, OUTPUT ); 

  return *this;          
}

// Event handler for the automaton
int Atm_blink::event( int id ) 
{
  switch ( id ) {
    case EVT_TIMER :
      return timer.expired();        
  }
  return 0;
}

// Action handler for state transitions
void Atm_blink::action( int id ) 
{
  switch ( id ) {
    case ACT_ON :
      digitalWrite( pin, HIGH );
      return;
    case ACT_OFF :
      digitalWrite( pin, LOW );
      return;
  }
}

// Configure switch callback for state transitions
Atm_blink & Atm_blink::onSwitch( swcb_sym_t switch_callback ) {
  Machine::onSwitch( switch_callback, "LED_ON\0LED_OFF", "EVT_TIMER\0ELSE" );
  return *this;
}

