{
    ros::init(argc, argv, "quadrotor_obstacle_avoidance");

    ros::NodeHandle node;
    // Advertise velocity command publisher
    ros::Publisher cmd_pub = node.advertise<geometry_msgs::Twist>("cmd_vel", 10);

