// Main thread execution function
void MsgListener::run()
{
    int length;
    erlang_msg msg;
    ei_x_buff buff;

    // Initialize buffer
    ei_x_new(&buff);

    // Receive message with timeout
    length = ei_xreceive_msg_tmo(m_fd, &msg, &buff, 1000);

    // Check if message received and is of correct type
    if (length > 0 && (msg.msgtype == ERL_SEND || msg.msgtype == ERL_REG_SEND))
