// Class definition for Object with typestate annotations
class [[clang::consumable(unconsumed)]] Object {
public:
    // Default constructor
    Object() {}

    // Move constructor
    Object(Object&& other) { 
        other.invalidate(); 
    }

    // Method callable only when unconsumed
    [[clang::callable_when(unconsumed)]]
    void do_something() { 
        assert(m_valid); 
    }

private:
    // Method that sets typestate to consumed
    [[clang::set_typestate(consumed)]]
    void invalidate() { 
        m_valid = false; 
    }

    bool m_valid { true };
};

// Main function
int main(int, char**) {
    // Create object
    Object object;

    // Move object
    auto other = std::move(object);

    // Attempt to use invalidated object - this will trigger assertion
    object.do_something();

    return 0;
}

