// Loads all game objects in the level
void Level::load()
{
    for(auto game_object : objects)
    {
        std::cout << "Loading " << game_object->name << std::endl;
        game_object->load();

        // Initialize hitboxes for the current object
        for(auto hit : game_object->get_hitboxes())
        {
            hit->initialize();
        }
    }
