// Performs the specified operation on the application context
void doOperation(Operation operation, AppContext *context)
{
    switch(operation) {
        case Convert:
            // Converts data using the context
            doConvert(context);
            break;
        case Save:
            // Saves current state using the context
            doSave(context);
            break;
        case Initialization:
            // Initializes the application state
            doInitialize(context);
            break;
        case Validation:
            // Validates data using the context
            doValidation(context);
            break;
        case Swap:
            // Swaps data using the context
            doSwap(context);
            break;
        case ConvertAddCode:
            // Converts and adds code using the context
            doConvertAddCode(context);
            break;
        case ChekingAddCode:
            // Checks and adds code using the context
            doChekingAddCode(context);
            break;
    }
}

