using namespace Cangjie;
using namespace Unicode;

// Test for NFC normalization using generated test data
TEST(UnicodeTest, GeneratedNFCTests)
{
    // Calculate the number of test cases
    int testDataLen{sizeof(NORMALISATION_TEST_DATA) / sizeof(NormalisationTest)};

    // Iterate through each test case
    for(int i=0; i<testDataLen; ++i)
    {
        // Perform canonical decomposition followed by recomposition
        auto f = CanonicalRecompose(
            reinterpret_cast<const UTF8*>(NORMALISATION_TEST_DATA[i].source.begin()),
            reinterpret_cast<const UTF8*>(NORMALISATION_TEST_DATA[i].source.end())
        );

        // Verify the result matches expected NFC form
        EXPECT_EQ(f, NORMALISATION_TEST_DATA[i].nfc);
    }
}

