#include <library/cpp/threading/future/future.h>
#include <library/cpp/threading/future/core/coroutine_traits.h>

// Test for argument-dependent lookup in future traits
TEST(TestFutureTraits, ArgumentDependentLookup)
{
    TVector<TString> result;

    // Create promise and future pair
    NThreading::TPromise<void> promise = NThreading::NewPromise<void>();
    NThreading::TFuture<void> future = promise.GetFuture();

    // Run awaitable task
    NSimpleTestTask::RunAwaitable(result, std::move(future));

    // Set promise value to resume coroutine
    promise.SetValue();

    // Verify result contains expected values
    EXPECT_THAT(
        result,
        ::testing::ContainerEq(
            TVector<TString>({
                "before co_await",
                "after co_await",
            })));
}

