#include "int_lib.h"

// Byte swap function for 32-bit integer
COMPILER_RT_ABI uint32_t __bswapsi2(uint32_t u)
{
    // Perform byte swapping using bitwise operations
    return (
        (((u) & 0xff000000) >> 24) |
        (((u) & 0x00ff0000) >> 8)  |
        (((u) & 0x0000ff00) << 8)  |
        (((u) & 0x000000ff) << 24)
    );
}

