/// generate a timestamp string in a target buffer
void GetTimeStampReplication(char* dst, size_t max_length) {
    struct tm tb;
    time_t tt = time(nullptr);
    utilities::GetGmtime(tt, &tb);
    strftime(dst, max_length, "%Y-%m-%dT%H:%M:%SZ", &tb);
}

/// generate a timestamp string in a target buffer
void GetTimeStampReplication(double time_stamp, char* dst, size_t max_length) {
    struct tm tb;
    time_t tt = static_cast<time_t>(time_stamp);
    utilities::GetGmtime(tt, &tb);
    strftime(dst, max_length, "%Y-%m-%dT%H:%M:%SZ", &tb);
}

