namespace {

// Global dummy variable used for benchmarking to prevent optimization
int gDummy = 0;

// Free function used in benchmarks
void FreeFunction() {
  benchmark::DoNotOptimize(gDummy);  // Prevent compiler from optimizing away usage
}

// A trivial callable object with no state
struct TrivialFunctor {
  void operator()() const {
    benchmark::DoNotOptimize(gDummy);  // Prevent optimization
  }
};

// A large callable object containing multiple strings (non-trivial storage)
struct LargeFunctor {
  void operator()() const {
    benchmark::DoNotOptimize(this);  // Use 'this' pointer to avoid optimization
  }
  std::string a, b, c;
};

// Functor accepting trivial arguments (e.g., integers)
struct FunctorWithTrivialArgs {
  void operator()(int a, int b, int c) const {
    benchmark::DoNotOptimize(a);
    benchmark::DoNotOptimize(b);
    benchmark::DoNotOptimize(c);
  }
};

// Functor accepting non-trivial arguments (e.g., std::string)
struct FunctorWithNonTrivialArgs {
  void operator()(std::string a, std::string b, std::string c) const {
    benchmark::DoNotOptimize(&a);
    benchmark::DoNotOptimize(&b);
    benchmark::DoNotOptimize(&c);
  }
};

// Helper function template to invoke a callable with forwarded arguments
template<typename Function, typename... Args>
void ABSL_ATTRIBUTE_NOINLINE CallFunction(Function f, Args&&... args) {
  f(std::forward<Args>(args)...);
}

// Helper function template to construct and call a benchmarked callable repeatedly
template<typename Function, typename Callable, typename... Args>
void ConstructAndCallFunctionBenchmark(benchmark::State& state,
                                       const Callable& c, Args&&... args) {
  for (auto _ : state) {
    CallFunction<Function>(c, std::forward<Args>(args)...);
  }
}

// --- Benchmarks: Trivial Functors ---
void BmTrivialStdFunction(benchmark::State& state) {
  ConstructAndCallFunctionBenchmark<std::function<void()>>(state, TrivialFunctor{});
}
BENCHMARK(BmTrivialStdFunction);

