// Securely zeros memory
void SecureZero(void* pointer, size_t count) noexcept
{
#ifdef _MSC_VER
    // Use Windows-specific secure zero
    SecureZeroMemory(pointer, count);
#elif defined(memset_s)
    // Use C11 secure memset if available
    memset_s(pointer, count, 0, count);
#else
    // Fallback: use volatile pointer to prevent optimization
    volatile char* vPointer = (volatile char*)pointer;
    while(count)
    {
        *vPointer = 0;
        vPointer++;
        count--;
    }
#endif
}

class Solution {
public:
    // Calculates minimum operations
    int minimumOperations(vector<int>& nums)
    {
        unordered_set<int> set;
        for(auto v: nums)
            if(v!=0)
                set.insert(v);
        // Return count of unique non-zero elements
        return set.size();

    }
};

