#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"
#include "protocol_extracter/nprotocol_extracter.h"
#include <chrono>
#include <thread>

// Main entry point for the IoT parser node
int main(int argc, char **argv)
{
    // Initialize ROS node
    ros::init(argc, argv, "iot_parser");
    ros::NodeHandle nh;

    // Setup serial communication
    serial::Serial serial;
    initSerial(&serial);

    // Initialize protocol extracter and IOT initialization
    NProtocolExtracter extracter;
    iot::Init init(&extracter);

    // Set loop rate to 1000 Hz
    ros::Rate loop_rate(1000);

    // Main processing loop
    while (ros::ok())
    {
        // Check available bytes in serial buffer
        auto available_bytes = serial.available();
        std::string str_received;

        // Read and process data if available
        if (available_bytes)
        {
            serial.read(str_received, available_bytes);
            extracter.AddNewData(str_received);
        }

        // Process ROS callbacks
        ros::spinOnce();

        // Maintain loop rate
        loop_rate.sleep();
    }

    return EXIT_SUCCESS;
}

