#include <iostream>
#include "sophus/geometry.hpp"

// Main function demonstrating SO(3) operations
int main()
{
    // The following demonstrates the group multiplication of rotation matrices
    // Create rotation matrices from rotations around the x and y and z axes:
    const double kPi = Sophus::Constants<double>::pi();
    Sophus::SO3d R1 = Sophus::SO3d::rotX(kPi / 4);
    Sophus::SO3d R2 = Sophus::SO3d::rotY(kPi / 6);
    Sophus::SO3d R3 = Sophus::SO3d::rotZ(-kPi / 3);

    std::cout << "The rotation matrices are" << std::endl;
    std::cout << "R1:\n" << R1.matrix() << std::endl;
    std::cout << "R2:\n" << R2.matrix() << std::endl;
    std::cout << "R3:\n" << R3.matrix() << std::endl;
    std::cout << "Their product R1*R2*R3:\n"
              << (R1 * R2 * R3).matrix() << std::endl;
    std::cout << std::endl;

    // Rotation matrices can act on vectors
    Eigen::Vector3d x;
    x << 0.0, 0.0, 1.0;
    std::cout << "Rotation matrices can act on vectors" << std::endl;
    std::cout << "x\n" << x << std::endl;
    std::cout << "R2*x\n" << R2 * x << std::endl;
    std::cout << "R1*(R2*x)\n" << R1 * (R2 * x) << std::endl;
    std::cout << "(R1*R2)*x\n" << (R1 * R2) * x << std::endl;
    std::cout << std::endl;

    // SO(3) are internally represented as unit quaternions.
    std::cout << "R1 in matrix form:\n" << R1.matrix() << std::endl;
    std::cout << "R1 in unit quaternion form:\n"
              << R1.unit_quaternion().coeffs() << std::endl;
    // Note that the order of coefficiences of Eigen's quaternion class is
    // (imag0, imag1, imag2, real)
    std::cout << std::endl;

    return 0;
}

#include "aeronet/string-trim.hpp"
#include <gtest/gtest.h>

namespace aeronet {

// Tests trimming of spaces and tabs
TEST(StringTrimTest, TrimsSpacesAndTabs) {
  EXPECT_EQ(TrimOws("  hello  "), std::string_view("hello"));
  EXPECT_EQ(TrimOws("\thello\t"), std::string_view("hello"));
  EXPECT_EQ(TrimOws(" \thello \t"), std::string_view("hello"));
}

// Tests preservation of non-OWS whitespace (e.g., newlines)
TEST(StringTrimTest, PreservesOtherWhitespace) {
  // Newline is not OWS and should not be trimmed by TrimOws
  EXPECT_EQ(TrimOws("\nhello\n"), std::string_view("\nhello\n"));
  EXPECT_EQ(TrimOws(" \nhello\n "), std::string_view("\nhello\n"));
}

// Tests edge cases: empty string and all-whitespace input
TEST(StringTrimTest, EmptyAndAllWhitespace) {
  EXPECT_EQ(TrimOws(""), std::string_view(""));
  EXPECT_EQ(TrimOws("   \t  "), std::string_view(""));
}

// Tests that strings without leading/trailing OWS remain unchanged
TEST(StringTrimTest, NoTrimNeeded) {
  EXPECT_EQ(TrimOws("hello"), std::string_view("hello"));
}

// Tests that internal whitespace (including tabs) is preserved
TEST(StringTrimtest, SpacesInMiddleShouldNotBeTrimmed) {
  EXPECT_EQ(TrimOws("  hello world  "), std::string_view("hello world"));
  EXPECT_EQ(TrimOws("  hello \tworld  "), std::string_view("hello \tworld"));
}

