	void (*)(), void(*)(), void(*)());

// Entry point for C runtime
void _start_c(long *p)
{
    // Extract argc and argv from the stack
    int argc = p[0];
    char **argv = (void *)(p+1);

    // Call the main libc_start_main function
    __libc_start_main(main, argc, argv, _init, _fini, 0);
}

#include <stdio.h>
