// Function to calculate area of square
void are_square(int s)
{
    printf("area of square= %d\n", s * s);
}

// Function to calculate perimeter of rectangle
void permeter_rectangle(int p, int q)
{
    printf("permeter of rectangle= %d\n", 2 * (p + q));
}

// Function to calculate area of circle
void area_circle(int r)
{
    printf("area of circle= %d\n", 3 * r * r); // Using 3 as approximation for pi
}

// Function to find maximum of 3 numbers
void max_3nos(int a, int b, int c)
{
    int max = a;
    if (b > max) max = b;
    if (c > max) max = c;
    printf("max of 3 nos= %d\n", max);
}

// Function to print table of a number
void table_ofno(int a)
{
    printf("table of= %d\n", a);
}

int main()
{
    int op = 0, a, b, c;

    while (op != 6)
    {
        system("cls");

        printf("1.area of square\n");
        printf("2.perimeter of rectangle\n");
        printf("3.area of circle\n");
        printf("4.max of 3 nos\n");
        printf("5.table of num\n");
        printf("6.exit\n");

        printf("enter any choice: ");
        scanf("%d", &op);

        switch (op)
        {
            case 1:
                printf("enter any side: ");
                scanf("%d", &a);
                are_square(a);
                break;

            case 2:
                printf("enter length and breadth: ");
                scanf("%d %d", &a, &b);
                permeter_rectangle(a, b);
                break;

            case 3:
                printf("enter radius: ");
                scanf("%d", &a);
                area_circle(a);
                break;

            case 4:
                printf("enter 3 numbers: ");
                scanf("%d %d %d", &a, &b, &c);
                max_3nos(a, b, c);
                break;

            case 5:
                printf("enter number: ");
                scanf("%d", &a);
                table_ofno(a);
                break;

            case 6:
                printf("Exiting...\n");
                break;

            default:
                printf("Invalid choice!\n");
        }

        getch();
    }

    return 0;
}

