// Structure definition for S1
typedef struct __attribute__((packed)) {
  char *name;
  char id;
} S1;

S1 devices[4];

extern void avoid_opt(S1 *);

int main()
{
    // Call to avoid optimization
    avoid_opt(&devices[0]);

    // Print device IDs
    for(unsigned i=0; i<4; ++i)
    {
        printf("id=%d\n", devices[i].id);
    }

    // Non-deterministic integer input
    int x = nd_int();
    __CRAB_assume(x >= 0);
    __CRAB_assume(x < 4);

    // Assertions about device ID bounds
    __CRAB_assert(devices[x].id >= 0);
    __CRAB_assert(devices[x].id <= 4);

    return 0;
}

