#include "nextcapstone.h"
#undef X86_INS_

la_name_enum_t next_x86_insn_tr[X86_INS_ENDING + 1];
la_name_enum_t next_x86_insn_reg[X86_REG_ENDING + 1];
la_name_enum_t next_x86_insn_bcast[5];
la_name_enum_t next_x86_insn_op_type[4];
la_name_enum_t next_x86_insn_avx_cc[X86_AVX_CC_TRUE_US + 1];

csh next_handle;
char next_cap_tmp[IR1_INST_SIZE];
uint8_t dt_nextcatstone_mode;

struct la_dt_insn *nextcapstone_get_from_insn(cs_insn *inputinfo,
    int ir1_num, void *pir1_base)
{
    if (inputinfo == NULL) {
        return NULL;
    }

    struct la_dt_insn *ret;
    if (pir1_base) {
        uint64_t current_address = (uint64_t)pir1_base +
            (ir1_num * sizeof(struct la_dt_insn));
        ret = (void *)current_address;
    } else {
        ret = malloc(sizeof(struct la_dt_insn));
    }

    //prefix
#ifdef LATX_DISASSEMBLE_TRACE_DEBUG
    strncpy(ret->mnemonic, inputinfo->mnemonic, 32);
    strncpy(ret->op_str, inputinfo->op_str, 160);
#endif

    lsassert(inputinfo->id <= X86_INS_ENDING);
    ret->id = next_x86_insn_tr[inputinfo->id].id;

    for (int i = 0; i < 4; i++) {
        ret->x86.prefix[i] = inputinfo->detail->x86.prefix[i];
    }

    for (int i = 0; i < 4; i++) {
        ret->x86.opcode[i] = inputinfo->detail->x86.opcode[i];
    }

    for (int i = 0; i < 24; i++) {
        ret->bytes[i] = inputinfo->bytes[i];
    }

    ret->x86.addr_size = inputinfo->detail->x86.addr_size;
    ret->x86.rex = inputinfo->detail->x86.rex;
    ret->x86.op_count = inputinfo->detail->x86.op_count;

    for (int i = 0; i < 8; i++) {
        int otype = inputinfo->detail->x86.operands[i].type;
        ret->x86.operands[i].type = next_x86_insn_op_type[otype].id;

        if (otype == X86_OP_IMM) {
            ret->x86.operands[i].imm = inputinfo->detail->x86.operands[i].imm;
        } else if (otype == X86_OP_REG) {
            lsassert(inputinfo->detail->x86.operands[i].reg <=
                dt_X86_REG_ENDING);
            ret->x86.operands[i].reg =
                next_x86_insn_reg[inputinfo->detail->x86.operands[i].reg].id;
        } else if (otype == X86_OP_MEM) {
            lsassert(inputinfo->detail->x86.operands[i].mem.segment <=
                dt_X86_REG_ENDING);
            lsassert(inputinfo->detail->x86.operands[i].mem.base <=
                dt_X86_REG_ENDING);
            lsassert(inputinfo->detail->x86.operands[i].mem.index <=
                dt_X86_REG_ENDING);

            ret->x86.operands[i].mem.segment =
                next_x86_insn_reg[inputinfo->detail->
                x86.operands[i].mem.segment].id;
            ret->x86.operands[i].mem.default_segment =
                dt_X86_REG_INVALID;
            ret->x86.operands[i].mem.base =
                next_x86_insn_reg[inputinfo->detail->
                x86.operands[i].mem.base].id;
            ret->x86.operands[i].mem.index =
                next_x86_insn_reg[inputinfo->detail->
                x86.operands[i].mem.index].id;
            ret->x86.operands[i].mem.scale =
                inputinfo->detail->x86.operands[i].mem.scale;
            ret->x86.operands[i].mem.disp =
                inputinfo->detail->x86.operands[i].mem.disp;
        }

        ret->x86.operands[i].size = inputinfo->detail->x86.operands[i].size;

        switch (inputinfo->detail->x86.operands[i].access) {
            default:
                break;
            case CS_AC_READ:
                ret->x86.operands[i].access = dt_CS_AC_READ;
                break;
            case CS_AC_WRITE:
                ret->x86.operands[i].access = dt_CS_AC_WRITE;
                break;
            case CS_AC_READ | CS_AC_WRITE:
                ret->x86.operands[i].access = dt_CS_AC_READ|dt_CS_AC_WRITE;
                break;
        }

        ret->x86.operands[i].avx_bcast =
            next_x86_insn_bcast[inputinfo->detail->
            x86.operands[i].avx_bcast].id;
        ret->x86.operands[i].avx_zero_opmask =
            inputinfo->detail->x86.operands[i].avx_zero_opmask;
    }

    ret->x86.avx_cc =
        next_x86_insn_avx_cc[inputinfo->detail->x86.avx_cc].id;
    ret->size = inputinfo->size;
    ret->address = inputinfo->address;

    return ret;
}

int nextcapstone_get(const uint8_t *code, size_t code_size,
        uint64_t address,
        size_t count, struct la_dt_insn **insn,
        int ir1_num, void *pir1_base)
{
    cs_insn *inputinfo;
    struct la_dt_insn *ret;

    dtassert(next_handle);

    int next_count = latx_cs_disasm(next_handle, code, code_size,
        address, count, &inputinfo, 0, next_cap_tmp);

    if (inputinfo == NULL) {
        *insn = NULL;
        qemu_log_mask(LAT_LOG_DT, "%s: can't disasm code 0x%x\n",
            __func__, *(uint32_t *)code);
        return next_count;
    }

    ret = nextcapstone_get_from_insn(inputinfo, ir1_num, pir1_base);
    *insn = ret;

    return next_count;
}

static void init_insn_tr();
static void init_insn_reg();
static void init_insn_bcast();
static void init_insn_op_type();
static void init_insn_avx_cc();

static void xtm_capstone_init(int abi_bits)
{
    int mode = 0;
    dt_nextcatstone_mode = abi_bits;

    if(abi_bits == 32)
        mode = CS_MODE_32;
    else
        mode = CS_MODE_64;

    if (cs_open(CS_ARCH_X86, mode, &next_handle) != CS_ERR_OK) {
        fprintf(stderr, "%s %s %d error : cs_open\n",
                __FILE__, __func__, __LINE__);
        exit(-1);
    }

    cs_option(next_handle, CS_OPT_DETAIL, CS_OPT_ON);
}

void nextcapstone_init(int abi_bits)
{
#ifdef CONFIG_LATX_CAPSTONE_NEXT
    dtassert(handle != NULL);
    next_handle = handle;
#else
    xtm_capstone_init(abi_bits);
#endif

    init_insn_tr();
    init_insn_reg();
    init_insn_bcast();
    init_insn_op_type();
    init_insn_avx_cc();
}

static void init_insn_avx_cc()
{
    LA_X86_INSN_ENUM(next_x86_insn_avx_cc, X86_AVX_CC_, X86_AVX_CC_, INVALID);
    LA_X86_INSN_ENUM(next_x86_insn_avx_cc, X86_AVX_CC_, X86_AVX_CC_, EQ);
    LA_X86_INSN_ENUM(next_x86_insn_avx_cc, X86_AVX_CC_, X86_AVX_CC_, LT);
    LA_X86_INSN_ENUM(next_x86_insn_avx_cc, X86_AVX_CC_, X86_AVX_CC_, LE);
    LA_X86_INSN_ENUM(next_x86_insn_avx_cc, X86_AVX_CC_, X86_AVX_CC_, UNORD);
