#include "metadb.h"
#include "console.h"

// Handles a file path by converting it to handles and processing each
void commandline_handler_metadb_handle::on_file(const char * url)
{
    metadb_handle_list handles;
    try
    {
        metadb_io::get()->path_to_handles_simple(url, handles);
    } catch(std::exception const & e)
    {
        console::complain("Path evaluation failure", e);
        return;
    }
    // Process each handle individually
    for(t_size walk = 0; walk < handles.get_size(); ++walk)
    {
        on_file(handles[walk]);
    }
}

