#include <pthread.h>
#include <stdio.h>

// Shared counter variable
int shared_counter = 0;
pthread_mutex_t lock;

// Thread function that safely increments the counter
void *increment_thread(void *arg)
{
    for(int i=0;i<1000;i++)
    {
        pthread_mutex_lock(&lock);
        shared_counter++;  // Protected
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

// Thread function with race condition (unsynchronized access)
void *buggy_thread(void *arg)
{
    for(int i=0;i<1000;i++)
    {
        shared_counter++;  // Bug: race condition
    }
    return NULL;
}

int main(void)
{
    pthread_t t1, t2;

    // Initialize mutex
    pthread_mutex_init(&lock, NULL);

    // Create threads
    pthread_create(&t1, NULL, increment_thread, NULL);
    pthread_create(&t2, NULL, buggy_thread, NULL);

    // Wait for threads to complete
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    // Print final counter value
    printf("Counter: %d\n", shared_counter);

    // Destroy mutex
    pthread_mutex_destroy(&lock);

    return 0;
}

