    TString ToStringViaOstream(T baseNumber)
    {
        std::stringstream ss;
        ss << baseNumber;
        return ss.str();
    }

    Y_UNIT_TEST(TestBin)
    {
        UNIT_ASSERT_VALUES_EQUAL(ToStringViaOstream(Bin(static_cast<ui32>(2), nullptr)), "10");
