int main(int argc, const char** argv)
{
  anm2ed::Loader loader(argc, argv);

  // Check for initialization errors
  if (loader.isError) 
    return EXIT_FAILURE;

  anm2ed::State state(loader.window, loader.settings, loader.arguments);

  // Main loop
  while (!state.isQuit)
    state.loop(loader.window, loader.settings);

  return EXIT_SUCCESS;
