    IO.mapOptional("OffsetToExceptionTbl", AuxSym.OffsetToExceptionTbl);
    IO.mapOptional("SizeOfFunction", AuxSym.SizeOfFunction);
    IO.mapOptional("SymIdxOfNextBeyond", AuxSym.SymIdxOfNextBeyond);
}

