#include <singleapplication.h>
#include "messagereceiver.h"

// Main entry point
int main(int argc, char *argv[])
{
    // Allow secondary instances
    SingleApplication app(argc, argv, true);
    MessageReceiver msgReceiver;

    // If this is a secondary instance
    if(app.isSecondary())
    {
        app.sendMessage(app.arguments().join(' ').toUtf8());
        qDebug() << "App already running.";
        qDebug() << "Primary instance PID: " << app.primaryPid();
        qDebug() << "Primary instance user: " << app.primaryUser();
        return 0;
    }
    else
    {
        QObject::connect(
            &app,
            &SingleApplication::receivedMessage,
            &msgReceiver,
            &MessageReceiver::receivedMessage
        );
    }

    return app.exec();
}

#include "bounding_box_diagonal.h"
#include "mat_max.h"
#include "mat_min.h"
#include <cmath>

// Computes the diagonal length of the bounding box
IGL_INLINE double igl::bounding_box_diagonal(
  const Eigen::MatrixXd & V)
{
    using namespace Eigen;
    VectorXd maxV, minV;
    VectorXi maxVI, minVI;

    // Find maximum and minimum values along rows
    mat_max(V, 1, maxV, maxVI);
    mat_min(V, 1, minV, minVI);

    // Compute Euclidean distance between min and max corners
    return sqrt((maxV - minV).array().square().sum());
}

