void ParseProgram(LPBYTE pointer, LPBYTE end, int type, ostream *outStream)
{
    LPBYTE begin = pointer;
    pointer += sizeof(UINT);
    pointer += sizeof(UINT);
    GetBytes(pointer, true);
    GetBytes(pointer, true);
    GetBytes(pointer, true);
    USHORT len = GetData<USHORT>(pointer);
    for (size_t i = 0; i < len; i++)
        GetString(pointer, true);
    int flag = GetData<int>(pointer);
    pointer += sizeof(UINT);
    if ((flag & 1) != 0) pointer += 16;
    GetBytes(pointer, true);
    GetBytes(pointer, true);
    outStream->write(C(begin), pointer - begin);
    vector<ESection_Program_Assembly> assemblies = GetAssemblies(pointer);
    vector<ESection_Program_Method> methods = GetMethods(pointer);
    if (type == 0)
    {
        vector<string *> list;
        for (ESection_Program_Assembly &item : assemblies)
            if ((item.Status & EtagStatus::C_External) == 0 && item.Remark.empty())
                list.push_back(&item.Remark);
        for (ESection_Program_Method &item : methods)
        {
            if ((item.Attributes & EMethodAttr::M_External) == 0 && item.Remark.empty())
            {
                size_t index = Random<size_t>(0, list.size());
                list.insert(list.begin() + index, &item.Remark);
            }
        }
        if (list.size())
        {
            for (size_t i = min(ccount, list.size()); i > 0; i--)
            {
                size_t index = Random<size_t>(0, i - 1);
                list[index]->append(join(GetCopyright[redacted]
                list.erase(list.begin() + index);
            }
        }
    }
    else if (type == 1)
    {
        vector<ESection_Program_Method *> list;
        for (ESection_Program_Method &item : methods)
            if ((item.Attributes & EMethodAttr::M_External) == 0)
                list.push_back(&item);
        for (size_t i = min(ccount, list.size()); i > 0; i--)
        {
            size_t index = Random<size_t>(0, i - 1);
            string remark;
            vector<UINT> row;
            for (string &line : GetCopyright[redacted]
            {
                row.push_back(remark.length());
                remark.append("\x6a\x00\x00\x00\x00\xff\xff\x00\x00\x00\x00\x00\x00", 13);
                UINT len = line.length() + 1;
                remark.append(C(&len), 4);
                remark.append(line.c_str(), len);
                remark.append("\x36\x01", 2);
            }
            ESection_Program_Method *item = list[index];
            UINT len = remark.length();
            LPBYTE ptr = item->RowOffset.begin()._Ptr;
            size_t size = item->RowOffset.size() / sizeof(UINT);
            for (size_t i = 0; i < size; i++, ptr += sizeof(UINT))
                *(LPUINT)ptr += len;
            item->RowOffset.insert(item->RowOffset.begin(), ((vector<BYTE> *)&row)->begin(), ((vector<BYTE> *)&row)->end());
            ptr = item->FlowOffset.begin()._Ptr;
            size = item->FlowOffset.size() / (sizeof(BYTE) + sizeof(UINT) + sizeof(UINT));
            for (size_t i = 0; i < size; i++, ptr += sizeof(BYTE) + sizeof(UINT) + sizeof(UINT))
            {
                *(LPUINT)(ptr + sizeof(BYTE)) += len;
                *(LPUINT)(ptr + sizeof(BYTE) + sizeof(UINT)) += len;
            }
            ptr = item->MethodOffset.begin()._Ptr;
            size = item->MethodOffset.size() / sizeof(UINT);
            for (size_t i = 0; i < size; i++, ptr += sizeof(UINT))
                *(LPUINT)ptr += len;
            ptr = item->VariableOffset.begin()._Ptr;
            size = item->VariableOffset.size() / sizeof(UINT);
            for (size_t i = 0; i < size; i++, ptr += sizeof(UINT))
                *(LPUINT)ptr += len;
            list[index]->Code.insert(list[index]->Code.begin(), remark.begin(), remark.end());
            list.erase(list.begin() + index);
        }
    }
    WriteVectorAssembly(outStream, assemblies);
    WriteVectorMethod(outStream, methods);
    outStream->write(C(pointer), end - pointer);
}

void Parse(LPBYTE data, size_t size, int type, ostream *outStream)
{
    Efile_Header header;
    mempcpy(&header, data, sizeof(Efile_Header));
    if (arrcmp(header.Magic1, Magic1, 4) && arrcmp(header.Magic2, Magic2, 4))
    {
        outStream->write(C(&header), sizeof(Efile_Header));
        long long offset = sizeof(Efile_Header);
        while (offset < size)
        {
            ESection_Header sh = GetData<ESection_Header>(data, offset);
            if (!arrcmp(sh.Magic, Magic_Section, 4))
                goto end;
            ESection_Info si = GetData<ESection_Info>(data, offset);
            if (!arrcmp(si.Key, KEY, 4))
                Decode_Str(si.Name, si.Key);
            LPSZ Block_Name = (LPSZ)si.Name;
            if (strcmp(Block_Name, "") == 0)
            {
                outStream->write(C(data + offset - sizeof(ESection_Header) - sizeof(ESection_Info)), sizeof(ESection_Header) + sizeof(ESection_Info) + si.DataLength);
                break;
            }
            else if (type == 2 && strcmp(Block_Name, "(u7bOo`k") == 0)
            {
                ostringstream stream(NULL, 0, ios::binary);
                ParseUserInfo(data + offset, data + offset + si.DataLength, &stream);
                UINT oldlen = si.DataLength;
                if (!arrcmp(si.Key, KEY, 4)) Decode_Str(si.Name, si.Key);
                si.DataLength = stream.pcount();
                si.Data_CheckSum = GetChecksumValue(D(stream.str()), stream.pcount());
                sh.Info_CheckSum = GetChecksumValue(D(&si), sizeof(ESection_Info));
                outStream->write(C(&sh), sizeof(ESection_Header));
                outStream->write(C(&si), sizeof(ESection_Info));
                outStream->write(stream.str(), stream.pcount());
                si.DataLength = oldlen;
            }
            else if ((type == 0 || type == 1) && strcmp(Block_Name, "z^k") == 0)
            {
                ostringstream stream(NULL, 0, ios::binary);
                ParseProgram(data + offset, data + offset + si.DataLength, type, &stream);
                UINT oldlen = si.DataLength;
                if (!arrcmp(si.Key, KEY, 4)) Decode_Str(si.Name, si.Key);
                si.DataLength = stream.pcount();
                si.Data_CheckSum = GetChecksumValue(D(stream.str()), stream.pcount());
                sh.Info_CheckSum = GetChecksumValue(D(&si), sizeof(ESection_Info));
                outStream->write(C(&sh), sizeof(ESection_Header));
                outStream->write(C(&si), sizeof(ESection_Info));
                outStream->write(stream.str(), stream.pcount());
                si.DataLength = oldlen;
            }
            else
                outStream->write(C(data + offset - sizeof(ESection_Header) - sizeof(ESection_Info)), sizeof(ESection_Header) + sizeof(ESection_Info) + si.DataLength);
            offset += si.DataLength;
        }
    }
end:;
}

int main(int argc, LPSTR argv[])
{
    if (argc == 5)
    {
        int type = atoi(argv[1]);
        //case 0://z^kYl
        //case 1://z^kNx
        //case 2://(u7bOo`k
        ccount = atoi(argv[2]);
        string path = argv[3];
        string list = argv[4];
        if (list.size())
        {
            ifstream fs(list, ios::binary);
            ostringstream stream(NULL, 0, ios::binary);
            stream << fs.rdbuf();
            fs.close();
            string text(stream.str(), stream.pcount());
            vector<string> list = split(text, "\r\n");
            for (string &line : list)
            {
                size_t size = line.size();
                if (size && line[size - 1] == '\r')
                    line.pop_back();
                list.push_back(split(line, "<br>"));
            }
        }
        if (list.size())
        {
            ifstream inStream(path, ios::binary);
            ostringstream stream(NULL, 0, ios::binary);
            stream << inStream.rdbuf();
            inStream.close();
            ofstream outStream(path.substr(0, path.length() - 2) + "_ic.e", ios::binary);
            Parse(D(stream.str()), stream.pcount(), type, &outStream);
            outStream.close();
        }
    }
    return 0;
}

