// Global variable declaration
extern std::size_t memory_size;

// Main entry point for the kernel
extern "C" void main()
{
    // Initialize C++ constructors
    utils::cxx::init_constructors();

    // Initialize bootloader components
    bootloader::init();

    // Initialize terminal
    utils::flanterm::init();

    // Initialize physical memory manager
    pmm::init();

    // Initialize paging system
    paging::init();

    // Initialize kernel heap
    kheap::init();

    // Fully initialize terminal
    utils::flanterm::fullinit();

    // Print memory information
    klibc::printf("PMM: Total usable memory: %lli bytes\r\n", memory_size);

    // Print paging information
    klibc::printf("Paging: Enabled kernel root with %d level paging\n\r", arch::level_paging());

    // Print heap information
    klibc::printf("KHeap: Available memory %lli bytes\r\n", KHEAP_SIZE);

    // Initialize ACPI tables
    acpi::init_tables();

    // Perform early architecture initialization
    arch::init(ARCH_INIT_EARLY);

    // Complete ACPI initialization
    acpi::full_init();

    // Perform common architecture initialization
    arch::init(ARCH_INIT_COMMON);

    // Set early boot flag to false
    extern int is_early;
    is_early = 0;

    // Indicate boot completion
    klibc::printf("Boot is done\r\n");

    // Print timing information before page fault test
    klibc::printf("current sec %lli, waiting 2 sec and page faulting\r\n", time::timer->current_nano() / (1000 * 1000 * 1000));
    klibc::printf("current sec %lli\r\n", time::timer->current_nano() / (1000 * 1000 * 1000));

    // Flush TLB entry for specific address
    arch::tlb_flush(0x47afe000, PAGE_SIZE);

    // Trigger page fault by writing to invalid address
    *(int*)0x47afe710 = 0;

    // Halt CPU on fatal error
    arch::hcf();
}

