    dcbt r0, addr
    blr
}

asm void DCBlockZero(register void* addr) {
    nofralloc
    dcbz r0, addr
    blr
}

asm void DCBlockStore(register void* addr) {
    nofralloc
    dcbst r0, addr
    blr
}

asm void DCBlockFlush(register void* addr) {
    nofralloc
    dcbf r0, addr
    blr
}

asm void DCBlockInvalidate(register void* addr) {
    nofralloc
    dcbi r0, addr
    blr
}

asm void DCInvalidateRange(register void* addr, register u32 nBytes) {
    nofralloc
    cmplwi nBytes, 0
    blelr
    clrlwi r5, addr, 27
    add    nBytes, nBytes, r5
    addi   nBytes, nBytes, 31
    srwi   nBytes, nBytes, 5
    mtctr  nBytes
@1
    dcbi r0, addr
    addi addr, addr, 32
    bdnz @1
    blr
}

asm void DCFlushRange(register void* addr, register u32 nBytes) {
    nofralloc
    cmplwi nBytes, 0
