class Solution {
public:
    // Generates Pascal's Triangle
    vector<vector<int>> generate(int numRows)
    {
        vector<vector<int>> pascalsTriangle;
        pascalsTriangle.push_back({1});

        for(int i = 1; i < numRows; i++)
        {
            vector<int> newTriangleBase;
            newTriangleBase.push_back(1);

            for(int j = 1; j < pascalsTriangle.back().size(); j++)
            {
                newTriangleBase.push_back(pascalsTriangle.back()[j] + pascalsTriangle.back()[j - 1]);
            }

            newTriangleBase.push_back(1);
            pascalsTriangle.push_back(newTriangleBase);
        }

        return pascalsTriangle;
    }
};

