using namespace std;

// Main function
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    // Read input
    if(!(cin >> n)) return 0;

    cout << "! ";
    // First loop: output n zeros
    for(int i=0; i<n; ++i)
    {
        if(i) cout << ' ';
        cout << 0;
    }
    // Second loop: output n more zeros
    for(int i=0; i<n; ++i)
    {
        cout << ' ' << 0;
    }
    cout << "\n";
    cout.flush();
    return 0;
}

