// Command line options
cl::opt<std::string> InputFilename(cl::Positional, cl::desc("<input file>"),
                                   cl::init("-"));
cl::opt<std::string> OutputFilename("o", cl::desc("Specify output filename"),
                                    cl::value_desc("filename"), cl::Required);

int main(int argc, char **argv)
{
    // Parse command line arguments
    cl::ParseCommandLineOptions(argc, argv);

    LLVMContext context;
    SMDiagnostic error;

    // Load IR module from input file
    auto module = parseIRFile(InputFilename, error, context);
    if (!module) {
        error.print(InputFilename.data(), errs());
        return -1;
    }

    // Instrument memory operations
    dynamic::MemoryInstrument().runOnModule(*module);

    // Write bitcode to output file
    std::error_code ec;
    ToolOutputFile outFile(OutputFilename, ec, sys::fs::OF_None);
    outFile.keep();
    WriteBitcodeToFile(*module, outFile.os());

    return 0;
}

#include <QtCore/QCommandLineParser>
#include <QtGui/QGuiApplication>
#include <QtMcpServer/QMcpServer>
#include "tools.h"

// Main entry point for the Qt Mcp Example Window Server
int main(int argc, char *argv[])
{
    QGuiApplication app(argc, argv);

    // Set application metadata
    app.setApplicationName("Qt Mcp Example Window Server");
    app.setApplicationVersion("1.0");
    app.setOrganizationName("Signal Slot Inc.");
    app.setOrganizationDomain("signal-slot.co.jp");

    // Command line parsing setup
    QCommandLineParser parser;
    parser.setApplicationDescription(app.applicationName());
    parser.addHelpOption();
    parser.addVersionOption();

    // Define backend option
    QCommandLineOption backendOption(
        QStringList() << "b" << "backend",
        "Backend to use (stdio/sse).",
        "backend", "stdio"
    );
    parser.addOption(backendOption);

    // Define address option
    QCommandLineOption addressOption(
        QStringList() << "a" << "address",
        "Address to listen on (host:port).",
        "address", "127.0.0.1:8000"
    );
    parser.addOption(addressOption);

    // Process command line arguments
    parser.process(app);

    // Extract parsed values
    QString backend = parser.value(backendOption);
    QString address = parser.value(addressOption);

    // Create and configure server
    QMcpServer server(backend);

    // Register tool set with descriptions
    server.registerToolSet(
        new Tools(&server),
        {
            { "screenShot", "Take screen shot of whole screen" },
            { "moveCursor", "Move cursor to specified position" },
            { "moveCursor/x", "X coordinate of cursor" },
            { "moveCursor/y", "Y coordinate of cursor" }
        }
    );

    // Connect server finished signal to application quit
    QObject::connect(&server, &QMcpServer::finished, &app, &QCoreApplication::quit);

    // Start server with specified address
    server.start(address);

    return app.exec();
}

