#include <unordered_map>
#include <string>

class Solution {
public:
    // Checks if two strings are isomorphic
    bool isIsomorphic(std::string s, std::string t) {
        std::unordered_map<char, char> mappingFromS;
        std::unordered_map<char, char> mappingFromT;

        for(int i = 0; i < s.size(); i++) {
            mappingFromS[s[i]] = t[i];
            mappingFromT[t[i]] = s[i];
        }

        for(int i = 0; i < s.size(); i++) {
            // Verify consistency of mappings
            if(s[i] != mappingFromT[t[i]] || t[i] != mappingFromS[s[i]]) {
                return false;
            }
        }

        return true;
    }
};

