// Serialize DMX packet data
void FDMXProtocolArtNetDMXPacket::Serialize(FArchive & Ar)
{
    Ar.Serialize((void*)ID, ARTNET_STRING_SIZE);
    Ar << OpCode;
    Ar << VerH;
    Ar << Ver;
    Ar << Sequence;
    Ar << Physical;
    Ar << Universe;
    Ar << LengthHi;
