#include "chan.h"
#include "gmock/gmock.h"
#include "gtest/gtest.h"
#include <thread>

// Test for channel put, take, and close operations
TEST(ChanTest, PutTakeClose)
{
    dap::Chan<int> chan;

    // Launch thread to put values into the channel
    auto thread = std::thread([&] {
        chan.put(10);
        chan.put(20);
        chan.put(30);
        chan.close();
    });

    // Verify values are taken in order
    EXPECT_EQ(chan.take(), dap::optional<int>(10));
    EXPECT_EQ(chan.take(), dap::optional<int>(20));
    EXPECT_EQ(chan.take(), dap::optional<int>(30));

    // After closing, take should return empty optional
    EXPECT_EQ(chan.take(), dap::optional<int>());

    // Wait for thread to complete
    thread.join();
}

