{
    ConnectionInfo ci;
    HttpRequest request(ci, 1);
    std::string_view url("/");
    request.parseUrl(url.data(), url.size());
    EXPECT_EQ("/", request.fullUrl());
    EXPECT_EQ("/", request.requestUrl());
