// Threshold in megabytes for determining low-memory devices
// IMPORTANT: Review the LinkerLowMemoryThresholdTest documentation in
// build/android/pylib/linker/test_case.py before changing this value.
#define LOW_RAM_DEVICE_MEMORY_LIMIT_MB 512

const int64 kLowRamThresholdBytes =
    1024 * 1024 * LOW_RAM_DEVICE_MEMORY_LIMIT_MB;

// Minimum SDK version required for low-end device detection (above Jelly Bean MR2)
const int kMinSdkForLowEndDetection = 18;

// JNI-exposed function to check if the current device is low-end
static jboolean IsLowEndDevice(JNIEnv* env, jclass clazz) {
  return base::android::SysUtils::IsLowEndDevice();
}

namespace base {
namespace android {

bool SysUtils::Register(JNIEnv* env) {
  return RegisterNativesImpl(env);
}

bool SysUtils::IsLowEndDevice() {
  const int64 physical_memory = SysInfo::AmountOfPhysicalMemory();
  const int sdk_version = BuildInfo::GetInstance()->sdk_int();
  return physical_memory <= kLowRamThresholdBytes &&
         sdk_version > kMinSdkForLowEndDetection;
}

SysUtils::SysUtils() { }

}  // namespace android
}  // namespace base

