void signalHandler(int sig) {
    void *buffer[100];
    size_t count;
    // Capture stack frames
    count = backtrace(buffer, 100);
    // Output to standard error
    fprintf(stderr, "Signal caught: %d\n", sig);
    backtrace_symbols_fd(buffer, count, STDERR_FILENO);
    _exit(1);
}
