using namespace caf;
using std::endl;

int main() {
  // Seed random number generator with current time
  std::srand(static_cast<unsigned>(std::time(nullptr)));

  // Spawn 50 actors with unique identifiers
  for (int actor_id = 1; actor_id <= 50; ++actor_id) {
    spawn<blocking_api>([actor_id](blocking_actor* self) {
      // Print initial greeting message
      aout(self) << "Hi there! This is actor nr. "
                 << actor_id << "!" << endl;

      // Generate random delay between 0-9 milliseconds
      std::random_device rd;
      std::default_random_engine re(rd());
      std::chrono::milliseconds timeout{re() % 10};

      // Schedule a 'done' message to self after the delay
      self->delayed_send(self, timeout, atom("done"));

      // Wait for the delayed message and respond
      self->receive(others() >> [actor_id, self] {
        aout(self) << "Actor nr. "
                   << actor_id << " says goodbye!" << endl;
      });
    });
  }

  // Wait for all spawned actors to complete their execution
  await_all_actors_done();

  // Terminate the system cleanly
  shutdown();
  return 0;
}

