// Check if message can be added to queue with space for CR/LF terminators
bool tryEnqueueMessage(QUEUE_TYPE(uint8_t)* buffer, uint8_t* data,
        int length) {
    if(queue_available(buffer) < length + 2) {
        return false;
    }
    for(int index = 0; index < length; index++) {
        QUEUE_PUSH(uint8_t, buffer, (uint8_t)data[index]);
    }
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\r');
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\n');
    return true;
}

void transmitMessage(Listener* handler, uint8_t* payload, int payloadLength) {
    if(!tryEnqueueMessage(&handler->usb->sendQueue, payload, payloadLength)) {
        debug("USB send buffer full, discarding CAN message: %s\r\n", payload);
    }
    if(!tryEnqueueMessage(&handler->serial->sendQueue, payload, payloadLength)) {
        debug("UART send buffer full, discarding CAN message: %s\r\n", payload);
    }
}

void handleInputProcessing(Listener* handler) {
    // USB processing must always occur as it manages MCU USB tasks including SETUP and enumeration
    processInputQueue(handler->usb);
    processInputQueue(handler->serial);
}

