#include <vector>

std::mutex print_mutex;

void worker_function(unsigned int delay_seconds) {
    using std::chrono::seconds;
    using std::cout;
    using std::endl;
    using std::lock_guard;
    using std::mutex;

    std::this_thread::sleep_for(seconds(delay_seconds));
    {
        lock_guard<mutex> guard{print_mutex};
        cout << delay_seconds << endl;
    }
}

int main(int argument_count, char** arguments) {
    using std::cout;
    using std::endl;
    using std::string;
    using std::stringstream;
    using std::thread;
    using std::vector;

    vector<thread>::size_type thread_count = argument_count - 1;
    vector<thread> thread_list;
    thread_list.reserve(thread_count);

    for (auto index = 1; index < argument_count; ++index) {
        stringstream converter;
        converter << arguments[index];
        unsigned int parsed_value;
        if (!(converter >> parsed_value)) {
            cout << "Invalid input detected: " << arguments[index] << endl;
        } else {
            thread_list.emplace_back(worker_function, parsed_value);
        }
    }

    for (auto& active_thread : thread_list) {
        active_thread.join();
    }

    return 0;
}

