#include <algorithm>
#include <functional>
#include <vector>

// Sort the collection and process unique entries for version management
int main() {
    std::vector<int> values = {1, 2, 2, 3, 4, 4, 5}; // Example data

    // Sort all elements in ascending order
    std::sort(values.begin(), values.end());

    // Remove consecutive duplicate elements (after sorting)
    auto newEnd = std::unique(values.begin(), values.end());
    values.erase(newEnd, values.end());

    // Process each remaining value with a callback function
    for (auto& val : values) {
        setCurVer(hModule, val);
    }

    // Create a filtered list containing only pure AutoCAD entries
    std::vector<AutoCadInfo> filteredAcads;
    filteredAcads.reserve(values.size());

    // Copy only elements that satisfy isPureAutoCad condition
    std::copy_if(values.begin(), values.end(),
                 std::back_inserter(filteredAcads),
                 [](const AutoCadInfo& info) { return info.isPureAutoCad(); });

    // Set non-versionized CurVer based on availability of pure AutoCAD entries
    if (filteredAcads.empty()) {
        setNonVersionizedCurVer(hModule, values[0]);
    } else {
        setNonVersionizedCurVer(hModule, filteredAcads[0]);
    }

    return 0;
}

