namespace rc {
namespace detail {

FrequencyMap::FrequencyMap(const std::vector<std::size_t>& freqs)
    : cumulativeTotal(0) {
  cumulativeTable.reserve(freqs.size());
  for (auto count : freqs) {
    cumulativeTotal += count;
    cumulativeTable.push_back(cumulativeTotal);
  }
}

std::size_t FrequencyMap::lookup(std::size_t value) const {
  return std::upper_bound(cumulativeTable.begin(), cumulativeTable.end(), value) -
         cumulativeTable.begin();
}

std::size_t FrequencyMap::total() const { 
  return cumulativeTotal; 
}

