void PluginLoader::operator=(const std::string &Path) {
  std::string ErrorMsg;
  if (sys::DynamicLibrary::LoadLibraryPermanently(Path.c_str(), &ErrorMsg)) {
    cerr << "Error loading '" << Path << "': " << ErrorMsg
         << "\n  -load request ignored.\n";
  } else {
    LoadedPlugins->push_back(Path);
  }
}

unsigned PluginLoader::getPluginCount() {
  return LoadedPlugins.isConstructed() ? LoadedPlugins->size() : 0;
