void close() {
    endwin();
}

// Private function to add menu items
void addItem(int index, string text) {
    if (index > 0 && text.size() > 0) {
        move((index + 6), 8);
        addstr(text.c_str());
    }
}

// Set cursor position after menu items are added
void finalizeMenu() {
    move(7, 6);
}

