#include <trng/lcg64_shift.hpp>

// Compute x^n using fast exponentiation (binary method)
unsigned long long power(unsigned long long base, unsigned long long exp) {
    unsigned long long res = 1;
    while (exp > 0) {
        if ((exp & 1) > 0) {
            res = res * base;
        }
        base = base * base;
        exp >>= 1;
    }
    return res;
}

// Compute floor(log2(x)) for x > 0
unsigned int floor_log2(unsigned long long value) {
    unsigned int bits(0);
    while (value > 0) {
        value >>= 1;
        ++bits;
    }
    --bits;
    return bits;
}

int main(void) {
    trng::lcg64_shift rng_default;
    trng::lcg64_shift rng_seed_777(777);
    trng::lcg64_shift rng_split_5_0;
    rng_split_5_0.split(5, 0);
    trng::lcg64_shift rng_split_5_1;
    rng_split_5_1.split(5, 1);
    trng::lcg64_shift rng_split_5_2;
    rng_split_5_2.split(5, 2);
    trng::lcg64_shift rng_jump_8193;
    trng::lcg64_shift rng_jump2_4099;

    std::cout << "# default, seed 777, split 5-0, split 5-1, split 5-2, jump-8193, jump2-4099" << std::endl;

    for (int idx = 0; idx < 1009; ++idx) {
        std::cout << static_cast<long long>(rng_default()) << ',';
        std::cout << static_cast<long long>(rng_seed_777()) << ',';
        std::cout << static_cast<long long>(rng_split_5_0()) << ',';
        std::cout << static_cast<long long>(rng_split_5_1()) << ',';
        std::cout << static_cast<long long>(rng_split_5_2()) << ',';

        rng_jump_8193.jump(idx);
        std::cout << static_cast<long long>(rng_jump_8193()) << ',';

        rng_jump2_4099.jump2(idx % 64);
        std::cout << static_cast<long long>(rng_jump2_4099()) << '\n';
    }

    return 0;
}

