AnalogAccel::AnalogAccel()
{
    // Configure ADC with prescaler of 64 (12MHz / 64 = 187.5 kHz),
    // within recommended range of 50-200 kHz. Enable interrupt,
    // auto-triggering, initiate conversion, and activate ADC.
    ADCSRA |= _BV(ADPS1) | _BV(ADPS2) | _BV(ADIE) | _BV(ADATE) \
            | _BV(ADSC) | _BV(ADEN);

    // Set free-running mode: continuous sampling while ADC is enabled
    ADCSRB = 0;

    // Power-saving: disable digital input buffers on ADC pins
    DIDR0 |= _BV(ADC0D) | _BV(ADC1D) | _BV(ADC2D);
}

AnalogAccel::~AnalogAccel()
{
    ADCSRA &= ~_BV(ADEN); // Deactivate ADC, which also disables its interrupt
}

