    }
    SECTION("uint64 large value") {
        encoder.add_uint64(1, (1ULL << 35));
        mapbox::util::pbf decoder(data.data(), data.size());
        REQUIRE(decoder.next());
        REQUIRE((1ULL << 35) == decoder.get_uint64());
    }
    SECTION("truncated varint stream") {
        encoder.add_uint64(1, (1ULL << 35));
        data.resize(data.size() - 1); // simulate missing final byte
        mapbox::util::pbf decoder(data.data(), data.size());
        REQUIRE(decoder.next());
        REQUIRE_THROWS_AS(decoder.get_uint64(), mapbox::util::pbf::end_of_buffer_exception);
    }
    SECTION("corrupted varint continuation bit") {
        encoder.add_uint64(1, (1ULL << 28));
        data[data.size() - 1] |= 0x80; // force extra byte expected
        mapbox::util::pbf decoder(data.data(), data.size());
        REQUIRE(decoder.next());
        REQUIRE_THROWS_AS(decoder.get_uint64(), mapbox::util::pbf::end_of_buffer_exception);
    }
    SECTION("corrupted varint exceeding max length") {
        encoder.add_uint64(1, std::numeric_limits<uint64_t>::max());
        data[data.size() - 1] |= 0x80; // indicate more bytes follow
        mapbox::util::pbf decoder(data.data(), data.size());
        REQUIRE(decoder.next());
        REQUIRE_THROWS_AS(decoder.get_uint64(), mapbox::util::pbf::varint_too_long_exception);
    }
}

#include "cell_refine.hpp"
#include <viennagrid/algorithm/refine.hpp>

/***************
 * CELL_REFINE *
 ***************/
// Refine triangular cells in a 2D Cartesian domain based on a user-defined condition
tuple TriangularCartesian2D_Domain_cell_refine(TriangularCartesian2D_Domain input_domain, 
                                               TriangularCartesian2D_Segmentation input_segmentation, 
                                               bool (*condition)(const TriangularCartesian2D_Cell &))
{
    TriangularCartesian2D_Domain          output_domain;
    TriangularCartesian2D_Segmentation    output_segmentation(output_domain);

    // Container to store refinement flags for each cell
    CellRefinementFlagContainerType     refinement_flags;

    viennagrid::result_of::field<CellRefinementFlagContainerType,
                                 TriangularCartesian2D_Cell_t>::type    flag_field(refinement_flags);

    // Iterate over all cells and mark those that satisfy the refinement condition
    TriangularCartesian2D_CellRange_t domain_cells = viennagrid::elements(input_domain.get_domain());
    for (TriangularCartesian2D_CellRange_t::iterator cell_iter = domain_cells.begin();
         cell_iter != domain_cells.end();
         ++cell_iter)
    {
        if (condition(TriangularCartesian2D_Cell(*cell_iter)))
            flag_field(*cell_iter) = true;
    }

    // Perform refinement on marked cells
    viennagrid::cell_refine(input_domain.get_domain(),
                            input_segmentation.get_segmentation(),
                            output_domain.get_domain(),
                            output_segmentation.get_segmentation(),
                            flag_field);

    // Return the refined domain and segmentation as a tuple
    return make_tuple<TriangularCartesian2D_Domain, TriangularCartesian2D_Segmentation>(output_domain, output_segmentation);
}

