using namespace rainy;

// Test sphere instance properties and intersection behavior
TEST(SphereTest, InstanceTest) {
    Sphere sphere(2.0, Vector3(0.0, 0.0, 0.0), Color(), Color(0.75, 0.75, 0.75), REFLECTION_DIFFUSE);

    // Verify center coordinates
    EXPECT_EQ(0.0, sphere.center().x());
    EXPECT_EQ(0.0, sphere.center().y());
    EXPECT_EQ(0.0, sphere.center().z());

    // Verify emission values are zero
    EXPECT_EQ(0.0, sphere.emission().x());
    EXPECT_EQ(0.0, sphere.emission().y());
    EXPECT_EQ(0.0, sphere.emission().z());

    // Verify color components
    EXPECT_EQ(0.75, sphere.color().x());
    EXPECT_EQ(0.75, sphere.color().y());
    EXPECT_EQ(0.75, sphere.color().z());

    // Verify reflection type
    EXPECT_EQ(REFLECTION_DIFFUSE, sphere.reftype());

    HitPoint hitPoint;

    // Test successful intersection with ray pointing toward sphere
    EXPECT_TRUE(sphere.intersect(Ray(Vector3(10.0, 0.0, 0.0), Vector3(-1.0, 0.0, 0.0)), hitPoint));

    // Verify hit point position
    EXPECT_EQ(2.0, hitPoint.position().x());
    EXPECT_EQ(0.0, hitPoint.position().y());
    EXPECT_EQ(0.0, hitPoint.position().z());

    // Verify normal vector at hit point
    EXPECT_EQ(1.0, hitPoint.normal().x());
    EXPECT_EQ(0.0, hitPoint.normal().y());
    EXPECT_EQ(0.0, hitPoint.normal().z());

    // Test non-intersection with ray missing the sphere
    EXPECT_FALSE(sphere.intersect(Ray(Vector3(10.0, 0.0, 0.0), Vector3(0.0, 1.0, 0.0)), hitPoint));
}

