namespace ion
{
	namespace Graphics
	{
		namespace GL
		{

			void CIndexBuffer::UploadData(void const * bufferData, size_t const numElements, EValueType const type)
			{
				// Bind the element array buffer for uploading index data
				CheckedGLCall(glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, Handle));

				// Calculate total byte size and upload the data
				size_t const byteCount = numElements * GetValueTypeSize(type);
				CheckedGLCall(glBufferData(GL_ELEMENT_ARRAY_BUFFER, byteCount, bufferData, GL_STATIC_DRAW));

				// Unbind the buffer after uploading
				CheckedGLCall(glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0));

				// Store the number of elements
				Size = numElements;
			}

		}
	}
}

#include "scene/scenegroup.hpp"
#include <algorithm>
using namespace scene;

// Constructor: initializes the octree with specified depth
SceneGroup::SceneGroup(unsigned int treeDepth) {
    addOctreeLayers(treeDepth);
}

// Recursively adds layers to build the octree structure
void SceneGroup::addOctreeLayers(unsigned int remainingLevels) {
    if(remainingLevels != 0) {
        childGroups.reset(new std::array<SceneGroup,8>);
        std::for_each(childGroups->begin(), childGroups->end(),
        [&remainingLevels](SceneGroup& subtree) {
            subtree.addOctreeLayers(--remainingLevels);
        });
    }
}

// Updates all scene items and recursively updates child groups
void SceneGroup::updateScene() {
    std::for_each(childItems.begin(), childItems.end(), [](std::unique_ptr<SceneItem>& node) {
        node->update();
    });
    if(childGroups != nullptr) {
        std::for_each(childGroups->begin(), childGroups->end(),
        [](SceneGroup& branch) {
            branch.updateScene();
        });
    }
}

// Renders all scene items and recursively renders child groups
void SceneGroup::renderScene() {
    std::for_each(childItems.begin(), childItems.end(), [](std::unique_ptr<SceneItem>& node) {
        node->draw();
    });
    if(childGroups != nullptr) {
        std::for_each(childGroups->begin(), childGroups->end(),
        [](SceneGroup& branch) {
            branch.renderScene();
        });
    }
}

