#include <optional>
#include <cassert>

struct B {};

int main() {
    // Test explicit deduction guides
    {
        // optional(T)
        std::optional val(42);
        static_assert(std::is_same_v<decltype(val), std::optional<int>>, "");
        assert(static_cast<bool>(val));
        assert(*val == 42);
    }

    {
        // optional(T)
        std::optional val(B{});
        static_assert(std::is_same_v<decltype(val), std::optional<B>>, "");
        assert(static_cast<bool>(val));
    }

    // Test implicit deduction guides
    {
        // optional(const optional &);
        std::optional<double> original(3.14);
        std::optional val(original);
        static_assert(std::is_same_v<decltype(val), std::optional<double>>, "");
        assert(static_cast<bool>(val) == static_cast<bool>(original));
        assert(*val == *original);
    }
}

#include<ros/ros.h>
