ics::ICS3* controller {nullptr};
ros::Publisher publisher;

void handleCommand(const servo_msgs::IdBased::ConstPtr& input) {
  servo_msgs::IdBased response;
  try {
    response.angle = controller->move(input->id, ics::Angle::newDegree(input->angle));
    response.id = input->id;
    publisher.publish(response);
  } catch (std::runtime_error err) {
    ROS_INFO("Communication failure: %s", err.what());
  }
}

int main(int argc, char** argv) {
