  ros::NodeHandle private_nh {"~"};
  std::string device_path {"/dev/ttyUSB1"};
  private_nh.param<std::string>("serial_port", device_path, device_path);
  ROS_INFO("Initializing servo connection on: %s", device_path.c_str());
  ics::ICS3 ics_instance {std::move(device_path)};
  controller = &ics_instance;
  ros::NodeHandle public_nh {};
  ros::Subscriber cmd_sub {public_nh.subscribe("input_command", 50, handleCommand)};
  publisher = public_nh.advertise<servo_msgs::IdBased>("output_pose", 20);
  ros::spin();
  return 0;
}

#include "utils/GLFWApp.h"
#include <string>
#include "utils/Shader.h"

class SecondaryColorBlendTest : public GLFWApp {
    public:
        void Initialize(GLFWwindow*) override {
            const std::string vertexShaderSource =
                R"(in vec4 a_position;
                void main(){
                    gl_Position = a_position;
                })";
            const std::string fragmentShaderSource =
                R"(#version 100
                   #extension GL_EXT_blend_func_extended : require
                   precision highp float;
                   uniform vec4 primaryColor;
                   uniform vec4 secondaryColor;
                   void main() {
                       gl_FragData[0] = primaryColor;
                       gl_SecondaryFragDataEXT[0] = secondaryColor;
                   })";
            mShaderProgram = CompileProgram(vertexShaderSource, fragmentShaderSource);
            glClearColor(0.2f, 0.2f, 0.2f, 1.0f);
        }

        void RenderFrame() override {
            glViewport(0, 0, 800, 600);
            glClear(GL_COLOR_BUFFER_BIT);
            glClearColor(0.3f, 0.3f, 0.3f, 1.0f);

            glEnable(GL_BLEND);
            glBlendEquation(GL_FUNC_ADD);
            glBlendFuncSeparate(GL_SRC1_COLOR, GL_SRC_ALPHA, 
                               GL_ONE_MINUS_SRC1_COLOR, GL_ONE_MINUS_SRC1_ALPHA);

            glUseProgram(mShaderProgram);

            GLint colorLoc = glGetUniformLocation(mShaderProgram, "primaryColor");
            glUniform4f(colorLoc, 0.8f, 0.2f, 0.5f, 1.0f);

            GLint secColorLoc = glGetUniformLocation(mShaderProgram, "secondaryColor");
            glUniform4f(secColorLoc, 0.1f, 0.4f, 0.7f, 0.8f);

            GLfloat triVertices[] = {
                 0.0f,  0.6f, 0.0f,
                -0.6f, -0.6f, 0.0f,
                 0.6f, -0.6f, 0.0f,
            };

            glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 0, triVertices);
            glEnableVertexAttribArray(0);
            glDrawArrays(GL_TRIANGLES, 0, 3);
        }

        void Cleanup() override {
            // Cleanup resources if needed
        }

        GLuint mShaderProgram;
};

int main(int argc, const char** argv) {
    return GLFWApp::Run(new SecondaryColorBlendTest);
}

