class PacketManagerTests : public PelotonTest {
};

static void* RunServer(void *) {
    try {
        // Initialization phase
        peloton::PelotonInit::Initialize();
        LOG_INFO("Server started\n");

        // Start the server instance
        peloton::wire::LibeventServer libeventserver;
        LOG_INFO("Server stopped\n");

        // Cleanup phase
        // Todo: Peloton cannot shut down normally, will try to fix this soon
        //peloton::PelotonInit::Shutdown();
        LOG_INFO("Peloton shutdown completed\n");
    } catch (peloton::ConnectionException exception) {
        // Exception handling - no action required
    }
    return NULL;
}

static void* ExecuteSimpleQuery(void *) {
    try {
        pqxx::connection conn("host=127.0.0.1 port=15721 user=postgres sslmode=disable");
        LOG_INFO("Connected to database %s\n", conn.dbname());

        pqxx::transaction T(conn);

        // Setup test data
        T.exec("DROP TABLE IF EXISTS staff;");
        T.exec("CREATE TABLE staff(id INT, name VARCHAR(100));");
        T.exec("INSERT INTO staff VALUES (1, 'Ming ZHANG');");
        T.exec("INSERT INTO staff VALUES (2, 'Jie WANG');");
        T.exec("INSERT INTO staff VALUES (3, 'Xiao LI');");

        // Execute query and verify results
        pqxx::result res = T.exec("SELECT name FROM staff where id=1;");
        EXPECT_EQ(res.size(), 1);
        LOG_INFO("Retrieved %lu record(s)\n", res.size());

        T.commit();
    } catch (const std::exception &err) {
        LOG_INFO("Error occurred during execution\n");
    }

    LOG_INFO("Client disconnected\n");
    return NULL;
}

TEST_F(PacketManagerTests, SimpleQueryTest) {
    pthread_t threads[THREAD_COUNT];

    int status = pthread_create(&threads[0], NULL, RunServer, NULL);
    if (status != 0) {
        LOG_INFO("Failed to create server thread");
        exit(-1);
    }

    sleep(5);

    ExecuteSimpleQuery(NULL);

    pthread_kill(threads[0], SIGHUP);
    pthread_join(threads[0], NULL);
}

