BrowserNonClientFrameView* GenerateBrowserNonClientFrameView(
    BrowserFrame* window_frame, BrowserView* browser_controller) {
  Browser::Type window_type = browser_controller->browser()->type();
  switch (window_type) {
    case Browser::TYPE_PANEL:
      if (CommandLine::ForCurrentProcess()->HasSwitch(
              switches::kEnablePanels)) {
        return new PanelBrowserFrameView(
            window_frame, static_cast<PanelBrowserView*>(browser_controller));
      }  // otherwise, proceed to popup handling
    case Browser::TYPE_POPUP:
      // TODO(anicolao): implement popups for touch devices
      NOTIMPLEMENTED();
      return new PopupNonClientFrameView(window_frame);
    default:
      return new TouchBrowserFrameView(window_frame, browser_controller);
  }
}

