#include <cassert>
#include <cmath>
#include <limits>
#include <serializer.h>

// Test serialization and deserialization of double values
void validate_double(const double input_value) {
  Serializer serializer_instance;
  writer<decltype(+input_value)>::write(serializer_instance, input_value);
  const auto buffer_data = serializer_instance.data();
  Deserializer deserializer(serializer_instance.buffer, 
                            serializer_instance.buffer.size() - buffer_data.second);
  const auto recovered_value = reader<decltype(+input_value)>::read(deserializer);

  // Verify equality or both NaN
  assert(input_value == recovered_value || 
         (std::isnan(input_value) && std::isnan(recovered_value)));
}

int main() {
  // Test special values and edge cases
  validate_double(std::numeric_limits<double>::infinity());
  validate_double(-std::numeric_limits<double>::infinity());
  validate_double(std::numeric_limits<double>::quiet_NaN());
  validate_double(0.0);
  validate_double(-0.0);
  validate_double(1.0);
  validate_double(-1.0);
  validate_double(2.0);
  validate_double(-2.0);
  validate_double(M_PI);
  validate_double(-M_PI);
  validate_double(std::numeric_limits<double>::epsilon());
  validate_double(std::numeric_limits<double>::min());
  validate_double(std::numeric_limits<double>::max());
  validate_double(std::numeric_limits<double>::denorm_min());

  return 0;
}

