int delta::runClang(llvm::ArrayRef<const char*> argv) {
    auto* diagnosticClient = new clang::TextDiagnosticPrinter(llvm::errs(), new clang::DiagnosticOptions());
    diagnosticClient->setPrefix(llvm::sys::path::filename(argv[0]));
    clang::DiagnosticsEngine diagnosticsEngine(new clang::DiagnosticIDs(), nullptr, diagnosticClient);
    clang::driver::Driver driverInstance(argv[0], llvm::sys::getDefaultTargetTriple(), diagnosticsEngine);
    std::unique_ptr<clang::driver::Compilation> compilationPtr(driverInstance.BuildCompilation(argv));

    if (compilationPtr) {
        llvm::SmallVector<std::pair<int, const clang::driver::Command*>, 4> errorCommands;
        return driverInstance.ExecuteCompilation(*compilationPtr, errorCommands);
    }

    diagnosticsEngine.getClient()->finish();
    return 1;
}

