    pthread_t thread_id;
    const size_t stack_size = 2048 * 1024;
    void *stack_memory = malloc(stack_size);

    pthread_attr_t attributes;
    pthread_attr_init(&attributes);
    pthread_attr_setstack(&attributes, stack_memory, stack_size);

