#include "TwoLevelDetection.h"
#include <opencv2/imgproc/imgproc.hpp>

void TwoLevelDetection(const cv::Mat& src, cv::Mat& dst, double threshold1, double threshold2, TwoLevelDetectionTemp& buffer)
{
    if (threshold2 > threshold1) {
        throw std::runtime_error("TwoLevelDetection: it is required that measurementLevel <= detectionLevel");
    }

    cv::threshold(src, dst, threshold2, 1, cv::THRESH_BINARY);
    buffer.contours.clear();
    cv::findContours(dst, buffer.contours, cv::RETR_EXTERNAL, cv::CHAIN_APPROX_SIMPLE);

    buffer.mask.create(src.size(), CV_8UC1);
    dst.setTo(0);

    for (size_t idx = 0, limit = buffer.contours.size(); idx < limit; ++idx) {
        buffer.mask.setTo(0);
        cv::drawContours(buffer.mask, buffer.contours, static_cast<int>(idx), 255, -1);

        double minVal, maxVal;
        cv::minMaxIdx(src, &minVal, &maxVal, NULL, NULL, buffer.mask);

        if (maxVal >= threshold1) {
            dst.setTo(std::numeric_limits<unsigned char>::max(), buffer.mask);
        }
    }
}

