// Function to capture stack trace and exit with error
static void RecordBacktraceAndTerminate() {
  std::string buffer;
  google::glog_internal_namespace_::CaptureStackTraceAsString(&buffer);
  LOG(ERROR) << "BACKTRACE:\n" << buffer;
  abort();
}

