#include "executor_metrics.h"
namespace proton {
void
ExecutorMetrics::refresh(const vespalib::ThreadStackExecutorBase::Stats &data)
{
    peakPending.set(data.queueSize.max());
    incoming.inc(data.acceptedTasks);
    dropped.inc(data.rejectedTasks);
    const auto & stats = data.queueSize;
    queueLength.addBatch(stats.average(), stats.count(), stats.min(), stats.max());
}
ExecutorMetrics::ExecutorMetrics(const std::string &label, metrics::MetricSet *owner)
    : metrics::MetricSet(label, {}, "Per-instance thread executor statistics", owner),
      peakPending("peakpending", {}, "Peak count of pending (active + queued) tasks", this),
      incoming("incoming", {}, "Total number of accepted tasks", this),
      dropped("dropped", {}, "Total number of rejected tasks", this),
      queueLength("queuesize", {}, "Task queue length distribution", this)
{
}
ExecutorMetrics::~ExecutorMetrics() = default;
} // namespace proton

