namespace py = pybind11;

void InitializeDeviceModule(pybind11::module& module) {
    py::class_<Device>(module, "Device")
        .def(py::init(&CreateDevice))
        .def("__eq__", py::overload_cast<const Device&, const Device&>(&AreEqual))
        .def("__ne__", py::overload_cast<const Device&, const Device&>(&AreNotEqual))
        .def("__repr__",
             [](Device dev) {
                 std::ostringstream stream;
                 stream << "<Device " << dev.name << ">";
                 return stream.str();
             });

    module.def("get_active_device", []() { return GetActiveDevice(); });
    module.def("set_active_device", [](const Device& dev) { SetActiveDevice(dev); });
    module.def("set_active_device", [](const std::string& device_name) { SetActiveDevice(device_name); });
}
}  // namespace xchainer

