// Fuzzer entry point: processes input data as image
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *inputData, size_t inputDataSize) {
  // Create blob from input data
  const Magick::Blob inputBlob(inputData, inputDataSize);

  // Initialize image object and set encoding format
  Magick::Image processedImage;
  processedImage.magick(FUZZ_ENCODER);
  processedImage.fileName(std::string(FUZZ_ENCODER) + ":");

  // Attempt to read the image from blob
  try {
    processedImage.read(inputBlob);
  }
  catch (Magick::Exception &error) {
    return 0;  // Gracefully handle read errors
  }

  // Prepare output blob for writing
  Magick::Blob resultBlob;
  try {
    processedImage.write(&resultBlob, FUZZ_ENCODER);
  }
  catch (Magick::Exception &error) {
    // Silently ignore write errors during fuzzing
  }

  return 0;  // Always return 0 for fuzzer compatibility
}

