typedef vector <string> vs;

int convertToInt(string val) {
    stringstream converter(val);
    int result;
    converter >> result;
    return result;
}

string convertToString(double value) {
    stringstream stream;
    stream << fixed << setprecision(10) << value;
    string str = stream.str();
    return str;
}

vs tokenize(string text, char delimiter) {
    vector < string > tokens;
    stringstream ss(text);
    string token;
    while (getline(ss, token, delimiter)) {
        tokens.pb(token);
    }
    return tokens;
}

int main() {
    vs dateParts = tokenize("1990/10/5", '/');
