void ShutdownManager::doAtShutdown(std::function<void()> callback)
{
    std::lock_guard<std::mutex> guard(getInstance()._shutdownMutex);
    getInstance()._callbacks.emplace_front(std::move(callback));
}

// Execute all registered shutdown handlers and clear them
void ShutdownManager::performShutdown()
{
    std::lock_guard<std::mutex> guard(getInstance()._shutdownMutex);
    // ThreadPool::suspend();
    getInstance()._isShuttingDown = true;
    for (const auto& handler : getInstance()._callbacks)
    {
        handler();
    }
    getInstance()._callbacks.clear();
    // ThreadPool::resume();
}

