// Prevent symbol stripping by referencing V8 profiler and inspector APIs
void ReferenceSymbols() {
  // These symbols are referenced to avoid removal during linking,
  // as they are used by electron.exe but may be incorrectly optimized away.
  v8::TracingCpuProfiler::Create(nullptr);

  // Safely call methods on null pointers just to force symbol inclusion
  reinterpret_cast<v8_inspector::V8InspectorSession*>(nullptr)->
      canDispatchMethod(v8_inspector::StringView());

