#include <boost/asio/io_service.hpp>
using boost::asio::ip::tcp;

BoostTransport::BoostTransport()
    : service_(),
      connection_(service_)
{
}

BoostTransport::~BoostTransport()
{
    connection_.close();
}

void
BoostTransport::EstablishConnection(std::string host, short port_number)
{
    tcp::resolver resolver(service_);
    auto endpoints = resolver.resolve({host, std::to_string(port_number)});
    try
    {
        boost::asio::connect(connection_, endpoints);
    }
    catch (const boost::system::system_error& err)
    {
        LOG(LogLevel::Warning) << "Failed to connect to " << host << ":" << port_number;
    }
}

void
BoostTransport::SendData(std::string message)
{
    try
    {
        boost::asio::write(connection_, boost::asio::buffer(message.c_str(), message.length()));
    }
    catch (const boost::system::system_error& exception)
    {
        LOG(LogLevel::Warning) << "Unable to send data over transport";
    }
}

