#include <iostream>
#include <cvd/connected_components.h>
#include <cvd/image.h>
using namespace std;
using namespace CVD;

int main() {
    // Iterate through all 9-bit patterns (0 to 511)
    for(int pattern = 0; pattern < (1 << 9); pattern++) {
        cout << "------------------------\n" << pattern << endl;

        int temp = pattern;
        vector<ImageRef> points;

        // Extract pixel positions from the bit pattern
        for(int row = 0; row < 3; row++) {
            for(int col = 0; col < 3; col++) {
                if(temp & 1) {
                    points.push_back(ImageRef(col, row));
                }
                temp >>= 1;
            }
        }

        // Find connected components
        vector<vector<ImageRef> > components;
        connected_components(points, components);

        // Create output image initialized with '.'
        Image<char> resultImage(ImageRef(3, 3), '.');

        // Label each component with uppercase letters starting from 'A'
        for(unsigned int compIdx = 0; compIdx < components.size(); compIdx++) {
            for(unsigned int ptIdx = 0; ptIdx < components[compIdx].size(); ptIdx++) {
                resultImage[components[compIdx][ptIdx]] = 'A' + compIdx;
            }
        }

        cout << "Created " << components.size() << " groups\n";

        // Print the 3x3 grid row by row
        cout.write(resultImage.data(), 3);
        cout << endl;
        cout.write(resultImage.data() + 3, 3);
        cout << endl;
        cout.write(resultImage.data() + 6, 3);
        cout << endl;
        cout << endl;

        cin.get();
    }

    return 0;
}

