struct Data {
  Data(int val) : value(val), unused(0) {}
  int value;
  int unused;
};

// Here Data is passed to ProcessData as a 64-bit integer.
// This triggers an optimization where 5000 * d.value is transformed into
// ((*(uint64_t *)&d) * (5000 * 2**32)) >> 32
// Test that MSan understands that this kills the uninitialized part of Data
// (i.e. Data::unused).
void ProcessData(Data d) {
  int64_t result = 5000 * d.value;
  __msan_check_mem_is_initialized(&result, sizeof(result));
}

int main(void) {
  Data obj(1);
  // Take &obj to ensure that it is allocated on the stack.
  Data *volatile ptr = &obj;
  ProcessData(obj);
  return 0;
}

