namespace base {

void safe_strerror_r(int error_code, char* buffer, size_t buffer_size) {
#if defined(__GLIBC__) || \
   (defined(OS_ANDROID) && defined(_GNU_SOURCE) && __ANDROID_API__ >= 23)
  char* result = strerror_r(error_code, buffer, buffer_size);
  if (result != buffer) {
    snprintf(buffer, buffer_size, "%s", result);
  }
#else
  int return_value = strerror_r(error_code, buffer, buffer_size);
  if (return_value != 0) {
    snprintf(buffer,
             buffer_size,
             "Error %d while retrieving error %d",
             return_value > 0 ? return_value : errno,
             error_code);
  }
#endif
}

std::string safe_strerror(int error_code) {
  char temp_buffer[256];
  safe_strerror_r(error_code, temp_buffer, size(temp_buffer));
  return std::string(temp_buffer);
}

}  // namespace base

