#include <iostream>
#include <sqlite3.h>
#include <string>
#include <vector>
using namespace std;

// Constructor: open database with given filename
Database::Database(string dbPath) {
  char pathBuffer[100];
  strcpy(pathBuffer, dbPath.c_str());
  sqlite3_open(pathBuffer, &connection);
}

// Destructor: close database connection
Database::~Database() { sqlite3_close(connection); }

// Callback function for sqlite3_exec to process query results
int resultHandler(void *output, int fieldCount, char **values, char **) {
  vector<vector<string>> &resultSet =
      *(static_cast<vector<vector<string>> *>(output));
  vector<string> record;

  for (int index = 0; index < fieldCount; index++) {
    string fieldValue = values[index] ? values[index] : "NULL";
    record.push_back(fieldValue);
    cout << values[index] << ", ";
  }

  resultSet.push_back(record);
  return 0;
}

// Execute SQL command and return results as 2D vector of strings
vector<vector<string>> Database::run(string sqlQuery) const {
  cout << "Executing SQL: " << sqlQuery << endl;
  cout << "Data: ";

  vector<vector<string>> queryResults;
  char *errorMessage;

  int executionStatus = sqlite3_exec(
      connection,           /* Open database handle */
      sqlQuery.c_str(),     /* SQL statement to execute */
      resultHandler,        /* Callback function for each row */
      &queryResults,        /* First argument passed to callback */
      &errorMessage         /* Error message output parameter */
  );

  cout << endl;
  cout << "DB status: " << executionStatus;

  if (errorMessage) {
    cout << ", Error: " << errorMessage;
    sqlite3_free(errorMessage);
  }

  cout << endl;
  return queryResults;
}

