using namespace clang;

OpenMPDirectiveKind clang::getOpenMPDirectiveKind(llvm::StringRef Text) {
  return llvm::StringSwitch<OpenMPDirectiveKind>(Text)
#define OPENMP_DIRECTIVE(Name) \
           .Case(#Name, OMPD_##Name)
#include "clang/Basic/OpenMPKinds.def"
           .Default(OMPD_unknown);
}

const char *clang::getOpenMPDirectiveName(OpenMPDirectiveKind Directive) {
  assert(Directive < NUM_OPENMP_DIRECTIVES);
  switch (Directive) {
  case OMPD_unknown:
    return ("unknown");
#define OPENMP_DIRECTIVE(Name) \
  case OMPD_##Name : return #Name;
#include "clang/Basic/OpenMPKinds.def"
  default:
    break;
  }
  llvm_unreachable("Invalid OpenMP directive kind");
}

