void display_usage() noexcept {
    std::cout << "usage: shinobi [options] [--] [filename]\n\n";
    std::cout << std::left << '\t' << std::setw(25) << "-h, --help"   << "display this help message and exit" << '\n';
    std::cout << std::left << '\t' << std::setw(25) << "-d, --debug"  << "generate debug ninja file"        << '\n';
    std::cout << std::left << '\t' << std::setw(25) << "-r, --release"<< "generate release ninja file (default)" << '\n';
}

int main(int argc, char* argv[]) {
    std::string output_file("build.ninja");
    std::map<std::string, int> arguments;

    for(int index = 0; index < argc; ++index) {
        arguments.emplace(argv[index], index);
    }

    if(arguments.count("-h") || arguments.count("--help")) {
        display_usage();
        return 0;
    }

    auto iter = arguments.find("--");

    if(iter != arguments.end()) {
        if(argv[iter->second + 1] != nullptr) {
            output_file = std::string(argv[iter->second + 1]) + ".ninja";
        }
    }

    std::ofstream out(output_file);
    util::maker generator{out};

    if(arguments.count("-d") || arguments.count("--debug")) {
        generator.set_debug(true);
    }

    if(arguments.count("-r") || arguments.count("--release")) {
        generator.set_debug(false);
    }

    generator.perform_regular_parsing();
}

