    // Format current time into a string buffer
    void string_fmt_time(std::string& output) {
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        while(!strftime(&output[0], output.capacity(), "%Y:%m:%d %H:%M", time_info))
            output.reserve(output.empty() ? 16 : output.capacity() << 1);
