ics::ICS3* controller {nullptr};
ros::Publisher publisher;

void handleCommand(const servo_msgs::IdBased::ConstPtr& request) {
  servo_msgs::IdBased response;
  response.id = request->id;
  try {
    response.angle = controller->move(request->id, ics::Angle::newDegree(request->angle));
    publisher.publish(response);
  } catch (const std::runtime_error& error) {
    ROS_WARN("Communication failure: %s", error.what());
  }
}

int main(int argc, char** argv) {
  ros::init(argc, argv, "servo_krs_node");
  ros::NodeHandle private_nh {"~"};
  std::string serial_port {"/dev/ttyUSB0"};
  private_nh.param<std::string>("serial_port", serial_port, serial_port);

  ics::ICS3 ics_controller {std::move(serial_port)};
  controller = &ics_controller;

  ros::NodeHandle node {};
  ros::Subscriber subscriber {node.subscribe("cmd_krs", 100, handleCommand)};
  publisher = node.advertise<servo_msgs::IdBased>("pose_krs", 10);

  ros::spin();
  return 0;
}

