// Control methods for the elevator mechanism
// These should be invoked from command classes
void ElevatorSubsystem::MoveElevator(float speed){
	// Prevent motion when lower limit is engaged and moving down
	// or when upper limit is engaged and moving up
	if(!(lowerLimitSwitch.Get() && speed > 0) && !(upperLimitSwitch.Get() && speed < 0)){
		motorLeft.Set(speed);
		motorRight.Set(speed);
	}
