/**
 * Definition for a binary tree node.
 */
struct TreeNode {
    int value;
    TreeNode *leftChild;
    TreeNode *rightChild;
    TreeNode(int x) : value(x), leftChild(NULL), rightChild(NULL) {}
};

class BinarySearchTreeValidator {
public:
    bool validateBST(TreeNode* node, int lowerBound, int upperBound)
    {
        if (node == NULL) {
            return true;
        }

        return (node->value > lowerBound &&
                node->value < upperBound &&
                validateBST(node->leftChild, lowerBound, node->value) &&
                validateBST(node->rightChild, node->value, upperBound));
    }

    bool isValidBST(TreeNode* root) {
        return validateBST(root, INT_MIN, INT_MAX);
    }
};

