namespace keron {
namespace server {

std::atomic_int shutdown_flag(0);

static BOOL signal_handler(DWORD control_type)
{
    switch (control_type) {
        case CTRL_C_EVENT:
        case CTRL_CLOSE_EVENT:
            std::cout << "The server is shutting down!" << std::endl;
            shutdown_flag.store(1);
            return TRUE;

        case CTRL_BREAK_EVENT:
        case CTRL_LOGOFF_EVENT:
        case CTRL_SHUTDOWN_EVENT:
            std::cout << "The server is shutting down!" << std::endl;
            shutdown_flag.store(1);
            // Fall through to default behavior

        default:
            return FALSE;
    }
}

int install_signal_handlers()
{
    return SetConsoleCtrlHandler((PHANDLER_ROUTINE)signal_handler, TRUE) == TRUE;
}

