// Add a message to the queue if there's enough space, otherwise log and drop
void enqueueIfSpace(QUEUE_TYPE(uint8_t)* buffer, uint8_t* data,
        int dataLength) {
    if(queue_available(buffer) < dataLength + 2) {
        debug("Dropped incoming CAN message -- send buffer (at %p) full\r\n",
                buffer);
        return;
    }
    for(int index = 0; index < dataLength; index++) {
        QUEUE_PUSH(uint8_t, buffer, (uint8_t)data[index]);
    }
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\r');
    QUEUE_PUSH(uint8_t, buffer, (uint8_t)'\n');
}

// Send a message via USB if available, otherwise use serial
void transmitMessage(Listener* handler, uint8_t* payload, int payloadSize) {
    if(handler->usb->configured) {
        enqueueIfSpace(&handler->usb->sendQueue, payload, payloadSize);
    } else {
        enqueueIfSpace(&handler->serial->sendQueue, payload, payloadSize);
    }
}

// Handle input from both USB and serial queues
void handleListenerBuffers(Listener* handler) {
    // Always process USB first, as it includes essential MCU USB tasks
    processInputQueue(handler->usb);
    if(!handler->usb->configured) {
        processInputQueue(handler->serial);
    }
}

