#include "buffers.h"
#include "strutil.h"
#include "log.h"

// Process incoming data queue with validation checks
void handleIncomingQueue(ByteQueue* inputBuffer, bool (*handler)(uint8_t*)) {
    uint8_t bufferCopy[QUEUE_MAX_LENGTH(uint8_t)];
    queue_snapshot(inputBuffer, bufferCopy);

    if(handler == NULL) {
        debug("Handler function pointer is NULL (%p) -- cannot process queue at %p\r\n",
                handler, inputBuffer);
        return;
    }

    if(handler(bufferCopy)) {
        queue_init(inputBuffer);
    } else if(queue_full(inputBuffer)) {
        debug("Data packet exceeds maximum length\r\n");
        queue_init(inputBuffer);
    } else if(strnchr((char*)bufferCopy, queue_length(inputBuffer), '\0') != NULL) {
        debug("Buffered data stream integrity check failed -- flushing buffer\r\n");
        queue_init(inputBuffer);
    }
}

