namespace capu
{
    Mutex ConsoleLogAppender::m_logMutex;

    ConsoleLogAppender::~ConsoleLogAppender()
    {
    }

    void ConsoleLogAppender::logMessage(const LogMessage& message)
    {
        ScopedMutexLock guard(m_logMutex);
        const uint64_t currentTime = Time::GetMilliseconds();
        Console::Print(Console::WHITE, "%.3f ", currentTime / 1000.0);

        switch(message.getLogLevel())
        {
        case LL_TRACE:
            Console::Print(Console::WHITE, "[  Trace  ] ");
            break;
        default:
        case LL_DEBUG :
            Console::Print(Console::WHITE, "[  Debug  ] ");
            break;
        case LL_INFO :
            Console::Print(Console::GREEN, "[  Info   ] ");
            break;
        case LL_WARN :
            Console::Print(Console::YELLOW, "[  Warn   ] ");
            break;
        case LL_ERROR :
            Console::Print(Console::RED, "[  Error  ] ");
            break;
        case LL_FATAL :
            Console::Print(Console::RED, "[  Fatal  ] ");
            break;
        }

        Console::Print(Console::AQUA, message.getContext().getContextName().c_str());
        Console::Print(" | %s\n", message.getLogMessage());
        Console::Flush();
    }
}

