#include <iostream>
#include <cmath>
using namespace std;

class Vector2D {
  double posX;
  double posY;
public:
  double getX() {
    return posX;
  }
  double getY() {
    return posY;
  }
  void setX(double newX) {
    posX = newX;
  }
  void setY(double newY) {
    posY = newY;
  }
  void shift(double deltaX, double deltaY) {
    setX(getX() + deltaX);
    setY(getY() + deltaY);
  }
  double distanceFrom(Vector2D other) {
    return sqrt(pow(getX() - other.getX(), 2) + pow(getY() - other.getY(), 2));
  }
  void display() {
    cout << '(' << getX() << ", " << getY() << ')' << '\n';
  }
};

void runShiftTest() {
  Vector2D location;
  location.setX(3);
  location.setY(5);
  location.shift(2, 3);
  location.display();
}

void runDistanceTest() {
  Vector2D firstLocation;
  firstLocation.setX(3);
  firstLocation.setY(5);
  Vector2D secondLocation;
  secondLocation.setX(4);
  secondLocation.setY(1);
  cout << firstLocation.distanceFrom(secondLocation) << '\n';
}

int main() {
  runShiftTest();
  runDistanceTest();
  return 0;
}

