#include <iostream>
#include "sudoku.h"

int main(int argc, char* argv[])
{
	// Solve the world's hardest sudoku puzzle 
	// Reference: http://www.mirror.co.uk/news/weird-news/worlds-hardest-sudoku-can-you-242294 
	std::string puzzleData = "005300000800000020070010500400005300010070006003200080060500009004000030000009700";
	Sudoku board;

	for(int index = 0; index < puzzleData.length(); ++index) {
		if(puzzleData[index] != '0') {
			board.setValue(index, puzzleData[index] - '0');
		}
	}

	std::cout << board << std::endl;
	Sudoku::solve(board);
	std::cout << board << std::endl;

	return 0;
}

