  // Determine the directory containing the executable using argv[0]
  char *execDir = dirname(argv[0]);
  chdir(execDir);

  // Load configuration from the INI file
  std::string configPath("lib/Rel.ini");
  std::ifstream configFile(configPath);
  std::string content((std::istreambuf_iterator<char>(configFile)), std::istreambuf_iterator<char>());

  // Handle missing or empty configuration file
  if (content.empty()) {
    std::cerr << ("Configuration file not found or corrupted: " + configPath).c_str() << std::endl;
    return 10;
  }

  // Append command-line arguments to the command string
  std::string additionalArgs("");
  for (int idx = 1; idx < argc; ++idx)
    additionalArgs += std::string(" \"") + std::string(argv[idx]) + std::string("\"");

  // Disable GTK3 support for SWT
  setenv("SWT_GTK3", "0", 1);

  // Execute the command read from the config file with appended arguments
  return system((content + additionalArgs).c_str());
}

