#include <vector>
#include <unordered_set>
#include <algorithm>
#include <string>

class Solution {
public:
    bool closeStrings(std::string str1, std::string str2) {
        std::vector<int> freq1(26, 0), freq2(26, 0);
        std::unordered_set<char> set1, set2;

        for (char ch : str1) {
            freq1[ch - 'a']++;
            set1.insert(ch);
        }

        for (char ch : str2) {
            freq2[ch - 'a']++;
            set2.insert(ch);
        }

        std::sort(freq1.begin(), freq1.end());
        std::sort(freq2.begin(), freq2.end());

        return set1 == set2 && freq1 == freq2;
    }
};

