namespace jsonv_test
{
using namespace jsonv;
using string_array = std::vector<std::string>;

template <typename FJsonCompare, typename FStrCompare>
static void verify_sorted(const formats& fmts, string_array input, FJsonCompare json_comp, FStrCompare str_comp)
{
    value original = to_json(input, fmts);
    if (input != extract<string_array>(original, fmts))
        throw std::logic_error("Extraction or encoding mechanism is faulty");

    std::sort(input.begin(),      input.end(),      str_comp);
    std::sort(original.begin_array(), original.end_array(), json_comp);

    if (input != extract<string_array>(original, fmts))
        throw std::logic_error("Sorting operations yielded inconsistent results");
}

TEST(functional_sort_strings)
{
    formats fmts =
        formats::compose
        ({
            formats_builder()
                .register_container<std::vector<std::string>>(),
            formats::defaults()
        });
    std::vector<std::string> test_data = { "fire", "wind", "water", "earth", "heart" };

    verify_sorted(fmts, test_data, value_less(),          std::less<std::string>());
    verify_sorted(fmts, test_data, value_less_equal(),    std::less_equal<std::string>());
    verify_sorted(fmts, test_data, value_greater(),       std::greater<std::string>());
    verify_sorted(fmts, test_data, value_greater_equal(), std::greater_equal<std::string>());
}
}

