using namespace clt::filesystem::operations;

void ExecutableLauncherUnix::execute(const entities::Path & filePath)
{
    pid_t childPid;

    childPid = fork();

    switch (childPid) {
        case -1: 
            perror("fork");
            break;

        case 0:
            execl(filePath.getValue().c_str(), filePath.getValue().c_str(), NULL, NULL); /* this is the child process */
            _exit(EXIT_FAILURE);
            break;

        default: 
            waitpid(childPid, NULL, 0);
            break;
    }
}

