// Convert cycle count between different clock frequencies
UInt64 convertCycleCount(UInt64 input_cycles, volatile float source_freq, volatile float target_freq)
{
   UInt64 result = (UInt64) ceil(((double) input_cycles) * (target_freq / source_freq));
   LOG_PRINT("convertCycleCount(%llu): source_freq(%f), target_freq(%f) -> (%llu)",
             input_cycles, source_freq, target_freq, result);
   return result;
}

