// Writes data to file using a const reference to span
template <typename T>
void output_data_const_ref(gsl::span<T> const& data, std::string const& path)
{
    std::ofstream out_file(path);
    std::copy(std::begin(data), std::end(data),
              std::ostream_iterator<T>(out_file, "\n"));
}

// Writes data to file by copying the span parameter
template <typename T>
void output_data_by_copy(gsl::span<T> const data, std::string const& path)
{
    std::ofstream out_file(path);
    std::copy(std::begin(data), std::end(data),
              std::ostream_iterator<T>(out_file, "\n"));
}

int main()
{
    std::vector<int> numbers {10, 20, 30, 40, 50};
    output_data_const_ref(gsl::make_span(numbers), "output_ref.txt");
    output_data_by_copy(gsl::make_span(numbers), "output_copy.txt");
}

