// Check if any element in the collection satisfies the given predicate
template <typename T>
bool contains_matching(const std::vector<T>& collection,
                      boost::function<bool(const T&)> pred)
{
    return std::find_if(collection.begin(), collection.end(),
                        boost::bind(pred, _1)) != collection.end();
}

