// LED flashing state machine implementation
Atm_ledFlash & Atm_ledFlash::init(int pin_number, uint32_t interval_ms) {
  const static state_t states[] PROGMEM = {
    /*            ON_ENTER    ON_LOOP  ON_EXIT  EVT_TICK   ELSE */
    /* ACTIVE  */   ACT_HIGH,       -1,      -1,   ACT_LOW,    -1,
    /* INACTIVE*/  ACT_LOW,        -1,      -1,   ACT_HIGH,   -1 };

  Machine::init(states, ELSE);
  ledPin = pin_number;
  tickTimer.init(this, interval_ms);
  pinMode(ledPin, OUTPUT);
  return *this;
}

int Atm_ledFlash::handleEvent(int eventId) {
  switch (eventId) {
    case EVT_TICK:
      return tickTimer.isExpired();
  }
  return 0;
}

void Atm_ledFlash::performAction(int actionId) {
  switch (actionId) {
    case ACT_HIGH:
      digitalWrite(ledPin, HIGH);
      return;
    case ACT_LOW:
      digitalWrite(ledPin, LOW);
      return;
  }
}

Atm_ledFlash & Atm_ledFlash::registerSwitchCallback(swcb_sym_t callbackFn) {
  Machine::registerSwitchCallback(callbackFn, "LED_ACTIVE\0LED_INACTIVE", "EVT_TICK\0ELSE");
  return *this;
}

