#include <stdio.h>

// Compute the greatest common divisor using Euclidean algorithm
int compute_gcd(const int a, const int b)
{
    /* Ensure larger number is first */
    if (a < b) return compute_gcd(b, a); /* Swap arguments so that second is smaller */
    if (a % b == 0) return b; /* Base case: b divides a exactly, so b is GCD */
    /* Recursive step: apply Euclidean algorithm */
    return compute_gcd(b, a % b);
}

int main(void)
{
    int value1, value2;
    printf("Enter first number: "); scanf("%d", &value1);
    printf("Enter second number: "); scanf("%d", &value2);
    printf("GCD result: %d\n", compute_gcd(value1, value2));
    return 0;
}

