namespace {
class AndroidFileHandle
{
public:
    AndroidFileHandle(const std::string& filePath):
        m_filePath(filePath),
        m_asset(nullptr)
    {
        m_asset = AAssetManager_open(yarrar::android::getAssetManager(), m_filePath.c_str(), AASSET_MODE_BUFFER);
        if(!m_asset)
        {            
            throw std::runtime_error(std::string("unable to open file: ") + m_filePath);
        }
    }

    ~AndroidFileHandle()
    {
        AAsset_close(m_asset);
    }

    void loadData(std::string& outData)
    {
        if(!m_asset)
        {
            throw std::runtime_error(std::string("asset is invalid: ") + m_filePath);
        }

        size_t fileSize = AAsset_getLength(m_asset);
        outData.clear();
        outData.resize(fileSize);

        int bytesRead = AAsset_read(m_asset, &outData[0], fileSize);
        if(bytesRead <= 0)
        {
            throw std::runtime_error(std::string("error reading from file: ") + m_filePath);
        }
    }

private:
    std::string m_filePath;
    AAsset* m_asset;
};
}

