/* The Queue data structure
 * Public interface:
 * enqueue()
 * dequeue()
 * size()
 * clear()
 * begin()
 * end() : one pass the last item
 * empty()
 */
class QueueTest : public testing::Test {
 protected:
  // SetUp() & TearDown() are virtual functions from testing::Test,
  // so we just indicate that we override them here
  virtual void SetUp() {
    queueA_.enqueue(1);
    queueA_.enqueue(2);
    queueB_.enqueue(1);
    queueB_.enqueue(3);
  }
  virtual void TearDown() {
  }
  // setup fixtures
  Queue<int> emptyQueue_;
  Queue<int> queueA_;
  Queue<int> queueB_;
};
// Use TEST_F to test with fixtures.
TEST_F(QueueTest, DefaultConstructor) {
  EXPECT_EQ(0u, emptyQueue_.size());
}
TEST_F(QueueTest, enqueue){
  EXPECT_EQ(2u, queueA_.size());
  EXPECT_EQ(2u, queueB_.size());
  queueB_.enqueue(200);
  EXPECT_EQ(3u, queueB_.size());
}
TEST_F(QueueTest, clear) {
  queueA_.clear();
  EXPECT_TRUE(queueA_.empty());
}
TEST_F(QueueTest, dequeue) {
  int* removedItem = queueB_.dequeue();
  EXPECT_EQ(*removedItem, 1);
  EXPECT_EQ(queueB_.size(), 1);
  delete removedItem;
  removedItem = queueB_.dequeue();
  EXPECT_EQ(*removedItem, 3);
  EXPECT_TRUE(queueB_.empty());
  // queueB_ should be empty now. check it:
  delete removedItem;
  removedItem = queueB_.dequeue();
  EXPECT_EQ(nullptr, removedItem);
}

