namespace std {
class exception {};
} // namespace std

class custom_exception : public std::exception {};
class standalone_exception {};

void risky_function() {
  try {
    throw double(3.14); // Built-in type is not permitted
// CHECK-MESSAGES: [[@LINE-1]]:5: warning: throwing an exception whose type is not derived from 'std::exception'
  } catch (double e) {
  }
  throw double(2.71); // Invalid
// CHECK-MESSAGES: [[@LINE-1]]:3: warning: throwing an exception whose type is not derived from 'std::exception'
  try {
    throw standalone_exception(); // User-defined class not allowed
// CHECK-MESSAGES: [[@LINE-1]]:5: warning: throwing an exception whose type is not derived from 'std::exception'
// CHECK-MESSAGES: 9:1: note: type defined here
  } catch (standalone_exception &e) {
  }
  throw standalone_exception(); // Not allowed
// CHECK-MESSAGES: [[@LINE-1]]:3: warning: throwing an exception whose type is not derived from 'std::exception'
// CHECK-MESSAGES: 9:1: note: type defined here
}

void safe_throws() {
  try {
    throw std::exception(); // Acceptable
  } catch (std::exception &e) { // Acceptable
  }
  throw std::exception();
  try {
    throw custom_exception(); // Acceptable
  } catch (custom_exception &e) { // Acceptable
  }
  throw custom_exception(); // Acceptable
}

