#include "math_container.h"
using std::complex;

/******************************************************/
/*solve the equation cosh(x)=exp(y), input y, return x*/
/******************************************************/
complex<double> solve_coshx_eq_expy(double input_y)
{
    complex<double> exp_val{exp(input_y), 0.0};
    complex<double> result = log(exp_val - sqrt(exp_val * exp_val - 1.0));

    // Adjust result to be purely real or purely imaginary
    if (abs(result.real()) < abs(result.imag())) {
        result = complex<double>(0.0, result.imag());
    } else {
        result = complex<double>(result.real(), 0.0);
    }

    return result;
}

