#include<iostream>
using namespace std;

class TreeNode {
public:
    int value;
    TreeNode *leftChild, *rightChild;

    TreeNode() {}

    TreeNode(int val) {
        value = val;
        leftChild = NULL;
        rightChild = NULL;
    }

    TreeNode* addNode(TreeNode* currentRoot, int val) {
        if (!currentRoot)
            return new TreeNode(val);

        if (val <= currentRoot->value)
            currentRoot->leftChild = addNode(currentRoot->leftChild, val);
        else
            currentRoot->rightChild = addNode(currentRoot->rightChild, val);

        return currentRoot;
    }

    void displayInorder(TreeNode* currentRoot) {
        if (currentRoot) {
            if (currentRoot->leftChild)
                displayInorder(currentRoot->leftChild);

            cout << currentRoot->value << "\n";

            if (currentRoot->rightChild)
                displayInorder(currentRoot->rightChild);
        }
    }
};

int main() {
    int count, inputValue;
    TreeNode treeObj;
    TreeNode* root = NULL;

    cout << "Enter the number of elements in the tree: ";
    cin >> count;

    for (int index = 0; index < count; index++) {
        cout << "\nEnter the element " << index + 1 << " of the tree: ";
        cin >> inputValue;
        root = treeObj.addNode(root, inputValue);
    }

    cout << "\nInorder traversal of the tree gives:\n";
    treeObj.displayInorder(root);

    return 0;
}

