using namespace std;

// Shell sort implementation for array sorting
int shellSort(int data[], int size)
{
    for (int gap = size / 2; gap > 0; gap /= 2)
    {
        for (int index = gap; index < size; index++)
        {
            int temp = data[index];
            int position;
            for (position = index; (position >= gap) && (data[position - gap] > temp); position -= gap)
                data[position] = data[position - gap];
            data[position] = temp;
        }
    }
    return 0;
}

int main()
{
    int length, buffer[10000];
    cin >> length;
    for (int k = 0; k < length; k++)
        cin >> buffer[k];
    shellSort(buffer, length);
    cout << "Array after sorting: \n";
    for (int k = 0; k < length; k++)
        cout << buffer[k] << " ";
    cout << endl;
    return 0;
}

