// Comprehensive test for sepia effect on valid input
TEST(photoeffects, SepiaTest) {
    Mat input(10, 10, CV_8UC1), result, hsvResult;
    vector<Mat> channels(3);

    EXPECT_EQ(0, sepia(input, result));

    cvtColor(result, hsvResult, CV_BGR2HSV);
    split(hsvResult, channels);

    // Check hue value around 19 degrees (±1 tolerance)
    EXPECT_LE(19 - 1, channels[0].at<uchar>(0, 0));
    EXPECT_GE(19 + 1, channels[0].at<uchar>(0, 0));

    // Check saturation value around 78 (±1 tolerance)
    EXPECT_LE(78 - 1, channels[1].at<uchar>(0, 0));
    EXPECT_GE(78 + 1, channels[1].at<uchar>(0, 0));

    // Check brightness value: original + 20 (±1 tolerance)
    EXPECT_LE(input.at<uchar>(0, 0) + 20 - 1, channels[2].at<uchar>(0, 0));
    EXPECT_GE(input.at<uchar>(0, 0) + 20 + 1, channels[2].at<uchar>(0, 0));
}

