int main() {
    int num1, num2, result, choice;

    printf("Select an operation:\n");
    printf("1. Addition of two numbers\n");
    printf("2. Subtraction of two numbers\n");
    printf("3. Multiplication of two numbers\n");
    printf("4. Square of a number\n");
    printf("5. Cube of a number\n");
    scanf("%d", &choice);

    switch(choice) {
        case 1:
            printf("Enter two numbers: ");
            scanf("%d %d", &num1, &num2);
            result = num1 + num2;
            printf("Sum of two numbers = %d\n", result);
            break;

        case 2:
            printf("Enter two numbers: ");
            scanf("%d %d", &num1, &num2);
            result = num1 - num2;
            printf("Difference of two numbers = %d\n", result);
            break;

        case 3:
            printf("Enter two numbers: ");
            scanf("%d %d", &num1, &num2);
            result = num1 * num2;
            printf("Product of two numbers = %d\n", result);
            break;

        case 4:
            printf("Enter a number: ");
            scanf("%d", &num1);
            result = num1 * num1;
            printf("Square of the number = %d\n", result);
            break;

        case 5:
            printf("Enter a number: ");
            scanf("%d", &num1);
            result = num1 * num1 * num1;
            printf("Cube of the number = %d\n", result);
            break;

        default:
            printf("Invalid choice!\n");
            break;
    }

    char continueChoice;
    printf("Do you want to continue? (y/n): ");
    scanf(" %c", &continueChoice);

    if(continueChoice == 'y' || continueChoice == 'Y') {
        // Recursively call main or use a loop - here we'll just end
        // For a true clone with loop, we'd need restructuring
        return main(); // This is not standard C but shows intent
    } else {
        printf("Thank you!\n");
    }

    return 0;
}

