#include "sparse_block_matrix.h"
#include <iostream>

int main(int argc, char** argv) {
    using namespace std;
    using namespace g2o;
    using namespace Eigen;

    typedef SparseBlockMatrix<MatrixXd> SparseBlockMatrixX;

    std::ostream& operator<<(std::ostream& os, const SparseBlockMatrixX::SparseMatrixBlock& m) {
        for (int i = 0; i < m.rows(); ++i) {
            for (int j = 0; j < m.cols(); ++j)
                cerr << m(i, j) << " ";
            cerr << endl;
        }
        return os;
    }

    int row_sizes[] = {3, 6, 8, 12};
    int col_sizes[] = {2, 4, 13};

    cerr << "initialization" << endl;
    SparseBlockMatrixX* matrix = new SparseBlockMatrixX(row_sizes, col_sizes, 4, 3);

    cerr << "block manipulation" << endl;
    SparseBlockMatrixX::SparseMatrixBlock* blk1 = matrix->block(0, 0, true);
    cerr << blk1->rows() << " " << blk1->cols() << endl;
    for (int r = 0; r < blk1->rows(); ++r)
        for (int c = 0; c < blk1->cols(); ++c)
            (*blk1)(r, c) = r * blk1->cols() + c;

    cerr << "second block" << endl;
    SparseBlockMatrixX::SparseMatrixBlock* blk2 = matrix->block(0, 2, true);
    cerr << blk2->rows() << " " << blk2->cols() << endl;
    for (int r = 0; r < blk2->rows(); ++r)
        for (int c = 0; c < blk2->cols(); ++c)
            (*blk2)(r, c) = r * blk2->cols() + c;

    cerr << "third block" << endl;
    SparseBlockMatrixX::SparseMatrixBlock* blk3 = matrix->block(3, 2, true);
    cerr << blk3->rows() << " " << blk3->cols() << endl;
    for (int r = 0; r < blk3->rows(); ++r)
        for (int c = 0; c < blk3->cols(); ++c)
            (*blk3)(r, c) = r * blk3->cols() + c;

    cerr << *matrix << endl;
    cerr << "SUM" << endl;

    SparseBlockMatrixX* sum_result = nullptr;
    matrix->add(sum_result);
    matrix->add(sum_result);
    cerr << *sum_result << endl;

    SparseBlockMatrixX* transposed = nullptr;
    matrix->transpose(transposed);
    cerr << *transposed << endl;

    SparseBlockMatrixX* product = nullptr;
    matrix->multiply(product, transposed);
    cerr << *product << endl;

    int permutation_order[] = {3, 2, 1, 0};
    SparseBlockMatrixX* permuted = nullptr;
    product->symmPermutation(permuted, permutation_order, false);
    cerr << *permuted << endl;

    permuted->clear(true);
    product->block(3, 0)->fill(0.);
    product->symmPermutation(permuted, permutation_order, true);
    cerr << *permuted << endl;

    return 0;
}

