#include <stdio.h>
#define STB_DS_IMPLEMENTATION
#define STBDS_SIPHASH_2_4
#define STBDS_TEST_SIPHASH_2_4
#include "../stb_ds.h"

int main(int argc, char **argv)
{
  unsigned char buffer[64];
  int index, inner;

  // Initialize buffer with values 0 to 63
  for (index = 0; index < 64; ++index) 
    buffer[index] = (unsigned char)index;

  // Compute and print hash values for different input lengths
  for (index = 0; index < 64; ++index) {
    size_t result = stbds_hash_bytes(buffer, index, 0);
    printf("  { ");

    // Print hash bytes in little-endian order
    for (inner = 0; inner < 8; ++inner)
      printf("0x%02x, ", (unsigned char)((result >> (inner * 8)) & 255));

    printf(" },\n");
  }

  return 0;
}

