// Test comparison of timestamps using IsEarlierThan method
TEST(RoleTest, is_earlier_than) {
  RoleBase role_first;
  role_first.set_timestamp_ns(111);
  RoleBase role_second;
  role_second.set_timestamp_ns(222);

  EXPECT_TRUE(role_first.IsEarlierThan(role_second));
  EXPECT_FALSE(role_second.IsEarlierThan(role_first));
}

// Test Match functionality for RoleBase with various attribute combinations
TEST(RoleTest, rolebase_match) {
  RoleAttributes base_attr;
  base_attr.set_host_name("node_agent");
  base_attr.set_process_id(55555);
  base_attr.set_node_id(3);

  RoleBase base_role(base_attr, 9999999);

  RoleAttributes match_attr;
  EXPECT_TRUE(base_role.Match(match_attr));

  match_attr.set_host_name("remote_host");
  EXPECT_FALSE(base_role.Match(match_attr));

  match_attr.set_host_name("node_agent");
  EXPECT_TRUE(base_role.Match(match_attr));

  match_attr.set_process_id(11111);
  EXPECT_FALSE(base_role.Match(match_attr));

  match_attr.set_process_id(55555);
  EXPECT_TRUE(base_role.Match(match_attr));

  match_attr.set_node_id(7);
  EXPECT_FALSE(base_role.Match(match_attr));

  match_attr.set_node_id(3);
  EXPECT_TRUE(base_role.Match(match_attr));
}

// Test Match functionality for RoleWriter with channel and id attributes
TEST(RoleTest, rolewriter_match) {
  RoleAttributes writer_attr;
  writer_attr.set_host_name("publisher_node");
  writer_attr.set_process_id(33333);
  writer_attr.set_node_id(4);

  RoleAttributes target_attr(writer_attr);
  writer_attr.set_channel_id(5);
  writer_attr.set_id(6);

  RoleWriter writer(writer_attr, 8888888);

  EXPECT_TRUE(writer.Match(target_attr));

  target_attr.set_id(9);
  EXPECT_FALSE(writer.Match(target_attr));

  target_attr.set_id(6);
  EXPECT_TRUE(writer.Match(target_attr));

  target_attr.set_channel_id(10);
  EXPECT_FALSE(writer.Match(target_attr));

  target_attr.set_channel_id(5);
  EXPECT_TRUE(writer.Match(target_attr));
}

// Test Match functionality for RoleServer with service_id attribute
TEST(RoleTest, roleserver_match) {
  RoleAttributes server_attr;
  server_attr.set_host_name("service_host");
  server_attr.set_process_id(77777);
  server_attr.set_node_id(5);

  RoleAttributes target_attr(server_attr);
  server_attr.set_service_id(8);

  RoleServer server(server_attr, 7777777);

  EXPECT_TRUE(server.Match(target_attr));

  target_attr.set_service_id(12);
  EXPECT_FALSE(server.Match(target_attr));

  target_attr.set_service_id(8);
  EXPECT_TRUE(server.Match(target_attr));
}

