class Solution {
public:
    int minimumOperations(std::vector<int>& nums) {
        std::unordered_set<int> uniqueValues;
        for (auto value : nums) {
            if (value != 0) {
                uniqueValues.insert(value);
            }
        }
        return uniqueValues.size();
    }
};

