//=============================================================================
// SVNCleanupDialog
//-----------------------------------------------------------------------------
SVNCleanupDialog::SVNCleanupDialog(QWidget *parent, const QString &workingPath)
    : Dialog(TApp::instance()->getMainWindow(), true, false, "SvnCleanup") {
  setModal(false);
  setAttribute(Qt::WA_DeleteOnClose, true);
  setWindowTitle(tr("Version Control: Cleanup"));
  setMinimumSize(300, 150);
  beginVLayout();
  m_loadingLabel      = new QLabel;
  QMovie *loadingAnim = new QMovie(":Resources/waiting.gif");
  loadingAnim->setParent(this);
  m_loadingLabel->setMovie(loadingAnim);
  loadingAnim->setCacheMode(QMovie::CacheAll);
  loadingAnim->start();
  m_messageLabel = new QLabel(tr("Cleaning up %1...").arg(workingPath));
  addWidgets(m_loadingLabel, m_messageLabel);
  endVLayout();
  m_doneButton = new QPushButton(tr("Close"));
  connect(m_doneButton, SIGNAL(clicked()), this, SLOT(close()));
  m_doneButton->setEnabled(false);
  addButtonBarWidget(m_doneButton);
  // 0. Connect for svn errors (that may occur every time)
  connect(&m_worker, SIGNAL(error(const QString &)), this,
          SLOT(onError(const QString &)));
  // 1. Cleanup
  connect(&m_worker, SIGNAL(done(const QString &)), this,
          SLOT(onCleanupDone()));
  QStringList parameters;
  parameters << "cleanup";
  m_worker.executeCommand(workingPath, "svn", parameters);
}
//-----------------------------------------------------------------------------
void SVNCleanupDialog::onCleanupDone() {
  m_messageLabel->setText(tr("Cleanup done."));
  m_loadingLabel->hide();
  m_doneButton->setEnabled(true);
}
//-----------------------------------------------------------------------------
void SVNCleanupDialog::onError(const QString &message) {
  m_loadingLabel->hide();
  m_messageLabel->setText(message);
  m_doneButton->setEnabled(true);
}
//-----------------------------------------------------------------------------

