void SetupTableColumns(wxDataViewListCtrl *view,
                       const std::vector<wxString> &headers) {
  std::vector<int> colWidths = {90, 150, 180, 100, 120, 80, 80,  120, 80, 180,
                                80, 80,  80,  80,  80,  80, 100, 100, 80};
  int styleFlags = wxDATAVIEW_COL_RESIZABLE | wxDATAVIEW_COL_SORTABLE;

  auto *idRenderer =
      new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
  view->AppendColumn(new wxDataViewColumn(headers[0], idRenderer, 0,
                                          colWidths[0], wxALIGN_LEFT, styleFlags));

  view->AppendColumn(new wxDataViewColumn(
      headers[1], new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT),
      1, colWidths[1], wxALIGN_LEFT, styleFlags));

  view->AppendColumn(new wxDataViewColumn(
      headers[2], new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT),
      2, colWidths[2], wxALIGN_LEFT, styleFlags));

  view->AppendColumn(new wxDataViewColumn(
      headers[3], new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT),
      3, colWidths[3], wxALIGN_LEFT, styleFlags));

  view->AppendColumn(new wxDataViewColumn(
      headers[4], new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT),
      4, colWidths[4], wxALIGN_LEFT, styleFlags));

  view->AppendColumn(new wxDataViewColumn(
      headers[5], new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT),
      5, colWidths[5], wxALIGN_LEFT, styleFlags));

  view->AppendColumn(new wxDataViewColumn(
      headers[6], new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT),
      6, colWidths[6], wxALIGN_LEFT, styleFlags));

  for (size_t idx = 7; idx < headers.size() - 1; ++idx)
    view->AppendColumn(new wxDataViewColumn(
        headers[idx], new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT),
        idx, colWidths[idx], wxALIGN_LEFT, styleFlags));

  auto *iconTextRenderer =
      new ColorfulIconTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
  iconTextRenderer->EnableEllipsize(wxELLIPSIZE_NONE);
  view->AppendColumn(new wxDataViewColumn(
      headers.back(), iconTextRenderer, headers.size() - 1,
      colWidths.back(), wxALIGN_LEFT, styleFlags));

  ColumnUtils::EnforceMinColumnWidth(view);
}
