#include "protocol_extracter/nprotocol_extracter.h"
#include <chrono>
#include <thread>

int main(int argc, char **argv) {
  ros::init(argc, argv, "iot_parser");
  ros::NodeHandle node_handle;
  serial::Serial device_serial;
  initSerial(&device_serial);
  NProtocolExtracter protocol_extractor;
  iot::Init initializer(&protocol_extractor);
  ros::Rate update_rate(1000);

  while (ros::ok()) {
    auto bytes_available = device_serial.available();
    std::string incoming_data;

    if (bytes_available) {
      device_serial.read(incoming_data, bytes_available);
      protocol_extractor.AddNewData(incoming_data);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

