using namespace NPerforator::NProfile::NTest;

// NOLINTNEXTLINE(readability-identifier-naming)
struct ProfileConversionTest : testing::TestWithParam<TFsPath> {};

TEST_P(ProfileConversionTest, PprofToProfileCanon) {
    NPerforator::NProto::NPProf::Profile pprofInput;
    Y_ENSURE(pprofInput.ParseFromString(DecompressPprof(GetParam())));

    // Construct a new profile from the pprof input
    NPerforator::NProto::NProfile::Profile convertedProfile;
    NPerforator::NProfile::ConvertFromPProf(pprofInput, &convertedProfile);

    // Verify equivalence via flat comparison
    CompareFlatProfiles(pprofInput, convertedProfile);
}

TEST_P(ProfileConversionTest, RoundTripPprofToProfileCanon) {
    NPerforator::NProto::NPProf::Profile originalPprof;
    Y_ENSURE(originalPprof.ParseFromString(DecompressPprof(GetParam())));

    // Convert pprof to internal profile format
    NPerforator::NProto::NProfile::Profile intermediateProfile;
    NPerforator::NProfile::ConvertFromPProf(originalPprof, &intermediateProfile);

    // Convert back to pprof format
    NPerforator::NProto::NPProf::Profile roundTrippedPprof;
    NPerforator::NProfile::ConvertToPProf(intermediateProfile, &roundTrippedPprof);

    // Ensure round-trip preserves semantics
    CompareFlatProfiles(originalPprof, roundTrippedPprof);
}

TEST_P(ProfileConversionTest, DirectBytesToProfileCanon) {
    TString pprofData = DecompressPprof(GetParam());

    // Parse directly from bytes into internal profile
    NPerforator::NProto::NProfile::Profile parsedProfile;
    NPerforator::NProfile::ConvertFromPProf(pprofData, &parsedProfile);

    // Also parse original pprof for comparison
    NPerforator::NProto::NPProf::Profile originalPprof;
    Y_ENSURE(originalPprof.ParseFromString(pprofData));

    // Compare both representations
    CompareFlatProfiles(originalPprof, parsedProfile);
}

TEST_P(ProfileConversionTest, BytesRoundTripCanon) {
    TString originalBytes = DecompressPprof(GetParam());

    // Convert from raw bytes to internal profile
    NPerforator::NProto::NProfile::Profile convertedProfile;
    NPerforator::NProfile::ConvertFromPProf(originalBytes, &convertedProfile);

    // Convert back to pprof format
    NPerforator::NProto::NPProf::Profile regeneratedPprof;
    NPerforator::NProfile::ConvertToPProf(convertedProfile, &regeneratedPprof);

    // Parse original bytes again for final comparison
    NPerforator::NProto::NPProf::Profile referencePprof;
    Y_ENSURE(referencePprof.ParseFromString(originalBytes));

    // Validate round-trip fidelity
    CompareFlatProfiles(referencePprof, regeneratedPprof);
}

INSTANTIATE_TEST_SUITE_P(
