#include "capstone_git.h"
#undef X86_INS_
#define LATX_DT_X86    0
#define LATX_DT_X64    1
la_name_enum_t cap_x86_insn_map[X86_INS_ENDING + 1];
la_name_enum_t cap_x86_reg_map[X86_REG_ENDING + 1];
la_name_enum_t cap_x86_bcast_map[5];
la_name_enum_t cap_x86_op_type_map[4];
la_name_enum_t cap_x86_avx_cc_map[X86_AVX_CC_TRUE_US + 1];
csh cap_handle[2];
uint8_t dt_capstone_mode[2];
char cap_tmp_buf[IR1_INST_SIZE];

struct la_dt_insn *capstone_get_from_insn(cs_insn *src_info,
    int inst_num, void *base_ptr)
{
    if (src_info == NULL) {
        return NULL;
    }

    struct la_dt_insn *result;
    if (base_ptr) {
        uint64_t current_addr = (uint64_t)base_ptr +
            (inst_num * sizeof(struct la_dt_insn));
        result = (void *)current_addr;
    } else {
        result = malloc(sizeof(struct la_dt_insn));
    }

#ifdef LATX_DISASSEMBLE_TRACE_DEBUG
    strncpy(result->mnemonic, src_info->mnemonic, 32);
    strncpy(result->op_str, src_info->op_str, 160);
#endif

    lsassert(src_info->id <= X86_INS_ENDING);
    result->id = cap_x86_insn_map[src_info->id].id;

    for (int idx = 0; idx < 4; idx++) {
        result->x86.prefix[idx] = src_info->detail->x86.prefix[idx];
    }

    for (int idx = 0; idx < 4; idx++) {
        result->x86.opcode[idx] = src_info->detail->x86.opcode[idx];
    }

    for (int idx = 0; idx < 24; idx++) {
        result->bytes[idx] = src_info->bytes[idx];
    }

    result->x86.addr_size = src_info->detail->x86.addr_size;
    result->x86.rex = src_info->detail->x86.rex;
    result->x86.modrm = src_info->detail->x86.modrm;
    result->x86.op_count = src_info->detail->x86.op_count;

    for (int idx = 0; idx < 8; idx++) {
        int op_type = src_info->detail->x86.operands[idx].type; 
        result->x86.operands[idx].type = cap_x86_op_type_map[op_type].id;

        if (op_type == X86_OP_IMM) {
            result->x86.operands[idx].imm = src_info->detail->x86.operands[idx].imm;
        } else if (op_type == X86_OP_REG) {
            lsassert(src_info->detail->x86.operands[idx].reg <=
                dt_X86_REG_ENDING);
            result->x86.operands[idx].reg =
                cap_x86_reg_map[src_info->detail->x86.operands[idx].reg].id;
        } else if (op_type == X86_OP_MEM) {
            lsassert(src_info->detail->x86.operands[idx].mem.segment <=
                dt_X86_REG_ENDING);
            lsassert(src_info->detail->x86.operands[idx].mem.base <=
                dt_X86_REG_ENDING);
            lsassert(src_info->detail->x86.operands[idx].mem.index <=
                dt_X86_REG_ENDING);

            result->x86.operands[idx].mem.segment =
                cap_x86_reg_map[src_info->detail->
                x86.operands[idx].mem.segment].id;
            result->x86.operands[idx].mem.default_segment =
                dt_X86_REG_INVALID;
            result->x86.operands[idx].mem.base =
                cap_x86_reg_map[src_info->detail->
                x86.operands[idx].mem.base].id;
            result->x86.operands[idx].mem.index =
                cap_x86_reg_map[src_info->detail->
                x86.operands[idx].mem.index].id;
            result->x86.operands[idx].mem.scale =
                src_info->detail->x86.operands[idx].mem.scale;
            result->x86.operands[idx].mem.disp =
                src_info->detail->x86.operands[idx].mem.disp;
        }

        result->x86.operands[idx].size = src_info->detail->x86.operands[idx].size;

        switch (src_info->detail->x86.operands[idx].access) {
            default:
                break;
            case CS_AC_READ:
                result->x86.operands[idx].access = dt_CS_AC_READ;
                break;
            case CS_AC_WRITE:
                result->x86.operands[idx].access = dt_CS_AC_WRITE;
                break;
            case CS_AC_READ | CS_AC_WRITE:
                result->x86.operands[idx].access = dt_CS_AC_READ|dt_CS_AC_WRITE;
                break;
        }

        result->x86.operands[idx].avx_bcast =
            cap_x86_bcast_map[src_info->detail->
            x86.operands[idx].avx_bcast].id;
        result->x86.operands[idx].avx_zero_opmask =
            src_info->detail->x86.operands[idx].avx_zero_opmask;
    }

    result->x86.avx_cc =
        cap_x86_avx_cc_map[src_info->detail->x86.avx_cc].id;
    result->size = src_info->size;
    result->address = src_info->address;

    return result; 
}

int capstone_get(const uint8_t *code_data, size_t code_length,
        uint64_t instr_addr,
        size_t max_count, struct la_dt_insn **output_insn,
        int inst_index, void *base_address, int cpu_mode)
{
    cs_insn *disasm_result;
    struct la_dt_insn *ret_val;

    dtassert(cap_handle[cpu_mode]);

    int count = latx_cs_disasm(cap_handle[cpu_mode], code_data, code_length,
        instr_addr, max_count, &disasm_result, 0, cap_tmp_buf);

    if (disasm_result == NULL) {
        *output_insn = NULL;
        qemu_log_mask(LAT_LOG_DT, "%s: can't disasm code 0x%x\n",
            __func__, *(uint32_t *)code_data);
        return count;
    }

    ret_val = capstone_get_from_insn(disasm_result, inst_index, base_address);
    *output_insn = ret_val;

    return count; 
}

