{
    dt_capstone_mode[LATX_DT_X86] = 32;
    dt_capstone_mode[LATX_DT_X64] = 64;

    if (cs_open(CS_ARCH_X86, CS_MODE_32, &cap_handle[LATX_DT_X86]) != CS_ERR_OK) {
       fprintf(stderr, "%s %s %d error : cs_open\n",
               __FILE__, __func__, __LINE__);
       exit(-1);
    }

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &cap_handle[LATX_DT_X64]) != CS_ERR_OK) {
       fprintf(stderr, "%s %s %d error : cs_open\n",
               __FILE__, __func__, __LINE__);
       exit(-1);
    }

    cs_option(cap_handle[LATX_DT_X86], CS_OPT_DETAIL, CS_OPT_ON);
    cs_option(cap_handle[LATX_DT_X64], CS_OPT_DETAIL, CS_OPT_ON);
}

void capstone_init(int abi_bits)
{
    capstone_init_internal(abi_bits);
    handle[0]   = cap_handle[0];
    handle[1]   = cap_handle[1];
    init_insn_mapping();
    init_reg_mapping();
    init_bcast_mapping();
    init_op_type_mapping();
    init_avx_cc_mapping();
}

