#include "sophus/geometry.hpp"

int main() {
  // Compute the composition of three rotations around coordinate axes
  const double kPi = Sophus::Constants<double>::pi();
  Sophus::SO3d rotXAxis = Sophus::SO3d::rotX(kPi / 4);
  Sophus::SO3d rotYAxis = Sophus::SO3d::rotY(kPi / 6);
  Sophus::SO3d rotZAxis = Sophus::SO3d::rotZ(-kPi / 3);

  std::cout << "Individual rotation matrices:" << std::endl;
  std::cout << "R_x:\n" << rotXAxis.matrix() << std::endl;
  std::cout << "R_y:\n" << rotYAxis.matrix() << std::endl;
  std::cout << "R_z:\n" << rotZAxis.matrix() << std::endl;
  std::cout << "Combined rotation R_x * R_y * R_z:\n"
            << (rotXAxis * rotYAxis * rotZAxis).matrix() << std::endl;
  std::cout << std::endl;

  // Apply rotations to a test vector
  Eigen::Vector3d testVec;
  testVec << 0.0, 0.0, 1.0;
  std::cout << "Vector transformation under rotation:" << std::endl;
  std::cout << "Original vector:\n" << testVec << std::endl;
  std::cout << "R_y * testVec:\n" << rotYAxis * testVec << std::endl;
  std::cout << "R_x * (R_y * testVec):\n" << rotXAxis * (rotYAxis * testVec) << std::endl;
  std::cout << "(R_x * R_y) * testVec:\n" << (rotXAxis * rotYAxis) * testVec << std::endl;
  std::cout << std::endl;

  // Display SO(3) element in both matrix and quaternion form
  std::cout << "Rotation R_x as matrix:\n" << rotXAxis.matrix() << std::endl;
  std::cout << "Rotation R_x as unit quaternion:\n"
            << rotXAxis.unit_quaternion().coeffs() << std::endl;
  // Note: Eigen uses (imag0, imag1, imag2, real) ordering for quaternion coefficients
  std::cout << std::endl;
}

