// Calculate area of square
void calculateSquareArea(int sideLength) {
    cout << "area of square= " << sideLength * sideLength << endl;
}

// Calculate perimeter of rectangle
void calculateRectanglePerimeter(int length, int width) {
    cout << "perimeter of rectangle= " << 2 * (length + width) << endl;
}

// Calculate area of circle
void calculateCircleArea(int radius) {
    cout << "area of circle= " << 3.14 * radius * radius << endl;
}

// Find maximum of three numbers
int findMaximum(int x, int y, int z) {
    int maxVal = x;
    if (y > maxVal) maxVal = y;
    if (z > maxVal) maxVal = z;
    return maxVal;
}

// Display multiplication table
void displayMultiplicationTable(int number) {
    cout << "table of " << number << ":" << endl;
    for (int i = 1; i <= 10; i++) {
        cout << number << " * " << i << " = " << number * i << endl;
    }
}

int main() {
    int choice = 0, num1 = 0, num2 = 0, num3 = 0;

    while (choice != 6) {
        system("cls");

        cout << "1. area of square" << endl;
        cout << "2. perimeter of rectangle" << endl;
        cout << "3. area of circle" << endl;
        cout << "4. max of 3 nos" << endl;
        cout << "5. table of number" << endl;
        cout << "6. exit" << endl;
        cout << "enter any choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                cout << "enter any side: ";
                cin >> num1;
                calculateSquareArea(num1);
                break;

            case 2:
                cout << "enter length and breadth: ";
                cin >> num1 >> num2;
                calculateRectanglePerimeter(num1, num2);
                break;

            case 3:
                cout << "enter radius: ";
                cin >> num1;
                calculateCircleArea(num1);
                break;

            case 4:
                cout << "enter three numbers: ";
                cin >> num1 >> num2 >> num3;
                cout << "max of 3 nos= " << findMaximum(num1, num2, num3) << endl;
                break;

            case 5:
                cout << "enter a number: ";
                cin >> num1;
                displayMultiplicationTable(num1);
                break;

            case 6:
                cout << "Exiting..." << endl;
                break;

            default:
                cout << "Invalid choice! Please try again." << endl;
        }

        // Pause before showing menu again
        if (choice != 6) {
            cout << "Press Enter to continue...";
            cin.ignore();
            cin.get();
        }
    }

    return 0;
}

