// Apply byte modifications to a specific memory location
void applyPatch(void* targetLocation, const std::vector<BYTE>* byteSequence)
{
    DWORD previousProtection;
    VirtualProtect(targetLocation, byteSequence->size(), PAGE_EXECUTE_READWRITE, &previousProtection);
    std::memcpy(targetLocation, byteSequence->data(), byteSequence->size());
    VirtualProtect(targetLocation, byteSequence->size(), previousProtection, &previousProtection);
    FlushInstructionCache(GetCurrentProcess(), targetLocation, byteSequence->size());
}

