// Display received data in hexadecimal format
void displayHexStream(const std::string &buffer) {
  if (!buffer.empty()) {
    std::cout << "hex dump: ";
    for (size_t idx = 0; idx < buffer.size(); ++idx) {
      std::cout << std::hex << std::setfill('0') << std::setw(2)
                << static_cast<int>(static_cast<uint8_t>(buffer[idx])) << " ";
    }
    std::cout << std::endl;
  }
}

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_parser_node");
  ros::NodeHandle private_nh;
  serial::Serial device_serial;
  setupSerial(&device_serial);
  NProtocolExtracter parser;
  linktrack::Initializer initializer(&parser, &device_serial);

  ros::Rate update_rate(500);
  while (ros::ok()) {
    size_t bytes_available = device_serial.available();
    std::string incoming_data;

    if (bytes_available > 0) {
      device_serial.read(incoming_data, bytes_available);
      // displayHexStream(incoming_data);
      parser.ProcessNewData(incoming_data);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

