void _asm_megabuf(void)
{
  __asm__(
      LABEL_MARKER
    "fadd" EEL_F_SUFFIX " -8(%%esi)\n"
    "fistpl (%%edi)\n"
    // check if (%edi) is in range, and buffer available, otherwise call function
    "movl (%%edi), %%esi\n"
    "cmpl %0, %%esi\n"     //REPLACE=((NSEEL_RAM_BLOCKS*NSEEL_RAM_ITEMSPERBLOCK))
    "jae 1f\n"
      "movl %%esi, %%ebx\n"
      "shrl %1, %%ebx\n"      //REPLACE=(NSEEL_RAM_ITEMSPERBLOCK_LOG2 - 2/*log2(sizeof(void *))*/   )
      "andl %2, %%ebx\n"      //REPLACE=((NSEEL_RAM_BLOCKS-1)*4 /*sizeof(void*)*/                   )
      "movl (%%esi, %%ebx), %%ebx\n"
      "testl %%ebx, %%ebx\n"
      "jnz 2f\n"
    "1:\n"
      "subl $12, %%ebp\n" // keep stack aligned
      "movl $0xabababab, %%edx\n"
      "pushl %%esi\n" // argument
      "pushl %%esi\n" // push context pointer
      "jmp *%%edx\n"
      "addl $24, %%ebp\n"
      "jmp 3f\n"
    "2:\n"
      "andl %3, %%esi\n"      //REPLACE=(NSEEL_RAM_ITEMSPERBLOCK-1)
      "shll $3, %%esi\n"      // 3 is log2(sizeof(EEL_F))
      "addl %%esi, %%ebx\n"
    "3:"
    LABEL_MARKER
    #ifndef _MSC_VER
        :: "i" (((NSEEL_RAM_BLOCKS*NSEEL_RAM_ITEMSPERBLOCK))),
           "i" ((NSEEL_RAM_ITEMSPERBLOCK_LOG2 - 2/*log2(sizeof(void *))*/   )),
           "i" (((NSEEL_RAM_BLOCKS-1)*4 /*sizeof(void*)*/                   )),
           "i" ((NSEEL_RAM_ITEMSPERBLOCK-1                                  ))
    #endif
  );
}
void _asm_gmegabuf(void)
{
  __asm__(
      LABEL_MARKER
    "subl $24, %ebp\n" // keep stack aligned
    "movl $0xabababab, (%ebp)\n"
    "fadd" EEL_F_SUFFIX " -8(%esi)\n"
    "movl $0xabababab, %edi\n"
    "fistpl 8(%ebp)\n"
    "jmp *%edi\n"
    "addl $24, %ebp\n"
    LABEL_MARKER
 );
