void GameOfLifeWindow::init(SurfaceRenderer& renderer)
{
	using namespace tc;

	m_bufferX.reset(new BufferResource<float>{ BUFFER_SIZE });
	m_bufferX->randomize(0, 255);
	m_bufferY.reset(new BufferResource<float>{ BUFFER_SIZE });
	m_bufferY->randomize(0, 255);
	m_bufferZ.reset(new BufferResource<float>{ BUFFER_SIZE });

	m_AdderKernel.A.attach(m_bufferX.get());
	m_AdderKernel.B.attach(m_bufferY.get());
	m_AdderKernel.C.attach(m_bufferZ.get());

	using Backend = tc::gpu::GPUBackend;
	Backend gpuCompute;
	gpuCompute.uploadBuffer(*m_bufferX.get());
	gpuCompute.uploadBuffer(*m_bufferY.get());
	gpuCompute.uploadBuffer(*m_bufferZ.get());
	gpuCompute.useKernel(m_AdderKernel);
	gpuCompute.bindBuffer(m_AdderKernel.A);
	gpuCompute.bindBuffer(m_AdderKernel.B);
	gpuCompute.bindBuffer(m_AdderKernel.C);
	gpuCompute.execute(m_AdderKernel, tc::uvec3{ BUFFER_SIZE, 1, 1 });
	gpuCompute.downloadBuffer(*m_bufferZ.get());
}

