// SHA-1 implementation based on clibs: https://github.com/clibs/sha1
#define rotate_left(value, n) (((value) << (n)) | ((value) >> (32 - (n))))
#define block0(idx) m_workspace_block->words[idx]
#define block_n(idx)                                                                     \
    (m_workspace_block->words[(idx) & 15] =                                             \
         rotate_left(m_workspace_block->words[(idx) & 15] ^                             \
                         m_workspace_block->words[(idx + 2) & 15] ^                     \
                         m_workspace_block->words[(idx + 8) & 15] ^                     \
                         m_workspace_block->words[(idx + 13) & 15],                     \
                     1))

/* SHA-1 round functions */
#define ROUND_0(a, b, c, d, e, idx)                                                      \
    e += ((b & (c ^ d)) ^ d) + block0(idx) + 0x5A827999 + rotate_left(a, 5);            \
    b = rotate_left(b, 30);
#define ROUND_1(a, b, c, d, e, idx)                                                      \
    e += ((b & (c ^ d)) ^ d) + block_n(idx) + 0x5A827999 + rotate_left(a, 5);           \
    b = rotate_left(b, 30);
#define ROUND_2(a, b, c, d, e, idx)                                                      \
    e += (b ^ c ^ d) + block_n(idx) + 0x6ED9EBA1 + rotate_left(a, 5);                   \
    b = rotate_left(b, 30);
#define ROUND_3(a, b, c, d, e, idx)                                                      \
    e += (((b | c) & d) | (b & c)) + block_n(idx) + 0x8F1BBCDC + rotate_left(a, 5);     \
    b = rotate_left(b, 30);
#define ROUND_4(a, b, c, d, e, idx)                                                      \
    e += (b ^ c ^ d) + block_n(idx) + 0xCA62C1D6 + rotate_left(a, 5);                   \
    b = rotate_left(b, 30);

void CSHA1::Transform(unsigned int *state, const unsigned char *input_buffer) {
    unsigned int a, b, c, d, e;
    a = state[0];
    b = state[1];
    c = state[2];
    d = state[3];
    e = state[4];

    memcpy(m_workspace_block->bytes, input_buffer, 64);

    ROUND_0(a, b, c, d, e, 0);
    ROUND_0(e, a, b, c, d, 1);
    ROUND_0(d, e, a, b, c, 2);
    ROUND_0(c, d, e, a, b, 3);
    ROUND_0(b, c, d, e, a, 4);
    ROUND_0(a, b, c, d, e, 5);
    ROUND_0(e, a, b, c, d, 6);
    ROUND_0(d, e, a, b, c, 7);
    ROUND_0(c, d, e, a, b, 8);
