    ROUND_1(d, e, a, b, c, 17);
    ROUND_1(c, d, e, a, b, 18);
    ROUND_1(b, c, d, e, a, 19);
    ROUND_2(a, b, c, d, e, 20);
    ROUND_2(e, a, b, c, d, 21);
