    state[0] += a;
    state[1] += b;
    state[2] += c;
    state[3] += d;
    state[4] += e;
}

void CSHA1::Update(const unsigned char *data, unsigned int length) {
    unsigned int buffer_index, bytes_to_copy;
    buffer_index = (m_bit_count[0] / 8) % 64;

    m_bit_count[0] += length * 8;
    if (m_bit_count[0] < length * 8) {
        m_bit_count[1]++;
    }
    m_bit_count[1] += (length >> 29);

    if ((buffer_index + length) > 63) {
        bytes_to_copy = 64 - buffer_index;
        memcpy(&m_input_buffer[buffer_index], data, bytes_to_copy);
        Transform(m_state, m_input_buffer);

        for (unsigned int i = bytes_to_copy; i + 63 < length; i += 64) {
            Transform(m_state, &data[i]);
        }

        buffer_index = 0;
    } else {
        bytes_to_copy = 0;
    }

    if (length - bytes_to_copy != 0) {
        memcpy(&m_input_buffer[buffer_index], &data[bytes_to_copy], length - bytes_to_copy);
    }
}

const CSHA1::Digest &CSHA1::Final() {
    unsigned int i;
    unsigned char padding_bytes[8];
    unsigned char single_byte;

    for (i = 0; i < 8; i++) {
        padding_bytes[i] =
            (unsigned char)((m_bit_count[(i >= 4 ? 0 : 1)] >> ((3 - (i & 3)) * 8)) & 0xFF);
    }

    Update((const unsigned char *)"\x80", 1);
    while ((m_bit_count[0] & 504) != 448) {
        Update((const unsigned char *)"\x00", 1);
    }
    Update(padding_bytes, 8);

    for (i = 0; i < 20; i++) {
        m_result.digits[i] =
            (unsigned char)((m_state[i >> 2] >> ((3 - (i & 3)) * 8)) & 0xFF);
    }

    memset(m_input_buffer, 0, 64);
    memset(m_state, 0, 20);
    memset(m_bit_count, 0, 8);
    memset(padding_bytes, 0, 8);
    Transform(m_state, m_input_buffer);

    return m_result;
}

void CSHA1::Digest::Copy(unsigned char *output) const { memcpy(output, this, 20); }

void CSHA1::Digest::ReportHash(char *output, unsigned char format_type) const {
    char temp_buffer[24];
    unsigned int index;

    if (output) {
        if (format_type == 0) {
            sprintf(temp_buffer, "%02X", digits[0]);
            strcpy(output, temp_buffer);
            for (index = 1; index < 20; index++) {
                sprintf(temp_buffer, "%02X", digits[index & 0xFF]);
                strcat(output, temp_buffer);
            }
        } else if (format_type == 1) {
            sprintf(temp_buffer, "%u", digits[0]);
            strcpy(output, temp_buffer);
            for (index = 1; index < 20; index++) {
                sprintf(temp_buffer, " %u", digits[index & 0xFF]);
                strcat(output, temp_buffer);
            }
        } else {
            strcpy(output, "Error: Unknown report type!");
        }
    }
}

BinStream &operator<<(BinStream &stream, const CSHA1::Digest &digest) {
    stream.Write(digest.digits, 20);
    return stream;
}

BinStream &operator>>(BinStream &stream, CSHA1::Digest &digest) {
    stream.Read(digest.digits, 20);
    return stream;
}

CSHA1::CSHA1() {
    m_workspace_block = (SHA1_WORKSPACE_BLOCK *)m_workspace;
    Reset();
}

CSHA1::~CSHA1() { Reset(); }

