// Pack single value spanning 32-64 bits
template <uint16_t BITS, uint16_t SHIFT, uint64_t MASK>
        typename std::enable_if < BITS + SHIFT >= 32 &&
    BITS + SHIFT < 64>::type insert_value64(const uint64_t val,
                                           uint32_t *__restrict &dest) {
  if (SHIFT == 0) {
    *dest = static_cast<uint32_t>(val & MASK);
  } else {
    *dest |= (val & MASK) << SHIFT;
  }
  ++dest;
  if (BITS + SHIFT > 32) {
    *dest = static_cast<uint32_t>((val & MASK) >> (32 - SHIFT));
  }
}

// Pack single value spanning 64+ bits
template <uint16_t BITS, uint16_t SHIFT, uint64_t MASK>
typename std::enable_if<BITS + SHIFT >= 64>::type insert_value64(
    const uint64_t val, uint32_t *__restrict &dest) {
  *dest |= val << SHIFT;
  ++dest;
  *dest = static_cast<uint32_t>((val & MASK) >> (32 - SHIFT));
  ++dest;
  if (BITS + SHIFT > 64) {
    *dest = (val & MASK) >> (64 - SHIFT);
  }
}

// Unroller for 8-bit operations
template <uint16_t BITS, uint16_t POS = 0>
struct Unroller8 {
  static void Extract(const uint8_t *__restrict &src, uint8_t *__restrict dst) {
    extract_value<BITS, (BITS * POS) % 8>(src, dst + POS);
    Unroller8<BITS, POS + 1>::Extract(src, dst);
  }
  static void Insert(const uint8_t *__restrict src, uint8_t *__restrict dst) {
    insert_value<BITS, (BITS * POS) % 8, (1U << BITS) - 1>(src[POS], dst);
    Unroller8<BITS, POS + 1>::Insert(src, dst);
  }
};

// Specialization for last element in 8-bit unroller
template <uint16_t BITS>
struct Unroller8<BITS, 7> {
  enum { SHIFT_POS = (BITS * 7) % 8 };
  static void Extract(const uint8_t *__restrict src, uint8_t *__restrict dst) {
    dst[7] = (*src) >> SHIFT_POS;
  }
  static void Insert(const uint8_t *__restrict src, uint8_t *__restrict dst) {
    *dst |= (src[7] << SHIFT_POS);
  }
};

