// General unroller for 32-bit operations
template <uint16_t BITS, uint16_t POS = 0>
struct Unroller {
  static void Extract(const uint32_t *__restrict &src,
                     uint32_t *__restrict dst) {
    extract_value<BITS, (BITS * POS) % 32>(src, dst + POS);
    Unroller<BITS, POS + 1>::Extract(src, dst);
  }

  static void Extract(const uint32_t *__restrict &src,
                     uint64_t *__restrict dst) {
    extract_value<BITS, (BITS * POS) % 32>(src, dst + POS);
    Unroller<BITS, POS + 1>::Extract(src, dst);
  }

  static void Insert(const uint32_t *__restrict src,
                   uint32_t *__restrict dst) {
    insert_value<BITS, (BITS * POS) % 32, (1U << BITS) - 1>(src[POS],
                                                                    dst);
    Unroller<BITS, POS + 1>::Insert(src, dst);
  }

  static void Insert(const uint64_t *__restrict src,
                   uint32_t *__restrict dst) {
    insert_value64<BITS, (BITS * POS) % 32, (1ULL << BITS) - 1>(
        src[POS], dst);
    Unroller<BITS, POS + 1>::Insert(src, dst);
  }

  static void InsertNoMask(const uint32_t *__restrict src,
                         uint32_t *__restrict dst) {
    insert_value<BITS, (BITS * POS) % 32, uint32_t(-1)>(src[POS], dst);
    Unroller<BITS, POS + 1>::InsertNoMask(src, dst);
  }

  static void InsertNoMask(const uint64_t *__restrict src,
                         uint32_t *__restrict dst) {
    insert_value64<BITS, (BITS * POS) % 32, uint64_t(-1)>(src[POS],
                                                                 dst);
    Unroller<BITS, POS + 1>::InsertNoMask(src, dst);
  }
};

// Specialization for last element in general unroller
template <uint16_t BITS>
struct Unroller<BITS, 31> {
  enum { SHIFT_POS = (BITS * 31) % 32 };
  static void Extract(const uint32_t *__restrict src,
                     uint32_t *__restrict dst) {
    dst[31] = (*src) >> SHIFT_POS;
  }

  static void Extract(const uint32_t *__restrict src,
                     uint64_t *__restrict dst) {
    dst[31] = (*src) >> SHIFT_POS;
    if (BITS > 32) {
      ++src;
      dst[31] |= static_cast<uint64_t>(*src) << (32 - SHIFT_POS);
    }
  }

  static void Insert(const uint32_t *__restrict src,
                   uint32_t *__restrict dst) {
    *dst |= (src[31] << SHIFT_POS);
  }

  static void Insert(const uint64_t *__restrict src,
                   uint32_t *__restrict dst) {
    *dst |= (src[31] << SHIFT_POS);
    if (BITS > 32) {
      ++dst;
      *dst = static_cast<uint32_t>(src[31] >> (32 - SHIFT_POS));
    }
  }

  static void InsertNoMask(const uint32_t *__restrict src,
                         uint32_t *__restrict dst) {
    *dst |= (src[31] << SHIFT_POS);
  }

  static void InsertNoMask(const uint64_t *__restrict src,
                         uint32_t *__restrict dst) {
    *dst |= (src[31] << SHIFT_POS);
    if (BITS > 32) {
      ++dst;
      *dst = static_cast<uint32_t>(src[31] >> (32 - SHIFT_POS));
    }
  }
};

