    GM_ADDR inputTensor, GM_ADDR expertIndices, GM_ADDR sendDisplacements, GM_ADDR sendTokenLocations,
    GM_ADDR recvDisplacements, GM_ADDR recvCounts, GM_ADDR expertGlobalOffsets, GM_ADDR srcRankInExpertOffsets,
