int main()
{
    // Valid JSON pointer examples
    json::json_pointer ptr1;
    json::json_pointer ptr2("");
    json::json_pointer ptr3("/");
    json::json_pointer ptr4("//");
    json::json_pointer ptr5("/foo/bar");
    json::json_pointer ptr6("/foo/bar/-");
    json::json_pointer ptr7("/foo/~0");
    json::json_pointer ptr8("/foo/~1");

    // Invalid: missing leading slash
    try
    {
        json::json_pointer invalidPtr1("foo");
    }
    catch (const json::parse_error& error)
    {
        std::cout << error.what() << '\n';
    }

    // Invalid: ~ not followed by 0 or 1
    try
    {
        json::json_pointer invalidPtr2("/foo/~");
    }
    catch (const json::parse_error& error)
    {
        std::cout << error.what() << '\n';
    }

    // Invalid: ~ followed by invalid digit
    try
    {
        json::json_pointer invalidPtr3("/foo/~3");
    }
    catch (const json::parse_error& error)
    {
        std::cout << error.what() << '\n';
    }
}

