#include <string>
#include <vector>
#include "../include/parser.h"
#include <cassert>

// Evaluate integer operations using the parser
void evaluate_integer_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> test_cases = {
        {"42", "42"},
        {"-15", "-15"},
        {"(+ 10 20)", "30"},
        {"(- 50 30)", "20"},
        {"(* 6 7)", "42"},
        {"(div 20 5)", "4"},
        {"(mod 17 5)", "2"},
        {"(abs -42)", "42"}
    };

    std::cout << "=== Evaluating Integer Operations ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Input: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(entry.first);
        assert(output);
        std::string actual = parser->toString(output);
        std::cout << "  Output: " << actual << std::endl;
        assert(actual == entry.second && "integer operation result mismatch");
        std::cout << std::endl;
    }
}

// Evaluate real number arithmetic
void evaluate_real_ops(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, std::string>> test_cases = {
        {"3.14159", "3.14159"},
        {"-2.71828", "-2.71828"},
        {"(+ 3.5 2.7)", "6.2"},
        {"(- 10.5 4.2)", "6.3"},
        {"(* 2.5 4.0)", "10"},
        {"(/ 15.0 3.0)", "5"},
        {"(^ 2.0 3.0)", "8"},
        {"(sqrt 16.0)", "4"},
        {"(abs -9.81)", "9.81"}
    };

    std::cout << "=== Evaluating Real Number Arithmetic ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Input: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(entry.first);
        assert(output);
        std::string actual = parser->toString(output);
        std::cout << "  Output: " << actual << std::endl;
        assert(actual == entry.second && "real arithmetic result mismatch");
        std::cout << std::endl;
    }
}

// Evaluate comparison operations
void evaluate_comparisons(SMTParser::ParserPtr& parser) {
    std::vector<std::pair<std::string, bool>> test_cases = {
        {"(< 5 10)", true},
        {"(<= 7 7)", true},
        {"(> 15 5)", true},
        {"(>= 12 12)", true},
        {"(= 42 42)", true},
        {"(distinct 3 5 7)", true}
    };

    std::cout << "=== Evaluating Comparison Operations ===" << std::endl;
    for (const auto& entry : test_cases) {
        std::cout << "Input: " << entry.first << std::endl;
        std::shared_ptr<SMTParser::DAGNode> output = parser->mkExpr(entry.first);
        assert(output);
        std::cout << "  Output: " << parser->toString(output) << std::endl;
        assert(output->isTrue() == entry.second && "comparison should yield expected boolean");
        std::cout << std::endl;
    }
}

// Test evaluation precision settings
void evaluate_precision(SMTParser::ParserPtr& parser) {
    std::cout << "=== Testing Precision Settings ===" << std::endl;

    // Default precision (128 bits)
    std::cout << "=== Default Precision (128 bits) ===" << std::endl;
    auto res1 = parser->mkExpr("(+ 3.5 2.7)");
    auto res2 = parser->mkExpr("(- 10.5 4.2)");
    assert(res1 && res2);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Output: " << parser->toString(res1) << std::endl;
    assert(parser->toString(res1) == "6.2");
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Output: " << parser->toString(res2) << std::endl;
    assert(parser->toString(res2) == "6.3");

    // Higher precision (256 bits)
    parser->setEvaluatePrecision(256);
    std::cout << "\n=== Higher Precision (256 bits) ===" << std::endl;
    auto res3 = parser->mkExpr("(+ 3.5 2.7)");
    auto res4 = parser->mkExpr("(- 10.5 4.2)");
    assert(res3 && res4);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Output: " << parser->toString(res3) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Output: " << parser->toString(res4) << std::endl;
    assert(parser->toString(res3) == "6.2" && parser->toString(res4) == "6.3");

    // Disable floating point mode
    parser->setEvaluateUseFloating(false);
    std::cout << "\n=== Floating Point Disabled ===" << std::endl;
    auto res5 = parser->mkExpr("(+ 3.5 2.7)");
    auto res6 = parser->mkExpr("(- 10.5 4.2)");
    assert(res5 && res6);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Output: " << parser->toString(res5) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Output: " << parser->toString(res6) << std::endl;
    assert(parser->toString(res5) == "6.2" && parser->toString(res6) == "6.3");
}

int main() {
    std::cout << "======= Arithmetic Operations Validation =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    evaluate_integer_ops(parser);
    evaluate_real_ops(parser);
    evaluate_comparisons(parser);
    evaluate_precision(parser);

    return 0;
}

