FAnimBlueprintCompilerHandler_PropertyAccess::FAnimBlueprintCompilerHandler_PropertyAccess(IAnimBlueprintCompilerCreationContext& CreationContext)
{
	CreationContext.OnStartCompilingClass().AddRaw(this, &FAnimBlueprintCompilerHandler_PropertyAccess::StartCompilingClass);
	CreationContext.OnFinishCompilingClass().AddRaw(this, &FAnimBlueprintCompilerHandler_PropertyAccess::FinishCompilingClass);
}

int32 FAnimBlueprintCompilerHandler_PropertyAccess::AddCopy(TArrayView<FString> SourcePath, TArrayView<FString> DestPath, EPropertyAccessBatchType BatchType, UObject* Object)
{
	return PropertyAccessLibraryCompiler.AddCopy(SourcePath, DestPath, BatchType, Object);
}

void FAnimBlueprintCompilerHandler_PropertyAccess::StartCompilingClass(const UClass* Class, IAnimBlueprintCompilationBracketContext& CompilationContext, IAnimBlueprintGeneratedClassCompiledData& CompiledData)
{
	PropertyAccessLibraryCompiler.Setup(Class, &CompiledData.GetPropertyAccessLibrary());
	PropertyAccessLibraryCompiler.BeginCompilation(Class);
}

void FAnimBlueprintCompilerHandler_PropertyAccess::FinishCompilingClass(const UClass* Class, IAnimBlueprintCompilationBracketContext& CompilationContext, IAnimBlueprintGeneratedClassCompiledData& CompiledData)
{
	OnPreLibraryCompiledDelegate.Broadcast();
	if (!PropertyAccessLibraryCompiler.FinishCompilation())
	{
		PropertyAccessLibraryCompiler.IterateErrors([&CompilationContext](const FText& ErrorText, UObject* Object)
		{
			// Output any property access errors as warnings
			if (Object)
			{
				CompilationContext.GetMessageLog().Warning(*ErrorText.ToString(), Object);
			}
			else
			{
				CompilationContext.GetMessageLog().Warning(*ErrorText.ToString());
			}
		});
	}
	OnPostLibraryCompiledDelegate.Broadcast(CompiledData);
}

int32 FAnimBlueprintCompilerHandler_PropertyAccess::MapCopyIndex(int32 Index) const
{
	return PropertyAccessLibraryCompiler.MapCopyIndex(Index);
