#define SOL_ALL_SAFETIES_ON 1
#include <sol/sol.hpp>

#include <iostream>
#include <functional>

int main() {
    std::cout << "=== capturing variadic arguments for later use ==="
              << std::endl;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    std::function<void()> stored_callback;

    auto capture_function = [&stored_callback](sol::function func,
                                               sol::variadic_args args) {
        stored_callback = [func,
                           captured_args = std::vector<sol::object>(args.begin(),
                                                                    args.end())]() {
            func(sol::as_args(captured_args));
        };
    };

    lua_vm.set_function("capture_function", capture_function);

    lua_vm.script(R"(
function greet_user(username)
    print(username)
end
capture_function(greet_user, "Alice")
)");
    stored_callback();

    lua_vm.script(R"(
function display_info(count, message)
    print(count, "items:", message)
end
capture_function(display_info, 5, "oranges")
)");
    stored_callback();

    std::cout << std::endl;

    return 0;
}

