static void init_map_bcast();
static void init_map_op_type();
static void init_map_avx_cc();
static void init_capstone_module(int bits_abi)
{
    int mode_val = 0;
    mode_dt_nextstone = bits_abi;
    if(bits_abi == 32)
        mode_val = CS_MODE_32;
    else
        mode_val = CS_MODE_64;
    if (cs_open(CS_ARCH_X86, mode_val, &handle_next) != CS_ERR_OK) {
        fprintf(stderr, "%s %s %d error : cs_open\n",
                __FILE__, __func__, __LINE__);
        exit(-1);
    }   
    cs_option(handle_next, CS_OPT_DETAIL, CS_OPT_ON);
}
void init_capstone_wrapper(int bits_abi)
{
#ifdef CONFIG_LATX_CAPSTONE_NEXT
    dtassert(handle != NULL);
    handle_next = handle;
#else
    init_capstone_module(bits_abi);
#endif
    init_map_op();
    init_map_reg();
    init_map_bcast();
    init_map_op_type();
    init_map_avx_cc();
}
