LayoutController::LayoutController() {
}

void LayoutController::initialize(PaneLayout* layout, ClientManager* manager, domain::Window* win) {
    m_layout = layout;
    manager->onClientAdded([=](KakouneClient* client) {
        client->onUIOptionsChanged([=](const domain::UIOptions&) {
            m_layout->arrange();
        });
        m_layout->arrange();
    });
    manager->onClientRemoved([=](KakouneClient*) {
        m_layout->arrange();
    });
    win->onResize([this, win](int w, int h) {
        m_layout->setBounds(domain::Rectangle{0, 0, (float)w, (float)h});
        m_layout->arrange();
        win->setNeedsRerender();
    });
}

