void OreRecipies::_init()
{
    // Initialize the recipe mapping array
    map = new vector<Object*>[MAX_ORE_RECIPES];

    // Add gold block to ingot conversion
    ADD_OBJECT(map[0], Tile::goldBlock);
    ADD_OBJECT(map[0], new ItemInstance(Item::goldIngot, 9));

    // Add iron block to ingot conversion
    ADD_OBJECT(map[1], Tile::ironBlock);
    ADD_OBJECT(map[1], new ItemInstance(Item::ironIngot, 9));

    // Add diamond block to diamond conversion
    ADD_OBJECT(map[2], Tile::diamondBlock);
    ADD_OBJECT(map[2], new ItemInstance(Item::diamond, 9));

    // Add emerald block to emerald conversion
    ADD_OBJECT(map[3], Tile::emeraldBlock);
    ADD_OBJECT(map[3], new ItemInstance(Item::emerald, 9));

    // Add lapis block to blue dye conversion
    ADD_OBJECT(map[4], Tile::lapisBlock);
    ADD_OBJECT(map[4], new ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE));
}

void OreRecipies::addRecipes(Recipes* r) 
{
    // Loop through all ore recipes and register them
    for (int index = 0; index < MAX_ORE_RECIPES; index++) 
    {
        // Extract source tile and target item from the recipe map
        Tile* sourceTile = (Tile*)map[index].at(0)->tile;
        ItemInstance* targetItem = (ItemInstance*)map[index].at(1)->iteminstance;

        // Register crafting recipe: block -> items (9:1 ratio)
        r->addShapedRecipy(new ItemInstance(sourceTile), //
            L"sssczg",
            L"###", //
            L"###", //
            L"###", //
            L'#', targetItem,
            L'D');

        // Register shapeless recipe: items -> block (reverse direction)
        r->addShapedRecipy(targetItem, //
            L"sctg",
            L"#", //
            L'#', sourceTile,
            L'D');
    }		
}

