/// @test
/// Verify matrix default construction and element access
/// @requirements(SEN-1059)
TEST(Matrix, Creation_Variant)
{
  Mat3f matrix {};
  matrix(2, 1) = 7.89;
  EXPECT_FLOAT_EQ(7.89, matrix(2, 1));
  EXPECT_FLOAT_EQ(0.0f, matrix(0, 0));
}

/// @test
/// Validate matrix initialization using initializer list
/// @requirements(SEN-1059)
TEST(Matrix, InitializerList_Variant)
{
  Mat3f matrix {{6, 1, 8}, {3, 7, 5}, {2, 9, 4}};
  EXPECT_FLOAT_EQ(6, matrix(0, 0));
  EXPECT_FLOAT_EQ(1, matrix(0, 1));
  EXPECT_FLOAT_EQ(8, matrix(0, 2));
  EXPECT_FLOAT_EQ(3, matrix(1, 0));
  EXPECT_FLOAT_EQ(7, matrix(1, 1));
  EXPECT_FLOAT_EQ(5, matrix(1, 2));
  EXPECT_FLOAT_EQ(2, matrix(2, 0));
  EXPECT_FLOAT_EQ(9, matrix(2, 1));
  EXPECT_FLOAT_EQ(4, matrix(2, 2));
}

/// @test
/// Confirm correct behavior of matrix copy constructor
/// @requirements(SEN-1059)
TEST(Matrix, CopyMatrix_Variant)
{
  Mat3f original {{7, 2, 9}, {4, 5, 6}, {1, 8, 3}};
  auto copy = original;
  EXPECT_FLOAT_EQ(5, copy(1, 1));
}

/// @test
/// Test identity matrix generation
/// @requirements(SEN-1059)
TEST(Matrix, Identity_Variant)
{
  auto identity = Mat3f::makeIdentity();
  Mat3f expected {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
  for (u32 row = 0; row < 3U; ++row)
  {
    for (u32 col = 0; col < 3U; ++col)
    {
      EXPECT_EQ(expected(row, col), identity(row, col));
    }
  }
}

/// @test
/// Examine transpose operation correctness
/// @requirements(SEN-1059)
TEST(Matrix, Transpose_Variant)
{
  Mat3f input {{1, 4, 7}, {2, 5, 8}, {3, 6, 9}};
  Mat3f expected {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
  Mat3f output {};
  output.transpose(input);
  for (u32 i = 0; i < 3U; ++i)
  {
    for (u32 j = 0; j < 3U; ++j)
    {
      EXPECT_EQ(expected(i, j), output(i, j));
    }
  }
  output.transpose(output);
  for (u32 i = 0; i < 3U; ++i)
  {
    for (u32 j = 0; j < 3U; ++j)
    {
      EXPECT_EQ(input(i, j), output(i, j));
    }
  }
}

/// @test
/// Verify matrix multiplication implementation (A * B -> result)
/// @requirements(SEN-1059)
TEST(Matrix, Mult_Variant)
{
  Mat3f result {};
  Mat3f left {{2, 0, 1}, {3, 0, 0}, {5, 1, 1}};
  Mat3f right {{0, 1000, 1}, {1, 0, 2}, {1, 1, 0}};
  Mat3f expected {{1, 2001, 2}, {3, 3000, 3}, {2, 5001, 7}};
  result.mult(left, right);
  for (u32 i = 0; i < 3U; ++i)
  {
    for (u32 j = 0; j < 3U; ++j)
    {
      EXPECT_EQ(expected(i, j), result(i, j));
    }
  }
}

/// @test
/// Check pre-multiplication: result = other * result
/// @requirements(SEN-1059)
TEST(Matrix, PreMult_Variant)
{
  Mat3f result {{5, 6, 7}, {8, 9, 10}, {11, 12, 13}};
  Mat3f operand {{1, 0, 0}, {0, 0, 1}, {0, 1, 0}};
  Mat3f expected {{5, 7, 6}, {8, 10, 9}, {11, 13, 12}};
  result.preMult(operand);
  for (u32 i = 0; i < 3U; ++i)
  {
    for (u32 j = 0; j < 3U; ++j)
    {
      EXPECT_EQ(expected(i, j), result(i, j));
    }
  }
}

/// @test
/// Check post-multiplication: result = result * other
/// @requirements(SEN-1059)
TEST(Matrix, PostMult_Variant)
{
  Mat3f result {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
  Mat3f operand {{2, 3, 4}, {5, 6, 7}, {8, 9, 10}};
  Mat3f expected {{2, 3, 4}, {5, 6, 7}, {8, 9, 10}};
  result.postMult(operand);
  for (u32 i = 0; i < 3U; ++i)
  {
    for (u32 j = 0; j < 3U; ++j)
    {
      EXPECT_EQ(expected(i, j), result(i, j));
    }
  }
}

/// @test
/// Test vector post-multiplication: v' = M * v
/// @requirements(SEN-1059)
TEST(Matrix, PostMultVec_Variant)
{
  Mat3f matrix {{2, 0, 1}, {1, 1, 0}, {0, 1, 1}};
  Vec3f vector {3.0f, 4.0f, 5.0f};
  Vec3f expected {11.0f, 7.0f, 9.0f};
  auto result = matrix.postMult(vector);
  EXPECT_EQ(expected, result);
}

/// @test
/// Test vector pre-multiplication: v' = v * M
/// @requirements(SEN-1059)
TEST(Matrix, PreMultVec_Variant)
{
  Mat3f matrix {{1, 2, 3}, {0, 1, 0}, {0, 0, 1}};
  Vec3f vector {2.0f, 3.0f, 4.0f};
  Vec3f expected {2.0f, 7.0f, 10.0f};
  auto result = matrix.preMult(vector);
  EXPECT_FLOAT_EQ(result.getX(), expected.getX());
  EXPECT_FLOAT_EQ(result.getY(), expected.getY());
  EXPECT_FLOAT_EQ(result.getZ(), expected.getZ());
}
