void MySubClassImpl::update(sen::kernel::RunApi& context)
{
  MyClassImpl::update(context);
  std::chrono::duration<double> elapsed = context.getTime().sinceEpoch().toChrono();
  setNextADouble(cos(elapsed.count()) * 50.0);

  switch (iteration_++ % 5)
  {
    case 0:
      setNextAVariant(MyEnum::third);
      setNextASequence({1.5f, 2.5f, 3.5f});
      break;
    case 1:
      setNextAVariant(MyEnum::first);
      setNextASequence({-1.0f, -2.0f, -3.0f, -4.0f});
      break;
    case 2:
      setNextAVariant("another text");
      setNextASequence({10.0f, 9.0f, 8.0f});
      break;
    case 3:
      setNextAVariant("yet another string");
      setNextASequence({0.1f, 0.2f, 0.3f, 0.4f});
      break;
    case 4:
      setNextAFloat(getAFloat() - 3.21f);
      setNextASequence({7.7f, 6.6f, 5.5f, 4.4f});
      break;
  }
}

