// HATCHING is an automatic flow state.
// It should not react to random buffered input.
// We explicitly drain keyboard events and clear edge flags.
void uiHatchingHandle(InputState& input)
{
  while (input.kbHasEvent())
    (void)input.kbPop();
  input.clearEdges();
}

