#include <iostream>

// Test cases for IDL scanner functionality
int main() {
    // Comment tests
    std::cout << "comment_x: /*/*/ -> tokens at (1,1,1,6) and (1,6)" << std::endl;
    std::cout << "comment_wrp_cseq: /\\n*\\n*\\n/ -> tokens at (1,1,4,2) and (4,2)" << std::endl;
    std::cout << "comment_wrp_cseq_ident: /\\n*foo\\n/bar\\n*\\n/baz -> tokens at (1,1,5,2), (5,2)-(5,5), (5,5)" << std::endl;

    // Character literal tests
    std::cout << "char_literal: 'f' -> token at (1,1,1,4)" << std::endl;
    std::cout << "char_literal_wrp_cseq: '\\n\\n' -> token at (1,1,2,2)" << std::endl;

    // String literal tests
    std::cout << "string_literal: \"foo bar baz\" -> token at (1,1,1,14)" << std::endl;
    std::cout << "string_literal_wrp_seq: \"foo bar baz\\n\" -> token at (1,1,2,2)" << std::endl;

    // Integer literal tests
    std::cout << "integer_literal: 1 -> token at (1,1,1,1,2)" << std::endl;
    std::cout << "integer_literal_hex_dot: 0x1. -> hex token at (0x1,1,1,1,4), dot at (1,4,1,5)" << std::endl;

    // Floating point literal tests
    std::cout << "floating_pt_literal: 1\\n23. -> token at (123.0,1,1,2,4)" << std::endl;
    std::cout << "floating_pt_literal_dot_fraction: .1 -> token at (.1,1,1,1,3)" << std::endl;
    std::cout << "floating_pt_literal_int_dot_fraction_exp: 1.1e+3 -> token at (1.1e3,1,1,1,7)" << std::endl;
    std::cout << "floating_pt_literal_int_dot_fraction: 1.1e-3e3 -> token at (1.1e-3,1,1,1,7), 'e3' at (1,7,1,9)" << std::endl;

    // Identifier tests
    std::cout << "ident: a -> token at (1,1,1,2)" << std::endl;
    std::cout << "ident_tr_cseq: a\\r\\n -> token at (1,1,1,2)" << std::endl;
    std::cout << "ident_wrp_cseq: \\na\\r\\nb\\n -> token at (2,1,3,2)" << std::endl;

    // Scope operator tests
    std::cout << "scope: :: -> token at (1,1,1,3)" << std::endl;
    std::cout << "scope_wrp_cseq: \\n:\\r\\n:\\n -> token at (2,1,3,2)" << std::endl;

    // Scoped name with left scope (IDL_TOKEN_SCOPE_L)
    std::cout << "scope_l: foo:: -> token at (1,1,1,4), (1,4,1,6)" << std::endl;
    std::cout << "scope_l_wrp_cseq: foo\\n:: -> token at (1,1,1,4), (2,1,2,3)" << std::endl;
    std::cout << "scope_non_l: foo :: -> token at (1,1,1,4), (1,5,1,7)" << std::endl;

    // Scoped name with right scope (IDL_TOKEN_SCOPE_R)
    std::cout << "scope_r: ::foo -> token at (1,1,1,3), (1,3,1,6)" << std::endl;
    std::cout << "scope_r_wrp_cseq: ::\\r\\nfoo -> token at (1,1,1,3), (2,1,2,4)" << std::endl;
    std::cout << "scope_non_r: :: foo -> token at (1,1,1,3), (1,4,1,7)" << std::endl;

    // Scoped name with both scopes (IDL_TOKEN_SCOPE_LR)
    std::cout << "scope_lr: foo::bar -> tokens at (1,1,1,4), (1,4,1,6), (1,6,1,9)" << std::endl;
    std::cout << "scope_lr_wrp_cseq: foo\\n::\\r\\nbar -> tokens at (1,1,1,4), (2,1,2,3), (3,1,3,4)" << std::endl;
    std::cout << "scope_non_lr: foo :: bar -> tokens at (1,1,1,4), (1,5,1,7), (1,8,1,11)" << std::endl;
    std::cout << "scope_non_lr_l: foo:: bar -> tokens at (1,1,1,4), (1,4,1,6), (1,7,1,10)" << std::endl;
    std::cout << "scope_non_lr_r: foo ::bar -> tokens at (1,1,1,4), (1,5,1,7), (1,7,1,10)" << std::endl;

    // Preprocessor directive tests
    std::cout << "hash_line: #line\\n 1 -> tokens at (1,1,1,2), (1,2,1,6), (2,2,2,3)" << std::endl;
    std::cout << "hash_pragma: #pragma keylist foo bar baz\\n -> multiple tokens including pragma, keylist, identifiers" << std::endl;

    return 0;
}

