DEFINE_ENUM_WITH_UNDERLYING_TYPE(EDirection, signed char,
    ((Left)   (0))
    ((Up)     (1))
    ((Right)  (2))
    ((Down)   (3))
);

DEFINE_BIT_ENUM_WITH_UNDERLYING_TYPE(EFlags, ui16,
    ((Empty)    (0x0000))
    ((FlagA)    (0x0001))
    ((FlagB)    (0x0004))
    ((FlagC)    (0x0008))
);

DEFINE_BIT_ENUM(EProgrammingLanguages,
    ((None)       (0x00))
    ((Java)       (0x01))
    ((CSharp)     (0x02))
    ((TypeScript) (0x04))
    ((Swift)      (0x08))
    ((Kotlin)     (0x10))
    ((JavaCSharp) (0x03))
    ((All)        (0x1f))
    ((UnknownLang)(0x20))
);

DEFINE_ENUM_UNKNOWN_VALUE(EProgrammingLanguages, UnknownLang);
DEFINE_ENUM(EStatusWithFallback,
    ((Active)   (0))
    ((Inactive) (1))
    ((UnknownStatus) (2))
);
DEFINE_ENUM_UNKNOWN_VALUE(EStatusWithFallback, UnknownStatus);

TEST(TCastTest, TryCheckedEnumCast_Variants)
{
    EXPECT_EQ((TryCheckedEnumCast<EDirection, signed char>(1)), EDirection::Up);
    EXPECT_EQ((TryCheckedEnumCast<EDirection, int>(3)), EDirection::Down);
    EXPECT_FALSE((TryCheckedEnumCast<EDirection, signed char>(5)));
    EXPECT_FALSE((TryCheckedEnumCast<EDirection, int>(7)));

    EXPECT_EQ((TryCheckedEnumCast<EFlags, ui16>(0)), EFlags::Empty);
    EXPECT_EQ((TryCheckedEnumCast<EFlags, ui16>(ToUnderlying(EFlags::FlagA))), EFlags::FlagA);
    EXPECT_EQ((TryCheckedEnumCast<EFlags, ui16>(ToUnderlying(EFlags::FlagB))), EFlags::FlagB);
    EXPECT_EQ((TryCheckedEnumCast<EFlags, int>(ToUnderlying(EFlags::FlagC))), EFlags::FlagC);
    EXPECT_EQ((TryCheckedEnumCast<EFlags, ui16>(ToUnderlying(EFlags::FlagA | EFlags::FlagB))), EFlags::FlagA | EFlags::FlagB);
    EXPECT_FALSE((TryCheckedEnumCast<EFlags, ui16>(0x10)));
    EXPECT_FALSE(TryCheckedEnumCast<EStatusWithFallback>(3));
    EXPECT_EQ(TryCheckedEnumCast<EStatusWithFallback>(3, /*allowUnknown*/ true), EStatusWithFallback::UnknownStatus);
    EXPECT_FALSE(TryCheckedEnumCast<EProgrammingLanguages>(0x40));
    EXPECT_EQ(TryCheckedEnumCast<EProgrammingLanguages>(0x40, /*allowUnknown*/ true), EProgrammingLanguages::UnknownLang);
    EXPECT_EQ(TryCheckedEnumCast<EProgrammingLanguages>(0x41, /*allowUnknown*/ true), EProgrammingLanguages::UnknownLang | EProgrammingLanguages::Java);
}

TEST(TCastTest, CheckedEnumCast_Variants)
{
    EXPECT_EQ((CheckedEnumCast<EDirection, signed char>(2)), EDirection::Right);
    EXPECT_EQ((CheckedEnumCast<EDirection, int>(0)), EDirection::Left);
    EXPECT_THROW((CheckedEnumCast<EDirection, signed char>(10)), TSimpleException);
    EXPECT_THROW((CheckedEnumCast<EDirection, int>(20)), TSimpleException);

    EXPECT_EQ((CheckedEnumCast<EFlags, ui16>(0)), EFlags::Empty);
    EXPECT_EQ((CheckedEnumCast<EFlags, ui16>(ToUnderlying(EFlags::FlagA))), EFlags::FlagA);
    EXPECT_EQ((CheckedEnumCast<EFlags, ui16>(ToUnderlying(EFlags::FlagB))), EFlags::FlagB);
    EXPECT_EQ((CheckedEnumCast<EFlags, int>(ToUnderlying(EFlags::FlagA))), EFlags::FlagA);
    EXPECT_EQ((CheckedEnumCast<EFlags, ui16>(ToUnderlying(EFlags::FlagA | EFlags::FlagC))), EFlags::FlagA | EFlags::FlagC);
    EXPECT_THROW((CheckedEnumCast<EFlags, ui16>(0x20)), TSimpleException);
    EXPECT_EQ(CheckedEnumCast<EStatusWithFallback>(2), EStatusWithFallback::UnknownStatus);
    EXPECT_EQ(CheckedEnumCast<EProgrammingLanguages>(0x40), EProgrammingLanguages::UnknownLang);
    EXPECT_EQ(CheckedEnumCast<EProgrammingLanguages>(0x42), EProgrammingLanguages::UnknownLang | EProgrammingLanguages::CSharp);
}

TEST(TCastTest, IntegralRangeChecks)
{
    static_assert(CanFitSubtype<i64, i16>());
    static_assert(CanFitSubtype<ui64, ui16>());
    static_assert(CanFitSubtype<ui32, ui32>());
    static_assert(!CanFitSubtype<ui32, i16>());
    static_assert(!CanFitSubtype<i16, i64>());

    static_assert(IsInIntegralRange<ui16>(0));
    static_assert(IsInIntegralRange<ui16>(1ull));
    static_assert(!IsInIntegralRange<ui16>(-1));
    static_assert(!IsInIntegralRange<i16>(std::numeric_limits<i64>::max()));
    static_assert(IsInIntegralRange<i16>(1ull));
    static_assert(IsInIntegralRange<i16>(-1));
    static_assert(!IsInIntegralRange<ui16>(-1));
    static_assert(!IsInIntegralRange<ui16>(std::numeric_limits<i64>::max()));
    static_assert(IsInIntegralRange<ui64>(std::numeric_limits<i64>::max()));
}
