/// @brief Compute CRC32 checksum for the given data buffer.
/// @param buffer pointer to the input data.
/// @param size number of bytes to process.
/// @return CRC32 checksum of the input data.
UInt32 compute_crc32(const VoidPtr buffer, Int32 size) {
  if (!buffer) return ~0;
  UInt32 checksum = 0xffffffff;
  Char* data = static_cast<Char*>(buffer);
  while ((size--) > 0) checksum = (checksum >> 8) ^ crc_lookup_table[(checksum ^ *(data++)) & 0xFF];
  return ~checksum;
}
