void *safe_increment(void *arg) {
  for (int j = 0; j < 1000; j++) {
    pthread_mutex_lock(&mutex_lock);
    global_counter += 1;  // Safely incremented under lock
    pthread_mutex_unlock(&mutex_lock);
  }
  return NULL;
}

void *unsafe_increment(void *arg) {
  for (int j = 0; j < 1000; j++) {
    global_counter++;  // Unsafe: no synchronization, causes race condition
  }
  return NULL;
}

int main(void) {
  pthread_t thread_a, thread_b;
  pthread_mutex_init(&mutex_lock, NULL);

  pthread_create(&thread_a, NULL, safe_increment, NULL);
  pthread_create(&thread_b, NULL, unsafe_increment, NULL);

  pthread_join(thread_a, NULL);
  pthread_join(thread_b, NULL);

  printf("Final counter value: %d\n", global_counter);
  pthread_mutex_destroy(&mutex_lock);
  return 0;
}

