std::error_code
ConverterEBCDIC::convertToEBCDIC(StringRef InputData,
                                 SmallVectorImpl<char> &OutputBuffer) {
  assert(OutputBuffer.empty() && "Output buffer must be empty!");

  // Select the translation table for conversion
  const unsigned char *TranslationTable = Latin1ToEBCDIC;
  const unsigned char *CurrentBytePtr =
      reinterpret_cast<const unsigned char *>(InputData.data());
  size_t RemainingBytes = InputData.size();

  // Pre-allocate output buffer space
  OutputBuffer.reserve(RemainingBytes);

  while (RemainingBytes--) {
    unsigned char CurrentChar = *CurrentBytePtr++;

    // Handle UTF-8 multi-byte sequences in input
    if (CurrentChar >= 128) {
      // Only support two-byte UTF-8 sequences
      if (CurrentChar != 0xc2 && CurrentChar != 0xc3)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Check if we have enough bytes remaining
      if (!RemainingBytes)
        return std::make_error_code(std::errc::invalid_argument);

      unsigned char NextByte = *CurrentBytePtr++;

      // Validate continuation byte format (must be 0x80-0xBF)
      if ((NextByte & 0xc0) != 0x80)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Combine bytes into single Unicode code point
      CurrentChar = NextByte | (CurrentChar << 6);
      RemainingBytes--;
    }

    // Apply character translation
    CurrentChar = TranslationTable[CurrentChar];
    OutputBuffer.push_back(static_cast<char>(CurrentChar));
  }

  return std::error_code();
}

void ConverterEBCDIC::convertToUTF8(StringRef InputData,
                                    SmallVectorImpl<char> &OutputBuffer) {
  assert(OutputBuffer.empty() && "Output buffer must be empty!");

  // Select reverse translation table
  const unsigned char *TranslationTable = EBCDICToLatin1;
  const unsigned char *CurrentBytePtr =
      reinterpret_cast<const unsigned char *>(InputData.data());
  size_t RemainingBytes = InputData.size();

  // Pre-allocate output buffer space
  OutputBuffer.reserve(RemainingBytes);

  while (RemainingBytes--) {
    unsigned char CurrentChar = *CurrentBytePtr++;

    // Translate from EBCDIC to Latin-1
    CurrentChar = TranslationTable[CurrentChar];

    // Convert Latin-1 characters to UTF-8 when needed
    if (CurrentChar >= 128) {
      // First byte: prefix with 0xC0 and upper 6 bits
      OutputBuffer.push_back(static_cast<char>(0xc0 | (CurrentChar >> 6)));
      // Second byte: mask lower 6 bits
      CurrentChar = CurrentChar & 0xbf;
    }

    OutputBuffer.push_back(static_cast<char>(CurrentChar));
  }
}

