#include <Alembic/Abc/All.h>
#include <Alembic/AbcCoreOgawa/All.h>
#include <Alembic/AbcMaterial/OMaterial.h>
#include <Alembic/AbcMaterial/IMaterial.h>
#include <Alembic/AbcMaterial/MaterialFlatten.h>
#include "PrintMaterial.h"

namespace Abc = Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;

void createMaterials()
{
    Abc::OArchive archive(
            Alembic::AbcCoreOgawa::WriteArchive(), "FlattenMaterial.abc" );
    Abc::OObject root(archive, Abc::kTop);

    // Create a container object for materials
    Abc::OObject matContainer(root, "materials");
    Mat::OMaterial baseMaterial(matContainer, "baseMaterial");

    baseMaterial.getSchema().setShader("prman", "surface", "plastic");
    baseMaterial.getSchema().setShader("prman", "displacement", "rough");

    {
        Abc::OFloatProperty prop(
                baseMaterial.getSchema().getShaderParameters(
                        "prman", "surface"),
                        "Ks");
        prop.set(0.3);
    }
    {
        Abc::OStringProperty prop(
                baseMaterial.getSchema().getShaderParameters(
                        "prman", "surface"), "mapfile");
        prop.set("wood");
    }
    {
        Abc::OFloatProperty prop(
                baseMaterial.getSchema().getShaderParameters(
                        "prman", "displacement"),
                        "amplitude");
        prop.set(1.25);
    }

    Mat::OMaterial derivedMaterial(baseMaterial, "derivedMaterial");
    derivedMaterial.getSchema().setShader("prman", "surface",
            "glossyplastic");
    {
        Abc::OStringProperty prop(
                derivedMaterial.getSchema().getShaderParameters(
                        "prman", "surface"), "mapfile");
        prop.set("marble");
    }
}

void inspectMaterials()
{
    Abc::IArchive archive(Alembic::AbcCoreOgawa::ReadArchive(),
            "FlattenMaterial.abc");
    Abc::IObject matObj(archive.getTop(), "materials");
    Mat::IMaterial baseMaterial(matObj, "baseMaterial");
    Mat::IMaterial derivedMaterial(baseMaterial, "derivedMaterial");

    std::cout << "========================================\n";
    std::cout << "LOCAL MATERIALS\n";
    std::cout << "----------------------------------------\n";
    std::cout << "Base material definition:\n";
    printMaterialSchema(baseMaterial.getSchema());
    std::cout << "\nDerived material definition:\n";
    printMaterialSchema(derivedMaterial.getSchema());

    std::cout << "\n========================================\n";
    std::cout << "FLATTENED MATERIALS\n";
    printFlattenedMaterial(baseMaterial);
    printFlattenedMaterial(derivedMaterial);
}

int main(int argc, char *argv[])
{
    createMaterials();
    inspectMaterials();
    return 0;
}

