TEST_F(TrieTestSuite, VectorArithmeticInstructionsYieldVALU)
{
    EXPECT_EQ(Trie::instruction_category("v_add_f32", 10), InstCategory::VALU);
    EXPECT_EQ(Trie::instruction_category("v_mul_f16", 11), InstCategory::VALU);
    EXPECT_EQ(Trie::instruction_category("v_cmp_eq_u32", 12), InstCategory::VALU);
