{
    EXPECT_EQ(Trie::instruction_category("image_load v0, v[1:2], s[0:7]", 10), InstCategory::VMEM);
    EXPECT_EQ(Trie::instruction_category("image_store v0, v[1:2], s[0:7]", 11), InstCategory::VMEM);
    EXPECT_EQ(Trie::instruction_category("image_atomic_add v0, v[1:2], s[0:7]", 12), InstCategory::VMEM);
    EXPECT_EQ(Trie::instruction_category("image_gather4 v[0:3], v[1:2], s[0:7]", 10), InstCategory::VMEM);
    EXPECT_EQ(Trie::instruction_category("image_sample v0, v[1:2], s[0:7], s[8:11]", 11), InstCategory::VMEM);
}

// MFMA scale on non-GFX9 targets maps to VALU
TEST_F(TrieTestSuite, MfmaScaleFallbackOnNonGfx9)
{
    EXPECT_EQ(Trie::instruction_category("v_mfma_scale_f32_32x32x64_f8f6f4", 11), InstCategory::VALU);
    EXPECT_EQ(Trie::instruction_category("v_mfma_scale_f32_32x32x64_f8f6f4", 12), InstCategory::VALU);
}

// Branch detection is case-sensitive and handles operands correctly
TEST_F(TrieTestSuite, BranchRecognitionAcrossContexts)
{
    EXPECT_EQ(Trie::instruction_category("s_cbranch_vccz 0x10", 10), InstCategory::BRANCH);
    EXPECT_EQ(Trie::instruction_category("s_cbranch_vccnz label", 11), InstCategory::BRANCH);
    EXPECT_EQ(Trie::instruction_category("s_cbranch_cdbgsys", 12), InstCategory::BRANCH);
}

