    glLoadModel("debug/debug.glg", nullptr);
    glLoadModel("effects/meshes.glg", nullptr);
    glLoadTextureBundle("effects/effects.glt");
    ShadowStartup();
    EmissionManager::Startup(GLV_Particles);
    fxLoadTemplateBundle("art/effects/templates.fx");
    fxLoadGroupBundle("art/effects/scripts.fx");
    fxParticleStartup(2048);
    return true;
}

#include <stdio.h>

struct student {
    int mark1, mark2, mark3;
    char fullName[30];
    float sum;
};

int main() {
    struct student record;

    printf("Enter your name and marks for m1, m2, m3:\n");
    scanf("%s %d %d %d", record.fullName, &record.mark1, &record.mark2, &record.mark3);

    record.sum = record.mark1 + record.mark2 + record.mark3;

    printf("Name=%s\nMarks: %d %d %d\nTotal=%.2f\n", 
           record.fullName, record.mark1, record.mark2, record.mark3, record.sum);

    return 0;
}

