#include <cmath>

// Compute the length of the diagonal of the axis-aligned bounding box
IGL_INLINE double igl::bounding_box_diagonal(
  const Eigen::MatrixXd & points)
{
  using namespace Eigen;
  VectorXd max_vals, min_vals;
  VectorXi max_idx, min_idx;

  mat_max(points, 1, max_vals, max_idx);
  mat_min(points, 1, min_vals, min_idx);

  return sqrt((max_vals - min_vals).array().pow(2).sum());
}
