#include<vector>
using namespace std;

// Perform selection sort on the array
void selectionSort(vector<int>& data, int size) {
    for (int index = 0; index < size - 1; index++) {
        int minPos = index;
        for (int j = index + 1; j < size; j++) {
            if (data[j] < data[minPos]) {
                minPos = j;
            }
        }
        swap(data[minPos], data[index]);
    }
}

