{
	return BuildEncoding(DM_BinaryOp,PRM_R0,PRM_UIMM8,op,haswrite);
}
static u64 Encode_shift(s32 offset,bool arithm)
{
	if (offset>0)
	{
		//left shift
		return BuildEncoding(DM_Shift,PRM_RN,PRM_RN,shop_shl,offset);
	}
	else
	{
		return BuildEncoding(DM_Shift,PRM_RN,PRM_RN,arithm?shop_sar:shop_shr,-offset);
	}

}

static u64 Encode_cmp(shilop op, DecParam s1,DecParam s2)
{
