    // Reflection setup for camera_component
    REFLECT(camera_component)
    {
        auto ortho_check = entt::property_predicate<bool>(
            [](const entt::meta_any& val)    
            {
                return val.try_cast<camera_component>()->get_projection_mode() == projection_mode::orthographic;
            });

        auto perspective_check = entt::property_predicate<bool>(
            [](const entt::meta_any& val)
            {
                return val.try_cast<camera_component>()->get_projection_mode() == projection_mode::perspective;
            });

        entt::meta_factory<camera_component>{}
            .type("camera_component"_hs)
            .custom<entt::attributes>(entt::attributes{
