void computeParsimonyAnalysis(Params &config) {
    Alignment dataset(config.aln_file, config.sequence_type, config.intype, "");
    dataset.orderPatternByNumChars(PAT_VARIANT);
    ParsTree phylogeny;
    phylogeny.readTree(config.user_file, config.is_rooted);
    if (phylogeny.rooted)
        phylogeny.convertToUnrooted();
    phylogeny.setAlignment(&dataset);
    phylogeny.initCostMatrix(CM_LINEAR);
    phylogeny.setParsimonyKernel(config.SSE);
    phylogeny.initializeAllPartialPars();
    int overall_length = phylogeny.computeParsimony();
    std::cout << "total length: " << overall_length << std::endl;
    phylogeny.initCostMatrix(CM_UNIFORM);
    int score_parsimony = phylogeny.computeParsimony();
    std::cout.unsetf(std::ios::fixed);
    std::cout.precision(6);
    std::cout << "mean length: " << double(overall_length)/score_parsimony << std::endl;
    std::cout << "Parsimony score is: " << score_parsimony << std::endl;
	//std::cout << "Parsimony score ver2 is: " << phylogeny.computeParsimony() << std::endl;
	//phylogeny.printParsimonyStates();
}

