#include <fenv.h>

// Set floating-point exception flags according to mask
int fesetexceptflag(const fexcept_t *flag_ptr, int exception_mask)
{
    // Clear exceptions not in flag but in mask
    feclearexcept(exception_mask & ~(*flag_ptr));

    // Raise exceptions present in both flag and mask
    feraiseexcept(exception_mask & (*flag_ptr));

    return 0;
}

