vector<ESection_Variable> RetrieveVariables(LPBYTE& ptr, bool skip = false) {
    vector<ESection_Variable> resultArray;
    UINT varCount = GetData<UINT>(ptr);
    UINT dataLength = GetData<UINT>(ptr);
    LPBYTE savedPtr = ptr + dataLength;

    if (!skip) {
        resultArray = vector<ESection_Variable>(varCount);
        ETAG* tagArray = new ETAG[varCount];
        LPBYTE* offsetList = new LPBYTE[varCount];

        for (size_t i = 0; i < varCount; ++i)
            tagArray[i] = GetData<ETAG>(ptr);

        LPBYTE tempPtr = ptr + varCount * sizeof(UINT);
        for (size_t i = 0; i < varCount; ++i)
            offsetList[i] = tempPtr + GetData<UINT>(ptr);

        for (size_t i = 0; i < varCount; ++i) {
            ESection_Variable var;
            ptr = offsetList[i];
            UINT varSize = GetData<UINT>(ptr);
            var.Tag = tagArray[i];
            var.DataType = GetData<DataType>(ptr);
            var.Attributes = GetData<EVariableAttr>(ptr);
            var.ArrayInfo.Dimension = GetData<BYTE>(ptr);

            for (size_t n = 0; n < var.ArrayInfo.Dimension; ++n)
                var.ArrayInfo.Subscript.push_back(GetData<UINT>(ptr));

            var.Name = GetAutoString(ptr);
            var.Remark = GetAutoString(ptr);
            resultArray[i] = var;
        }

        delete[] tagArray;
        delete[] offsetList;
    }

    ptr = savedPtr;
    return resultArray;
}

vector<ESection_Program_Assembly> RetrieveAssemblies(LPBYTE& ptr, bool isClass = true) {
    vector<ESection_Program_Assembly> assemblyArray;
    UINT totalLength = GetData<UINT>(ptr) / 2;
    size_t count = totalLength / sizeof(ETAG);
    ETAG* tagBuffer = new ETAG[count];

    for (size_t i = 0; i < count; ++i)
        tagBuffer[i] = GetData<ETAG>(ptr);

    ptr += totalLength;

    for (size_t i = 0; i < count; ++i) {
        ESection_Program_Assembly assembly;
        assembly.Tag = tagBuffer[i];

        if (assembly.Tag.Type2 == ETYPES::WindowClass) {
            assembly.Base = GetData<ETAG>(ptr);
            ptr += 4;
        } else {
            assembly.Status = GetData<ETagStatus>(ptr);
            if (isClass)
                assembly.Base = GetData<ETAG>(ptr);
        }

        assembly.Name = GetString(ptr);
        assembly.Remark = GetString(ptr);

        if (isClass) {
            totalLength = GetData<UINT>(ptr);
            size_t methodCount = totalLength / sizeof(ETAG);
            for (size_t n = 0; n < methodCount; ++n)
                assembly.Methods.push_back(GetData<ETAG>(ptr));
        }

        assembly.Variables = RetrieveVariables(ptr);
        assemblyArray.push_back(assembly);
    }

    delete[] tagBuffer;
    return assemblyArray;
}

vector<ESection_Program_Method> RetrieveMethods(LPBYTE& ptr) {
    vector<ESection_Program_Method> methodArray;
    UINT totalLength = GetData<UINT>(ptr) / 2;
    size_t count = totalLength / sizeof(ETAG);
    ETAG* tagBuffer = new ETAG[count];

    for (size_t i = 0; i < count; ++i)
        tagBuffer[i] = GetData<ETAG>(ptr);

    ptr += totalLength;

    for (size_t i = 0; i < count; ++i) {
        ESection_Program_Method method;
        method.Tag = tagBuffer[i];
        method.Class = GetData<ETAG>(ptr);
        method.Attributes = GetData<EMethodAttr>(ptr);
        method.ReturnType = GetData<DataType>(ptr);
        method.Name = GetString(ptr);
        method.Remark = GetString(ptr);
        method.Variables = RetrieveVariables(ptr);
        method.Parameters = RetrieveVariables(ptr);
        method.RowOffset = GetBytes(ptr);
        method.FlowOffset = GetBytes(ptr);
        method.MethodOffset = GetBytes(ptr);
        method.VariableOffset = GetBytes(ptr);
        method.ParameterOffset = GetBytes(ptr);
        method.Code = GetBytes(ptr);
        methodArray.push_back(method);
    }

    delete[] tagBuffer;
    return methodArray;
}

vector<ESection_Program_Dll> RetrieveDlls(LPBYTE& ptr) {
    vector<ESection_Program_Dll> dllArray;
    UINT totalLength = GetData<UINT>(ptr) / 2;
    size_t count = totalLength / sizeof(ETAG);
    ETAG* tagBuffer = new ETAG[count];

    for (size_t i = 0; i < count; ++i)
        tagBuffer[i] = GetData<ETAG>(ptr);

    ptr += totalLength;

    for (size_t i = 0; i < count; ++i) {
        ESection_Program_Dll dll;
        dll.Tag = tagBuffer[i];
        dll.Status = GetData<ETagStatus>(ptr);
        dll.ReturnType = GetData<DataType>(ptr);
        dll.ShowName = GetString(ptr);
        dll.Remark = GetString(ptr);
        dll.Lib = GetString(ptr);
        dll.Name = GetString(ptr);
        dll.Parameters = RetrieveVariables(ptr);
        dllArray.push_back(dll);
    }

    delete[] tagBuffer;
    return dllArray;
}

void WriteVariableVector(ostream* stream, vector<ESection_Variable>& list) {
    ostringstream tagStream(NULL, 0, ios::binary);
    ostringstream offsetStream(NULL, 0, ios::binary);
    ostringstream dataStream(NULL, 0, ios::binary);

    for (ESection_Variable& item : list) {
        tagStream.write(C(&item.Tag), sizeof(ETAG));
        UINT len = dataStream.pcount();
        offsetStream.write(C(&len), sizeof(UINT));

        ostringstream buffer(NULL, 0, ios::binary);
        buffer.write(C(&item.DataType), sizeof(DataType));
        buffer.write(C(&item.Attributes), sizeof(EVariableAttr));
        buffer.write(C(&item.ArrayInfo.Dimension), sizeof(BYTE));
        buffer.write(C(item.ArrayInfo.Subscript.begin()._Ptr), item.ArrayInfo.Dimension * sizeof(UINT));
        WriteAutoString(&buffer, item.Name);
        WriteAutoString(&buffer, item.Remark);

        len = buffer.pcount();
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(buffer.str(), len);
    }

    UINT length = list.size();
    stream->write(C(&length), sizeof(UINT));

    length = tagStream.pcount() + offsetStream.pcount() + dataStream.pcount();
    stream->write(C(&length), sizeof(UINT));
    stream->write(tagStream.str(), tagStream.pcount());
    stream->write(offsetStream.str(), offsetStream.pcount());
    stream->write(dataStream.str(), dataStream.pcount());
}

void WriteAssemblyVector(ostream* stream, vector<ESection_Program_Assembly>& list) {
    ostringstream tagStream(NULL, 0, ios::binary);
    ostringstream offsetStream(NULL, 0, ios::binary);
    ostringstream dataStream(NULL, 0, ios::binary);

    for (ESection_Program_Assembly& item : list) {
        tagStream.write(C(&item.Tag), sizeof(ETAG));
        UINT len = dataStream.pcount();
        offsetStream.write(C(&len), sizeof(UINT));

        if (item.Tag.Type2 == ETYPES::WindowClass) {
            dataStream.write(C(&item.Base), sizeof(ETAG));
            len = 0;
            dataStream.write(C(&len), sizeof(UINT));
        } else {
            dataStream.write(C(&item.Status), sizeof(ETagStatus));
            dataStream.write(C(&item.Base), sizeof(ETAG));
        }

        WriteString(&dataStream, item.Name);
        WriteString(&dataStream, item.Remark);

        len = item.Methods.size() * sizeof(ETAG);
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(C(item.Methods.begin()._Ptr), len);

        WriteVariableVector(&dataStream, item.Variables);
    }

    UINT length = tagStream.pcount() + offsetStream.pcount();
    stream->write(C(&length), sizeof(UINT));
    stream->write(tagStream.str(), tagStream.pcount());
    stream->write(offsetStream.str(), offsetStream.pcount());
    stream->write(dataStream.str(), dataStream.pcount());
}

void WriteMethodVector(ostream* stream, vector<ESection_Program_Method>& list) {
    ostringstream tagStream(NULL, 0, ios::binary);
    ostringstream offsetStream(NULL, 0, ios::binary);
    ostringstream dataStream(NULL, 0, ios::binary);

    for (ESection_Program_Method& item : list) {
        tagStream.write(C(&item.Tag), sizeof(ETAG));
        UINT len = dataStream.pcount();
        offsetStream.write(C(&len), sizeof(UINT));

        dataStream.write(C(&item.Class), sizeof(ETAG));
        dataStream.write(C(&item.Attributes), sizeof(EMethodAttr));
        dataStream.write(C(&item.ReturnType), sizeof(DataType));
        WriteString(&dataStream, item.Name);
        WriteString(&dataStream, item.Remark);
        WriteVariableVector(&dataStream, item.Variables);
        WriteVariableVector(&dataStream, item.Parameters);

        len = item.RowOffset.size() * sizeof(BYTE);
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(C(item.RowOffset.begin()._Ptr), len);

        len = item.FlowOffset.size() * sizeof(BYTE);
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(C(item.FlowOffset.begin()._Ptr), len);

        len = item.MethodOffset.size() * sizeof(BYTE);
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(C(item.MethodOffset.begin()._Ptr), len);

        len = item.VariableOffset.size() * sizeof(BYTE);
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(C(item.VariableOffset.begin()._Ptr), len);

        len = item.ParameterOffset.size() * sizeof(BYTE);
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(C(item.ParameterOffset.begin()._Ptr), len);

        len = item.Code.size() * sizeof(BYTE);
        dataStream.write(C(&len), sizeof(UINT));
        dataStream.write(C(item.Code.begin()._Ptr), len);
    }

    UINT length = tagStream.pcount() + offsetStream.pcount();
    stream->write(C(&length), sizeof(UINT));
    stream->write(tagStream.str(), tagStream.pcount());
    stream->write(offsetStream.str(), offsetStream.pcount());
    stream->write(dataStream.str(), dataStream.pcount());
}

