void ParseProgram(LPBYTE ptr, LPBYTE end, int type, ostream* outStream) {
    LPBYTE start = ptr;
    ptr += sizeof(UINT);
    ptr += sizeof(UINT);
    GetBytes(ptr, true);
    GetBytes(ptr, true);
    GetBytes(ptr, true);

    USHORT length = GetData<USHORT>(ptr);
    for (size_t i = 0; i < length; ++i)
        GetString(ptr, true);

    int flag = GetData<int>(ptr);
    ptr += sizeof(UINT);

    if ((flag & 1) != 0) ptr += 16;

    GetBytes(ptr, true);
    GetBytes(ptr, true);

    outStream->write(C(start), ptr - start);

    vector<ESection_Program_Assembly> assemblies = RetrieveAssemblies(ptr);
    vector<ESection_Program_Method> methods = RetrieveMethods(ptr);

    if (type == 0) {
        vector<string*> list;
        for (ESection_Program_Assembly& item : assemblies)
            if ((item.Status & ETagStatus::C_External) == 0 && item.Remark.empty())
                list.push_back(&item.Remark);

        for (ESection_Program_Method& item : methods) {
            if ((item.Attributes & EMethodAttr::M_External) == 0 && item.Remark.empty()) {
                size_t index = GenerateRandom<size_t>(0, list.size());
                list.insert(list.begin() + index, &item.Remark);
            }
        }

        if (list.size()) {
            for (size_t i = min(m_count, list.size()); i > 0; --i) {
                size_t index = GenerateRandom<size_t>(0, i - 1);
                list[index]->append(join(GetRandomCopyright[redacted]
                list.erase(list.begin() + index);
            }
        }
    } else if (type == 1) {
        vector<ESection_Program_Method*> list;
        for (ESection_Program_Method& item : methods)
            if ((item.Attributes & EMethodAttr::M_External) == 0)
                list.push_back(&item);

        for (size_t i = min(m_count, list.size()); i > 0; --i) {
            size_t index = GenerateRandom<size_t>(0, i - 1);
            string remark;
            vector<UINT> row;

            for (string& line : GetRandomCopyright[redacted]
                row.push_back(remark.length());
                remark.append("\x6a\x00\x00\x00\x00\xff\xff\x00\x00\x00\x00\x00\x00", 13);
                UINT len = line.length() + 1;
                remark.append(C(&len), 4);
                remark.append(line.c_str(), len);
                remark.append("\x36\x01", 2);
            }

            ESection_Program_Method* methodItem = list[index];
            UINT len = remark.length();
            LPBYTE p = methodItem->RowOffset.begin()._Ptr;
            size_t size = methodItem->RowOffset.size() / sizeof(UINT);

            for (size_t i = 0; i < size; ++i, p += sizeof(UINT))
                *(LPUINT)p += len;

            methodItem->RowOffset.insert(methodItem->RowOffset.begin(), 
                ((vector<BYTE>*)&row)->begin(), ((vector<BYTE>*)&row)->end());

            p = methodItem->FlowOffset.begin()._Ptr;
            size = methodItem->FlowOffset.size() / (sizeof(BYTE) + sizeof(UINT) + sizeof(UINT));

            for (size_t i = 0; i < size; ++i, p += sizeof(BYTE) + sizeof(UINT) + sizeof(UINT)) {
                *(LPUINT)(p + sizeof(BYTE)) += len;
                *(LPUINT)(p + sizeof(BYTE) + sizeof(UINT)) += len;
            }

            p = methodItem->MethodOffset.begin()._Ptr;
            size = methodItem->MethodOffset.size() / sizeof(UINT);

            for (size_t i = 0; i < size; ++i, p += sizeof(UINT))
                *(LPUINT)p += len;

            p = methodItem->VariableOffset.begin()._Ptr;
            size = methodItem->VariableOffset.size() / sizeof(UINT);

            for (size_t i = 0; i < size; ++i, p += sizeof(UINT))
                *(LPUINT)p += len;

            list[index]->Code.insert(list[index]->Code.begin(), remark.begin(), remark.end());
            list.erase(list.begin() + index);
        }
    }

    WriteAssemblyVector(outStream, assemblies);
    WriteMethodVector(outStream, methods);
    outStream->write(C(ptr), end - ptr);
}

void Parse(LPBYTE data, size_t size, int type, ostream* outStream) {
    EFile_Header header;
    memcpy(&header, data, sizeof(EFile_Header));

    if (arrcmp(header.Magic1, Magic1, 4) && arrcmp(header.Magic2, Magic2, 4)) {
        outStream->write(C(&header), sizeof(EFile_Header));
        long long offset = sizeof(EFile_Header);

        while (offset < size) {
            ESection_Header sh = GetData<ESection_Header>(data, offset);
            if (!arrcmp(sh.Magic, Magic_Section, 4))
                goto finish;

            ESection_Info si = GetData<ESection_Info>(data, offset);
            if (!arrcmp(si.Key, KEY, 4))
                Decode_Str(si.Name, si.Key);

            LPSTR Block_Name = (LPSTR)si.Name;

            if (strcmp(Block_Name, "") == 0) {
                outStream->write(C(data + offset - sizeof(ESection_Header) - sizeof(ESection_Info)), 
                    sizeof(ESection_Header) + sizeof(ESection_Info) + si.DataLength);
                break;
            } else if (type == 2 && strcmp(Block_Name, "(u7bOo`k") == 0) {
                ostringstream stream(NULL, 0, ios::binary);
                ParseUserInfo(data + offset, data + offset + si.DataLength, &stream);
                UINT oldLen = si.DataLength;

                if (!arrcmp(si.Key, KEY, 4)) Decode_Str(si.Name, si.Key);
                si.DataLength = stream.pcount();
                si.Data_CheckSum = GetCheckValue(D(stream.str()), stream.pcount());
                sh.Info_CheckSum = GetCheckValue(D(&si), sizeof(ESection_Info));

                outStream->write(C(&sh), sizeof(ESection_Header));
                outStream->write(C(&si), sizeof(ESection_Info));
                outStream->write(stream.str(), stream.pcount());
                si.DataLength = oldLen;
            } else if ((type == 0 || type == 1) && strcmp(Block_Name, "z^k") == 0) {
                ostringstream stream(NULL, 0, ios::binary);
                ParseProgram(data + offset, data + offset + si.DataLength, type, &stream);
                UINT oldLen = si.DataLength;

                if (!arrcmp(si.Key, KEY, 4)) Decode_Str(si.Name, si.Key);
                si.DataLength = stream.pcount();
                si.Data_CheckSum = GetCheckValue(D(stream.str()), stream.pcount());
                sh.Info_CheckSum = GetCheckValue(D(&si), sizeof(ESection_Info));

                outStream->write(C(&sh), sizeof(ESection_Header));
                outStream->write(C(&si), sizeof(ESection_Info));
                outStream->write(stream.str(), stream.pcount());
                si.DataLength = oldLen;
            } else {
                outStream->write(C(data + offset - sizeof(ESection_Header) - sizeof(ESection_Info)), 
                    sizeof(ESection_Header) + sizeof(ESection_Info) + si.DataLength);
            }

            offset += si.DataLength;
        }
    }

finish:
    ;
}

int main(int argc, LPSTR argv[]) {
    if (argc == 5) {
        int type = atoi(argv[1]);
        m_count = atoi(argv[2]);
        string filePath = argv[3];
        string listFile = argv[4];

        if (listFile.size()) {
            ifstream fs(listFile, ios::binary);
            ostringstream stream(NULL, 0, ios::binary);
            stream << fs.rdbuf();
            fs.close();

            string text(stream.str(), stream.pcount());
            vector<string> lines = split(text, "\r\n");

            for (string& line : lines) {
                size_t len = line.size();
                if (len && line[len - 1] == '\r')
                    line.pop_back();
                m_list.push_back(split(line, "<br>"));
            }
        }

        if (m_list.size()) {
            ifstream inputStream(filePath, ios::binary);
            ostringstream outputStream(NULL, 0, ios::binary);
            outputStream << inputStream.rdbuf();
            inputStream.close();

            ofstream finalStream(filePath.substr(0, filePath.length() - 2) + "_ic.e", ios::binary);
            Parse(D(outputStream.str()), outputStream.pcount(), type, &finalStream);
            finalStream.close();
        }
    }

    return 0;
}

