namespace autolink {

using autolink::proto::Param;
using autolink::proto::ParamType;

class ParameterTest : public ::testing::Test {
 protected:
  virtual void SetUp() override {
    // Initialize test parameters before each test case
    bool_param_.reset(new Parameter("flag", false));
    int_param_.reset(new Parameter("count", 200));
    double_param_.reset(new Parameter("ratio", 1.5f));
    string_param_.reset(new Parameter("label", "sample"));

    proto::Param param;
    param.set_name("config");
    std::string data;
    param.SerializeToString(&data);
    std::string info;
    message::GetDescriptorString(param, &info);
    std::string type_name = proto::Param::descriptor()->full_name();
    protobuf_param_.reset(new Parameter("message", data, type_name, info));
  }

  virtual void TearDown() override {
    bool_param_.reset();
    int_param_.reset();
    double_param_.reset();
    string_param_.reset();
    protobuf_param_.reset();
  }

 protected:
  std::unique_ptr<Parameter> bool_param_;
  std::unique_ptr<Parameter> int_param_;
  std::unique_ptr<Parameter> double_param_;
  std::unique_ptr<Parameter> string_param_;
  std::unique_ptr<Parameter> protobuf_param_;
};

TEST_F(ParameterTest, constructors) {
  Parameter p1("example");
  EXPECT_EQ(ParamType::NOT_SET, p1.Type());

  Parameter p2(p1);
  EXPECT_EQ(ParamType::NOT_SET, p2.Type());
}

TEST_F(ParameterTest, from_pb) {
  proto::Param pb;
  pb.set_name("identifier");
  pb.set_type(proto::ParamType::INT);
  pb.set_int_value(42);

  Parameter pv;
  pv.FromProtoParam(pb);
  EXPECT_EQ("identifier", pv.Name());
  EXPECT_EQ(ParamType::INT, pv.Type());
  EXPECT_EQ(42, pv.AsInt64());

  pb.set_name("enabled");
  pb.set_type(proto::ParamType::BOOL);
  pb.set_bool_value(false);
  pv.FromProtoParam(pb);
  EXPECT_FALSE(pv.AsBool());

  pb.set_name("scale");
  pb.set_type(proto::ParamType::DOUBLE);
  pb.set_double_value(3.14);
  pv.FromProtoParam(pb);
  EXPECT_EQ(ParamType::DOUBLE, pv.Type());

  pb.set_name("tag");
  pb.set_type(proto::ParamType::STRING);
  pb.set_string_value("hello_world");
  pv.FromProtoParam(pb);
  EXPECT_EQ("hello_world", pv.AsString());
}

TEST_F(ParameterTest, to_pb) {
  proto::Param pb = int_param_->ToProtoParam();
  EXPECT_EQ("count", pb.name());
  EXPECT_EQ(ParamType::INT, pb.type());
  EXPECT_EQ(200, pb.int_value());
}

TEST_F(ParameterTest, type) {
  EXPECT_EQ(ParamType::BOOL, bool_param_->Type());
  EXPECT_EQ(ParamType::INT, int_param_->Type());
  EXPECT_EQ(ParamType::DOUBLE, double_param_->Type());
  EXPECT_EQ(ParamType::STRING, string_param_->Type());
  EXPECT_EQ(ParamType::PROTOBUF, protobuf_param_->Type());
}

TEST_F(ParameterTest, type_name) {
  EXPECT_EQ("BOOL", bool_param_->TypeName());
  EXPECT_EQ("INT", int_param_->TypeName());
  EXPECT_EQ("DOUBLE", double_param_->TypeName());
  EXPECT_EQ("STRING", string_param_->TypeName());
  EXPECT_EQ("autolink.proto.Param", protobuf_param_->TypeName());
}

TEST_F(ParameterTest, name) {
  EXPECT_EQ("flag", bool_param_->Name());
  EXPECT_EQ("count", int_param_->Name());
  EXPECT_EQ("ratio", double_param_->Name());
  EXPECT_EQ("label", string_param_->Name());
  EXPECT_EQ("message", protobuf_param_->Name());
}

TEST_F(ParameterTest, as_bool) {
  EXPECT_FALSE(bool_param_->AsBool());
  EXPECT_TRUE(Parameter("flag", true).AsBool());
}

TEST_F(ParameterTest, as_int) { 
  EXPECT_EQ(200, int_param_->AsInt64()); 
}

TEST_F(ParameterTest, as_double) { 
  EXPECT_EQ(1.5, double_param_->AsDouble()); 
}

TEST_F(ParameterTest, AsString) { 
  EXPECT_EQ(string_param_->AsString(), "sample"); 
}

TEST_F(ParameterTest, value) {
  EXPECT_FALSE(bool_param_->value<bool>());
  EXPECT_EQ("", bool_param_->value<std::string>());
  EXPECT_EQ(200, int_param_->value<uint8_t>());
  EXPECT_EQ(200, int_param_->value<uint32_t>());
  EXPECT_EQ(200, int_param_->value<int64_t>());
  EXPECT_EQ(200, int_param_->value<int>());
  EXPECT_EQ("", int_param_->value<std::string>());
  EXPECT_EQ(1.5, double_param_->value<float>());
  EXPECT_EQ(1.5, double_param_->value<double>());
  EXPECT_EQ("", double_param_->value<std::string>());
  EXPECT_EQ("sample", string_param_->value<std::string>());
  string_param_->value<int>();

  auto msg = protobuf_param_->value<proto::Param>();
  EXPECT_EQ("message", protobuf_param_->Name());
  EXPECT_EQ("autolink.proto.Param", protobuf_param_->TypeName());
  std::string serialized;
  msg.SerializeToString(&serialized);
  EXPECT_EQ(serialized, protobuf_param_->value<std::string>());
  protobuf_param_->value<int>();
}

TEST_F(ParameterTest, debug_string) {
  EXPECT_EQ("{name: \"flag\", type: \"BOOL\", value: false}", bool_param_->DebugString());
  EXPECT_EQ("{name: \"count\", type: \"INT\", value: 200}", int_param_->DebugString());
  EXPECT_EQ("{name: \"ratio\", type: \"DOUBLE\", value: 1.500000}", double_param_->DebugString());
  EXPECT_EQ("{name: \"label\", type: \"STRING\", value: \"sample\"}", string_param_->DebugString());
  EXPECT_EQ(
      "{name: \"message\", type: \"autolink.proto.Param\", value: "
      "\"name: \"config\"\"}",
      protobuf_param_->DebugString());
}

