extern std::size_t total_ram;
extern "C" void kernel_entry() {
    utils::cxx::run_static_initializers();
    bootloader::load();
    utils::display::initialize();
    pmmngr::bootstrap();
    mmu::setup_identity_mapping();
    slab::initialize();
    utils::display::complete_init();

    klibc::print("PMM: Usable physical memory: %llu bytes\r\n", total_ram);
    klibc::print("MMU: Kernel page table active with %d levels\r\n", cpu_arch::get_paging_depth());
    klibc::print("Slab Allocator: Free space %llu bytes\r\n", SLAB_TOTAL_SIZE);

    acpi::parse_rsdp();
    cpu_arch::early_setup(ARCH_STAGE_PRELIMINARY);
    acpi::enable_acpi_subsystems();
    cpu_arch::early_setup(ARCH_STAGE_STANDARD);

    extern int boot_phase;
    boot_phase = 1;

    klibc::print("System initialization complete\r\n");
    klibc::print("Timestamp: %llu seconds, pausing for 2 seconds before testing page fault handler\r\n", 
                 clock::get_timestamp_ns() / 1000000000ULL);
    klibc::print("Current timestamp: %llu seconds\r\n", 
                 clock::get_timestamp_ns() / 1000000000ULL);

    cpu_arch::flush_tlb_entry(0x47AFE000, PAGE_SIZE);
    *(volatile int*)0x47AFE710 = 0;

    cpu_arch::halt_forever();
}

