namespace dynamic {

LogPrinter::LogPrinter(const char *filePath, std::ostream &outputStream)
    : LogProcessor(filePath), os(outputStream) {}

/// Outputs a memory allocation event in a readable format
void LogPrinter::visitAllocRecord(const AllocRecord &record) {
  os << "[ALLOC] ";
  switch (record.type) {
  case AllocType::Global:
    os << "Global ";
    break;
  case AllocType::Stack:
    os << "Stack ";
    break;
  case AllocType::Heap:
    os << "Heap ";
    break;
  default:
    std::cerr << "Invalid allocation type. Log file may be corrupted\n";
    std::exit(-1);
  }
  os << "Ptr# " << record.id << " = " << record.address << '\n';
}

/// Outputs a pointer assignment event
void LogPrinter::visitPointerRecord(const PointerRecord &record) {
  os << "[POINTER] Ptr# " << record.id << " = " << record.address << '\n';
}

/// Outputs a function entry event
void LogPrinter::visitEnterRecord(const EnterRecord &record) {
  os << "[ENTER] Function# " << record.id << '\n';
}

/// Outputs a function exit event
void LogPrinter::visitExitRecord(const ExitRecord &record) {
  os << "[EXIT] Function# " << record.id << '\n';
}

/// Outputs a function call event
void LogPrinter::visitCallRecord(const CallRecord &record) {
  os << "[CALL] Inst# " << record.id << '\n';
}

