DVAPI TSpectrumT<TPixel64> transform(const TSpectrumT<TPixel32> &source) {
  std::vector<TSpectrum64::ColorKey> colorKeys;
  for (int index = 0; index < source.getKeyCount(); ++index) {
    TSpectrumT<TPixel32>::Key originalKey = source.getKey(index);
    TSpectrum64::ColorKey convertedKey(originalKey.first, toPixel64(originalKey.second));
    colorKeys.push_back(convertedKey);
  }
  return TSpectrumT<TPixel64>(colorKeys.size(), &colorKeys[0]);
}

