// Wrapper function for IPv4 hostname resolution
int resolve_host_ipv4(const char *hostname,
	struct hostent *host_entry, char *buffer, size_t buffer_size,
	struct hostent **result, int *error_code)
{
	return gethostbyname2_r(hostname, AF_INET, host_entry, buffer, buffer_size, result, error_code);
}

