#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"

void run_kernel(const volatile struct RuntimeParams* runtime_params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt_config = runtime_params->formats;
#endif

    // Configure unpack hardware with source and destination formats
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmt_config.unpack_A_src, fmt_config.unpack_B_src,
        fmt_config.unpack_A_dst, fmt_config.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, runtime_params->num_faces, runtime_params->num_faces);

    // Initialize unpack A operation
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        runtime_params->UNPACK_TRANSPOSE_FACES, 0, FACE_R_DIM,
        runtime_params->num_faces, fmt_config.unpack_A_src, fmt_config.unpack_A_dst);

    // Unpack all input tiles from buffer_A
    for (int tile_idx = 0; tile_idx < runtime_params->TILE_CNT; ++tile_idx)
    {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(runtime_params->buffer_A[tile_idx]),
            fmt_config.unpack_A_src, fmt_config.unpack_A_dst);
    }

    // Mark dummy valid for Source B (unpack B) to prevent stalls
    for (int tile_idx = 0; tile_idx < runtime_params->TILE_CNT; ++tile_idx)
    {
        _llk_unpack_set_srcb_dummy_valid_();
    }
}
#endif

#ifdef LLK_TRISC_MATH
#include "llk_math_common.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "llk_math_transpose_dest.h"
using namespace ckernel;

void run_kernel(const volatile struct RuntimeParams* runtime_params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt_config = runtime_params->formats;
#endif

    constexpr bool is32 = is_fp32_dest_acc_en;

#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(
        runtime_params->num_faces, fmt_config.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(
        runtime_params->num_faces, fmt_config.math);
#endif

    // Initialize packer sync and math hardware
    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmt_config.math, fmt_config.math);
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Process each tile via datacopy
    for (int tile_idx = 0; tile_idx < runtime_params->TILE_CNT; ++tile_idx)
    {
        LLK_ASSERT(
            tile_idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tile_idx, fmt_config.math, fmt_config.math);
#else
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tile_idx, fmt_config.math, fmt_config.math);
#endif
    }

    // Prepare transpose operation
    _llk_math_transpose_dest_init_<MATH_TRANSPOSE_FACES, is32>();

    // Perform transpose on each tile
    for (int tile_idx = 0; tile_idx < runtime_params->TILE_CNT; ++tile_idx)
    {
        LLK_ASSERT(
            tile_idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_transpose_dest_<is_fp32_dest_acc_en, MATH_TRANSPOSE_FACES, is32>(tile_idx);
#else
        _llk_math_transpose_dest_<MATH_TRANSPOSE_FACES, is32>(tile_idx);
#endif
    }

    // Signal completion of destination section
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"

void run_kernel(const volatile struct RuntimeParams* runtime_params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmt_config = runtime_params->formats;
#endif

#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(
        fmt_config.pack_src, fmt_config.pack_dst,
        16 * 16 * 4, FACE_R_DIM, TILE_C_DIM, runtime_params->num_faces);
    _llk_pack_init_<false, false, false>(
        fmt_config.pack_dst, FACE_R_DIM, TILE_C_DIM, runtime_params->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(
        fmt_config.pack_src, fmt_config.pack_dst,
        16 * 16 * 4, FACE_R_DIM, runtime_params->num_faces);
    _llk_pack_init_<false, false>(
        fmt_config.pack_dst, FACE_R_DIM, runtime_params->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>();
#endif

    // Wait until math operations complete before packing
    _llk_packer_wait_for_math_done_();

    // Pack output tiles to result buffer
    for (int tile_idx = 0; tile_idx < runtime_params->TILE_CNT; ++tile_idx)
    {
        LLK_ASSERT(
            tile_idx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>(),
            "Block tile index exceeds maximum destination tiles");
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            tile_idx, L1_ADDRESS(runtime_params->buffer_Res[tile_idx]));
    }

    // Finalize destination section
    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

