XmlPolarWriter::XmlPolarWriter(QFile &file) : XflXmlWriter(file)
{
}

void XmlPolarWriter::writeXMLPolar(Polar *polarData)
{
    if (!polarData) return;

    QString buffer;
    writeHeader();
    writeStartElement("Polar");
    {
        writeTextElement("Foil_Name",  polarData->foilName());
        writeTextElement("Polar_Name", polarData->name());
        writeTextElement("Type",       objects::polarType(polarData->type()));

        switch (polarData->BLMethod())
        {
            default:
            case BL::XFOIL: 
                writeTextElement("Method", "XFoil"); 
                break;
        }

        if (!polarData->isControlPolar())
        {
            writeTextElement("Fixed_Reynolds",           QString("%1").arg(polarData->Reynolds(), 11, 'f', 0));
            writeTextElement("Fixed_AOA",                QString("%1").arg(polarData->aoaSpec(), 11, 'f', 3));
            writeTextElement("Mach",                     QString("%1").arg(polarData->Mach(), 7, 'f', 2));
            writeTextElement("ReType",                   QString("%1").arg(polarData->ReType()));
            writeTextElement("MaType",                   QString("%1").arg(polarData->MaType()));
            writeTextElement("NCrit",                    QString("%1").arg(polarData->NCrit(), 7, 'f', 1));
            writeTextElement("Forced_Top_Transition",    QString("%1").arg(polarData->XTripTop(), 7, 'f', 2));
            writeTextElement("Forced_Bottom_Transition", QString("%1").arg(polarData->XTripBot(), 7, 'f', 2));
        }
    }
    writeEndElement();
    writeEndDocument();
}

void XmlPolarWriter::writeHeader()
{
    setAutoFormatting(true);
    writeStartDocument();
    writeDTD("<!DOCTYPE flow5>");
    writeStartElement("Foil_Polar");
    writeAttribute("version", "1.0");
}

#include <bpf/bpf.h>

// Structure representing the arguments for scheduler switch tracepoint
struct sched_switch_event {
    u64 reserved;
    u8 previous_task_name[16];
    u32 previous_process_id;
    u32 previous_priority;
    u64 previous_state_flag;
    u8 next_task_name[16];
    u32 next_process_id;
    u32 next_priority;
};

// Structure to hold a large buffer (e.g., for data storage)
struct large_data_buffer {
    u8 data_area[1024];
};

BTF_EXPORT(struct large_data_buffer);

// Define a BPF map structure for storing large arrays
BPF_MAP_STRUCT(storage_map, BPF_MAP_TYPE_ARRAY, u32, struct large_data_buffer, 400 * 1024, 0);

// Nested map definition: array of maps
struct {
    BPF_MAP_DEF_UINT(type, BPF_MAP_TYPE_ARRAY_OF_MAPS);
    BPF_MAP_DEF_UINT(key_size, sizeof(u32));
    BPF_MAP_DEF_UINT(max_entries, 1024);
    BPF_MAP_DEF_ARRAY(entries, struct storage_map);
} multi_gigabyte_storage SEC(BPF_SEC_BTF_MAPS);

// Tracepoint handler for scheduler switch events
SEC("tracepoint/sched/sched_switch")
int handle_sched_switch(struct sched_switch_event* event) {
    BPF_PRINTK("Processing switch from PID %d to PID %d\n", event->previous_process_id, event->next_process_id);
    return 0;
}

