class EnumIntActionTest : public PlainTestSuite {
  Q_OBJECT
 public:
  template <typename T>
  void VerifyEnumActionBehavior(T enumLow, T enumHigh, T invalidVal, QActionGroup::ExclusionPolicy policy) {
    QAction action1{"zulu alpha minor"};
    action1.setCheckable(true);
    QAction action2{"alpha zulu major"};
    QVERIFY(action1.text() > action2.text());
    action2.setCheckable(true);
    QVERIFY(enumLow < enumHigh);

    if (policy == QActionGroup::ExclusionPolicy::Exclusive) {
      action2.setChecked(true);
    }

    EnumIntAction<T> testAction;
    QCOMPARE(testAction, false);
    testAction.init({{&action1, enumLow}, {&action2, enumHigh}}, invalidVal, policy);
    QCOMPARE(testAction, true);
    QCOMPARE(testAction.defVal(), invalidVal);

    if (policy == QActionGroup::ExclusionPolicy::Exclusive) {
      QCOMPARE(testAction.curVal(), enumHigh);
    } else {
      QCOMPARE(testAction.curVal(), invalidVal);
    }

    auto* grp = testAction.getActionGroup();
    QVERIFY(grp != nullptr);
    QCOMPARE(grp->actions().size(), 2);

    // Order depends on initialization — not strictly guaranteed
    QCOMPARE(testAction.getActionEnumAscendingList(), (QList<QAction*>{&action1, &action2}));
    QCOMPARE(testAction.getActionNameAscendingList(), (QList<QAction*>{&action2, &action1}));

    QCOMPARE(testAction.act2Enum(&action1), enumLow);
    QCOMPARE(testAction.act2Enum((const QAction*)&action1), enumLow);
    QCOMPARE(testAction.intVal2Enum(static_cast<int>(enumLow)), enumLow);

    QCOMPARE(testAction.act2Enum(&action2), enumHigh);
    QCOMPARE(testAction.act2Enum((const QAction*)&action2), enumHigh);
    QCOMPARE(testAction.intVal2Enum(static_cast<int>(enumHigh)), enumHigh);

    QCOMPARE(testAction.setCheckedIfActionExist(static_cast<int>(enumHigh)), &action2);
    QCOMPARE(testAction.setCheckedIfActionExist(enumHigh), &action2);

    if (policy != QActionGroup::ExclusionPolicy::None) {
      QCOMPARE(testAction.curVal(), enumHigh);
    }
  }

 private slots:
  void enum_in_action_exclusive() {
    VerifyEnumActionBehavior<ViewTypeTool::ViewType>(
        ViewTypeTool::ViewType::TABLE,
        ViewTypeTool::ViewType::SEARCH,
        ViewTypeTool::DEFAULT_VIEW_TYPE,
        QActionGroup::ExclusionPolicy::Exclusive);

    VerifyEnumActionBehavior<Style::StyleE>(
        Style::StyleE::STYLE_WINDOWS_VISTA,
        Style::StyleE::STYLE_FUSION,
        Style::StyleE::STYLE_WINDOWS_VISTA,
        QActionGroup::ExclusionPolicy::Exclusive);

    VerifyEnumActionBehavior<Style::StyleSheetE>(
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        Style::StyleSheetE::STYLESHEET_DARK_THEME_MOON_FOG,
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        QActionGroup::ExclusionPolicy::Exclusive);

    VerifyEnumActionBehavior<SearchTools::SearchModeE>(
        SearchTools::SearchModeE::REGEX,
        SearchTools::SearchModeE::FILE_CONTENTS,
        SearchTools::DEFAULT_SEARCH_MODE,
        QActionGroup::ExclusionPolicy::Exclusive);

    VerifyEnumActionBehavior<BytesRangeTool::BytesRangeE>(
        BytesRangeTool::BytesRangeE::FIRST_16_BYTES,
        BytesRangeTool::BytesRangeE::ENTIRE_FILE,
        BytesRangeTool::DEFAULT_BYTE_RANGE,
        QActionGroup::ExclusionPolicy::Exclusive);

    VerifyEnumActionBehavior<QCryptographicHash::Algorithm>(
        QCryptographicHash::Algorithm::Md5,
