#include "UndoManager.hpp"
#include <iostream>
// NOTE: It might be feasible to monitor network objects via their raw pointer addresses rather than NetObjIDs, since the NetObjID gets reassigned upon movement and isn't newly allocated.
bool UndoManager::can_undone() {
    return !undoStack.empty();
}
bool UndoManager::can_redone() {
    return !redoStack.empty();
}
void UndoManager::record(const UndoRedoPair& undoRedoAction) {
    store_undo(undoRedoAction);
    redoStack.clear();
}
void UndoManager::store_undo(const UndoRedoPair& undoRedoAction) {
    if(undoStack.size() == maxHistorySize)
        undoStack.pop_front();
    undoStack.emplace_back(undoRedoAction);
}
void UndoManager::store_redo(const UndoRedoPair& undoRedoAction) {
    if(redoStack.size() == maxHistorySize)
        redoStack.pop_front();
    redoStack.emplace_back(undoRedoAction);
}
void UndoManager::undid() {
    if(undoStack.empty())
        return;
    if(!undoStack.back().undo()) {
        reset();
    }
    else {
        store_redo(undoStack.back());
        undoStack.pop_back();
    }
}
void UndoManager::redid() {
    if(redoStack.empty())
        return;
    if(!redoStack.back().redo()) {
        reset();
    }
    else {
        store_undo(redoStack.back());
        redoStack.pop_back();
    }
}
void UndoManager::reset() {
    redoStack.clear();
    undoStack.clear();
}

