    blelr
    clrlwi r5, address, 27
    add byteCount, byteCount, r5
    addi byteCount, byteCount, 31
    srwi byteCount, byteCount, 5
    mtctr byteCount
@loop1
    dcbf r0, address
    addi address, address, 32
