// Locked cache constants
#define LOCKED_CACHE_LINES 512
#define CACHE_LINE_COUNT 1024

// Locked cache enable function
static asm void InitializeLockedCache(void) {
    nofralloc
    mfmsr   r5
    ori     r5, r5, 0x1000
    mtmsr   r5
    lis     r3, OS_CACHED_REGION_PREFIX
    li      r4, CACHE_LINE_COUNT
    mtctr   r4
@touchLoop
    dcbt    0,r3
    dcbst   0,r3
    addi    r3,r3,32
    bdnz    @touchLoop
    mfspr   r4, HID2_REG
    oris    r4, r4, 0x100F
    mtspr   HID2_REG, r4
    nop 
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    lis     r3, LC_BASE_PREFIX
    ori     r3, r3, 0x0002
    mtspr   DBAT3L, r3
    ori     r3, r3, 0x01fe
    mtspr   DBAT3U, r3
    isync
    lis     r3, LC_BASE_PREFIX
    li      r6, LOCKED_CACHE_LINES
    mtctr   r6
    li      r6, 0
@lockLoop
    dcbz_l  r6, r3
    addi    r3, r3, 32
    bdnz+   @lockLoop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    blr
}

// Public locked cache enable wrapper
void EnableLockedCache(void) {
    BOOL interruptsSaved;
    interruptsSaved = OSDisableInterrupts();
    InitializeLockedCache();
    OSRestoreInterrupts(interruptsSaved);
}

asm void DisableLockedCache(void) {
    nofralloc
    lis     r3, LC_BASE_PREFIX
    li      r4, LOCKED_CACHE_LINES
    mtctr r4
@loop1
    dcbi r0, r3
    addi r3, r3, 32
    bdnz @loop1
    mfspr r4, HID2_REG
    rlwinm r4, r4, 0, 4, 2
    mtspr HID2_REG, r4
    blr
}

asm void AllocateSingleLockedTag(register BOOL shouldInvalidate, register void* tagAddress) {
    nofralloc
    cmpwi shouldInvalidate, 0
    beq @skipInvalidate
    dcbi r0, tagAddress
@skipInvalidate
    dcbz_l r0, tagAddress
    blr
}

asm void AllocateMultipleLockedTags(register BOOL shouldInvalidate, register void* startAddress, register u32 blockCount) {
    nofralloc
    mflr r6
    cmplwi blockCount, 0
    ble @endAllocation
    mtctr blockCount
    cmpwi shouldInvalidate, 0
    beq @noInvalidate
@withInvalidate
    dcbi r0, startAddress
    dcbz_l r0, startAddress
    addi startAddress, startAddress, 32
    bdnz @withInvalidate
    b @endAllocation
@noInvalidate
    dcbz_l r0, startAddress
    addi startAddress, startAddress, 32
    bdnz @noInvalidate
@endAllocation
    mtlr r6
    blr
}

asm void LoadLockedCacheBlocks(register void* destTag, register void* srcAddress, register u32 blockCount) {
    nofralloc
    rlwinm  r6, blockCount, 30, 27, 31
    rlwinm  srcAddress, srcAddress, 0, 4, 31
    or      r6, r6, srcAddress
    mtspr   DMA_U, r6
    rlwinm  r6, blockCount, 2, 28, 29
    or      r6, r6, destTag
    ori     r6, r6, 0x12
    mtspr   DMA_L, r6
    blr
}

asm void StoreLockedCacheBlocks(register void* destAddress, register void* srcTag, register u32 blockCount) {
    nofralloc
    rlwinm  r6, blockCount, 30, 27, 31
    rlwinm  destAddress, destAddress, 0, 4, 31
    or      r6, r6, destAddress
    mtspr   DMA_U, r6
    rlwinm  r6, blockCount, 2, 28, 29
    or      r6, r6, srcTag
    ori     r6, r6, 0x2
    mtspr   DMA_L, r6
    blr
}
#endif

// High-level locked cache allocation
void AllocateLockedCache(void* address, u32 sizeBytes) {
    u32 numBlocks = sizeBytes >> 5;
    u32 hid2Value = PPCMfhid2();
    ASSERTMSGLINE(1319, !((u32)address & 31), "AllocateLockedCache(): address must be 32 byte aligned");
    ASSERTMSGLINE(1321, !((u32)sizeBytes & 31), "AllocateLockedCache(): sizeBytes must be 32 byte aligned");
    if ((hid2Value & 0x10000000) == 0) {
        EnableLockedCache();
    }
    AllocateMultipleLockedTags(TRUE, address, numBlocks);
}

void AllocateLockedCacheNoInvalidate(void* address, u32 sizeBytes) {
    u32 numBlocks = sizeBytes >> 5;
    u32 hid2Value = PPCMfhid2();
    ASSERTMSGLINE(1366, !((u32)address & 31), "AllocateLockedCacheNoFlush(): address must be 32 byte aligned");
    ASSERTMSGLINE(1368, !((u32)sizeBytes & 31), "AllocateLockedCacheNoFlush(): sizeBytes must be 32 byte aligned");
    if ((hid2Value & 0x10000000) == 0) {
        EnableLockedCache();
    }
    AllocateMultipleLockedTags(FALSE, address, numBlocks);
}

// Data transfer functions
u32 TransferDataToLockedCache(void* destAddress, void* srcAddress, u32 sizeBytes) {
    u32 numBlocks = (sizeBytes + 31) / 32;
    u32 numTransactions = (numBlocks + 128 - 1) / 128;
    ASSERTMSGLINE(1426, !((u32)srcAddress & 31), "TransferDataToLockedCache(): srcAddress not 32 byte aligned");
    ASSERTMSGLINE(1428, !((u32)destAddress & 31), "TransferDataToLockedCache(): destAddress not 32 byte aligned");
    while (numBlocks > 0) {
        if (numBlocks < 128) {
            LoadLockedCacheBlocks(destAddress, srcAddress, numBlocks);
            numBlocks = 0;
        } else {
            LoadLockedCacheBlocks(destAddress, srcAddress, 0);
            numBlocks -= 128;
            destAddress = (void*)((u32)destAddress + 4096);
            srcAddress = (void*)((u32)srcAddress + 4096);
        }
    }
    return numTransactions;
}

u32 TransferDataFromLockedCache(void* destAddress, void* srcAddress, u32 sizeBytes) {
    u32 numBlocks = (sizeBytes + 31) / 32;
    u32 numTransactions = (numBlocks + 128 - 1) / 128;
    ASSERTMSGLINE(1494, !((u32)srcAddress & 31), "TransferDataFromLockedCache(): srcAddress not 32 byte aligned");
    ASSERTMSGLINE(1496, !((u32)destAddress & 31), "TransferDataFromLockedCache(): destAddress not 32 byte aligned");
    while (numBlocks > 0) {
        if (numBlocks < 128) {
            StoreLockedCacheBlocks(destAddress, srcAddress, numBlocks);
            numBlocks = 0;
        } else {
            StoreLockedCacheBlocks(destAddress, srcAddress, 0);
            numBlocks -= 128;
            destAddress = (void*)((u32)destAddress + 4096);
            srcAddress = (void*)((u32)srcAddress + 4096);
        }
    }
    return numTransactions;
}

