// Flush the locked cache queue
void FlushLockedCacheQueue() {
    union {
        u32 value;
        struct {
            u32 lcAddress : 27;
            u32 dmaLoad : 1;
            u32 dmaLengthLow : 2;
            u32 dmaTrigger : 1;
            u32 dmaFlush : 1;
        } fields;
    } dmaLowRegister;
    dmaLowRegister.value = 0;
    dmaLowRegister.fields.dmaFlush = 1;
    PPCMtdmaU(0);
    PPCMtdmaL(dmaLowRegister.value);
    PPCSync();
}

// L2 cache initialization
static void InitializeL2Cache(void) {
    u32 savedMSR;
    savedMSR = PPCMfmsr();
    __sync();
    PPCMtmsr(MSR_IR | MSR_DR);
    __sync();
    DisableL2Cache();
    GlobalInvalidateL2Cache();
    PPCMtmsr(savedMSR);
}

void EnableL2Cache(void) { 
    PPCMtl2cr((PPCMfl2cr() | L2CR_L2E) & ~L2CR_L2I);
}

void DisableL2Cache(void) {
    __sync();
    PPCMtl2cr(PPCMfl2cr() & ~0x80000000);
    __sync();
}

void GlobalInvalidateL2Cache(void) {
    DisableL2Cache();
    PPCMtl2cr(PPCMfl2cr() | 0x00200000);
    while (PPCMfl2cr() & 0x00000001u);
    PPCMtl2cr(PPCMfl2cr() & ~0x00200000);
    while (PPCMfl2cr() & 0x00000001u) {
        DBPrintf(">>> L2 INVALIDATE : SHOULD NEVER HAPPEN\n");
    }
}

void SetL2ModeDataOnly(BOOL dataOnly) {
    if (dataOnly) {
        PPCMtl2cr(PPCMfl2cr() | 0x400000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFBFFFFF);
}

void SetL2WriteThrough(BOOL writeThrough) {
    if (writeThrough) {
        PPCMtl2cr(PPCMfl2cr() | 0x80000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFF7FFFF);
}

// Machine check error handler
void HandleDMATransferError(OSError error, OSContext* context, ...) {
    u32 hid2Value = PPCMfhid2();
    OSReport("Machine check received\n");
    OSReport("HID2 = 0x%x   SRR1 = 0x%x\n", hid2Value, context->srr1);
    if (!(hid2Value & (HID2_DCHERR | HID2_DNCERR | HID2_DCMERR | HID2_DQOERR)) || !(context->srr1 & SRR1_DMA_BIT)) {
        OSReport("Machine check was not DMA/locked cache related\n");
        OSDumpContext(context);
        PPCHalt();
    }
    OSReport("HandleDMATransferError(): An error occurred while processing DMA.\n");
    OSReport("The following errors have been detected and cleared :\n");
    if (hid2Value & HID2_DCHERR) {
        OSReport("\t- Requested a locked cache tag that was already in the cache\n");
    }
    if (hid2Value & HID2_DNCERR) {
        OSReport("\t- DMA attempted to access normal cache\n");
    }
    if (hid2Value & HID2_DCMERR) {
        OSReport("\t- DMA missed in data cache\n");
    }
    if (hid2Value & HID2_DQOERR) {
        OSReport("\t- DMA queue overflowed\n");
    }
    // write hid2 back to clear the error bits
    PPCMthid2(hid2Value);
}

void InitializeCaches(void) {
    if (!(PPCMfhid0() & HID0_ICE)) {
        EnableInstructionCache();
        DBPrintf("L1 i-caches initialized\n");
    }
    if (!(PPCMfhid0() & HID0_DCE)) {
        EnableDataCache();
        DBPrintf("L1 d-caches initialized\n");
    }
    if (!(PPCMfl2cr() & L2CR_L2E)) {
        InitializeL2Cache();
        EnableL2Cache();
        DBPrintf("L2 cache initialized\n");
    }
    OSSetErrorHandler(OS_ERROR_MACHINE_CHECK, HandleDMATransferError);
    DBPrintf("Locked cache machine check handler installed\n");
}

#include "valdi_core/cpp/Utils/PathUtils.hpp"
