// Function to set all callbacks in a listener to a constant function pointer
static void configure_all_listeners (dds_listener_t *listener, void (*callback) (void))
{
  dds_lset_data_available (listener, (dds_on_data_available_fn) callback);
  dds_lset_data_on_readers (listener, (dds_on_data_on_readers_fn) callback);
  dds_lset_inconsistent_topic (listener, (dds_on_inconsistent_topic_fn) callback);
  dds_lset_liveliness_changed (listener, (dds_on_liveliness_changed_fn) callback);
  dds_lset_liveliness_lost (listener, (dds_on_liveliness_lost_fn) callback);
  dds_lset_offered_deadline_missed (listener, (dds_on_offered_deadline_missed_fn) callback);
  dds_lset_offered_incompatible_qos (listener, (dds_on_offered_incompatible_qos_fn) callback);
  dds_lset_publication_matched (listener, (dds_on_publication_matched_fn) callback);
