// Macro to assert that a callback matches the expected value
#define VERIFY_CALLBACK_MATCH(fntype, listener, expected) \
  do { \
    dds_on_##fntype##_fn cb; \
    dds_lget_##fntype(listener, &cb); \
    CU_ASSERT_EQUAL(cb, expected); \
  } while (0)

// Function to verify all callbacks match a constant function pointer
static void validate_all_const (const dds_listener_t *listener, void (*callback) (void))
{
  VERIFY_CALLBACK_MATCH (data_available, listener, (dds_on_data_available_fn) callback);
  VERIFY_CALLBACK_MATCH (data_on_readers, listener, (dds_on_data_on_readers_fn) callback);
  VERIFY_CALLBACK_MATCH (inconsistent_topic, listener, (dds_on_inconsistent_topic_fn) callback);
  VERIFY_CALLBACK_MATCH (liveliness_changed, listener, (dds_on_liveliness_changed_fn) callback);
  VERIFY_CALLBACK_MATCH (liveliness_lost, listener, (dds_on_liveliness_lost_fn) callback);
  VERIFY_CALLBACK_MATCH (offered_deadline_missed, listener, (dds_on_offered_deadline_missed_fn) callback);
  VERIFY_CALLBACK_MATCH (offered_incompatible_qos, listener, (dds_on_offered_incompatible_qos_fn) callback);
  VERIFY_CALLBACK_MATCH (publication_matched, listener, (dds_on_publication_matched_fn) callback);
  VERIFY_CALLBACK_MATCH (requested_deadline_missed, listener, (dds_on_requested_deadline_missed_fn) callback);
  VERIFY_CALLBACK_MATCH (requested_incompatible_qos, listener, (dds_on_requested_incompatible_qos_fn) callback);
  VERIFY_CALLBACK_MATCH (sample_lost, listener, (dds_on_sample_lost_fn) callback);
  VERIFY_CALLBACK_MATCH (sample_rejected, listener, (dds_on_sample_rejected_fn) callback);
  VERIFY_CALLBACK_MATCH (subscription_matched, listener, (dds_on_subscription_matched_fn) callback);
}

// Function to validate all callbacks match specific named callbacks
static void validate_all (const dds_listener_t *listener)
{
  VERIFY_CALLBACK_MATCH (data_available, listener, data_available_cb);
  VERIFY_CALLBACK_MATCH (data_on_readers, listener, data_on_readers_cb);
  VERIFY_CALLBACK_MATCH (inconsistent_topic, listener, inconsistent_topic_cb);
  VERIFY_CALLBACK_MATCH (liveliness_changed, listener, liveliness_changed_cb);
  VERIFY_CALLBACK_MATCH (liveliness_lost, listener, liveliness_lost_cb);
  VERIFY_CALLBACK_MATCH (offered_deadline_missed, listener, offered_deadline_missed_cb);
  VERIFY_CALLBACK_MATCH (offered_incompatible_qos, listener, offered_incompatible_qos_cb);
  VERIFY_CALLBACK_MATCH (publication_matched, listener, publication_matched_cb);
  VERIFY_CALLBACK_MATCH (requested_deadline_missed, listener, requested_deadline_missed_cb);
  VERIFY_CALLBACK_MATCH (requested_incompatible_qos, listener, requested_incompatible_qos_cb);
  VERIFY_CALLBACK_MATCH (sample_lost, listener, sample_lost_cb);
  VERIFY_CALLBACK_MATCH (sample_rejected, listener, sample_rejected_cb);
  VERIFY_CALLBACK_MATCH (subscription_matched, listener, subscription_matched_cb);
}

