// Mapping for PdbObject structure
void MappingTraits<PdbObject>::mapping(IO &io, PdbObject &obj) {
  io.mapOptional("MSF", obj.Headers);
  io.mapOptional("StreamSizes", obj.StreamSizes);
  io.mapOptional("StreamMap", obj.StreamMap);
  io.mapOptional("StringTable", obj.StringTable);
  io.mapOptional("PdbStream", obj.PdbStream);
  io.mapOptional("DbiStream", obj.DbiStream);
  io.mapOptional("TpiStream", obj.TpiStream);
  io.mapOptional("IpiStream", obj.IpiStream);
  io.mapOptional("PublicsStream", obj.PublicsStream);
}

// Mapping for MSFHeaders structure
void MappingTraits<MSFHeaders>::mapping(IO &io, MSFHeaders &headersObj) {
  io.mapOptional("SuperBlock", headersObj.SuperBlock);
  io.mapOptional("NumDirectoryBlocks", headersObj.NumDirectoryBlocks);
  io.mapOptional("DirectoryBlocks", headersObj.DirectoryBlocks);
  io.mapOptional("NumStreams", headersObj.NumStreams);
  io.mapOptional("FileSize", headersObj.FileSize);
}

// Mapping for SuperBlock structure
void MappingTraits<msf::SuperBlock>::mapping(IO &io, msf::SuperBlock &superBlock) {
  if (!io.outputting()) {
    ::memcpy(superBlock.MagicBytes, msf::Magic, sizeof(msf::Magic));
  }
  using u32 = support::ulittle32_t;
  io.mapOptional("BlockSize", superBlock.BlockSize, u32(4096U));
  io.mapOptional("FreeBlockMap", superBlock.FreeBlockMapBlock, u32(0U));
  io.mapOptional("NumBlocks", superBlock.NumBlocks, u32(0U));
  io.mapOptional("NumDirectoryBytes", superBlock.NumDirectoryBytes, u32(0U));
  io.mapOptional("Unknown1", superBlock.Unknown1, u32(0U));
  io.mapOptional("BlockMapAddr", superBlock.BlockMapAddr, u32(0U));
}

// Mapping for StreamBlockList structure
void MappingTraits<StreamBlockList>::mapping(IO &io, StreamBlockList &streamList) {
  io.mapRequired("Stream", streamList.Blocks);
}

// Mapping for PdbInfoStream structure
void MappingTraits<PdbInfoStream>::mapping(IO &io, PdbInfoStream &infoStream) {
  io.mapOptional("Age", infoStream.Age, 1U);
  io.mapOptional("Guid", infoStream.Guid);
  io.mapOptional("Signature", infoStream.Signature, 0U);
  io.mapOptional("Features", infoStream.Features);
  io.mapOptional("Version", infoStream.Version, PdbImplVC70);
}

// Mapping for PdbDbiStream structure
void MappingTraits<PdbDbiStream>::mapping(IO &io, PdbDbiStream &dbiStream) {
  io.mapOptional("VerHeader", dbiStream.VerHeader, PdbDbiV70);
  io.mapOptional("Age", dbiStream.Age, 1U);
  io.mapOptional("BuildNumber", dbiStream.BuildNumber, uint16_t(0U));
  io.mapOptional("PdbDllVersion", dbiStream.PdbDllVersion, 0U);
  io.mapOptional("PdbDllRbld", dbiStream.PdbDllRbld, uint16_t(0U));
  io.mapOptional("Flags", dbiStream.Flags, uint16_t(1U));
  io.mapOptional("MachineType", dbiStream.MachineType, PDB_Machine::x86);
  io.mapOptional("Modules", dbiStream.ModInfos);
}

// Mapping for PdbTpiStream structure
void MappingTraits<PdbTpiStream>::mapping(IO &io,
                                          pdb::yaml::PdbTpiStream &tpiStream) {
  io.mapOptional("Version", tpiStream.Version, PdbTpiV80);
  io.mapRequired("Records", tpiStream.Records);
}

// Mapping for PdbPublicsStream structure
void MappingTraits<PdbPublicsStream>::mapping(
    IO &io, pdb::yaml::PdbPublicsStream &publicsStream) {
  io.mapRequired("Records", publicsStream.PubSyms);
}

// Mapping for NamedStreamMapping structure
void MappingTraits<NamedStreamMapping>::mapping(IO &io,
                                                NamedStreamMapping &namedStream) {
  io.mapRequired("Name", namedStream.StreamName);
  io.mapRequired("StreamNum", namedStream.StreamNumber);
}

// Mapping for PdbModiStream structure
void MappingTraits<PdbModiStream>::mapping(IO &io, PdbModiStream &modiStream) {
  io.mapOptional("Signature", modiStream.Signature, 4U);
  io.mapRequired("Records", modiStream.Symbols);
}

// Mapping for PdbDbiModuleInfo structure
void MappingTraits<PdbDbiModuleInfo>::mapping(IO &io, PdbDbiModuleInfo &moduleInfo) {
  io.mapRequired("Module", moduleInfo.Mod);
  io.mapOptional("ObjFile", moduleInfo.Obj, moduleInfo.Mod);
  io.mapOptional("SourceFiles", moduleInfo.SourceFiles);
  io.mapOptional("Subsections", moduleInfo.Subsections);
  io.mapOptional("Modi", moduleInfo.Modi);
}

