LevelGenerators::LevelGenerators()
{
}

void LevelGenerators::addLevelGenerator(const wstring &name, LevelGenerationOptions *generator)
{
	if (!name.empty()) {
		generator->setDisplayName(name);
	}
	m_generators.push_back(generator);
}

void LevelGenerators::removeLevelGenerator(LevelGenerationOptions *generator)
{
	vector<LevelGenerationOptions*>::iterator iter;
	while ((iter = find(m_generators.begin(),
						m_generators.end(),
						generator)) != m_generators.end())
	{
		m_generators.erase(iter);
	}
}

