#include "libm.h"

// Copy the sign of y to x
double copysign(double x, double y) {
	union {double f; uint64_t i;} u_x = {x}, u_y = {y};
	u_x.i &= (0xFFFFFFFFFFFFFFFFULL >> 1);
	u_x.i |= (u_y.i & (1ULL << 63));
	return u_x.f;
}

