#include <iostream>

// Program to check if a number is prime or not
int main() {
    int number, divisor;

    std::cout << "Enter a number to check: ";
    std::cin >> number;

    // Handle special case for 1
    if (number == 1) {
        std::cout << "It is not prime" << std::endl;
    } else {
        bool isPrime = true;
        for (divisor = 2; divisor * divisor <= number; divisor++) {
            if (number % divisor == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            std::cout << "It is prime" << std::endl;
        } else {
            std::cout << "It is not prime" << std::endl;
        }
    }

    return 0;
}

#include<iostream>
using namespace std;

class measurement {
	private:
		int length_feet, length_inches;
	public:
		void input();
		void display();
		measurement combine(measurement m);
};

void measurement::input() {
	cout << "enter feet and inches";
	cin >> length_feet >> length_inches;
}

void measurement::display() {
	cout << length_feet << "feet" << length_inches << "inches" << endl;
}

measurement measurement::combine(measurement m) {
	measurement temp;
	temp.length_feet = length_feet + m.length_feet;
	temp.length_inches = length_inches + m.length_inches;

	if (temp.length_inches >= 12) {
		temp.length_feet += temp.length_inches / 12;
		temp.length_inches = temp.length_inches % 12;
	}

	return temp;
}

int main() {
	measurement m1, m2, m3;
	m1.input(); m2.input();
	m1.display(); m2.display();
	m3 = m1.combine(m2);
	m3.display();
	return 0;
}

