RayTracerWindow::RayTracerWindow(GLuint width, GLuint height)
	: m_pCameraRaysImage{ nullptr }
{
}

RayTracerWindow::~RayTracerWindow()
{
}

void RayTracerWindow::init(SurfaceRenderer& renderer)
{
	tc::ivec2 size{ renderer.getWidth(), renderer.getHeight() };
	tc::gpu::GPUBackend gpu_backend;

	m_pCameraRaysImage = new tc::BufferResource<tc::cpu::RGBA8, tc::Dim::D2>{ size };
	gpu_backend.uploadImage<tc::InternalFormat::RGBA32F>(*m_pCameraRaysImage);
	m_RayTracerKernel.outData.attach(m_pCameraRaysImage);
	m_VisualizeRaysKernel.inData.attach(m_pCameraRaysImage);
	m_VisualizeRaysKernel.outData.attach(renderer.getRenderBuffer());
}

void RayTracerWindow::compute(SurfaceRenderer& renderer)
{
	tc::gpu::GPUBackend gpu_backend;
	//tc::CPUBackend backend;

	tc::ivec2 size{ renderer.getWidth(), renderer.getHeight() };

	gpu_backend.useKernel(m_RayTracerKernel);
	gpu_backend.bindImage(m_RayTracerKernel.outData);
	gpu_backend.bindUniform(m_RayTracerKernel.fieldOfView);
	gpu_backend.execute(m_RayTracerKernel, tc::uvec3{ size.x, size.y, 1 });
	gpu_backend.useKernel(m_VisualizeRaysKernel);
	gpu_backend.bindImage(m_VisualizeRaysKernel.inData);
	gpu_backend.bindImage(m_VisualizeRaysKernel.outData);
	gpu_backend.execute(m_VisualizeRaysKernel, tc::uvec3{ size.x, size.y, 1 });
}

