/// Transmit an IR command to a Sherwood device.
/// Status: STABLE / Verified functionality.
/// @param[in] payload The data payload to be transmitted.
/// @param[in] bitCount The number of bits in the payload.
/// @param[in] repetitions The number of times the command should be repeated.
/// @note Sherwood remote signals follow the NEC protocol and require at least
///   one additional repeat transmission. Hence, repetitions must be >= 
///   kSherwoodMinRepeat (1).
void IRsend::sendSherwood(uint64_t payload, uint16_t bitCount, uint16_t repetitions) {
  sendNEC(payload, bitCount,
          std::max(static_cast<uint16_t>(kSherwoodMinRepeat), repetitions));
}
