#define DEBUG_TYPE "instcount"

STATISTIC(TotalInstructions, "Total count of all instructions processed");
STATISTIC(TotalBasicBlocks, "Total number of basic blocks encountered");
STATISTIC(TotalFunctions, "Total number of non-external functions");

#define HANDLE_INST(N, OPCODE, CLASS)                                          \
  STATISTIC(Num##OPCODE##Instructions, "Count of " #OPCODE " instructions");

#include "llvm/IR/Instruction.def"

namespace {

class InstructionCounter : public InstVisitor<InstructionCounter> {
  friend class InstVisitor<InstructionCounter>;

  void visitFunction(Function &Func) { 
    ++TotalFunctions; 
  }

  void visitBasicBlock(BasicBlock &BB) { 
    ++TotalBasicBlocks; 
  }

#define HANDLE_INST(N, OPCODE, CLASS)                                          \
  void visit##OPCODE(CLASS &Instr) {                                           \
    ++Num##OPCODE##Instructions;                                               \
    ++TotalInstructions;                                                       \
  }

#include "llvm/IR/Instruction.def"

  void visitInstruction(Instruction &Instr) {
    errs() << "Instruction Counter does not recognize: " << Instr;
    llvm_unreachable(nullptr);
  }
};

} // namespace

PreservedAnalyses InstCountPass::run(Function &F,
                                     FunctionAnalysisManager &FAM) {
  LLVM_DEBUG(dbgs() << "INSTCOUNT: analyzing function " << F.getName()
                    << "\n");
  InstructionCounter counter;
  counter.visit(F);
  return PreservedAnalyses::all();
}

