    try {
        throw fs::PathNotFoundError("Error: path not found");
    }
    catch (const std::runtime_error &err) {
        REQUIRE(std::strcmp(err.what(), "Error: path not found") == 0);
    }

    try {
        throw fs::PathNotFoundError("Error: path not found");
