TEST_CASE("Check if canonize works", "[Canonize]") {
    std::ofstream dummyfile("sample.txt");
    dummyfile << "Sample content for testing\n";
    dummyfile.close();

    auto canonicalPath = fs::Canonical("sample.txt");
    std::cout << "Ensure test path does not contain backslash\n";
    REQUIRE(canonicalPath.find_first_of('\\') == canonicalPath.npos);
    REQUIRE(canonicalPath.find_first_of('/') != canonicalPath.npos);
    REQUIRE(fs::Canonical(".").back() != '/');

    REQUIRE(fs::IsFile(canonicalPath));

    std::ifstream reader(canonicalPath);
    std::string line;
    std::getline(reader, line);
    REQUIRE(line == "Sample content for testing");

    fs::Delete("sample.txt");
}

