    REQUIRE(fs::Relative("sample.txt") == "sample.txt");
    REQUIRE(fs::Relative("sample.txt", fs::Canonical("somedir")) == "../sample.txt");
    REQUIRE(fs::Relative(fs::Canonical("sample.txt")) == "sample.txt");

    fs::Delete("sample.txt");
    fs::Delete("somedir");
}

