    REQUIRE(fs::Canonical(fs::CurrentDirectory()) == fs::Canonical(TESTDIR));
    REQUIRE(fs::CurrentDirectory().find_first_of('\\') == std::string::npos);

    fs::CreateDirectory("somedir");
    REQUIRE(fs::ChangeDirectory("somedir"));
    REQUIRE(fs::Canonical(fs::CurrentDirectory()) == fs::Canonical(TESTDIR "/somedir"));
    REQUIRE(fs::ChangeDirectory(".."));
    REQUIRE(fs::Canonical(fs::CurrentDirectory()) == fs::Canonical(TESTDIR));
    fs::Delete("somedir");
    REQUIRE_FALSE(fs::ChangeDirectory("somedir"));
}

TEST_CASE("Copy file", "[Copy]") {
    fs::Save("source.txt", "Source content\n");
    REQUIRE(fs::Copy("source.txt", "dest.txt"));
    REQUIRE(fs::Load("dest.txt") == "Source content\n");
    fs::Delete("source.txt");
    fs::Delete("dest.txt");
}

TEST_CASE("Copy binary file", "[Copy]") {
    std::string data = "Binary content\n";
    data.push_back(0);
    fs::Save("source.bin", data);
    REQUIRE(fs::Copy("source.bin", "dest.bin"));
    REQUIRE(fs::Load("dest.bin") == data);
    fs::Delete("source.bin");
    fs::Delete("dest.bin");
    REQUIRE_FALSE(fs::Copy("source.bin", "dest.bin"));
}

TEST_CASE("Copy directory", "[Copy]") {
    fs::CreateDirectory("srcdir/subdir");
    std::string binData = "Binary content\n";
    binData.push_back(0);
    fs::Save("srcdir/data.bin", binData);
    fs::Save("srcdir/subdir/info.txt", "Text content\n");

    REQUIRE(fs::Copy("srcdir", "dstdir"));
    REQUIRE(fs::IsDirectory("dstdir"));
    REQUIRE(fs::IsDirectory("dstdir/subdir"));
    REQUIRE(fs::Load("dstdir/data.bin") == binData);
    REQUIRE(fs::Load("dstdir/subdir/info.txt") == "Text content\n");

    fs::Delete("dstdir");

    fs::Iterator iterStart("srcdir"), iterEnd;
    fs::CreateDirectory("dstdir");
    REQUIRE(fs::Copy("srcdir", iterStart, iterEnd, "dstdir"));
    REQUIRE(fs::IsDirectory("dstdir"));
    REQUIRE(fs::IsDirectory("dstdir/subdir"));
    REQUIRE(fs::Load("dstdir/data.bin") == binData);
    REQUIRE(fs::Load("dstdir/subdir/info.txt") == "Text content\n");

    fs::Delete("dstdir");

    std::vector<std::string> paths;
    REQUIRE(fs::Copy(paths, "dstdir"));
    fs::CreateDirectory("dstdir");

    paths.push_back("srcdir/subdir");
    paths.push_back("srcdir/data.bin");
    REQUIRE(fs::Copy(paths, "dstdir"));
    REQUIRE(fs::IsDirectory("dstdir"));
    REQUIRE(fs::IsDirectory("dstdir/subdir"));
    REQUIRE(fs::Load("dstdir/data.bin") == binData);
    REQUIRE(fs::Load("dstdir/subdir/info.txt") == "Text content\n");

    fs::Delete("srcdir");
    fs::Delete("dstdir");
    REQUIRE_FALSE(fs::Copy(paths, "dstdir"));
    fs::Delete("dstdir");
}

TEST_CASE("Move file", "[Move]") {
    REQUIRE_FALSE(fs::Move("source.txt", "dest.txt"));
