GetBulkProfileDataProcessor::GetBulkProfileDataProcessor(SpectreRpcType rpcType) :
	WebsocketPacketProcessor(rpcType) {
}

void GetBulkProfileDataProcessor::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock) {
	std::unique_ptr<GetBulkProfileDataMessage> request = packet.GetPayloadAsMessage<GetBulkProfileDataMessage>();
	BulkProfileDataResponse response;

	for (int index = 0; index < request->playerids_size(); ++index) {
		response.add_bulkprofiledata()->CopyFrom(
			*PlayerDatabase::Get().GetField<ProfileData>(FieldKey::PROFILE_DATA, request->playerids(index))
		);
	}

	sock.SendPacket(response, packet.GetResponseType(), packet.GetRequestId());
}

