// Test that header file is self-contained.
#include "asio/coroutine.hpp"
#include "unit_test.hpp"

// Must come after all other headers.
#include "asio/yield.hpp"

//------------------------------------------------------------------------------
// Coroutine completes via yield break (modified version)
void modified_yield_break(asio::coroutine& coro)
{
  reenter (coro)
  {
    yield return;
    yield break;
  }
}

void modified_yield_break_test()
{
  asio::coroutine coro;
  ASIO_CHECK(!coro.is_complete());
  modified_yield_break(coro);
  ASIO_CHECK(!coro.is_complete());
  modified_yield_break(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes via early return (renamed)
void early_return_coroutine(asio::coroutine& coro)
{
  reenter (coro)
  {
    return;
  }
}

void early_return_test()
{
  asio::coroutine coro;
  early_return_coroutine(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes via exception handling (restructured)
void throwing_coroutine(asio::coroutine& coro)
{
  reenter (coro)
  {
    throw 42;
  }
}

void exception_handling_test()
{
  asio::coroutine coro;
  try { throwing_coroutine(coro); } catch (int) {}
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
// Coroutine completes by reaching end naturally
void natural_termination_coroutine(asio::coroutine& coro)
{
  reenter (coro)
  {
    // Empty body - falls through
  }
}

void natural_termination_test()
{
  asio::coroutine coro;
  natural_termination_coroutine(coro);
  ASIO_CHECK(coro.is_complete());
}

//------------------------------------------------------------------------------
ASIO_TEST_SUITE
(
  "coroutine",
  ASIO_TEST_CASE(modified_yield_break_test)
  ASIO_TEST_CASE(early_return_test)
  ASIO_TEST_CASE(exception_handling_test)
  ASIO_TEST_CASE(natural_termination_test)
)

