static cl::opt<std::string> InputFile(cl::Positional, 
                                      cl::desc("<input file>"),
                                      cl::init("-"));
static cl::opt<std::string> OutputFile("o", 
                                       cl::desc("Specify output filename"),
                                       cl::value_desc("filename"), 
                                       cl::Required);

int main(int argc, char **argv) {
  cl::ParseCommandLineOptions(argc, argv);

  LLVMContext ctx;
  SMDiagnostic diag;

  auto irModule = parseIRFile(InputFile, diag, ctx);
  if (!irModule) {
    diag.print(InputFile.data(), errs());
    return -1;
  }

  dynamic::MemoryInstrument memInst;
  memInst.runOnModule(*irModule);

  std::error_code err;
  ToolOutputFile outStream(OutputFile, err, sys::fs::OF_None);
  outStream.keep();
  WriteBitcodeToFile(*irModule, outStream.os());

  return 0;
}

