int main(int argc, char *argv[])
{
    QGuiApplication application(argc, argv);
    application.setApplicationName("Qt Mcp Example Window Server");
    application.setApplicationVersion("1.0");
    application.setOrganizationName("Signal Slot Inc.");
    application.setOrganizationDomain("signal-slot.co.jp");

    QCommandLineParser cmdParser;
    cmdParser.setApplicationDescription(application.applicationName());
    cmdParser.addHelpOption();
    cmdParser.addVersionOption();

    QCommandLineOption backendChoice(QStringList() << "b" << "backend",
                                     "Backend to use (stdio/sse).",
                                     "backend", "stdio");
