    QCommandLineOption listenAddress(QStringList() << "a" << "address",
                                     "Address to listen on (host:port).",
                                     "address", "127.0.0.1:8000");
    cmdParser.addOption(listenAddress);

    cmdParser.process(application);

    QString selectedBackend = cmdParser.value(backendChoice);
    QString serverAddress = cmdParser.value(listenAddress);

    QMcpServer mcpServer(selectedBackend);
