#include "TuyaDatapoints.h"
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandBool(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier, 
  bool dp_state, bool synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPBool(tuya_payload, dp_identifier, dp_state ? 1 : 0);

  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET, 
    TUYA_DP_ZCL_PAYLOAD_8, (uint8_t*)&tuya_payload, synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandEnum8(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier, 
  uint8_t dp_state, bool synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPEnum8(tuya_payload, dp_identifier, dp_state);

  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET, 
    TUYA_DP_ZCL_PAYLOAD_8, (uint8_t*)&tuya_payload, synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandValue32(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier, 
  uint32_t dp_state, bool synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPValue32(tuya_payload, dp_identifier, dp_state);

  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET, 
    TUYA_DP_ZCL_PAYLOAD_32, (uint8_t*)&tuya_payload, synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandData(
  ZigbeeGateway *hub, zbg_device_params_t *target, uint8_t dp_identifier,
  uint8_t dp_format, uint32_t dp_state, bool synchronous, uint8_t tuya_command) {
  switch (dp_format) {
    case TUYA_DP_TYPE_BOOL:
      return
        transmitTuyaCommandBool(
          hub, target, dp_identifier, dp_state, synchronous, tuya_command);
    break;
    case TUYA_DP_TYPE_VALUE:
      return
        transmitTuyaCommandValue32(
          hub, target, dp_identifier, dp_state, synchronous, tuya_command); 
    break;
    case TUYA_DP_TYPE_ENUM:
      return
        transmitTuyaCommandEnum8(
          hub, target, dp_identifier, dp_state, synchronous, tuya_command); 
    break;
    default:
      log_e("unsupported Tuya datapoint %02x format %02x", dp_identifier, dp_format); 
    break;
  }
  return false;
}
bool transmitTuyaQueryCommand(
  ZigbeeGateway *hub, zbg_device_params_t *target, bool synchronous) {
  return hub->sendCustomClusterCmd(
    target, TUYA_PRIVATE_CLUSTER_EF00, TUYA_QUERY_CMD, 
    ESP_ZB_ZCL_ATTR_TYPE_NULL, TUYA_DP_ZCL_PAYLOAD_0, nullptr, synchronous);
}

