// Function to perform TRSM operations based on TRANS mode
int CNAME(blas_arg_t *input_args, BLASLONG *range_m, BLASLONG *range_n, FLOAT *scratch_a, FLOAT *scratch_b, BLASLONG thread_id) {
#if TRANS == 1
    LASWP_PLUS(input_args->n, 1, input_args->m, ZERO, ZERO, input_args->b, input_args->ldb, NULL, 0, input_args->c, 1);
    TRSM_LNLU(input_args, range_m, range_n, scratch_a, scratch_b, 0);
    TRSM_LNUN(input_args, range_m, range_n, scratch_a, scratch_b, 0);
#elif TRANS == 2
    TRSM_LTUN(input_args, range_m, range_n, scratch_a, scratch_b, 0);
    TRSM_LTLU(input_args, range_m, range_n, scratch_a, scratch_b, 0);

    LASWP_MINUS(input_args->n, 1, input_args->m, ZERO, ZERO, input_args->b, input_args->ldb, NULL, 0, input_args->c, -1);
#elif TRANS == 3
    LASWP_PLUS(input_args->n, 1, input_args->m, ZERO, ZERO, input_args->b, input_args->ldb, NULL, 0, input_args->c, 1);
    TRSM_LRLU(input_args, range_m, range_n, scratch_a, scratch_b, 0);
    TRSM_LRUN(input_args, range_m, range_n, scratch_a, scratch_b, 0);
#else
    TRSM_LCUN(input_args, range_m, range_n, scratch_a, scratch_b, 0);
    TRSM_LCLU(input_args, range_m, range_n, scratch_a, scratch_b, 0);
    LASWP_MINUS(input_args->n, 1, input_args->m, ZERO, ZERO, input_args->b, input_args->ldb, NULL, 0, input_args->c, -1);
#endif
    return 0;
}

