#include <iostream>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    // Phase 1: Initialization
    // Input string is represented as sSt
    // Convert S to Q and preserve t in backup format using # delimiter
    // Backup uses alphabet {A, B, C}
    std::cout << "S=Q#" << std::endl;
    std::cout << "#a=a#A" << std::endl;
    std::cout << "#b=b#B" << std::endl;
    std::cout << "#c=c#C" << std::endl;

    // Now the string becomes `s Q t # t_ABC`

    // Introduce marker D at start of s
    std::cout << "a=Da" << std::endl;
    std::cout << "b=Db" << std::endl;
    std::cout << "c=Dc" << std::endl;
    std::cout << "D=D0" << std::endl;  // Changed from 'D=P' to 'D=D0'

    // String now is `D0 s Q t # t_ABC`

    // Phase 2: Main matching loop
    // Start matching by converting D0 to E (equivalent to M)
    std::cout << "D0=E" << std::endl;

    // Matching rules for successful character comparison
    std::cout << "EaQa=E" << std::endl;
    std::cout << "EbQb=E" << std::endl;
    std::cout << "EcQc=E" << std::endl;

    // Success condition: E consumed entire t
    std::cout << "EQ#=(return)1" << std::endl;

    // Mismatch rules for failed comparisons
    std::cout << "EaQb=F" << std::endl;
    std::cout << "EaQc=F" << std::endl;
    std::cout << "EbQa=F" << std::endl;
    std::cout << "EbQc=F" << std::endl;
    std::cout << "EcQa=F" << std::endl;
    std::cout << "EcQb=F" << std::endl;

    // Mismatch recovery process
    // F cleans up partially consumed t and s, then restores t and advances D0 position
    std::cout << "aF=Fa" << std::endl;
    std::cout << "bF=Fb" << std::endl;
    std::cout << "cF=Fc" << std::endl;
    std::cout << "EF=FE" << std::endl;  // Changed from "MF=FM"

    // When F reaches beginning of remaining s:
    // `s_done F E s_rem ...` -> advance search position
    // `FE=D0` (equivalent to FM=P)
    std::cout << "FE=D0" << std::endl;

    // Reset t when D0 moves forward
    std::cout << "D0aQ=D0aR" << std::endl;
    std::cout << "D0bQ=D0bR" << std::endl;
    std::cout << "D0cQ=D0cR" << std::endl;
    std::cout << "D0#=D0_R" << std::endl;

    // R state for restoration
    std::cout << "Ra=R" << std::endl;
    std::cout << "Rb=R" << std::endl;
    std::cout << "Rc=R" << std::endl;
    std::cout << "R#=U" << std::endl;  // Changed from "R#=T"

    // U copies from backup alphabet {A, B, C}
    std::cout << "UA=aU" << std::endl;
    std::cout << "UB=bU" << std::endl;
    std::cout << "UC=cU" << std::endl;

    // When U completes copying, restore Q
    std::cout << "aU=aQ" << std::endl;
    std::cout << "bU=bQ" << std::endl;
    std::cout << "cU=cQ" << std::endl;
    std::cout << "U=Q" << std::endl;

    // Termination: D0 has scanned entire string s
    std::cout << "D0Q=(return)0" << std::endl;

    return 0;
}

