        .AddLongOption('o', "output-profile", "Path for the output profile (defaults to input path)")
        .Optional()
        .StoreResult(&outputProfile);

    NLastGetopt::TOptsParseResult result(&options, argc, argv);

    if (TString(outputProfile).empty()) {
        outputProfile = inputProfile;
    }

    TFileInput inputStream(inputProfile);
    NPerforator::NProto::NPProf::Profile profileData;

    if (TString{inputProfile}.EndsWith(".tar.gz")) {
        TZLibDecompress decompressor(&inputStream);
        profileData.ParseFromArcadiaStream(&decompressor);
    } else {
        profileData.ParseFromArcadiaStream(&inputStream);
    }

    NPerforator::NSymbolize::TProfileSymbolizer symbolizerInstance;
    symbolizerInstance.Symbolize(profileData);

    TFileOutput outputStream(outputProfile);
    TZLibCompress compressor(&outputStream, ZLib::GZip, 1);
    profileData.SerializeToArcadiaStream(&compressor);
}

