#include "Packets/DMXProtocolArtNetPackets.h"
#include "DMXProtocolTypes.h"
#include "DMXProtocolMacros.h"
#include "Serialization/BufferArchive.h"

// Register all Art-Net packet types for serialization
REGISTER_DMX_ARCHIVE(FDMXProtocolArtNetDMXPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolArtNetPollPacket);
REGISTER_DMX_ARCHIVE(FDMXProtocolArtNetPacketReply);
REGISTER_DMX_ARCHIVE(FDMXProtocolArtNetTodRequest);
REGISTER_DMX_ARCHIVE(FDMXProtocolArtNetTodData);
REGISTER_DMX_ARCHIVE(FDMXProtocolArtNetTodControl);
REGISTER_DMX_ARCHIVE(FDMXProtocolArtNetRDM);

// Pack DMX data into a buffer archive
TSharedPtr<FBufferArchive> FDMXProtocolArtNetDMXPacket::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

// Serialize DMX packet fields to/from archive
void FDMXProtocolArtNetDMXPacket::Serialize(FArchive & Stream)
{
	Stream.Serialize((void*)Identifier, ARTNET_STRING_SIZE);
	Stream << Opcode;
	Stream << VersionHigh;
	Stream << Version;
	Stream << SeqNum;
	Stream << PhysicalPort;
	Stream << NetAddress;
	Stream << DataLengthHi;
	Stream << DataLength;
	Stream.Serialize((void*)Payload, ARTNET_DMX_LENGTH);
}

// Pack Poll packet into buffer archive
TSharedPtr<FBufferArchive> FDMXProtocolArtNetPollPacket::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

// Serialize Poll packet fields
void FDMXProtocolArtNetPollPacket::Serialize(FArchive & Stream)
{
	Stream.Serialize((void*)Identifier, ARTNET_STRING_SIZE);
	Stream << Opcode;
	Stream << VersionHigh;
	Stream << Version;
	Stream << ConfigFlags;
	Stream << PriorityLevel;
}

// Serialize Packet Reply fields
void FDMXProtocolArtNetPacketReply::Serialize(FArchive & Stream)
{
	Stream.Serialize((void*)Identifier, ARTNET_STRING_SIZE);
	Stream << Opcode;
	Stream.Serialize((void*)IpAddress, sizeof(IpAddress));
	Stream << UdpPort;
	Stream << FirmwareVersion;
	Stream << NetSwitch;
	Stream << SubnetSwitch;
	Stream << OemCode;
	Stream << UbeaEnabled;
	Stream << NodeStatus1;
	Stream << EstaManufacturerId;
	Stream.Serialize((void*)ShortNameStr, ARTNET_SHORT_NAME_LENGTH);
	Stream.Serialize((void*)LongNameStr, ARTNET_LONG_NAME_LENGTH);
	Stream.Serialize((void*)ReportData, ARTNET_REPORT_LENGTH);
	Stream.Serialize((void*)PortCount, sizeof(PortCount));
	Stream.Serialize((void*)PortType, ARTNET_MAX_PORTS);
	Stream.Serialize((void*)InputActive, ARTNET_MAX_PORTS);
	Stream.Serialize((void*)OutputActive, ARTNET_MAX_PORTS);
	Stream.Serialize((void*)SwInput, ARTNET_MAX_PORTS);
	Stream.Serialize((void*)SwOutput, ARTNET_MAX_PORTS);
	Stream << VideoConfig;
	Stream << MacroSupport;
	Stream << RemoteControl;
	Stream << Reserved1;
	Stream << Reserved2;
	Stream << Reserved3;
	Stream << NodeStyle;
	Stream.Serialize((void*)MacAddress, sizeof(MacAddress));
	Stream.Serialize((void*)BindIpAddr, sizeof(BindIpAddr));
	Stream << BindIndexVal;
	Stream << NodeStatus2;
	Stream.Serialize((void*)Padding, sizeof(Padding));
}

// Pack TOD Request packet
TSharedPtr<FBufferArchive> FDMXProtocolArtNetTodRequest::Pack()
{
	TSharedPtr<FBufferArchive> Serializer = MakeShared<FBufferArchive>();
	*Serializer << *this;
	return Serializer;
}

// Serialize TOD Request fields
void FDMXProtocolArtNetTodRequest::Serialize(FArchive & Stream)
{
	Stream.Serialize((void*)Identifier, ARTNET_STRING_SIZE);
	Stream << Opcode;
	Stream << VersionHigh;
	Stream << Version;
	Stream << Reserved1;
	Stream << Reserved2;
	Stream << SpareByte1;
	Stream << SpareByte2;
	Stream << SpareByte3;
	Stream << SpareByte4;
	Stream << SpareByte5;
	Stream << SpareByte6;
	Stream << SpareByte7;
	Stream << NetAddress;
	Stream << CommandCode;
	Stream << DeviceCount;
	Stream.Serialize((void*)DeviceList, ARTNET_MAX_RDM_ADCOUNT);
}

// Pack TOD Data packet
TSharedPtr<FBufferArchive> FDMXProtocolArtNetTodData::Pack()
