// Serialize RDM packet fields
void FDMXProtocolArtNetRDM::Serialize(FArchive & Stream)
{
	Stream.Serialize((void*)Identifier, ARTNET_STRING_SIZE);
	Stream << Opcode;
	Stream << VersionHigh;
