                              "32768", "65535", "65k",   "100000000",  "1m",
                              "10m",   "100m",  "4000m", "4294967295", "1g",
                              "2g",    "3g",    "4g"};
  for (auto val : valid_vals) {
    std::string temp(val);
    uint32_t factor = 1;
    if (temp.ends_with('k')) {
      temp = temp.substr(0, temp.size() - 1);
      factor = 1000;
    } else if (temp.ends_with('m')) {
      temp = temp.substr(0, temp.size() - 1);
      factor = 1000 * 1000;
    } else if (temp.ends_with('g')) {
      temp = temp.substr(0, temp.size() - 1);
      factor = 1000 * 1000 * 1000;
    }
    EXPECT_EQ(std::stoull(temp) * factor,
              sdb::options::units_helper::ToNumber<uint32_t>(val));
  }
  const char* invalid_vals[] = {"-1",    "-66666",     "-129", "-255", "-10000",
                                "4500m", "4294967296", "4GiB", "5g"};
  for (auto val : invalid_vals) {
    try {
      sdb::options::units_helper::ToNumber<uint32_t>(val);
      FAIL() << "Should have thrown out_of_range";
    } catch (const std::out_of_range&) {
    }
  }
}

