TEST(HttpRequestTest, testUrlEncoding) {
  ConnectionInfo connInfo;
  HttpRequest req(connInfo, 1);
  std::string_view path(
    "/api/v1/"
    "data?key=%2fpath%2ffile%2etxt&num=123&msg=hello+world&special=%2F%5B%5D%3D%3F%26&tab=%09");
  req.parseUrl(path.data(), path.size());
  EXPECT_EQ("/path/file.txt", req.value("key"));
  EXPECT_EQ("123", req.value("num"));
  EXPECT_EQ("hello world", req.value("msg"));
  EXPECT_EQ("/[]=?&", req.value("special"));
  EXPECT_EQ("\x09", req.value("tab"));
}

