#include "unittest/gtest.hpp"
#include "arch/streamed_tcp.hpp"
namespace unittest {
namespace {
// Initiates a RethinkDB IO layer thread pool and executes the provided callback within a coroutine
struct thread_pool_runner : public thread_message_t {
    thread_pool_t *pool;
    boost::function<void()> callback;
    thread_pool_runner(thread_pool_t *p, boost::function<void()> f) : pool(p), callback(f) { }

    void execute() {
        callback();
        pool->shutdown();
    }

    void on_thread_change() {
        coro_t::spawn_now(boost::bind(&thread_pool_runner::execute, this));
    }
};

void run_with_thread_pool(boost::function<void()> func) {
    thread_pool_t pool(1);
    thread_pool_runner runner(&pool, func);
    pool.run(&runner);
}

void echo_connection_handler(boost::scoped_ptr<streamed_tcp_conn_t> &connection) {
    while (connection->get_istream().good()) {
        // Read input and echo it back
        std::string line;
        connection->get_istream() >> line;
        if (!connection->get_istream().fail()) {
            connection->get_ostream() << line << std::endl; // endl triggers flush
        }
    }
}

}   /* anonymous namespace */

void perform_tcp_echo_test() {
    int server_port = 10000 + (rand() % 20000);
    streamed_tcp_listener_t server(server_port, boost::bind(&echo_connection_handler, _1));
    streamed_tcp_conn_t client("localhost", server_port);

    std::string base_string = "0";
    for (int counter = 0; counter < (8192 / 32); ++counter) {
        base_string += std::string(32, static_cast<char>('a' + (counter % 26)));

        // Split string into two parts and send
        client.get_ostream() << base_string.substr(0, counter);
        client.get_ostream() << base_string.substr(counter) << std::endl;

        // Receive and verify response
        std::string received;
        client.get_istream() >> received;

        EXPECT_TRUE(!client.get_istream().fail());
        EXPECT_EQ(received, base_string);
    }
    client.get_ostream().flush();
}

TEST(TCPStreamTest, StartStop) {
    run_with_thread_pool(&perform_tcp_echo_test);
}
}

