// Threshold for low-memory devices: RAM below this value (in MB) qualifies
#define LOW_RAM_THRESHOLD_MB 512

// Convert MB to bytes for comparison with AmountOfPhysicalMemory()
const int64 kLowRamThresholdBytes = 
    static_cast<int64>(LOW_RAM_THRESHOLD_MB) * 1024 * 1024;

// Minimum SDK version required to consider low-end device classification
const int kMinSdkForLowEndDetection = 18; // Android JELLY_BEAN_MR2

// JNI method implementation
static jboolean IsLowEndDevice(JNIEnv* env, jclass clazz) {
  return base::android::SysUtils::IsLowEndDevice() ? JNI_TRUE : JNI_FALSE;
}

namespace base {
namespace android {

bool SysUtils::Register(JNIEnv* env) {
  return RegisterNativesImpl(env);
}

bool SysUtils::IsLowEndDevice() {
  const int64 physical_memory = SysInfo::AmountOfPhysicalMemory();
  const BuildInfo* build_info = BuildInfo::GetInstance();

  // A device is considered low-end if:
  // 1. Its physical memory is at or below the threshold
  // 2. AND its SDK version is higher than the minimum required version
  return physical_memory <= kLowRamThresholdBytes &&
         build_info->sdk_int() > kMinSdkForLowEndDetection;
}

SysUtils::SysUtils() { }

