#include <random>
#include <chrono>
#include <cstdlib>
#include <iostream>
#include "caf/all.hpp"

using namespace caf;
using std::endl;

int main() {
  // Seed random number generator with current time
  std::srand(static_cast<unsigned>(std::time(nullptr)));

  // Spawn 50 actors using a different loop structure
  int actor_count = 1;
  while (actor_count <= 50) {
    spawn<blocking_api>([actor_count](blocking_actor* self) {
      // Print initial greeting message
      aout(self) << "Hi there! This is actor nr. "
                 << actor_count << "!" << endl;

      // Generate random delay between 0-9 milliseconds
      std::random_device rd;
      std::default_random_engine re(rd());
      std::chrono::milliseconds tout{re() % 10};

      // Schedule a 'done' message to self
      self->delayed_send(self, tout, atom("done"));

      // Wait for the delayed message and respond
      self->receive(others() >> [actor_count, self] {
        aout(self) << "Actor nr. "
                   << actor_count << " says goodbye!" << endl;
      });
    });

    // Increment counter instead of using for-loop increment
    ++actor_count;
  }

  // Wait for all spawned actors to complete their execution
  await_all_actors_done();

  // Clean shutdown of the actor system
  shutdown();
  return 0;
}

