// Optimized version of the trigonometric benchmark
#include <math.h>
volatile double sum = 0.0; // volatile, global so not optimized away
static void Trig(benchmark::State &state)
{
    double increment = 0.000001;
    double current_val = 0.01;

    while (state.KeepRunning())
    {
        sum += sin(current_val);
        current_val += increment;
    }
}
