    // Output all successfully recognized tokens
    for (const auto& token : tokens) {
        cout << *token << '\n';
    }

    // Report any lexical errors to standard error stream
    for (const auto& msg : errors) {
        cerr << msg << '\n';
    }

    // Handle lexical errors: exit with non-zero status if any occurred
    if (!errors.empty()) {
