// Check if message can be enqueued with space for payload + line ending
bool tryEnqueueMessage(QUEUE_TYPE(uint8_t)* queue, uint8_t* data,
        int length) {
    // Reserve space for two additional characters: '\r' and '\n'
    if(queue_available(queue) < length + 2) {
        return false;
    }

    // Copy each byte of the message into the queue
    for(int idx = 0; idx < length; idx++) {
        QUEUE_PUSH(uint8_t, queue, (uint8_t)data[idx]);
    }

    // Append line termination sequence
    QUEUE_PUSH(uint8_t, queue, (uint8_t)'\r');
    QUEUE_PUSH(uint8_t, queue, (uint8_t)'\n');
    return true;
}

// Attempt to send a message over both USB and serial interfaces
void transmitMessage(Listener* listener, uint8_t* payload, int size) {
    // Try sending via USB first
    if(!tryEnqueueMessage(&listener->usb->sendQueue, payload, size)) {
        debug("USB send buffer overflow, discarding CAN message: %s\r\n", payload);
    }

    // Then attempt serial transmission
    if(!tryEnqueueMessage(&listener->serial->sendQueue, payload, size)) {
        debug("UART send buffer overflow, discarding CAN message: %s\r\n", payload);
    }
}

// Handle input processing for all communication channels
void handleListenerBuffers(Listener* listener) {
    // USB processing is mandatory — it includes critical USB task handling
    processInputQueue(listener->usb);
    processInputQueue(listener->serial);
}

