int main(int argument_count, char** arguments) {
    using std::cout;
    using std::endl;
    using std::string;
    using std::stringstream;
    using std::thread;
    using std::vector;

    // Determine number of threads from command line arguments
    vector<thread>::size_type thread_count = argument_count - 1;
    vector<thread> thread_pool;
    thread_pool.reserve(thread_count);

    // Process each argument and spawn threads
    for (int index = 1; index < argument_count; ++index) {
        stringstream converter;
        converter << arguments[index];
        unsigned int parsed_value;

        if (!(converter >> parsed_value)) {
            cout << "Invalid input detected: " << arguments[index] << " is not an integer." << endl;
        } else {
            thread_pool.emplace_back(worker_thread, parsed_value);
        }
    }

    // Wait for all threads to complete
    for (auto& active_thread : thread_pool) {
        active_thread.join();
    }

    return 0;
}

