// Sort the values to group identical entries together
std::sort(values.begin(), values.end());

// Eliminate consecutive duplicate elements (version numbers are compared, product names ignored)
auto newEnd = std::unique(values.begin(), values.end());
values.erase(newEnd, values.end());

// Apply setCurVer to each remaining element
std::for_each(values.begin(), values.end(),
              boost::bind(&setCurVer, hModule, _1));

// Create a filtered list containing only pure AutoCAD entries
AutoCadInfoVector pureAcadsOnly;
pureAcadsOnly.reserve(values.size());

std::copy_if(values.begin(), values.end(),
             std::back_inserter(pureAcadsOnly),
             [](const AutoCadInfo& info) { return info.isPureAutoCad(); });

// Set non-versionized CurVer: use latest pure AutoCAD if available,
// otherwise fall back to the first (latest) entry in original list
if (pureAcadsOnly.empty()) {
    setNonVersionizedCurVer(hModule, values.front());
} else {
    setNonVersionizedCurVer(hModule, pureAcadsOnly.front());
}

