FrequencyMap::FrequencyMap(const std::vector<std::size_t>& frequencies)
    : m_sum(0) {
  m_table.reserve(frequencies.size());
  for (const auto& freq : frequencies) {
    m_sum += freq;
    m_table.emplace_back(m_sum);
  }
}

std::size_t FrequencyMap::lookup(std::size_t value) const {
  return static_cast<std::size_t>(
      std::upper_bound(m_table.begin(), m_table.end(), value) - m_table.begin());
}

std::size_t FrequencyMap::total() const {
  return m_sum;
}

} // namespace detail
} // namespace rc

