void verify_cell_for_point(Triangulation<3> &mesh, const Point<3> &query_point)
{
  auto found_cell = GridTools::find_active_cell_around_point(mesh, query_point);
  deallog << found_cell << std::endl;

  for (unsigned int vertex_index = 0; 
       vertex_index < GeometryInfo<2>::vertices_per_cell; 
       ++vertex_index)
  {
    deallog << "<" << found_cell->vertex(vertex_index) << "> ";
  }
  deallog << std::endl;

  Assert(query_point.distance(found_cell->center()) < found_cell->diameter() / 2,
         ExcInternalError());
}

int main() 
{
  std::ofstream log_file("find_cell_1/output");
  deallog.attach(log_file);
  deallog.depth_console(0);
  deallog.threshold_double(1.e-10);

  Triangulation<3> grid;
  GridGenerator::hyper_cube(grid);
  grid.refine_global(3);

  Point<3> test_point(0.75, 0.0, 0.0);
  verify_cell_for_point(grid, test_point);
}

