#include <stdio.h>
#include <Halide.h>
using namespace Halide;

int main(int argc, char **argv) {
    Var i, j;
    Func condition("condition");
    condition(i, j) = j > i;  // Equivalent to i < j

    Func mask("mask");
    mask(i, j) = select(condition(i, j), 1, 0);

    // Compute root for both functions
    condition.compute_root();
    mask.compute_root().vectorize(i, 8);

    // Define domain for summation
    RDom domain(0, 100, 0, 100);

    // Calculate sum using lambda expression
    int32_t computed_sum = evaluate<int32_t>(lambda(sum(mask(domain.x, domain.y))));

    // Verify result matches expected value
    if (computed_sum == 4950) {
        printf("Success!\n");
        return 0;
    } else {
        printf("Failed: expected 4950, got %d\n", computed_sum);
        return 1;
    }
}

