using namespace llvm;

// Internal storage for loaded plugin filenames
static ManagedStatic<std::vector<std::string>> LoadedPlugins;

// Overloaded assignment operator to load a plugin from a file path
void PluginLoader::operator=(const std::string& filepath) {
    std::string loadError;

    // Attempt to permanently load the dynamic library
    if (sys::DynamicLibrary::LoadLibraryPermanently(filepath.c_str(), &loadError)) {
        // Report failure and ignore the request
        cerr << "Error opening '" << filepath << "': " << loadError
             << "\n  -load request ignored.\n";
    } else {
        // Successfully loaded, store the filename
        LoadedPlugins->push_back(filepath);
    }
}

// Return the number of currently loaded plugins
unsigned PluginLoader::getNumPlugins() {
    return LoadedPlugins.isConstructed() ? LoadedPlugins->size() : 0;
}

// Retrieve a specific plugin filename by index
std::string& PluginLoader::getPlugin(unsigned index) {
    // Ensure the plugin list is initialized and index is valid
    assert(LoadedPlugins.isConstructed() && 
           index < LoadedPlugins->size() &&
           "Asking for an out-of-bounds plugin");

    return (*LoadedPlugins)[index];
}

