JobIdentifier::JobIdentifier()
{
  // Generate timestamp string
  std::time_t currentTime = std::time(nullptr);
  char timeBuffer[64];
  std::strftime(timeBuffer, sizeof(timeBuffer), "%a %b %d %H:%M:%S %Y", 
                std::localtime(&currentTime));

  // Start building the identifier with program name
  id = std::string(program_id()) + " ";

  // Add hostname if available and not in debug mode
#if defined(HAVE_GETHOSTNAME) && !defined(DEBUG)
  char hostName[100];
  gethostname(hostName, sizeof(hostName));
  id += std::string(hostName) + " ";
#else
  id += "unknown ";
#endif

  // Append formatted timestamp (removing trailing newline from ctime)
  id += std::string(timeBuffer);
}

const std::string
JobIdentifier::operator ()() const
{
  return id;
}

