void displayMenuHeader(const string& heading) {
    // Position cursor at row 5, column 5
    move(5, 5);

    // Output each character of the title with a space after
    for (size_t idx = 0; idx < heading.length(); ++idx) {
        addch(heading[idx]);
        addch(' ');
    }

    // Add menu items
    appendMenuItem(1, "start");
    appendMenuItem(2, "quit");

    // Finalize menu layout
    finalizeMenuDisplay();
    refresh();

    // Keep screen displayed
    while (true);
}

