class SmallStringTest : public testing::Test {
protected:
  using StringType = SmallString<40>;
  StringType theString;

  void verifyEmpty(StringType & container) {
    // Verify size-related properties
    EXPECT_EQ(0u, container.size());
    EXPECT_TRUE(container.empty());

    // Verify iterator behavior
    EXPECT_TRUE(container.begin() == container.end());
  }
};

// Test that a newly constructed SmallString is empty
TEST_F(SmallStringTest, EmptyStringTest) {
  SCOPED_TRACE("EmptyStringTest");
  verifyEmpty(theString);
  EXPECT_TRUE(theString.rbegin() == theString.rend());
}

