// Custom visitor for debugging TAC program structure
struct DebugVisitor : public boost::static_visitor<> {
    void operator()(tac::Program& program) {
        std::cout << "Three-Address Code Program" << std::endl << std::endl;
        traverse_all(*this, program.functions);
    }

    void operator()(std::shared_ptr<tac::Function> function) {
        std::cout << "Function: " << function->getName() << std::endl;
        traverse_each(*this, function->getStatements());
    }

    void operator()(tac::Quadruple& quadruple) {
        // No output needed for quadruples in debug mode
    }

    void operator()(tac::IfFalse& ifFalse) {
        // No output needed for conditional jumps in debug mode
    }

    void operator()(tac::Goto& goto_) {
        // No output needed for unconditional jumps in debug mode
    }

    void operator()(tac::Param& param) {
        // No output needed for parameter instructions in debug mode
    }

    void operator()(tac::Return& return_) {
        // No output needed for return statements in debug mode
    }

    void operator()(tac::Call& call) {
        // No output needed for function calls in debug mode
    }

    void operator()(std::string& label) {
        std::cout << label << ":" << std::endl;
    }
};

void tac::Printer::print(tac::Program& program) const {
    DebugVisitor debugVisitor;
    debugVisitor(program);
}

