// Fast exponentiation using binary method
unsigned long long power(unsigned long long base, unsigned long long exp) {
    unsigned long long res = 1;
    while (exp > 0) {
        if (exp & 1) {
            res *= base;
        }
        base *= base;
        exp >>= 1;
    }
    return res;
}

// Compute floor of log base 2
unsigned int integer_log2(unsigned long long value) {
    if (value == 0) return 0;
    unsigned int count = 0;
    while (value > 1) {
        value >>= 1;
        ++count;
    }
    return count;
}

int main() {
    // Simulate multiple random number generators with different seeds/initializations
    // Using simple LCG-like behavior for demonstration (not cryptographically secure)
    class SimpleLCG {
    private:
        unsigned long long state;
        static constexpr unsigned long long A = 6364136223846793005ULL;
        static constexpr unsigned long long C = 1442695040888963407ULL;
    public:
        SimpleLCG(unsigned long long seed = 12345) : state(seed) {}

        unsigned long long operator()() {
            state = A * state + C;
            return state;
        }

        void jump(int steps) {
            // Simulate jump by advancing the generator
            for (int i = 0; i < steps; ++i) {
                (*this)();
            }
        }

        void jump2(int steps) {
            // Alternative jump method
            for (int i = 0; i < steps % 64; ++i) {
                (*this)();
            }
        }

        void split(int total_parts, int part_index) {
            // Initialize based on part index to simulate splitting
            state = 111 * (part_index + 1) * 100 + part_index;
        }
    };

    // Create instances simulating the original code's generators
    SimpleLCG default_gen;
    SimpleLCG seed_111(111);
    SimpleLCG split_3_0;
    split_3_0.split(3, 0);
    SimpleLCG split_3_1;
    split_3_1.split(3, 1);
    SimpleLCG split_3_2;
    split_3_2.split(3, 2);
    SimpleLCG jump_gen;
    SimpleLCG jump2_gen;

    std::cout << "# default, seed 111, split 3-0, split 3-1, split 3-2, jump-6361, jump2-5657" << std::endl;

    for (int i = 0; i < 1009; ++i) {
        std::cout << static_cast<long long>(default_gen()) << ',';
        std::cout << static_cast<long long>(seed_111()) << ',';
        std::cout << static_cast<long long>(split_3_0()) << ',';
        std::cout << static_cast<long long>(split_3_1()) << ',';
        std::cout << static_cast<long long>(split_3_2()) << ',';

        jump_gen.jump(i);
        std::cout << static_cast<long long>(jump_gen()) << ',';

        jump2_gen.jump2(i % 64);
        std::cout << static_cast<long long>(jump2_gen()) << '\n';
    }

    return 0;
}

