IListIteratorBase::IListIteratorBase()
  : mpCurrentNode(nullptr) {
}

IListIteratorBase::IListIteratorBase(IListNodeBase* pNodeRef)
  : mpCurrentNode(pNodeRef) {
}

void IListIteratorBase::advance() {
  if (nullptr == mpCurrentNode) {
    assert(false && "null iterator cannot move forward");
  }
  mpCurrentNode = mpCurrentNode->next();
}

void IListIteratorBase::retreat() {
  if (nullptr == mpCurrentNode) {
    assert(false && "null iterator cannot move backward");
  }
  mpCurrentNode = mpCurrentNode->previous();
}

