// Constructor: Initialize ADC for continuous sampling with power-saving features
AnalogAccel::AnalogAccel()
{
    // Configure ADC clock prescaler to 64 (12MHz / 64 = 187.5kHz)
    // Enable interrupt, auto-triggering, start conversion, and activate ADC
    ADCSRA |= _BV(ADPS1) | _BV(ADPS2) | _BV(ADIE) | _BV(ADATE) \
            | _BV(ADSC) | _BV(ADEN);

    // Set free-running mode (default when ADCSRB is zero)
    ADCSRB = 0x00;

    // Disable digital input buffers on ADC pins to reduce power consumption
    DIDR0 |= _BV(ADC0D) | _BV(ADC1D) | _BV(ADC2D);
}

// Destructor: Safely shut down the ADC module
AnalogAccel::~AnalogAccel()
{
    // Turn off the ADC, which also disables associated interrupts
    ADCSRA &= ~_BV(ADEN);
}

