#include <test.hpp>
#include <limits>

TEST_CASE("variable-length integer encoding/decoding") {
    std::string encoded_data;
    mapbox::util::pbf_writer encoder(encoded_data);

    SECTION("32-bit signed integer roundtrip") {
        encoder.add_int32(1, 42);
        mapbox::util::pbf decoder(encoded_data.data(), encoded_data.size());
        REQUIRE(decoder.next());
        REQUIRE(42 == decoder.get_int32());
    }

    SECTION("32-bit unsigned integer roundtrip") {
        encoder.add_uint32(1, 99U);
        mapbox::util::pbf decoder(encoded_data.data(), encoded_data.size());
        REQUIRE(decoder.next());
        REQUIRE(99U == decoder.get_uint32());
    }

    SECTION("64-bit unsigned integer with large value") {
        uint64_t large_value = (1ULL << 50);
        encoder.add_uint64(1, large_value);
        mapbox::util::pbf decoder(encoded_data.data(), encoded_data.size());
        REQUIRE(decoder.next());
        REQUIRE(large_value == decoder.get_uint64());
    }

    SECTION("truncated buffer during varint decoding") {
        encoder.add_uint64(1, (1ULL << 35));
        encoded_data.pop_back(); // shorten buffer by one byte
        mapbox::util::pbf decoder(encoded_data.data(), encoded_data.size());
        REQUIRE(decoder.next());
        REQUIRE_THROWS_AS(decoder.get_uint64(), mapbox::util::pbf::end_of_buffer_exception);
    }

    SECTION("corrupted varint - missing final byte") {
        encoder.add_uint64(1, (1ULL << 28));
        encoded_data[encoded_data.size() - 1] |= 0x80; // mark continuation bit as set
        mapbox::util::pbf decoder(encoded_data.data(), encoded_data.size());
        REQUIRE(decoder.next());
        REQUIRE_THROWS_AS(decoder.get_uint64(), mapbox::util::pbf::end_of_buffer_exception);
    }

    SECTION("corrupted varint - exceeds maximum length") {
        encoder.add_uint64(1, std::numeric_limits<uint64_t>::max());
        encoded_data.back() |= 0x80; // force extra continuation byte beyond valid range
        mapbox::util::pbf decoder(encoded_data.data(), encoded_data.size());
        REQUIRE(decoder.next());
        REQUIRE_THROWS_AS(decoder.get_uint64(), mapbox::util::pbf::varint_too_long_exception);
    }
}

