/***************
 * CELL_REFINE *
 ***************/
// Triangular
tuple TriangularCartesian2D_Domain_cell_refine(TriangularCartesian2D_Domain domain_in, 
                                               TriangularCartesian2D_Segmentation segmentation_in, 
                                               bool (*predicate)(const TriangularCartesian2D_Cell &))
{
    TriangularCartesian2D_Domain          domain_out;
    TriangularCartesian2D_Segmentation    segmentation_out(domain_out);

    // Container to store refinement flags for cells
    CellRefinementFlagContainerType     cell_refinement_flags;

    // Create a field to associate refinement flags with cells
    viennagrid::result_of::field<CellRefinementFlagContainerType,
                                 TriangularCartesian2D_Cell_t>::type  
        refinement_flag_field(cell_refinement_flags);

    // Iterate over all cells and mark those that satisfy the refinement predicate
    TriangularCartesian2D_CellRange_t cells = viennagrid::elements(domain_in.get_domain());
    for (TriangularCartesian2D_CellRange_t::iterator it = cells.begin(); 
         it != cells.end(); 
         ++it)
    {
        if (predicate(TriangularCartesian2D_Cell(*it)))
            refinement_flag_field(*it) = true;
    }

    // Perform mesh refinement based on the marked cells
    viennagrid::cell_refine(domain_in.get_domain(),
                            segmentation_in.get_segmentation(),
                            domain_out.get_domain(),
                            segmentation_out.get_segmentation(),
                            refinement_flag_field);

    // Return the refined domain and segmentation as a tuple
    return make_tuple<TriangularCartesian2D_Domain, TriangularCartesian2D_Segmentation>(domain_out, segmentation_out);
}

#include "StorageDeleteFileChunkJob.h"
#include "System/Stopwatch.h"
#include "System/FileSystem.h"
#include "StorageFileChunk.h"

StorageDeleteFileChunkJob::StorageDeleteFileChunkJob(StorageFileChunk* chunk_)
    : chunk(chunk_) {}

void StorageDeleteFileChunkJob::Execute() {
    Stopwatch timer;
    char filenameBuffer[256]; // Fixed-size buffer for filename

    Log_Debug("Initiating deletion of file chunk %U from disk", chunk->GetChunkID());
    timer.Reset();
    timer.Start();

    // Copy the filename to local buffer before deleting the chunk
    const char* src = chunk->GetFilename();
    int i = 0;
    while (src[i] != '\0' && i < 255) {
        filenameBuffer[i] = src[i];
        ++i;
    }
    filenameBuffer[i] = '\0';

    delete chunk;

    // Note: Actual filesystem deletion is commented out for safety
    // FS_Delete(filenameBuffer);

    timer.Stop();
    Log_Debug("Deletion completed, duration: %U ms", (uint64_t)timer.ElapsedMilliseconds());
}

void StorageDeleteFileChunkJob::OnComplete() {
    delete this;
}

