using namespace rainy;

// Test sphere instance properties and intersection behavior
TEST(SphereTest, InstanceTest) {
    // Create a sphere with radius 2.0 at origin, no emission, gray color, diffuse reflection
    Sphere sp(2.0, Vector3(0.0, 0.0, 0.0), Color(), Color(0.75, 0.75, 0.75), REFLECTION_DIFFUSE);

    // Verify center coordinates
    EXPECT_DOUBLE_EQ(0.0, sp.center().x());
    EXPECT_DOUBLE_EQ(0.0, sp.center().y());
    EXPECT_DOUBLE_EQ(0.0, sp.center().z());

    // Verify emission is zero
    EXPECT_DOUBLE_EQ(0.0, sp.emission().x());
    EXPECT_DOUBLE_EQ(0.0, sp.emission().y());
    EXPECT_DOUBLE_EQ(0.0, sp.emission().z());

    // Verify color values
    EXPECT_DOUBLE_EQ(0.75, sp.color().x());
    EXPECT_DOUBLE_EQ(0.75, sp.color().y());
    EXPECT_DOUBLE_EQ(0.75, sp.color().z());

    // Verify reflection type
    EXPECT_EQ(REFLECTION_DIFFUSE, sp.reftype());

    // Test ray intersection: ray from (10,0,0) towards (-1,0,0) should hit the sphere
    HitPoint hitpoint;
    Ray ray1(Vector3(10.0, 0.0, 0.0), Vector3(-1.0, 0.0, 0.0));
    EXPECT_TRUE(sp.intersect(ray1, hitpoint));

    // Check intersection point: should be at (2,0,0)
    EXPECT_DOUBLE_EQ(2.0, hitpoint.position().x());
    EXPECT_DOUBLE_EQ(0.0, hitpoint.position().y());
    EXPECT_DOUBLE_EQ(0.0, hitpoint.position().z());

    // Check normal vector at intersection: should be (1,0,0)
    EXPECT_DOUBLE_EQ(1.0, hitpoint.normal().x());
    EXPECT_DOUBLE_EQ(0.0, hitpoint.normal().y());
    EXPECT_DOUBLE_EQ(0.0, hitpoint.normal().z());

    // Test ray that misses the sphere: ray from (10,0,0) in direction (0,1,0)
    Ray ray2(Vector3(10.0, 0.0, 0.0), Vector3(0.0, 1.0, 0.0));
    EXPECT_FALSE(sp.intersect(ray2, hitpoint));
}

int main(int argc, char **argv) {
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}

