#include "CIndexBuffer.h"

#include <glad/glad.h>

namespace ion
{
    namespace Graphics
    {
        namespace GL
        {

            void CIndexBuffer::UploadData(void const * Data, size_t const Elements, EValueType const ValueType)
            {
                // Bind the element array buffer for uploading data
                CheckedGLCall(glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, Handle));

                // Compute total byte size based on element count and value type size
                size_t const ByteSize = Elements * GetValueTypeSize(ValueType);

                // Upload the index data to the GPU buffer
                CheckedGLCall(glBufferData(GL_ELEMENT_ARRAY_BUFFER, ByteSize, Data, GL_STATIC_DRAW));

                // Unbind the buffer to avoid unintended modifications
                CheckedGLCall(glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0));

                // Store the number of elements for later use
                Size = Elements;
            }

        }
    }
}

