};

// Server startup function with renamed variables and restructured exception handling
static void* StartDatabaseServer(void *arg) {
    try {
        // Initialization sequence
        peloton::PelotonInit::Initialize();
        LOG_INFO("Database server started successfully\n");

        // Create and start the network server
        peloton::wire::LibeventServer server_instance;
        LOG_INFO("Server shutdown initiated\n");

        // Note: Normal shutdown not yet implemented
        //peloton::PelotonInit::Shutdown();
        LOG_INFO("Peloton system termination complete\n");
    } catch (const peloton::ConnectionException& ex) {
        // Connection exceptions are expected and handled silently
        LOG_INFO("Connection exception caught and ignored\n");
    }

    return nullptr;
}

// Client-side test function with modified query execution order
static void* ExecuteSimpleClientTest(void *param) {
    try {
        // Establish connection with slightly different parameter formatting
        pqxx::connection conn("host=127.0.0.1 port=15721 user=postgres sslmode=disable");
        LOG_INFO("Connected to database: %s\n", conn.dbname());

        // Begin transaction
        pqxx::transaction<> txn(conn);

        // Execute operations in a more compact form
        txn.exec("DROP TABLE IF EXISTS employee;");
        txn.exec("CREATE TABLE employee(id INT, name VARCHAR(100));");

        // Insert records with varied formatting
        txn.exec("INSERT INTO employee VALUES (1, 'Han LI');");
        txn.exec("INSERT INTO employee VALUES (2, 'Shaokun ZOU');");
        txn.exec("INSERT INTO employee VALUES (3, 'Yilei CHU');");

        // Perform query and verify results
        pqxx::result res = txn.exec("SELECT name FROM employee WHERE id = 1;");
        EXPECT_EQ(res.size(), 1u);
        LOG_INFO("Query returned %zu record(s)\n", res.size());

        // Commit transaction
        txn.commit();
    } catch (const std::exception& error) {
        LOG_INFO("Exception occurred during client operation: %s\n", error.what());
    }

    LOG_INFO("Client session terminated\n");
    return nullptr;
}

// Main test case with reordered operations and different synchronization approach
TEST_F(PacketManagerTests, SimpleQueryTest) {
    pthread_t server_thread;
    int result_code = pthread_create(&server_thread, nullptr, StartDatabaseServer, nullptr);

    if (result_code != 0) {
        LOG_INFO("Error: unable to create server thread\n");
        exit(-1);
    }

    // Allow time for server initialization
    sleep(5);

    // Run client operations
    ExecuteSimpleClientTest(nullptr);

    // Graceful server shutdown
    pthread_kill(server_thread, SIGHUP);
    pthread_join(server_thread, nullptr);
}

