namespace browser {

BrowserNonClientFrameView* CreateBrowserNonClientFrameView(
    BrowserFrame* frame, BrowserView* browser_view) {
  // Determine browser type and select appropriate frame view
  Browser::Type browser_type = browser_view->browser()->type();

  BrowserNonClientFrameView* result = nullptr;

  if (browser_type == Browser::TYPE_PANEL) {
    const base::CommandLine& cmd_line = *base::CommandLine::ForCurrentProcess();
    if (cmd_line.HasSwitch(switches::kEnablePanels)) {
      result = new PanelBrowserFrameView(
          frame, static_cast<PanelBrowserView*>(browser_view));
    } else {
      // Fall through to popup handling
      goto handle_popup;
    }
  }

  if (browser_type == Browser::TYPE_POPUP || 
      (browser_type == Browser::TYPE_PANEL && !result)) {
handle_popup:
    // TODO(anicolao): implement popups for touch
    NOTIMPLEMENTED();
    result = new PopupNonClientFrameView(frame);
  }

  if (!result) {
    result = new TouchBrowserFrameView(frame, browser_view);
  }

  return result;
}

