#include <cassert>
#include <cmath>
#include <limits>
#include <serializer.h>

// Test serialization and deserialization of double values, including special cases
void validate_serialization(const double input_value) {
  Serializer serializer_instance;
  writer<decltype(+input_value)>::write(serializer_instance, input_value);
  const auto buffer_info = serializer_instance.data();

  Deserializer deserializer(serializer_instance.buffer, 
                            serializer_instance.buffer.size() - buffer_info.second);
  const auto restored_value = reader<decltype(+input_value)>::read(deserializer);

  // Check equality or both being NaN (since NaN != NaN by definition)
  assert(input_value == restored_value || 
         (std::isnan(input_value) && std::isnan(restored_value)));
}

int main() {
  // Test positive infinity
  validate_serialization(std::numeric_limits<double>::infinity());

  // Test negative infinity
  validate_serialization(-std::numeric_limits<double>::infinity());

  // Test quiet NaN
  validate_serialization(std::numeric_limits<double>::quiet_NaN());

  // Test regular numbers
  validate_serialization(0.0);
  validate_serialization(-0.0);
  validate_serialization(1.0);
  validate_serialization(-1.0);
  validate_serialization(2.0);
  validate_serialization(-2.0);

  // Test mathematical constants
  validate_serialization(M_PI);
  validate_serialization(-M_PI);

  // Test edge case values
  validate_serialization(std::numeric_limits<double>::epsilon());
  validate_serialization(std::numeric_limits<double>::min());
  validate_serialization(std::numeric_limits<double>::max());
  validate_serialization(std::numeric_limits<double>::denorm_min());

  return 0;
}

