#include <llvm/Support/raw_ostream.h>
#pragma warning(pop)

int delta::invokeClang(llvm::ArrayRef<const char*> commandLineArgs) {
    // Create diagnostic client with error stream and options
    std::unique_ptr<clang::DiagnosticOptions> diagOpts(new clang::DiagnosticOptions());
    auto* diagPrinter = new clang::TextDiagnosticPrinter(llvm::errs(), diagOpts.get());
    diagPrinter->setPrefix(llvm::sys::path::filename(commandLineArgs[0]));

    // Initialize diagnostics engine
    clang::DiagnosticsEngine diags(
        std::unique_ptr<clang::DiagnosticIDs>(new clang::DiagnosticIDs()), 
        nullptr, 
        diagPrinter
    );

    // Construct driver with target triple
    clang::driver::Driver driver(
        commandLineArgs[0], 
        llvm::sys::getDefaultTargetTriple(), 
        diags
    );

    // Build compilation job
    std::unique_ptr<clang::driver::Compilation> compilation(driver.BuildCompilation(commandLineArgs));

    if (compilation) {
        // Execute compilation and collect failing commands
        llvm::SmallVector<std::pair<int, const clang::driver::Command*>, 4> failedCommands;
        return driver.ExecuteCompilation(*compilation, failedCommands);
    }

    // Handle failure case: finalize diagnostics and return error code
    diags.getClient()->finish();
    return 1;
}

