#include <pthread.h>
#include <stdlib.h>

// Thread function that does nothing and returns null
void* WorkerFunction(void*) {
    return nullptr;
}

int main() {
    pthread_t thread_id;
    const size_t stack_size = 1024 * 1024;

    // Allocate memory for the thread stack
    void* stack_memory = malloc(stack_size);

    // Initialize thread attributes
    pthread_attr_t attributes;
    pthread_attr_init(&attributes);

    // Set custom stack for the thread
    pthread_attr_setstack(&attributes, stack_memory, stack_size);

    // Create thread with custom stack
    pthread_create(&thread_id, &attributes, WorkerFunction, nullptr);

    // Wait for thread to complete
    pthread_join(thread_id, nullptr);

    // Clean up allocated memory
    free(stack_memory);

    return 0;
}

