#include "TwoLevelDetection.h"
#include <opencv2/imgproc/imgproc.hpp>
#include <limits>

void TwoLevelDetection(const cv::Mat& input, cv::Mat& output, double detectionLevel, double measurementLevel, TwoLevelDetectionTemp& temp)
{
    if (measurementLevel > detectionLevel) {
        throw std::runtime_error("TwoLevelDetection: measurementLevel must not exceed detectionLevel");
    }

    // Create binary mask based on measurement threshold
    cv::threshold(input, output, measurementLevel, 1, cv::THRESH_BINARY);

    // Clear previous contour data and extract external contours
    temp.contours.clear();
    cv::findContours(output, temp.contours, cv::RETR_EXTERNAL, cv::CHAIN_APPROX_SIMPLE);

    // Prepare mask for region analysis
    temp.mask.create(input.size(), CV_8UC1);
    output = cv::Scalar::all(0);  // Reset output image

    // Analyze each detected contour
    for (size_t idx = 0; idx < temp.contours.size(); ++idx) {
        temp.mask = cv::Scalar::all(0);  // Clear mask for current contour
        cv::drawContours(temp.mask, temp.contours, static_cast<int>(idx), 255, cv::FILLED);

        double minVal, maxVal;
        cv::minMaxIdx(input, &minVal, &maxVal, nullptr, nullptr, temp.mask);

        // Include region if its maximum intensity meets detection threshold
        if (maxVal >= detectionLevel) {
            output |= temp.mask;  // Use bitwise OR to accumulate valid regions
        }
    }
}

