// Draw the sprite at position (x, y), handling rotation if needed
void ofxTPSprite::draw(int x, int y) {
    // Handle rotated texture by applying transformation matrix
    if (data->isRotated()) {
        ofPushMatrix();
        ofTranslate(x + data->getOffsetX(), y + data->getOffsetY());
        ofRotate(90);
        // Adjust drawing coordinates due to rotation
        texture->drawSubsection(0, 0, 
                                data->getW(), data->getH(), 
                                data->getX(), data->getY(), 
                                data->getW(), data->getH());
        ofPopMatrix();
    } else {
        // Normal (non-rotated) drawing
        texture->drawSubsection(x + data->getOffsetX(), 
                                y + data->getOffsetY(), 
                                data->getW(), data->getH(), 
                                data->getX(), data->getY(), 
                                data->getW(), data->getH());
    }
}

