namespace proton {

void ExecutorMetrics::update(const vespalib::ThreadStackExecutorBase::Stats &stats) {
    // Update maximum pending tasks observed
    if (stats.queueSize.max() > maxPending.get()) {
        maxPending.set(stats.queueSize.max());
    }

    // Increment counters for accepted and rejected tasks
    accepted.add(stats.acceptedTasks);
    rejected.add(stats.rejectedTasks);

    // Batch update queue size statistics
    const auto& qStats = stats.queueSize;
    queueSize.addValueBatch(qStats.average(), qStats.count(), qStats.min(), qStats.max());
}

ExecutorMetrics::ExecutorMetrics(const std::string &name, metrics::MetricSet *parent)
    : metrics::MetricSet(name, {}, "Instance specific thread executor metrics", parent),
      maxPending("maxpending", {}, "Maximum number of pending (active + queued) tasks", this),
      accepted("accepted", {}, "Total number of accepted tasks", this),
      rejected("rejected", {}, "Total number of rejected tasks", this),
      queueSize("queuesize", {}, "Distribution of task queue sizes", this)
{
