void InitXchainerDevice(pybind11::module& m) {
    // Bind the Device class to Python
    py::class_<Device>(m, "Device")
        .def(py::init(&MakeDevice))
        .def("__eq__", py::overload_cast<const Device&, const Device&>(&operator==))
