        .def("__repr__",
             [](Device device) {
                 std::ostringstream stream;
                 stream << "<Device " << device.name << ">";
                 return stream.str();
             });

    // Expose device management functions
    m.def("get_current_device", []() { return GetCurrentDevice(); });
    m.def("set_current_device", [](const Device& dev) { SetCurrentDevice(dev); });
    m.def("set_current_device", [](const std::string& dev_name) { SetCurrentDevice(dev_name); });
