// Custom memory allocation function with alignment support
void* swift::swift_slowAlloc(size_t size, size_t alignMask) {
    // Compute actual alignment value (alignMask + 1)
    size_t alignment = alignMask + 1;

    // Attempt to allocate aligned memory
    void* result = AlignedAlloc(size, alignment);

    // Handle allocation failure by triggering crash handler
    if (!result) {
        swift::crash("Memory allocation failed: insufficient memory available.");
    }

    return result;
}

// Custom memory deallocation function
void swift::swift_slowDealloc(void* ptr, size_t /*bytes*/, size_t /*alignMask*/) {
    // Free the aligned memory block
    AlignedFree(ptr);
}

