extern "C" int LLVMFuzzerTestOneInput(const uint8_t *inputData, size_t inputSize) {
  // Initialize blob with fuzzer input data
  const Magick::Blob inputBlob(inputData, inputSize);

  // Create image object and configure for encoding
  Magick::Image processedImage;
  processedImage.magick(FUZZ_ENCODER);
  processedImage.fileName(std::string(FUZZ_ENCODER) + ":");

  // Attempt to read the input blob into the image
  try {
    processedImage.read(inputBlob);
  }
  catch (const Magick::Exception&) {
    return 0;  // Gracefully handle read errors
  }

  // Prepare output blob for encoded result
  Magick::Blob outputBlob;

  // Attempt to write the processed image to the output blob
  try {
    processedImage.write(&outputBlob, FUZZ_ENCODER);
  }
  catch (const Magick::Exception&) {
    // Silently ignore write exceptions (e.g., unsupported format)
  }

  return 0;  // Always return 0 as per fuzzer convention
}

