// Convert string to integer using stringstream
int convertToInt(const string& str) {
    int value = 0;
    stringstream converter(str);
    converter >> value;
    return value;
}

// Convert double to string with fixed precision
string convertToString(double val) {
    ostringstream oss;
    oss << fixed << setprecision(10) << val;
    return oss.str();
}

// Split a string by delimiter into vector of strings
vector<string> tokenize(const string& input, char delimiter) {
    vector<string> tokens;
    stringstream stream(input);
    string token;
    while (getline(stream, token, delimiter)) {
        tokens.push_back(token);
    }
    return tokens;
}

