int main()
{
    // Create a non-deterministic random device for seeding
    std::random_device seed_source;

    // Initialize the Mersenne Twister engine with the seed
    std::mt19937 generator{seed_source()};

    // Define a uniform distribution over integers [1, 6]
    std::uniform_int_distribution<int> dice_roll_dist(1, 6);

    // Generate one random outcome simulating a die roll
    int result = dice_roll_dist(generator);
}
// This code produces a uniformly distributed random integer between 1 and 6,
// emulating the roll of a fair six-sided die.
//
// First, `std::random_device` (on [7]) is used to obtain entropy from the
// system's non-deterministic random number generator, where supported.
// This ensures that each program run can start with a different seed.
//
// Next, the Mersenne Twister pseudo-random generator (`std::mt19937`, on [8])
// is seeded with this value. It offers high-quality randomness and a very long
// period (2^19937−1), making it suitable for most applications.
//
// Then, a `std::uniform_int_distribution<int>` (on [9]) is constructed to map
// the generator’s output onto the discrete interval [1, 6] with equal probability.
//
// Finally, invoking `dice_roll_dist(generator)` yields a single random sample
// from that distribution ([11]). Repeated calls produce additional independent
// samples—each representing another independent die toss.

