#include <boost/asio/io_service.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <string>

using boost::asio::ip::tcp;

BoostTransport::BoostTransport()
    : io_service_(),
      socket_(io_service_)
{
}

BoostTransport::~BoostTransport()
{
    if (socket_.is_open()) {
        socket_.close();
    }
}

void
BoostTransport::Connect(const std::string& hostname, short port)
{
    tcp::resolver resolver(io_service_);
    auto endpoints = resolver.resolve({hostname, std::to_string(port)});

    boost::system::error_code ec;
    boost::asio::connect(socket_, endpoints, ec);

    if (ec) {
        LOG(LogLevel::Warning) << "Could not connect to " << hostname << ":" << port 
                               << " - error: " << ec.message();
    }
}

void
BoostTransport::Write(const std::string& content)
{
    if (!socket_.is_open()) {
        LOG(LogLevel::Warning) << "Cannot write: socket is not open";
        return;
    }

    boost::system::error_code ec;
    size_t bytes_written = boost::asio::write(socket_, 
                                              boost::asio::buffer(content.data(), content.size()),
                                              ec);

    if (ec || bytes_written != content.size()) {
        LOG(LogLevel::Warning) << "Could not write to transport - error: " 
                               << (ec ? ec.message() : "incomplete write");
    }
}

