// Demonstration of various GNU attributes with corrected placements and valid usage
int main() {
    // Attribute on variable declaration (valid: unused)
    int [[gnu::unused]] var_unused = 42;

    // Aligned variable (valid placement)
    [[gnu::aligned(16)]] int aligned_var = 0;

    // Function declaration with alias attribute (valid)
    void helper_func() {}
    void aliased_func [[gnu::alias("_Z12helper_funcv")]] ();

    // Aligned function (valid placement)
    void aligned_function [[gnu::aligned(32)]] () {}

    // Packed struct definition (valid placement)
    struct [[gnu::packed]] packed_struct {
        char c;
        int n;
    };

    // TLS variable with tls_model attribute (valid placement)
    __thread int tls_var [[gnu::tls_model("local-exec")]];

    // Cleanup attribute on local variable (valid placement)
    auto cleanup_fn = [](int* p) { /* dummy implementation */ };
    {
        int local_var [[gnu::cleanup(cleanup_fn)]];
    }

    // Deprecated function declarations (valid placement)
    void deprecated_func1 [[gnu::deprecated]] ();
    void deprecated_func2 [[gnu::deprecated("use new_api instead")]] ();

    // Noreturn function (valid placement)
    void noreturn_func [[gnu::noreturn]] () {}

    // Always inline function (valid placement)
    void inline_func [[gnu::always_inline]] () {}

    // malloc-like function with alloc_size (valid placement)
    [[gnu::malloc, gnu::alloc_size(1,2)]] void* custom_alloc(int size, int count);

