  argv.reserve(args->size());

  // Copy values from the input vector to local V8 handles
  for (size_t i = 0; i < args->size(); ++i) {
    argv.push_back((*args)[i]);
  }

  // Execute the emit callback on the object
  return node::MakeCallback(
      isolate, obj, "emit", static_cast<int>(argv.size()), 
      argv.data(), node::async_context{});
}

