#include <iostream>
#include <vector>
#include <cvd/connected_components.h>
#include <cvd/image.h>

using namespace std;
using namespace CVD;

int main() {
    // Iterate through all 512 possible 3x3 binary patterns (2^9)
    for (int pattern = 0; pattern < (1 << 9); ++pattern) {
        cout << "------------------------\n" << pattern << endl;

        int temp = pattern;
        vector<ImageRef> foregroundPixels;

        // Extract pixel positions from the pattern bits
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 3; ++col) {
                if (temp & 1) {
                    foregroundPixels.push_back(ImageRef(col, row));
                }
                temp >>= 1;
            }
        }

        // Find connected components in the foreground pixels
        vector<vector<ImageRef>> componentGroups;
        connected_components(foregroundPixels, componentGroups);

        // Create a 3x3 output image initialized with '.'
        Image<char> resultImage(ImageRef(3, 3), '.');

        // Label each component with uppercase letters starting from 'A'
        for (size_t groupIdx = 0; groupIdx < componentGroups.size(); ++groupIdx) {
            char labelChar = static_cast<char>('A' + groupIdx);
            for (size_t pixelIdx = 0; pixelIdx < componentGroups[groupIdx].size(); ++pixelIdx) {
                resultImage[componentGroups[groupIdx][pixelIdx]] = labelChar;
            }
        }

        // Output results
        cout << "Created " << componentGroups.size() << " groups\n";

        // Print the 3x3 grid row by row
        cout.write(resultImage.data(), 3);
        cout << '\n';
        cout.write(resultImage.data() + 3, 3);
        cout << '\n';
        cout.write(resultImage.data() + 6, 3);
        cout << "\n\n";

        // Pause for user interaction
        cin.get();
    }

    return 0;
}

#include "check_unique_char.h"

CheckUniqueChar::CheckUniqueChar() {
}

CheckUniqueChar::~CheckUniqueChar() {
}

// Determines uniqueness by checking each character against all previous ones - O(n^2) time
bool CheckUniqueChar::solver_boolean(std::string test_string) {
    for (size_t i = 0; i < test_string.length(); ++i) {
        for (size_t j = 0; j < i; ++j) {
            if (test_string[i] == test_string[j]) {
                return false;
            }
        }
    }
    return true;
}

// Determines uniqueness by sorting the string first and then checking adjacent characters - O(n log n) time
bool CheckUniqueChar::solver_sorted(std::string test_string) {
    if (test_string.empty()) return true;

    // Sort the string to bring duplicate characters together
    std::sort(test_string.begin(), test_string.end());

    // Check adjacent characters for duplicates
    for (size_t i = 1; i < test_string.length(); ++i) {
        if (test_string[i] == test_string[i-1]) {
            return false;
        }
    }
    return true;
}

// Runs test cases to verify the correctness of both methods
bool CheckUniqueChar::test_case() {
    // Test case 1: String with unique characters
    std::string unique_str = "abcdef";
    bool result1_bool = solver_boolean(unique_str);
    bool result1_sorted = solver_sorted(unique_str);

    // Test case 2: String with duplicate characters
    std::string duplicate_str = "hello";
    bool result2_bool = solver_boolean(duplicate_str);
    bool result2_sorted = solver_sorted(duplicate_str);

    // Verify results match expected behavior
    return (result1_bool && result1_sorted && 
            !result2_bool && !result2_sorted);
}

