namespace base {

void safe_strerror_r(int err, char* buf, size_t len) {
#if defined(__GLIBC__) || \
   (defined(OS_ANDROID) && defined(_GNU_SOURCE) && __ANDROID_API__ >= 23)
  // Glibc-specific version: strerror_r may return a static string
  char* result = strerror_r(err, buf, len);
  if (result != buf) {
    // The result is not the same as buf, so copy it
    snprintf(buf, len, "%s", result);
  }
#else
  // POSIX version: strerror_r returns int
  int status = strerror_r(err, buf, len);
  if (status != 0) {
    // Error occurred while retrieving error message
    int actual_err = (status > 0) ? status : errno;
    snprintf(buf, len, "Error %d while retrieving error %d", actual_err, err);
  }
#endif
}

std::string safe_strerror(int err) {
  char buffer[256];
  safe_strerror_r(err, buffer, sizeof(buffer));
  return std::string(buffer);
}

}  // namespace base

