    return 0;
}

vector<vector<string>> Database::execute(string sqlStatement) const {
    cout << "Executing SQL: " << sqlStatement << endl;
    cout << "Data: ";

    vector<vector<string>> queryResults;
    char *errorMessage = nullptr;

    int executionResult = sqlite3_exec(
        db,
        sqlStatement.c_str(),
        queryHandler,
        &queryResults,
        &errorMessage
    );

    cout << endl;
    cout << "DB status: " << executionResult;

    if (errorMessage) {
        cout << ", Error: " << errorMessage;
        sqlite3_free(errorMessage);
    }

    cout << endl;
    return queryResults;
}

