using namespace clang;

OpenMPDirectiveKind clang::getOpenMPDirectiveKind(llvm::StringRef DirectiveName) {
  // Map string representation to OpenMP directive enum using StringSwitch
  return llvm::StringSwitch<OpenMPDirectiveKind>(DirectiveName)
#define OPENMP_DIRECTIVE(Name) \
           .Case(#Name, OMPD_##Name)
#include "clang/Basic/OpenMPKinds.def"
           .Default(OMPD_unknown);
}

const char *clang::getOpenMPDirectiveName(OpenMPDirectiveKind DirectiveKind) {
  // Ensure the directive kind is within valid range
  assert(DirectiveKind < NUM_OPENMP_DIRECTIVES);

  // Convert enum value back to string representation
  switch (DirectiveKind) {
  case OMPD_unknown:
    return "unknown";
#define OPENMP_DIRECTIVE(Name) \
  case OMPD_##Name: \
    return #Name;
#include "clang/Basic/OpenMPKinds.def"
  default:
    break;
  }

  // Should never reach here if assertion holds
  llvm_unreachable("Invalid OpenMP directive kind");
}

