// Initialize translation system based on system locale
void setupLocalization() {
    QString localeIdentifier = QLocale::system().name();
    QString languageCode = localeIdentifier.left(2);
    const QString translationPrefix("sailfactor_");
    const QString resourcePath(":/lang/");
    const QString fileExtension(".qm");

    QString translationFile = resourcePath + translationPrefix + languageCode + fileExtension;
    if (QFile::exists(translationFile)) {
        QTranslator* translator = new QTranslator(QCoreApplication::instance());
        translator->load(translationPrefix + languageCode, resourcePath);
        QCoreApplication::installTranslator(translator);
    }
}

int main(int argc, char *argv[]) {
    // Create application instance using SailfishApp helper
    QScopedPointer<QGuiApplication> application(SailfishApp::application(argc, argv));

    // Create and configure QML view
    QScopedPointer<QQuickView> window(SailfishApp::createView());

