void display_usage() noexcept {
    std::cout << "usage: shinobi [options] [--] [filename]\n\n";
    std::cout << std::left << '\t' << std::setw(25) << "-h, --help"   << "display this help message and terminate" << '\n';
    std::cout << std::left << '\t' << std::setw(25) << "-d, --debug"  << "generate debug ninja file"             << '\n';
    std::cout << std::left << '\t' << std::setw(25) << "-r, --release"<< "generate release ninja file (default)" << '\n';
}

int main(int argc, char* argv[]) {
    std::string output_file("build.ninja");
    std::map<std::string, int> argument_map;

    for (int index = 0; index < argc; ++index) {
        argument_map.emplace(argv[index], index);
    }

    if (argument_map.count("-h") || argument_map.count("--help")) {
        display_usage();
        return 0;
    }

    auto separator_pos = argument_map.find("--");

    if (separator_pos != argument_map.end()) {
        int next_index = separator_pos->second + 1;
        if (next_index < argc && argv[next_index] != nullptr) {
            output_file = std::string(argv[next_index]) + ".ninja";
        }
    }

    std::ofstream out(output_file);
    util::maker creator{out};

    if (argument_map.count("-d") || argument_map.count("--debug")) {
        creator.set_debug_mode(true);
    }

    if (argument_map.count("-r") || argument_map.count("--release")) {
        creator.set_debug_mode(false);
    }

    creator.perform_regular_parsing();
}

