void lldb_private::lldb_assert(bool condition, const char *condition_text,
                               const char *function_name, const char *source_file,
                               unsigned int line_number) {
  if (LLVM_LIKELY(condition))
    return;

  raw_ostream &err_stream = errs();
  err_stream << format("Assertion failed: (%s), function %s, file %s, line %u\n",
                       condition_text, function_name, source_file, line_number);
  err_stream << "stack trace at point of failure:\n";
  llvm::sys::PrintStackTrace(err_stream);
  err_stream << " kindly submit a bug report for lldb with this error output and "
                "as much context as you can provide\n";
}

