// Global pointer to the ICS3 driver instance
ics::ICS3* ics_driver {nullptr};
ros::Publisher pose_publisher;

// Callback function to handle incoming movement commands
void handle_servo_command(const servo_msgs::IdBased::ConstPtr& command) {
  servo_msgs::IdBased response;
  response.id = command->id;

  try {
    // Execute movement and get resulting angle
    response.angle = ics_driver->move(
      command->id, 
      ics::Angle::newDegree(command->angle)
    );

    // Publish the result
    pose_publisher.publish(response);
  } catch (const std::runtime_error& error) {
    ROS_WARN("Communication failure: %s", error.what());
  }
}

int main(int argc, char** argv) {
