  // Initialize ICS3 driver with the specified serial port
  ics::ICS3 ics_instance {std::move(serial_port_path)};
  ics_driver = &ics_instance;

  // Create public node handle for topics
  ros::NodeHandle public_nh {};

  // Subscribe to command topic
  ros::Subscriber cmd_subscriber {
