// Control logic for elevator movement with limit switch protection
void ElevatorSubsystem::DriveElevator(float speed) {
    bool shouldMove = true;

    // Prevent upward motion when lower limit switch is activated
    if (underSwitch.Get() && speed > 0.0f) {
        shouldMove = false;
    }

    // Prevent downward motion when upper limit switch is activated
    if (upSwitch.Get() && speed < 0.0f) {
        shouldMove = false;
    }

    if (shouldMove) {
        pullMotorLeft.Set(speed);
        pullMotorRight.Set(speed);
    }
}

