// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

class Solution {
public:
    bool validateBST(TreeNode* node, long lowerBound, long upperBound) {
        if (node == nullptr) {
            return true;
        }

        // Check current node's value against bounds
        bool currentValid = node->val > lowerBound && node->val < upperBound;

        // Recursively validate left and right subtrees with updated bounds
        bool leftValid = validateBST(node->left, lowerBound, static_cast<long>(node->val));
        bool rightValid = validateBST(node->right, static_cast<long>(node->val), upperBound);

        return currentValid && leftValid && rightValid;
    }

    bool isValidBST(TreeNode* root) {
        // Use extended range to handle INT_MIN and INT_MAX edge cases
        return validateBST(root, static_cast<long>(INT_MIN) - 1, static_cast<long>(INT_MAX) + 1);
    }
};

