namespace CodeHero {

IndexBufferGL::IndexBufferGL() {
    // Generate one OpenGL buffer object for index data
    glGenBuffers(1, &_GetGPUObjectHandle()->intHandle);
}

IndexBufferGL::~IndexBufferGL() {
    // Clean up the OpenGL buffer when destroyed
    glDeleteBuffers(1, &_GetGPUObjectHandle()->intHandle);
}

void IndexBufferGL::Activate() {
    // Bind the buffer to the element array buffer target
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, GetGPUObject().intHandle);
}

void IndexBufferGL::Deactivate() {
    // Unbind the current element array buffer
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0);
}

void IndexBufferGL::_SetDataImpl(const void* iData) {
    // Ensure the buffer is bound before uploading data
    Activate();

    // Compute total size: number of indices times size of each index (unsigned int)
    const GLsizei bufferSize = static_cast<GLsizei>(m_IndexSize * sizeof(unsigned int));

    // Upload data to GPU with appropriate usage hint
    glBufferData(
        GL_ELEMENT_ARRAY_BUFFER,
        bufferSize,
        iData,
        m_IsDynamic ? GL_DYNAMIC_DRAW : GL_STATIC_DRAW
    );
}

