struct NixArgs : virtual MultiCommand, virtual MixCommonArgs {
    NixArgs() : MultiCommand(*RegisterCommand::commands), MixCommonArgs("nix") {
        // Handle help flag
        mkFlag('h', "help", "display this message", [this]() {
            printHelp(programName, std::cout);
            std::cout << "\nWarning: This tool is in experimental stage and may change.\n";
            throw Exit();
        });

        // Handle version flag
        mkFlag(0, "version", "print version details", 
               []() { printVersion("nix"); });
    }
};

void runNixProgram(int argc, char * * argv) {
    initializeNixSystem();
    setupGarbageCollection();

    std::string progName = extractBaseName(argv[0]);

    // Check for legacy command handlers first
    auto legacyHandler = (*RegisterLegacyCommand::commands)[progName];
    if (legacyHandler) {
        legacyHandler(argc, argv);
        return;
    }

    // Process standard command-line arguments
    NixArgs cliArgs;
    cliArgs.parseArguments(argvToStrings(argc, argv));

    if (!cliArgs.command) {
        throw UsageError("no command specified");
    }

    cliArgs.command->setup();
    cliArgs.command->execute();
}

}

int main(int argc, char * * argv) {
    return nix::catchExceptions(argv[0], [&]() {
        nix::runNixProgram(argc, argv);
    });
}

