#include "listener.h"
#include "log.h"
#include "buffers.h"

// Check if message can be enqueued; drop if insufficient space
void tryEnqueueMessage(QUEUE_TYPE(uint8_t)* queue, uint8_t* data,
        int length) {
    // Reserve 2 bytes for line ending characters
    if (queue_free_space(queue) < static_cast<int>(length + 2)) {
        debug("Dropped incoming CAN message -- send queue (at %p) full\r\n",
                queue);
        return;
    }

    // Copy each byte of the message
    for (int idx = 0; idx < length; ++idx) {
        QUEUE_PUSH(uint8_t, queue, data[idx]);
    }

    // Append line termination sequence
    QUEUE_PUSH(uint8_t, queue, '\r');
    QUEUE_PUSH(uint8_t, queue, '\n');
}

// Route message to appropriate output based on connection status
void transmitMessage(Listener* listener, uint8_t* payload, int payloadLength) {
    if (listener->usbConnection->isConfigured) {
        tryEnqueueMessage(&listener->usbConnection->outputQueue, 
                         payload, payloadLength);
    } else {
        tryEnqueueMessage(&listener->serialConnection->outputQueue, 
                         payload, payloadLength);
    }
}

// Handle input processing for active communication channels
void handleInputProcessing(Listener* listener) {
    // USB processing is mandatory to maintain enumeration and control
    processInputQueue(listener->usbConnection);

    // Only process serial input when USB is not configured
    if (!listener->usbConnection->isConfigured) {
        processInputQueue(listener->serialConnection);
    }
}

