// Avoid manual memory management by using classes that implement
// RAII (Resource Acquisition Is Initialization).
// 
// Each object declared above ([10-14]) internally manages dynamically
// allocated memory—typically allocated via `new`. However, these standard
// types automatically release their resources when they go out of scope,
// ensuring safe and exception-safe cleanup.
// 
// This pattern eliminates the need for explicit `delete` calls and helps
// prevent memory leaks, dangling pointers, and double-free errors.
// 
// Furthermore, it's recommended to design your own custom classes following
// the RAII principle—for instance, by encapsulating raw pointers within
// smart pointers or other resource-managing wrappers.

#include <thread>
#include <iostream>
#include <vector>

void printMessage() {
    std::cout << "Hello, world" << std::endl;
}

int main() {
    std::vector<std::thread> workerThreads;

    // Launch 5 threads to execute the function concurrently
    for (int index = 0; index < 5; ++index) {
        workerThreads.emplace_back(printMessage);
    }

    // Wait for all threads to complete before exiting
    for (auto& t : workerThreads) {
        t.join();
    }

    return 0;
}

