#include "buffers.h"
#include "strutil.h"
#include "log.h"

void handleIncomingData(ByteQueue* queue, bool (*processBuffer)(uint8_t*)) {
    uint8_t tempBuffer[QUEUE_MAX_LENGTH(uint8_t)];
    queue_snapshot(queue, tempBuffer);

    if(processBuffer == nullptr) {
        debug("Handler function is null (%p) -- cannot process queue at %p\r\n",
                processBuffer, queue);
        return;
    }

    if(processBuffer(tempBuffer)) {
        queue_init(queue);
    } else if(queue_full(queue)) {
        debug("Received data exceeds buffer capacity\r\n");
        queue_init(queue);
    } else if(strnchr((char*)tempBuffer, queue_length(queue), '\0') != nullptr) {
        debug("Buffered data contains unexpected null terminator -- resetting buffer\r\n");
        queue_init(queue);
    }
}

