#include <iostream>
#include <cmath>

class Point2D {
  double x;
  double y;

public:
  double getX() const {
    return x;
  }

  double getY() const {
    return y;
  }

  void setX(double newX) {
    x = newX;
  }

  void setY(double newY) {
    y = newY;
  }

  void moveBy(double deltaX, double deltaY) {
    x += deltaX;
    y += deltaY;
  }

  double getDistanceTo(const Point2D& other) const {
    double dx = x - other.x;
    double dy = y - other.y;
    return std::sqrt(dx * dx + dy * dy);
  }

  void display() const {
    std::cout << '(' << x << ", " << y << ")\n";
  }
};

void runTranslationTest() {
  Point2D p;
  p.setX(3.0);
  p.setY(5.0);
  p.moveBy(2.0, 3.0);
  p.display();
}

void runDistanceTest() {
  Point2D a;
  a.setX(3.0);
  a.setY(5.0);

  Point2D b;
  b.setX(4.0);
  b.setY(1.0);

  std::cout << a.getDistanceTo(b) << '\n';
}

int main() {
  runTranslationTest();
  runDistanceTest();
  return 0;
}

