// Function to decrypt a single character using additive cipher with given key
char decryptChar(char c, int key) {
    if (c >= 'A' && c <= 'Z') {
        return static_cast<char>('A' + (c - 'A' - key + 26) % 26);
    } else if (c >= 'a' && c <= 'z') {
        return static_cast<char>('a' + (c - 'a' - key + 26) % 26);
    }
    return c; // Non-alphabetic characters remain unchanged
}

// Generate decrypted text for a specific key
std::string generatePlaintext(const std::string& cipherText, int key) {
    std::string result = "";
    for (size_t i = 0; i < cipherText.length(); ++i) {
        result += decryptChar(cipherText[i], key);
    }
    return result;
}

void findPossiblePlainTexts(const std::string& cipherText, int num);
int main(int argc, char** argv)
{
  std::cout << "Letter Frequency attack on additive cipher\n";
  std::cout << "Enter the cipher text: ";
  std::string ciphertext;
  std::cin >> ciphertext;
  int num;
  std::cout << "Total possible plaintext sets: ";
  std::cin >> num;
  findPossiblePlainTexts(ciphertext, num);
}

void findPossiblePlainTexts(const std::string& cipherText, int num)
{
  int key = 0;
  while (key < num) {
    std::string plaintext = generatePlaintext(cipherText, key);
    std::cout << key + 1 << ": " << plaintext << "\n";
    key++;
  }
}

