#include <bits/stdc++.h>
#define MAX ...
using namespace std;

vector<int> adj[MAX];
bool seen[MAX];

void depthFirstSearch(int startNode) {
    if (seen[startNode]) 
        return;

    stack<int> dfsStack;
    dfsStack.push(startNode);
    seen[startNode] = true;

    while (!dfsStack.empty()) {
        int currentNode = dfsStack.top();
        dfsStack.pop();

        for (int j = 0; j < (int)adj[currentNode].size(); j++) {
            int neighbor = adj[currentNode][j];
            if (!seen[neighbor]) {
                seen[neighbor] = true;
                dfsStack.push(neighbor);
            }
        }
    }
}

