bool ShouldQuit(ConsCell *exp)
{
  std::ostringstream oss;
  oss << *exp;
  std::string exp_str = oss.str();
  return EQ(exp, EOF) || exp_str == "QUIT" || exp_str == "(QUIT)";
}

