#include <stan/math/matrix/mdivide_left_spd.hpp>
#include <stan/math/matrix/typedefs.hpp>
#include <gtest/gtest.h>

TEST(MathMatrix, mdivide_left_spd_identity_check) {
  using stan::math::mdivide_left_spd;

  stan::math::matrix_d A(2, 2);
  stan::math::matrix_d result;

  // Define a symmetric positive definite matrix
  A << 2.0, 3.0,
       3.0, 7.0;

  // Compute A^{-1} * A which should yield identity matrix
  result = mdivide_left_spd(A, A);

  // Verify the result is close to identity matrix
  EXPECT_NEAR(1.0, result(0, 0), 1.0E-12);
  EXPECT_NEAR(0.0, result(0, 1), 1.0E-12);
  EXPECT_NEAR(0.0, result(1, 0), 1.0E-12);
  EXPECT_NEAR(1.0, result(1, 1), 1.0E-12);
}

