#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    bool closeStrings(const std::string& str1, const std::string& str2) {
        // Frequency counters for each letter
        std::vector<int> freq1(26, 0), freq2(26, 0);

        // Track which characters appear in each string
        bool chars1[26] = {false}, chars2[26] = {false};

        // Count frequencies and mark present characters for first string
        for (char ch : str1) {
            int idx = ch - 'a';
            freq1[idx]++;
            chars1[idx] = true;
        }

        // Count frequencies and mark present characters for second string
        for (char ch : str2) {
            int idx = ch - 'a';
            freq2[idx]++;
            chars2[idx] = true;
        }

        // Verify both strings use exactly the same set of characters
        for (int i = 0; i < 26; ++i) {
            if (chars1[i] != chars2[i]) {
                return false;
            }
        }

        // Sort frequency arrays to compare if frequency patterns match
        std::sort(freq1.begin(), freq1.end());
        std::sort(freq2.begin(), freq2.end());

        return freq1 == freq2;
    }
};

