namespace jsonv_test
{
using namespace jsonv;
using string_list = std::vector<std::string>;

// Helper function to verify sorting consistency between JSON and std::vector
template <typename JsonComparator, typename StringComparator>
static void validate_sorting(const formats& fmts, string_list input_data, 
                             JsonComparator json_comp, StringComparator str_comp)
{
    // Convert input vector to JSON value
    value json_input = to_json(input_data, fmts);

    // Verify round-trip conversion works correctly
    if (input_data != extract<string_list>(json_input, fmts))
        throw std::logic_error("JSON conversion or extraction failed");

    // Sort both representations using respective comparators
    std::sort(input_data.begin(), input_data.end(), str_comp);
    std::sort(json_input.begin_array(), json_input.end_array(), json_comp);

    // Ensure sorted results match after conversion
    if (input_data != extract<string_list>(json_input, fmts))
        throw std::logic_error("Sorted results do not match between JSON and vector");
}

TEST(functional_sort_strings)
{
    // Configure custom formats with vector<string> support
    formats fmts = formats::compose({
        formats_builder()
            .register_container<std::vector<std::string>>(),
        formats::defaults()
    });

    // Test data: unsorted list of strings
    std::vector<std::string> test_strings = { "fire", "wind", "water", "earth", "heart" };

    // Test all four comparison types
    validate_sorting(fmts, test_strings, value_less(),          std::less<std::string>());
    validate_sorting(fmts, test_strings, value_less_equal(),    std::less_equal<std::string>());
    validate_sorting(fmts, test_strings, value_greater(),       std::greater<std::string>());
    validate_sorting(fmts, test_strings, value_greater_equal(), std::greater_equal<std::string>());
}
}

