// Convert cycle count between different clock frequencies using ceiling division
UInt64 convertCycleCount(UInt64 cycle_count, volatile float from_frequency, volatile float to_frequency)
{
   // Compute the ratio and apply ceiling to ensure sufficient cycles are counted
   double ratio = static_cast<double>(to_frequency) / static_cast<double>(from_frequency);
   UInt64 converted_cycle_count = static_cast<UInt64>(std::ceil(ratio * static_cast<double>(cycle_count)));

   LOG_PRINT("convertCycleCount(%llu): from_frequency(%f), to_frequency(%f) -> (%llu)",
             cycle_count, from_frequency, to_frequency, converted_cycle_count);
   return converted_cycle_count;
}

