// Writes data to file using const reference span
template <typename T>
void output_to_file_by_const_ref(gsl::span<T const> const& view, std::string const& path)
{
    std::ofstream out_stream(path);
    for (auto const& element : view) {
        out_stream << element << '\n';
    }
}

// Writes data to file by value span (copying the span object)
template <typename T>
void output_to_file_by_value(gsl::span<T> view, std::string const& path)
{
    std::ofstream out_stream(path);
    auto iter = view.begin();
    while (iter != view.end()) {
        out_stream << *iter << '\n';
        ++iter;
    }
}

int main()
{
    std::vector<int> data {1, 2, 3, 4, 5};
    output_to_file_by_const_ref(gsl::make_span(data), "output_const_ref.txt");
    output_to_file_by_value(gsl::make_span(data), "output_by_value.txt");
}

