// Check if any element in the container satisfies the given predicate
template <typename T>
bool contains_matching(const std::vector<T>& container,
                       boost::function<bool(const T&)> predicate)
{
    return std::find_if(container.begin(), container.end(),
                        boost::bind(predicate, _1)) != container.end();
}

// Determine whether an integer is odd
bool is_odd(const int& value)
{
    return value % 2 != 0;
}

void verify_contains_matching()
{
    std::vector<int> values;
    values.push_back(3); // first element is odd
    assert(contains_matching<int>(values, is_odd));
    values.push_back(4);
    assert(contains_matching<int>(values, is_odd));
    values.clear();
    values.push_back(2);
    values.push_back(4);
    assert(!contains_matching<int>(values, is_odd));
    std::cout << "verify_contains_matching: OK" << std::endl;
}

