// Function to compute the greatest common divisor using Euclidean algorithm
int compute_gcd(int a, int b) {
    // Ensure a >= b by swapping if necessary
    if (a < b) {
        int temp = a;
        a = b;
        b = temp;
    }

    // Iteratively apply Euclidean algorithm
    while (b != 0) {
        int remainder = a % b;
        a = b;
        b = remainder;
    }

    return a;
}

int main() {
