namespace {
class AndroidFileReader
{
public:
    explicit AndroidFileReader(const std::string& filePath):
        m_filePath(filePath),
        m_asset(nullptr)
    {
        m_asset = AAssetManager_open(yarrar::android::getAssetManager(), m_filePath.c_str(), AASSET_MODE_BUFFER);
        if (!m_asset)
        {            
            throw std::runtime_error("Unable to open asset: " + m_filePath);
        }
    }

    ~AndroidFileReader()
    {
        if (m_asset)
        {
            AAsset_close(m_asset);
        }
    }

    void loadInto(std::string& outputBuffer)
    {
        if (!m_asset)
        {
            throw std::runtime_error("Asset is not available for reading: " + m_filePath);
        }

        size_t totalSize = static_cast<size_t>(AAsset_getLength64(m_asset));
        outputBuffer.clear();
        outputBuffer.reserve(totalSize);

        // Read the entire content into the buffer
        ssize_t bytesRead = AAsset_read(m_asset, &outputBuffer[0], totalSize);
        if (bytesRead < 0 || static_cast<size_t>(bytesRead) != totalSize)
        {
            throw std::runtime_error("Failed to fully read file: " + m_filePath);
        }
    }

private:
    std::string m_filePath;
    AAsset* m_asset;
};
}

namespace yarrar {
namespace filesystem {

void readFile(const std::string& relativePath, std::string& destinationBuffer)
{
    yarrar::android::log("Attempting to load asset: " + relativePath);

    AndroidFileReader reader(relativePath);
    reader.loadInto(destinationBuffer);
}

}
