void SimpleGameWorld::addEntity(shared_ptr<gamefw::Entity> entity)
{
    m_entity_list.emplace_back(entity);
}

void SimpleGameWorld::update()
{
    for (size_t i = 0; i < m_entity_list.size(); ++i) {
        auto& entity = m_entity_list[i];

        // Compute trigonometric values once for efficiency
        float angle_rad = glm::radians(entity->m_orientation.x);
        float cos_theta = glm::cos(angle_rad);
        float sin_theta = glm::sin(angle_rad);

        // Update position using rotated velocity components
        entity->m_position.x += entity->m_velocity_local.x * cos_theta -
                                entity->m_velocity_local.z * sin_theta;
        entity->m_position.z += entity->m_velocity_local.x * sin_theta +
                                entity->m_velocity_local.z * cos_theta;
        entity->m_position.y += entity->m_velocity_local.y;

        // Update orientation with angular velocity
        entity->m_orientation += entity->m_angular_velocity;
    }
}

