// Queue data structure test suite
// Public methods under test:
// - enqueue: adds element to the back
// - dequeue: removes and returns pointer to front element (nullptr if empty)
// - size: returns number of elements
// - clear: removes all elements
// - empty: checks if queue is empty

class QueueTest : public testing::Test {
 protected:
  // Override virtual functions from testing::Test
  virtual void SetUp() override {
    q1_.enqueue(1);
    q1_.enqueue(2);
    q2_.enqueue(1);
    q2_.enqueue(3);
  }

  virtual void TearDown() override {
    // No cleanup needed - destructors handle it
  }

  // Test fixtures
  Queue<int> emptyQueue_;
  Queue<int> queueOne_;
  Queue<int> queueTwo_;
};

// Test default constructor creates empty queue
TEST_F(QueueTest, DefaultConstructor) {
  EXPECT_EQ(0u, emptyQueue_.size());
  EXPECT_TRUE(emptyQueue_.empty());
}

// Test enqueue operation increases size correctly
TEST_F(QueueTest, EnqueueElements) {
  EXPECT_EQ(2u, queueOne_.size());
  EXPECT_EQ(2u, queueTwo_.size());

  queueTwo_.enqueue(100);
  EXPECT_EQ(3u, queueTwo_.size());
}

// Test clear removes all elements
TEST_F(QueueTest, ClearQueue) {
  queueTwo_.clear();
  EXPECT_TRUE(queueTwo_.empty());
  EXPECT_EQ(0u, queueTwo_.size());
}

// Test dequeue returns correct elements in FIFO order
TEST_F(QueueTest, DequeueElements) {
  int* firstItem = queueOne_.dequeue();
  EXPECT_EQ(1, *firstItem);
  EXPECT_EQ(1u, queueOne_.size());
  delete firstItem;

  int* secondItem = queueOne_.dequeue();
  EXPECT_EQ(2, *secondItem);
  EXPECT_TRUE(queueOne_.empty());
  delete secondItem;

  // Attempt to dequeue from empty queue
  int* nullItem = queueOne_.dequeue();
  EXPECT_EQ(nullptr, nullItem);
}

