// Custom exception base class mimicking std::exception
class custom_exception {
public:
    virtual const char* what() const noexcept { return "custom exception"; }
};

// Derived from custom_exception (analogous to derived_exception)
class my_derived_exception : public custom_exception {};

// Non-derived custom exception (analogous to non_derived_exception)
class standalone_exception {};

void test_function() {
  try {
    throw 100; // Built-in type not allowed
// CHECK-MESSAGES: [[@LINE-1]]:5: warning: throwing an exception whose type is not derived from 'custom_exception'
  } catch (int e) {
  }
  throw 200; // Also bad
// CHECK-MESSAGES: [[@LINE-1]]:3: warning: throwing an exception whose type is not derived from 'custom_exception'

  try {
    throw standalone_exception(); // User-defined but not derived
// CHECK-MESSAGES: [[@LINE-1]]:5: warning: throwing an exception whose type is not derived from 'custom_exception'
// CHECK-MESSAGES: 14:1: note: type defined here
  } catch (standalone_exception &e) {
  }
  throw standalone_exception(); // Still bad
// CHECK-MESSAGES: [[@LINE-1]]:3: warning: throwing an exception whose type is not derived from 'custom_exception'
// CHECK-MESSAGES: 14:1: note: type defined here
}

void safe_exceptions() {
  try {
    throw custom_exception(); // Allowed
  } catch (custom_exception &e) { // Allowed
  }
  throw custom_exception();

  try {
    throw my_derived_exception(); // Allowed
  } catch (my_derived_exception &e) { // Allowed
  }
  throw my_derived_exception(); // Allowed
}

