#include "math_container.h"
using std::complex;

/******************************************************/
/*solve the equation cosh(x)=exp(y), input y, return x*/
/******************************************************/
complex<double> coshx_eq_expy(double y) {
    // Compute e^y as a complex number with zero imaginary part
    complex<double> exp_y(exp(y), 0.0);

    // Compute sqrt(e^(2y) - 1)
    complex<double> discriminant = sqrt(exp_y * exp_y - 1.0);

    // Compute log(e^y - sqrt(e^(2y) - 1))
    complex<double> result = log(exp_y - discriminant);

    // Normalize result to be purely real or purely imaginary based on magnitude of parts
    if (std::abs(result.real()) < std::abs(result.imag())) {
        result = complex<double>(0.0, result.imag());
    } else {
        result = complex<double>(result.real(), 0.0);
    }

    return result;
}

