// (plesslie)
// posix_time_zone only parses the "-XX" part and subtracts it from UTC,
// so daylight saving time adjustments are not applied.
// A proper fix isn't implemented here, and currently this isn't a priority.
//
Logger::Logger() 
    : ss_(),
      tz_(new boost::local_time::posix_time_zone("CST-06")),  // Changed offset from -05 to -06
      output_facet_(new boost::local_time::local_time_facet()),
      input_facet_(new boost::local_time::local_time_input_facet()) {

    // Set up output locale with ISO extended time format
    std::locale classic_locale = std::locale::classic();
    ss_.imbue(std::locale(classic_locale, output_facet_));

    // Set up input locale for parsing
    ss_.imbue(std::locale(ss_.getloc(), input_facet_));

    // Configure time formatting
    output_facet_->format(boost::local_time::local_time_facet::iso_time_format_specifier);  // Changed to non-extended variant
}

Logger::~Logger() {
    delete input_facet_;
    delete output_facet_;
}

Logger& Logger::instance() {
    static Logger instance_;
    return instance_;
}

