#include <iostream>
using namespace std;

// Binary Search Tree node structure
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;

    TreeNode() : value(0), leftChild(nullptr), rightChild(nullptr) {}

    TreeNode(int val) : value(val), leftChild(nullptr), rightChild(nullptr) {}

    // Insert a new value into the BST
    TreeNode* addValue(TreeNode* current, int val) {
        if (current == nullptr) {
            return new TreeNode(val);
        }

        if (val <= current->value) {
            current->leftChild = addValue(current->leftChild, val);
        } else {
            current->rightChild = addValue(current->rightChild, val);
        }

        return current;
    }

    // Perform inorder traversal and print values
    void displayInorder(TreeNode* current) {
        if (current != nullptr) {
            if (current->leftChild != nullptr) {
                displayInorder(current->leftChild);
            }

            cout << current->value << "\n";

            if (current->rightChild != nullptr) {
                displayInorder(current->rightChild);
            }
        }
    }
};

int main() {
    int count, inputValue;
    TreeNode treeHelper;
    TreeNode* rootPointer = nullptr;

    cout << "Enter the number of elements in the tree: ";
    cin >> count;

    for (int index = 0; index < count; ++index) {
        cout << "\nEnter element " << (index + 1) << " of the tree: ";
        cin >> inputValue;
        rootPointer = treeHelper.addValue(rootPointer, inputValue);
    }

    cout << "\nInorder traversal of the tree yields:\n";
    treeHelper.displayInorder(rootPointer);

    return 0;
}

