#include <iostream>
using namespace std;

// Shell sort implementation using gap sequence halving
int shellSort(int arr[], int size) {
    // Start with a large gap, then reduce it
    for (int gap = size / 2; gap > 0; gap /= 2) {
        // Perform gapped insertion sort for this gap size
        for (int i = gap; i < size; ++i) {
            int temp = arr[i];
            int j = i;

            // Shift earlier gap-sorted elements until correct location is found
            while (j >= gap && arr[j - gap] > temp) {
                arr[j] = arr[j - gap];
                j -= gap;
            }

            arr[j] = temp;
        }
    }
    return 0;
}

int main() {
    int n;
    int data[10000];

    cin >> n;
    for (int index = 0; index < n; ++index) {
        cin >> data[index];
    }

    shellSort(data, n);

    cout << "Array after sorting: \n";
    for (int index = 0; index < n; ++index) {
        cout << data[index] << " ";
    }
    cout << endl;

    return 0;
}

