// Test to verify WebKitThread behavior with ChromeThread::DeleteSoon
TEST(WebKitThreadTest, DISABLED_ExposedInChromeThread) {
  int* dummy_ptr = nullptr;  // Provide a null pointer for the template deduction

  // Before creating WebKitThread, DeleteSoon should return false
  EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_ptr));

  {
    WebKitThread webkit_thread;

    // Still no WebKitThread initialized, so DeleteSoon should be false
    EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_ptr));

    // Initialize the thread
    webkit_thread.Initialize();

    // After initialization, DeleteSoon should succeed (return true)
    EXPECT_TRUE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_ptr));
  }

  // After the WebKitThread object is destroyed, DeleteSoon should again return false
  EXPECT_FALSE(ChromeThread::DeleteSoon(ChromeThread::WEBKIT, FROM_HERE, dummy_ptr));
}

