// Delay execution for specified number of milliseconds
void SleepMiliseconds(ulong i_miliseconds) {
#ifdef _WIN32
    // Windows: use Sleep function (parameter in milliseconds)
    Sleep(static_cast<DWORD>(i_miliseconds));
#else
    // Unix-like systems: usleep expects microseconds
    usleep(static_cast<useconds_t>(i_miliseconds * 1000));
#endif
}

