using namespace eddic;
using std::endl;

// Overridden method to write the main function declaration in assembly
void MainDeclaration::write(AssemblyFileWriter& writer) {
    writer.stream() << ".text" << endl
                    << ".globl main" << endl
                    << "\t.type main, @function" << endl;
}

// Enhanced function existence check with improved error message formatting
void FunctionCall::checkFunctions(Program& program) {
    if (!program.exists(m_function)) {
        throw CompilerException("Error: Function \"" + m_function + "\" does not exist");
    }
}

// Method to emit function prologue, body, and epilogue in x86 assembly
void Function::write(AssemblyFileWriter& writer) {
    writer.stream() << endl << m_name << ":" << endl;

    // Function prologue
    writer.stream() << "pushl %ebp" << std::endl;
    writer.stream() << "movl %esp, %ebp" << std::endl;

    // Generate code for the function body
    ParseNode::write(writer);

    // Function epilogue
    writer.stream() << "leave" << std::endl;
    writer.stream() << "ret" << std::endl;
}

// Emit a function call instruction in assembly
void FunctionCall::write(AssemblyFileWriter& writer) {
    writer.stream() << "call " << m_function << std::endl;
}

