extern "C"
void botan_sha160_ia32_compress(u32bit[5], const byte[64], u32bit[81]);

}

// Perform multiple SHA-1 compression operations
void SHA_160_IA32::compress_n(const byte input[], u32bit blocks)
   {
   // Process each block sequentially
   for(u32bit idx = 0; idx != blocks; ++idx)
      {
      // Apply the optimized IA-32 SHA-1 compression to current block
      botan_sha160_ia32_compress(digest, input, W);

      // Advance pointer to next block
      input += HASH_BLOCK_SIZE;
      }
   }
}

