typedef __char32_t char32_t;
typedef long unsigned int size_t;

template <class _CharT>
struct __attribute__((__type_visibility__("default"))) char_traits;

template <>
struct __attribute__((__type_visibility__("default"))) char_traits<char32_t> {
  typedef char32_t char_type;

  static void assign(char_type& __dest, const char_type& __source) throw() {
    __dest = __source;
  }

  static char_type* move(char_type* __destination, const char_type* __source, size_t __count);
};

char32_t* char_traits<char32_t>::move(char_type* __destination, 
                                      const char_type* __source,
                                      size_t __count) {
  if (__count > 0) {
    size_t __index = 0;
    do {
      assign(__destination[__index], __source[__index]);
      __index++;
    } while (__index < __count);
  }
  return __destination;
}
