TEST(photoeffects, SepiaFakeTest) {
    Mat original(10, 10, CV_8UC1), result;
    EXPECT_EQ(0, sepia(original, result));
}

TEST(photoeffects, SepiaFailTest) {
    Mat input(10, 10, CV_8UC3), output;
    EXPECT_EQ(1, sepia(input, output));
}

TEST(photoeffects, SepiaTest) {
    Mat input(10, 10, CV_8UC1), processed, hsvConverted;
    std::vector<Mat> splitChannels(3);

    EXPECT_EQ(0, sepia(input, processed));
    cvtColor(processed, hsvConverted, COLOR_BGR2HSV);
    split(hsvConverted, splitChannels);

    // Verify hue value around 19 degrees
    EXPECT_LE(18, splitChannels[0].at<uchar>(0, 0));
    EXPECT_GE(20, splitChannels[0].at<uchar>(0, 0));

    // Verify saturation value around 78
    EXPECT_LE(77, splitChannels[1].at<uchar>(0, 0));
    EXPECT_GE(79, splitChannels[1].at<uchar>(0, 0));

    // Verify brightness/value offset by 20 from source
    int sourceValue = static_cast<int>(input.at<uchar>(0, 0));
    EXPECT_LE(sourceValue + 19, splitChannels[2].at<uchar>(0, 0));
    EXPECT_GE(sourceValue + 21, splitChannels[2].at<uchar>(0, 0));
}

