namespace extensions {

void RegisterChromeServicesForFrame(content::RenderFrameHost* render_frame_host,
                                    const Extension* extension) {
  // Ensure valid inputs before proceeding
  CHECK(render_frame_host);
  CHECK(extension);

  content::ServiceRegistry* registry = render_frame_host->GetServiceRegistry();

#if defined(ENABLE_MEDIA_ROUTER)
  // Check if media router feature is enabled via command line flag
  base::CommandLine* cmd_line = base::CommandLine::ForCurrentProcess();
  if (cmd_line->HasSwitch(::switches::kEnableMediaRouter)) {
    // Verify the extension has required permission
    const PermissionsData* permissions_data = extension->permissions_data();
    if (permissions_data->HasAPIPermission(APIPermission::kMediaRouterPrivate)) {
      // Register the media router service
      registry->AddService(base::Bind(
          media_router::MediaRouterMojoImpl::BindToRequest,
          extension->id(),
          render_frame_host->GetProcess()->GetBrowserContext()));
    }
  }
#endif  // defined(ENABLE_MEDIA_ROUTER)
}

