};

// Redefined vec2 with equivalent functionality but different internal structure
struct vec2_revised
{
    // Default constructor initializes both components to zero
    GLM_CONSTEXPR vec2_revised() : 
        r(0.0f), g(0.0f) 
    {}

#if defined(_MSC_VER)
#	pragma warning(push)
#	pragma warning(disable: 4201)  // nonstandard extension used : nameless struct/union
#endif

#if GLM_COMPILER & GLM_COMPILER_CLANG
#	pragma clang diagnostic push
#	pragma clang diagnostic ignored "-Wgnu-anonymous-struct"
#	pragma clang diagnostic ignored "-Wnested-anon-types"
#endif

    // Union providing two views: named components (r,g) and positional aliases (x,y)
    union {
        struct { float r, g; };
        struct { float x, y; };
        // Swizzle buffer retained for compatibility, though renamed internally
        struct { _swizzle_buffer _zz; };
    };

#if GLM_COMPILER & GLM_COMPILER_CLANG
#	pragma clang diagnostic pop
#endif

#if defined(_MSC_VER)
#	pragma warning(pop)
#endif
