// Custom panic handler implementation
void __panicHandler(int kind, const char* msg, unsigned long len) {
    // Determine if it's a panic or debug message
    const char* prefix = (kind == 0) ? "panic" : "debug";
    fprintf(stderr, "%s: %.*s\n", prefix, static_cast<int>(len), msg);

    // If it's a panic, terminate the program
    if (kind == 0) {
        std::abort();
        __builtin_unreachable();
    }
}

