int main() {
    int choice;
    int num1, num2, result;
    char continueChoice;

    do {
        cout << "Choose any option:\n";
        cout << "1. Addition of two numbers\n";
        cout << "2. Difference between two numbers\n";
        cout << "3. Multiplication of two numbers\n";
        cout << "4. Square of a number\n";
        cout << "5. Cube of a number\n";
        cout << "Enter your choice: ";
        cin >> choice;

        switch (choice) {
            case 1:
                cout << "Enter two numbers: ";
                cin >> num1 >> num2;
                result = num1 + num2;
                cout << "Sum of two numbers = " << result << endl;
                break;

            case 2:
                cout << "Enter two numbers: ";
                cin >> num1 >> num2;
                result = num1 - num2;
                cout << "Difference of two numbers = " << result << endl;
                break;

            case 3:
                cout << "Enter two numbers: ";
                cin >> num1 >> num2;
                result = num1 * num2;
                cout << "Product of two numbers = " << result << endl;
                break;

            case 4:
                cout << "Enter a number: ";
                cin >> num1;
                result = num1 * num1;
                cout << "Square of the number = " << result << endl;
                break;

            case 5:
                cout << "Enter a number: ";
                cin >> num1;
                result = num1 * num1 * num1;
                cout << "Cube of the number = " << result << endl;
                break;

            default:
                cout << "Invalid choice! Please try again.\n";
                continue; // Skip rest and prompt again
