// Alias for the sparse block matrix type
using SparseBlockMatrixX = SparseBlockMatrix<MatrixXd>;

// Overload stream output operator — prints each block element-wise to cerr
ostream& operator<<(ostream& os, const SparseBlockMatrixX::SparseMatrixBlock& blk) {
    for (int row = 0; row < blk.rows(); ++row) {
        for (int col = 0; col < blk.cols(); ++col) {
            cerr << blk(row, col) << ' ';
        }
        cerr << '\n';
    }
    return os;
}

int main(int argc, char** argv) {
    // Define row/column partitioning arrays
    int rowPart[] = {3, 6, 8, 12};
    int colPart[] = {2, 4, 13};

    cerr << "initialization\n";
    SparseBlockMatrixX* matrixA = new SparseBlockMatrixX(rowPart, colPart, 4, 3);

    // Fill first block (0,0)
    cerr << "populating block (0,0)\n";
    auto* block00 = matrixA->block(0, 0, true);
    for (int r = 0; r < block00->rows(); ++r) {
        for (int c = 0; c < block00->cols(); ++c) {
            (*block00)(r, c) = r * block00->cols() + c;
        }
    }

    // Fill block (0,2)
    cerr << "populating block (0,2)\n";
    auto* block02 = matrixA->block(0, 2, true);
    for (int r = 0; r < block02->rows(); ++r) {
        for (int c = 0; c < block02->cols(); ++c) {
            (*block02)(r, c) = r * block02->cols() + c;
        }
    }

    // Fill block (3,2)
    cerr << "populating block (3,2)\n";
    auto* block32 = matrixA->block(3, 2, true);
    for (int r = 0; r < block32->rows(); ++r) {
        for (int c = 0; c < block32->cols(); ++c) {
            (*block32)(r, c) = r * block32->cols() + c;
        }
    }

    // Print full matrix
    cerr << *matrixA << endl;

    // Perform addition operations (with null pointer — will allocate Ms internally)
    cerr << "SUM\n";
    SparseBlockMatrixX* sumMatrix = nullptr;
    matrixA->add(sumMatrix);
    matrixA->add(sumMatrix); // now sumMatrix = 2 * matrixA

    // Transpose operation
    SparseBlockMatrixX* transposed = nullptr;
    matrixA->transpose(transposed);
    cerr << *transposed << endl;

    // Matrix multiplication: M * M^T
    SparseBlockMatrixX* product = nullptr;
    matrixA->multiply(product, transposed);
    cerr << *product << endl;

    // Symmetric permutation with index mapping
    int permIndex[] = {3, 2, 1, 0};

    SparseBlockMatrixX* permuted = nullptr;
    product->symmPermutation(permuted, permIndex, false);
    cerr << *permuted << endl;

    // Clear and modify before second permutation
    permuted->clear(true);
    product->block(3, 0)->fill(0.0);
    product->symmPermutation(permuted, permIndex, true);
    cerr << *permuted << endl;

    // Cleanup dynamically allocated memory (optional in simple test programs)
    delete matrixA;
    delete sumMatrix;
    delete transposed;
    delete product;
    delete permuted;

    return 0;
}

