// A pollable that always throws when polled
struct ExceptionThrowingTask : arc::Pollable<ExceptionThrowingTask> {
    bool poll(arc::Context& cx) {
        throw std::runtime_error("Intentional failure in task");
        return false;
    }
};

// A pollable that completes successfully without throwing
struct SuccessfulTask : arc::NoexceptPollable<SuccessfulTask, void> {
    bool poll(arc::Context& cx) noexcept {
        return true;
    }
};

Future<> mainCoroutine() {
    // First await the successful task
    co_await SuccessfulTask{};

    // Then attempt to await the exception-throwing task
    try {
        co_await ExceptionThrowingTask{};
        fmt::println("No exception was thrown (unexpected)");
    } catch (const std::exception& ex) {
        fmt::println("Caught standard exception: {}", ex.what());
    } catch (...) {
        fmt::println("Caught non-standard exception");
    }
}

ARC_DEFINE_MAIN_NT(mainCoroutine, 1);

