// Swap bytes in a 32-bit unsigned integer
COMPILER_RT_ABI uint32_t __bswapsi2(uint32_t value) {
    uint32_t result = 0;

    // Extract each byte and place it in the swapped position
    result |= (value & 0x000000FF) << 24;  // Move byte 0 to position 3
    result |= (value & 0x0000FF00) << 8;   // Move byte 1 to position 2
    result |= (value & 0x00FF0000) >> 8;   // Move byte 2 to position 1
    result |= (value & 0xFF000000) >> 24;  // Move byte 3 to position 0

    return result;
}

