namespace sdb {

// Create a timestamp string in the provided buffer using current time
void GetTimeStampReplication(char* dst, size_t max_length) {
  struct tm time_info;
  time_t current_time = time(nullptr);
  utilities::GetGmtime(current_time, &time_info);
  strftime(dst, max_length, "%Y-%m-%dT%H:%M:%SZ", &time_info);
}

// Create a timestamp string from a given Unix timestamp (as double)
void GetTimeStampReplication(double unix_timestamp, char* dst, size_t max_length) {
  struct tm time_info;
  time_t converted_time = static_cast<time_t>(unix_timestamp);
  utilities::GetGmtime(converted_time, &time_info);
  strftime(dst, max_length, "%Y-%m-%dT%H:%M:%SZ", &time_info);
}

}  // namespace sdb

