// Dummy global variable for benchmarking purposes
static int dummyValue = 0;

// Helper function to prevent optimization
inline void preventOptimization(int& val) {
    benchmark::DoNotOptimize(val);
}

// Helper struct to simulate trivial callable
struct SimpleCallable {
    void operator()() const {
        preventOptimization(dummyValue);
    }
};

// Helper struct to simulate large callable (contains strings)
struct HeavyCallable {
    void operator()() const {
        preventOptimization(this);
    }
    std::string data1, data2, data3;
};

// Callable with trivial arguments
struct TrivialArgCallable {
    void operator()(int x, int y, int z) const {
        preventOptimization(x);
        preventOptimization(y);
        preventOptimization(z);
    }
};

// Callable with non-trivial arguments
struct NonTrivialArgCallable {
    void operator()(std::string s1, std::string s2, std::string s3) const {
        preventOptimization(&s1);
        preventOptimization(&s2);
        preventOptimization(&s3);
    }
};

// Free function for function pointer tests
void freeFunction() {
    preventOptimization(dummyValue);
}

// Template to invoke any callable — uses std::invoke for flexibility
template<typename F, typename... Args>
auto invokeCallable(F&& f, Args&&... args)
    -> decltype(std::forward<F>(f)(std::forward<Args>(args)...)) {
    return std::forward<F>(f)(std::forward<Args>(args)...);
}

// Generic benchmark runner: constructs or assigns once, then runs loop
template<typename FuncType, typename Callable, typename... Args>
void runBenchmarkWithPreConstruction(benchmark::State& state,
                                     const Callable& callable,
                                     Args... arguments) {
    FuncType funcObj = callable;
    for (auto _ : state) {
        benchmark::DoNotOptimize(&funcObj);
        invokeCallable(funcObj, arguments...);
    }
}

// Alternative benchmark runner: constructs inside loop (measures construction + call)
template<typename FuncType, typename Callable, typename... Args>
void runBenchmarkWithConstructionInLoop(benchmark::State& state,
                                        const Callable& callable,
                                        Args... arguments) {
    for (auto _ : state) {
        FuncType tempFunc = callable;
        invokeCallable(tempFunc, arguments...);
    }
}

