using json = nlohmann::json;

int main() {
    // Initialize JSON pointers with various paths
    json::json_pointer p0;
    json::json_pointer p1("");
    json::json_pointer p2("/foo");

    // Define string representations for comparison
    std::string s0("");
    std::string s1("/foo");
    std::string s2("bar");

    // Output comparisons between pointers and strings
    std::cout << std::boolalpha
              << "\"" << p0 << "\" != \"" << s0 << "\": " << (p0 != s0) << '\n'
              << "\"" << s0 << "\" != \"" << p1 << "\": " << (s0 != p1) << '\n'
              << "\"" << p2 << "\" != \"" << s1 << "\": " << (p2 != s1) << '\n';

    // Attempt comparison that may trigger exception
    try {
        std::cout << "\"" << s2 << "\" != \"" << p2 << "\": " << (s2 != p2) << std::endl;
    }
    catch (const json::parse_error& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    return 0;
}

