        std::cerr << "  solverName: Name of the participant as defined in the preCICE config\n";
        return EXIT_FAILURE;
    }

    // Extract parameters from command line
    std::string configPath = argv[1];
    std::string participantName = argv[2];

    // Delegate to the library function
    return csumo_precice::csumo_precice(configPath, participantName);
}

