// Helper to print register context in case of exception
void dump_registers(aarch64::el::int_frame* frame_ptr) {
    klibc::printf("Kernel panic\n\nReason: %s\n\r", "cpu exception");
    klibc::printf(
        "x0:  0x%p x1:  0x%p x2:  0x%p x3:  0x%p\n"
        "x4:  0x%p x5:  0x%p x6:  0x%p x7:  0x%p\n"
        "x8:  0x%p x9:  0x%p x10: 0x%p x11: 0x%p\n"
        "x12: 0x%p x13: 0x%p x14: 0x%p x15: 0x%p\n"
        "x16: 0x%p x17: 0x%p x18: 0x%p x19: 0x%p\n"
        "x20: 0x%p x21: 0x%p x22: 0x%p x23: 0x%p\n"
        "x24: 0x%p x25: 0x%p x26: 0x%p x27: 0x%p\n"
        "x28: 0x%p x29: 0x%p x30: 0x%p\r\n"
        "sp: 0x%p pc: 0x%p flags: 0x%p, 1 %d",
        frame_ptr->x[0],  frame_ptr->x[1],  frame_ptr->x[2],  frame_ptr->x[3],
        frame_ptr->x[4],  frame_ptr->x[5],  frame_ptr->x[6],  frame_ptr->x[7],
        frame_ptr->x[8],  frame_ptr->x[9],  frame_ptr->x[10], frame_ptr->x[11],
        frame_ptr->x[12], frame_ptr->x[13], frame_ptr->x[14], frame_ptr->x[15],
        frame_ptr->x[16], frame_ptr->x[17], frame_ptr->x[18], frame_ptr->x[19],
        frame_ptr->x[20], frame_ptr->x[21], frame_ptr->x[22], frame_ptr->x[23],
        frame_ptr->x[24], frame_ptr->x[25], frame_ptr->x[26], frame_ptr->x[27],
        frame_ptr->x[28], frame_ptr->x[29], frame_ptr->x[30],
        frame_ptr->sp, frame_ptr->ip, frame_ptr->flags, 1);
}

