// External symbol for interrupt vector table
extern "C" char int_table[];

// Stack pointer for EL1 kernel mode
std::uint64_t el1_kernel_sp = 0;

// Initialize exception level settings
void aarch64::el::init() {
    // Allocate stack memory and compute virtual address
    auto stack_mem = pmm::buddy::alloc(KERNEL_STACK_SIZE);
    el1_kernel_sp = reinterpret_cast<std::uint64_t>(stack_mem.phys + etc::hhdm());

    // Set up vector base address register
    asm volatile("msr VBAR_EL1, %0" :: "r"(int_table));

    klibc::printf("EL: aarch64 int_table is 0x%p sp_el1 is 0x%p\r\n", int_table, el1_kernel_sp);
}

