using proto::RoleAttributes;

// Helper lambda to check timestamp equality for brevity
auto check_timestamp = [](const RoleBase& role, int64_t expected) {
    EXPECT_EQ(role.timestamp_ns(), expected);
};

TEST(RoleTest, constructor_getter_setter) {
  // Default constructed instances
  RoleBase instance_a;
  check_timestamp(instance_a, 0);

  instance_a.set_timestamp_ns(123);
  check_timestamp(instance_a, 123);

  RoleWriter writer_instance_a;
  check_timestamp(writer_instance_a, 0);

  RoleServer server_instance_a;
  check_timestamp(server_instance_a, 0);

  // Set attributes and verify
  RoleAttributes attrs;
  attrs.set_host_name("caros");
  attrs.set_process_id(12345);
  instance_a.set_attributes(attrs);

  EXPECT_EQ(instance_a.attributes().host_name(), "caros");
  EXPECT_EQ(instance_a.attributes().process_id(), 12345);

  // Parameterized constructors
  RoleBase instance_b(attrs, 321);
  check_timestamp(instance_b, 321);

  RoleWriter writer_instance_b(attrs, 321);
  check_timestamp(writer_instance_b, 321);

  RoleServer server_instance_b(attrs, 321);
  check_timestamp(server_instance_b, 321);
}

TEST(RoleTest, is_earlier_than) {
  RoleBase first_role;
  first_role.set_timestamp_ns(123);

  RoleBase second_role;
  second_role.set_timestamp_ns(456);

  EXPECT_TRUE(first_role.IsEarlierThan(second_role));
  EXPECT_FALSE(second_role.IsEarlierThan(first_role));
}

TEST(RoleTest, rolebase_match) {
  RoleAttributes base_attrs;
  base_attrs.set_host_name("caros");
  base_attrs.set_process_id(12345);
  base_attrs.set_node_id(1);

  RoleBase target_role(base_attrs, 1234567);

  RoleAttributes match_attrs;
  // Initially empty — should match on host/process/node if defaults allow; here we expect true due to partial match logic
  EXPECT_TRUE(target_role.Match(match_attrs));

  // Change hostname
  match_attrs.set_host_name("sorac");
  EXPECT_FALSE(target_role.Match(match_attrs));

  // Restore hostname
  match_attrs.set_host_name("caros");
  EXPECT_TRUE(target_role.Match(match_attrs));

  // Change process ID
  match_attrs.set_process_id(54321);
  EXPECT_FALSE(target_role.Match(match_attrs));

  // Restore process ID
  match_attrs.set_process_id(12345);
  EXPECT_TRUE(target_role.Match(match_attrs));

  // Change node ID
  match_attrs.set_node_id(2);
  EXPECT_FALSE(target_role.Match(match_attrs));

  // Restore node ID
  match_attrs.set_node_id(1);
  EXPECT_TRUE(target_role.Match(match_attrs));
}

TEST(RoleTest, rolewriter_match) {
  RoleAttributes writer_attrs;
  writer_attrs.set_host_name("caros");
  writer_attrs.set_process_id(12345);
  writer_attrs.set_node_id(1);

  RoleAttributes match_attrs(writer_attrs);

  writer_attrs.set_channel_id(2);
  writer_attrs.set_id(3);
  RoleWriter writer_instance(writer_attrs, 1234567);

  EXPECT_TRUE(writer_instance.Match(match_attrs));

  match_attrs.set_id(4);
  EXPECT_FALSE(writer_instance.Match(match_attrs));

  match_attrs.set_id(3);
  EXPECT_TRUE(writer_instance.Match(match_attrs));

  match_attrs.set_channel_id(3);
  EXPECT_FALSE(writer_instance.Match(match_attrs));

  match_attrs.set_channel_id(2);
  EXPECT_TRUE(writer_instance.Match(match_attrs));
}

TEST(RoleTest, roleserver_match) {
  RoleAttributes server_attrs;
  server_attrs.set_host_name("caros");
  server_attrs.set_process_id(12345);
  server_attrs.set_node_id(1);

  RoleAttributes match_attrs(server_attrs);

  server_attrs.set_service_id(2);
  RoleServer server_instance(server_attrs, 1234567);

  EXPECT_TRUE(server_instance.Match(match_attrs));

  match_attrs.set_service_id(3);
  EXPECT_FALSE(server_instance.Match(match_attrs));

  match_attrs.set_service_id(2);
  EXPECT_TRUE(server_instance.Match(match_attrs));
}

