    #include <Windows.h>
#endif

// Safely zero out a memory region in a way that compilers cannot optimize away
void SecureZero(void* pointer, size_t count) noexcept {
#ifdef _MSC_VER
    SecureZeroMemory(pointer, count);
#elif defined(__STDC_LIB_EXT1__) && defined(memset_s)
    memset_s(pointer, count, 0, count);
#else
    // Use volatile pointer to prevent compiler optimization of the zeroing loop
    unsigned char* data = static_cast<unsigned char*>(pointer);
    for (size_t i = 0; i < count; ++i) {
        data[i] = 0;
    }
#endif
}

#include <vector>
#include <unordered_set>

class Solution {
public:
    int minimumOperations(std::vector<int>& nums) {
        std::unordered_set<int> uniqueValues;
        for (int value : nums) {
            if (value != 0) {
                uniqueValues.insert(value);
            }
        }
        return static_cast<int>(uniqueValues.size());
    }
};

