UNIT_TEST(GoldenRecode)
{
  string input("\x01\x23\x45\x67\x89\xAB\xCD\xEF");
  string expectedHex("0123456789ABCDEF");
  TEST_EQUAL(ToHex(input), expectedHex, ());
  TEST_EQUAL(input, FromHex(expectedHex), ());
}

UNIT_TEST(RandomRecode)
{
  mt19937 prng(0);
  for (size_t count = 0; count < 256; ++count)
  {
    size_t length = 1 + (prng() % 20);
    string buffer(length, '\0');
    for (size_t idx = 0; idx < length; ++idx)
      buffer[idx] = static_cast<char>(prng() % 26) + 'A';
    string encoded = ToHex(buffer);
    string decoded = FromHex(encoded);
    TEST_EQUAL(buffer, decoded, ());
  }
}

UNIT_TEST(EncodeNumber)
{
  uint64_t value = 0x0123456789ABCDEFULL;
  TEST_EQUAL(NumToHex(value), "0123456789ABCDEF", ());
}

UNIT_TEST(DecodeLowerCaseHex)
{
  string hexInput = "fe";
  string expectedBytes("\xfe", 1);
  TEST_EQUAL(FromHex(hexInput), expectedBytes, ());
}

