//=============================================================================
// SVNCleanupDialog (restructured variant)
//-----------------------------------------------------------------------------
SVNCleanupDialog::SVNCleanupDialog(QWidget *parent, const QString &workingDir)
    : Dialog(TApp::instance()->getMainWindow(), true, false, "SvnCleanup") {
  setModal(false);
  setAttribute(Qt::WA_DeleteOnClose, true);
  setWindowTitle(tr("Version Control: Cleanup"));
  setMinimumSize(300, 150);

  // Initialize layout vertically
  QVBoxLayout *mainLayout = new QVBoxLayout(this);
  mainLayout->setContentsMargins(0, 0, 0, 0);

  // Setup animated waiting indicator
  QLabel *loaderLabel = new QLabel;
  QMovie *loaderGif = new QMovie(":Resources/waiting.gif", {}, this);
  loaderLabel->setMovie(loaderGif);
  loaderGif->setCacheMode(QMovie::CacheAll);
  loaderGif->start();

  // Display status message with working directory path
  QLabel *statusLabel = new QLabel(tr("Cleaning up %1...").arg(workingDir));

  // Add widgets to layout
  mainLayout->addWidget(loaderLabel);
  mainLayout->addWidget(statusLabel);

  // Store references for later updates
  m_waitingLabel = loaderLabel;
  m_textLabel    = statusLabel;

  // Create close button and connect signal/slot
  QPushButton *quitButton = new QPushButton(tr("Close"));
  connect(quitButton, &QPushButton::clicked, this, &SVNCleanupDialog::close);
  quitButton->setEnabled(false);
  addButtonBarWidget(quitButton);
  m_closeButton = quitButton;

  // Set up SVN thread connections
  connect(&m_thread, &SvnThread::error, this, &SVNCleanupDialog::handleSvnError);
  connect(&m_thread, &SvnThread::finished, this, &SVNCleanupDialog::onCleanupCompleted);

  // Prepare and execute cleanup command
  QStringList cmdArgs;
  cmdArgs << "cleanup";
  m_thread.runCommand(workingDir, "svn", cmdArgs);
}

//-----------------------------------------------------------------------------
void SVNCleanupDialog::onCleanupCompleted() {
  m_textLabel->setText(tr("Cleanup done."));
  m_waitingLabel->setVisible(false);
  m_closeButton->setEnabled(true);
}

//-----------------------------------------------------------------------------
void SVNCleanupDialog::handleSvnError(const QString &msg) {
  m_waitingLabel->hide();
  m_textLabel->setText(msg);
  m_closeButton->setEnabled(true);
}
