std::vector<wxString> DefaultLabels() {
  return {"Fixture ID", "Name",        "Type",      "Layer",
          "Hang Pos",   "Universe",    "Channel",   "Mode",
          "Ch Count",   "Model file",  "Pos X",     "Pos Y",
          "Pos Z",      "Roll (X)",    "Pitch (Y)", "Yaw (Z)",
          "Power (W)",  "Weight (kg)", "Color"};
}

void ConfigureColumns(wxDataViewListCtrl *table,
                      const std::vector<wxString> &columnLabels) {
  // Predefined column widths for the fixture table
  std::vector<int> colWidths = {90, 150, 180, 100, 120, 80, 80,  120, 80, 180,
                                80, 80,  80,  80,  80,  80, 100, 100, 80};

  int commonFlags = wxDATAVIEW_COL_RESIZABLE | wxDATAVIEW_COL_SORTABLE;

  // Create and append first seven columns using a loop
  for (size_t idx = 0; idx < 7; ++idx) {
    auto *renderer = new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
    table->AppendColumn(new wxDataViewColumn(columnLabels[idx], renderer, static_cast<int>(idx),
                                             colWidths[idx], wxALIGN_LEFT, commonFlags));
  }

  // Append remaining columns (except last one) similarly
  for (size_t i = 7; i < columnLabels.size() - 1; ++i) {
    auto *renderer = new ColorfulTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
    table->AppendColumn(new wxDataViewColumn(columnLabels[i], renderer, static_cast<int>(i),
                                             colWidths[i], wxALIGN_LEFT, commonFlags));
  }

  // Special handling for the last column (color)
  auto *colorRenderer = new ColorfulIconTextRenderer(wxDATAVIEW_CELL_INERT, wxALIGN_LEFT);
  colorRenderer->EnableEllipsize(wxELLIPSIZE_NONE);
  size_t lastColIndex = columnLabels.size() - 1;
  table->AppendColumn(new wxDataViewColumn(
      columnLabels[lastColIndex], colorRenderer, static_cast<int>(lastColIndex),
      colWidths[lastColIndex], wxALIGN_LEFT, commonFlags));

  // Apply minimum width enforcement
  ColumnUtils::EnforceMinColumnWidth(table);
}

