#include "ocs2_mpc/SystemObservation.h"
#include <utility>

namespace ocs2 {

/******************************************************************************************************/
/******************************************************************************************************/
/******************************************************************************************************/
void swap(SystemObservation& first, SystemObservation& second) noexcept {
  using std::swap;
  swap(first.mode, second.mode);
  swap(first.time, second.time);
  first.state.swap(second.state);
  first.input.swap(second.input);
}

/******************************************************************************************************/
/******************************************************************************************************/
/******************************************************************************************************/
std::ostream& operator<<(std::ostream& stream, const SystemObservation& data) {
  stream << "Observation: \n";
  stream << "\t time:      " << data.time << '\n';
  stream << "\t mode:      " << data.mode << '\n';

  // Output state vector
  stream << "\t state:    [";
  if (!data.state.empty()) {
    for (size_t idx = 0; idx < data.state.size() - 1; ++idx) {
      stream << data.state(idx) << ", ";
    }
    stream << data.state(data.state.size() - 1);
  }
  stream << "]\n";

  // Output input vector
  stream << "\t input:    [";
  if (!data.input.empty()) {
    for (size_t idx = 0; idx < data.input.size() - 1; ++idx) {
      stream << data.input(idx) << ", ";
    }
    stream << data.input(data.input.size() - 1);
  }
  stream << "]";

  return stream;
}

}  // namespace ocs2

