std::string retrieveOperatingSystemInfo() {
    std::stringstream buffer;

    #if defined(_WIN32) || defined(_WIN64)
        buffer << "Windows";
    #elif defined(__APPLE__) || defined(__MACH__)
        buffer << "macOS";
    #elif defined(__linux__)
        buffer << "Linux";
    #elif defined(__unix__) || defined(__unix)
        buffer << "Unix-like";
    #else
        buffer << "Unknown OS";
    #endif

    // Append architecture information (32-bit or 64-bit)
    buffer << " " << (sizeof(void*) * 8) << "-bit";

    return buffer.str();
}

