#ifndef DEF_SPI_FREQ
  #define DEF_SPI_FREQ        40000000UL      /* Set to 0 for system default */
#endif

// Helper alias for SPI bus selection
constexpr bool useHSPI = DSP_HSPI;

DspCore::DspCore()
    : Adafruit_ST7789(useHSPI ? &SPI2 : &SPI, TFT_CS, TFT_DC, TFT_RST) {}

void DspCore::initDisplay() {
    // Determine display dimensions based on model
    uint16_t width = 240;
    uint16_t height = (DSP_MODEL == DSP_ST7789) ? 320 : 240;

    switch (DSP_MODEL) {
        case DSP_ST7789_76:
            width = 76;
            height = 284;
            break;
        case DSP_ST7789_170:
            width = 170;
            height = 320;
            break;
        case DSP_ST7789_240:
            // Keep defaults: 240x240
            break;
        default:
            // For DSP_ST7789 or unknown fallback
            break;
    }

    init(width, height);

    if (DEF_SPI_FREQ > 0U) {
        setSPISpeed(DEF_SPI_FREQ);
    }

    invert();
    cp437(true);
    flip();
    setTextWrap(false);
    setTextSize(1);
    fillScreen(0x0000);
}

void DspCore::clearDsp(bool useBlack) {
    fillScreen(useBlack ? 0 : config.theme.background);
}

void DspCore::flip() {
    uint8_t rotation = 0;

#if DSP_MODEL == DSP_ST7789 || DSP_MODEL == DSP_ST7789_76 || DSP_MODEL == DSP_ST7789_170
    rotation = config.store.flipscreen ? 3 : 1;
#elif DSP_MODEL == DSP_ST7789_240
    if (ROTATE_90) {
        rotation = config.store.flipscreen ? 3 : 1;
    } else {
        rotation = config.store.flipscreen ? 2 : 0;
    }
#endif

    setRotation(rotation);
}

void DspCore::invert() {
    bool inverted = config.store.invertdisplay;
#if DSP_MODEL == DSP_ST7789_170
    inverted = !inverted;
#endif
    invertDisplay(inverted);
}

void DspCore::sleep() {
    enableSleep(true);
    delay(150);
    enableDisplay(false);
    delay(150);
}

void DspCore::wake() {
    enableDisplay(true);
    delay(150);
    enableSleep(false);
    delay(150);
}

