// Simplified domain identifiers
enum class hip_domain_id {
    last = 0,
    runtime,
    compiler
};

// Base trait for API domain info
template<hip_domain_id Id>
struct hip_domain_info {};

// Specialization for base case
template<>
struct hip_domain_info<hip_domain_id::last> {
    using args_type              = void*;
    using retval_type            = void*;
    using callback_data_type     = void*;
    using buffered_data_type     = void*;
    using buffered_ext_data_type = void*;
};

// Runtime domain specialization
template<>
struct hip_domain_info<hip_domain_id::runtime> : hip_domain_info<hip_domain_id::last> {
    static constexpr auto callback_domain_idx     = "HIP_RUNTIME";
    static constexpr auto buffered_domain_idx     = "HIP_RUNTIME_BUFFERED";
    static constexpr auto buffered_ext_domain_idx = "HIP_RUNTIME_BUFFERED_EXT";
    static constexpr auto none                    = "NONE_RUNTIME";
    static constexpr auto last                    = "LAST_RUNTIME";
};

// Compiler domain specialization
template<>
struct hip_domain_info<hip_domain_id::compiler> : hip_domain_info<hip_domain_id::last> {
    static constexpr auto callback_domain_idx     = "HIP_COMPILER";
    static constexpr auto buffered_domain_idx     = "HIP_COMPILER_BUFFERED";
    static constexpr auto buffered_ext_domain_idx = "HIP_COMPILER_BUFFERED_EXT";
    static constexpr auto none                    = "NONE_COMPILER";
    static constexpr auto last                    = "LAST_COMPILER";
};

// Helper to simulate API info definition
#define DEFINE_HIP_API(DOMAIN, ID, NAME, FUNC, ...) \
    inline constexpr auto api_##ID = std::make_tuple(#NAME, #FUNC, #DOMAIN);

// Simulated API entries
DEFINE_HIP_API(runtime, hipMalloc, hipMalloc, hipMalloc_fn, ptr, size)
DEFINE_HIP_API(runtime, hipFree, hipFree, hipFree_fn, ptr)
DEFINE_HIP_API(compiler, __hipRegisterFatBinary, __hipRegisterFatBinary, __hipRegisterFatBinary_fn, data)

int main() {
    std::cout << "HIP API domains registered:\n"
              << "Runtime domain: " << hip_domain_info<hip_domain_id::runtime>::callback_domain_idx << "\n"
              << "Compiler domain: " << hip_domain_info<hip_domain_id::compiler>::callback_domain_idx << "\n";
    return 0;
}

#include <ros/ros.h>
#include "init.h"
#include "init_serial.h"
#include "protocol_extracter/nprotocol_extracter.h"
#include <chrono>
#include <thread>

int main(int argc, char **argv) {
  ros::init(argc, argv, "iot_parser");
  ros::NodeHandle nh;
  serial::Serial device;
  initSerial(&device);
  NProtocolExtracter parser;
  iot::Init initializer(&parser);

  ros::Rate update_rate(1000);

  while (ros::ok()) {
    size_t bytes_available = device.available();
    std::string buffer;

    if (bytes_available > 0) {
      device.read(buffer, bytes_available);
      parser.AddNewData(buffer);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

