    H5G_obj_t result;           /* Function return value */

    FUNC_ENTER_API(H5G_UNKNOWN)
    H5TRACE3("Go", "iRt*x", id, ref_type, ref);

    /* Validate input parameters */
    if (H5G_loc(id, &loc_info) < 0)
        HGOTO_ERROR(H5E_ARGS, H5E_BADTYPE, H5G_UNKNOWN, "not a valid location")

    if (!(ref_type > H5R_BADTYPE && ref_type < H5R_MAXTYPE))
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, H5G_UNKNOWN, "invalid reference type")

    if (!ref)
        HGOTO_ERROR(H5E_ARGS, H5E_BADVALUE, H5G_UNKNOWN, "null reference pointer")

    /* Retrieve object type information */
    if (H5R_get_obj_type(loc_info.oloc->file, H5AC_ind_dxpl_id, ref_type, ref, &obj_kind) < 0)
        HGOTO_ERROR(H5E_REFERENCE, H5E_CANTINIT, H5G_UNKNOWN, "cannot determine object type")

    /* Map internal type to public API type */
    result = H5G_map_obj_type(obj_kind);

done:
    FUNC_LEAVE_API(result)
}   /* end H5Rget_obj_type1() */
#endif /* H5_NO_DEPRECATED_SYMBOLS */

