// NOLINTNEXTLINE(readability-identifier-naming)
struct GoldenProfileDiffTest : testing::TestWithParam<TFsPath> {};

TEST_P(GoldenProfileDiffTest, ConvertPprofCanon) {
    NPerforator::NProto::NPProf::Profile pprofProto;
    TString rawData = DecompressPprof(GetParam());
    Y_ENSURE(pprofProto.ParseFromString(rawData));

    // Construct a new profile from the parsed pprof data
    NPerforator::NProto::NProfile::Profile convertedProfile;
    NPerforator::NProfile::ConvertFromPProf(pprofProto, &convertedProfile);

    // Validate that both representations match
    CompareFlatProfiles(pprofProto, convertedProfile);
}

TEST_P(GoldenProfileDiffTest, ConvertPprofRoundTripCanon) {
    NPerforator::NProto::NPProf::Profile originalPprof;
    TString rawData = DecompressPprof(GetParam());
    Y_ENSURE(originalPprof.ParseFromString(rawData));

    // First conversion: pprof -> internal profile
    NPerforator::NProto::NProfile::Profile intermediateProfile;
    NPerforator::NProfile::ConvertFromPProf(originalPprof, &intermediateProfile);

    // Second conversion: internal profile -> pprof
    NPerforator::NProto::NPProf::Profile roundTrippedPprof;
    NPerforator::NProfile::ConvertToPProf(intermediateProfile, &roundTrippedPprof);

    // Ensure round-trip fidelity
    CompareFlatProfiles(originalPprof, roundTrippedPprof);
}

