    NPerforator::NProto::NProfile::Profile profileProto;
    NPerforator::NProfile::ConvertFromPProf(pprofBytes, &profileProto);

    NPerforator::NProto::NPProf::Profile directParsedProto;
    Y_ENSURE(directParsedProto.ParseFromString(pprofBytes));

    CompareFlatProfiles(directParsedProto, profileProto);
}

TEST_P(GoldenProfileDiffTest, ConvertPprofBytesRoundTripCanon) {
    TString originalBytes = DecompressPprof(GetParam());

    // Parse and convert to internal representation
    NPerforator::NProto::NProfile::Profile internalProfile;
    NPerforator::NProfile::ConvertFromPProf(originalBytes, &internalProfile);

    // Convert back to pprof format
    NPerforator::NProto::NPProf::Profile convertedBack;
    NPerforator::NProfile::ConvertToPProf(internalProfile, &convertedBack);

    // Parse original bytes directly for comparison
    NPerforator::NProto::NPProf::Profile originalParsed;
    Y_ENSURE(originalParsed.ParseFromString(originalBytes));

    CompareFlatProfiles(originalParsed, convertedBack);
}

