#undef X86_INS_
#define LATX_DT_X86    0
#define LATX_DT_X64    1

// Renamed arrays and variables for obfuscation
la_name_enum_t insn_map_table[X86_INS_ENDING + 1];
la_name_enum_t reg_map_table[X86_REG_ENDING + 1];
la_name_enum_t bcast_map_table[5];
la_name_enum_t op_type_map_table[4];
la_name_enum_t avx_cc_map_table[X86_AVX_CC_TRUE_US + 1];

// Handle storage with different naming
csh cap_handle_storage[2];
uint8_t mode_bits_storage[2];
char temp_buffer[IR1_INST_SIZE];

// Modified function with different control flow structure
struct la_dt_insn *gitcapstone_get_from_insn(cs_insn *inputinfo,
    int ir1_num, void *pir1_base)
{
    if (inputinfo == nullptr) {
        return nullptr;
    }

    struct la_dt_insn *result;

    // Alternative memory allocation strategy
    if (pir1_base != nullptr) {
        uint64_t current_address = reinterpret_cast<uint64_t>(pir1_base) +
            (ir1_num * sizeof(struct la_dt_insn));
        result = reinterpret_cast<struct la_dt_insn*>(current_address);
    } else {
        result = static_cast<struct la_dt_insn*>(malloc(sizeof(struct la_dt_insn)));
    }

#ifdef LATX_DISASSEMBLE_TRACE_DEBUG
    strncpy(result->mnemonic, inputinfo->mnemonic, 32);
    strncpy(result->op_str, inputinfo->op_str, 160);
#endif

    lsassert(inputinfo->id <= X86_INS_ENDING);
    result->id = insn_map_table[inputinfo->id].id;

    // Copy prefix data with loop unrolling alternative
    for (int i = 0; i < 4; ++i) {
        result->x86.prefix[i] = inputinfo->detail->x86.prefix[i];
    }

    // Copy opcode data
    for (int i = 0; i < 4; ++i) {
        result->x86.opcode[i] = inputinfo->detail->x86.opcode[i];
    }

    // Copy instruction bytes
    for (int i = 0; i < 24; ++i) {
        result->bytes[i] = inputinfo->bytes[i];
    }

    result->x86.addr_size = inputinfo->detail->x86.addr_size;
    result->x86.rex = inputinfo->detail->x86.rex;
    result->x86.modrm = inputinfo->detail->x86.modrm;
    result->x86.op_count = inputinfo->detail->x86.op_count;

    // Process operands with refactored logic
    for (int i = 0; i < 8; ++i) {
        int operand_type = inputinfo->detail->x86.operands[i].type;
        result->x86.operands[i].type = op_type_map_table[operand_type].id;

        switch (operand_type) {
            case X86_OP_IMM:
                result->x86.operands[i].imm = inputinfo->detail->x86.operands[i].imm;
                break;
            case X86_OP_REG:
                lsassert(inputinfo->detail->x86.operands[i].reg <= dt_X86_REG_ENDING);
                result->x86.operands[i].reg = reg_map_table[inputinfo->detail->x86.operands[i].reg].id;
                break;
            case X86_OP_MEM:
                lsassert(inputinfo->detail->x86.operands[i].mem.segment <= dt_X86_REG_ENDING);
                lsassert(inputinfo->detail->x86.operands[i].mem.base <= dt_X86_REG_ENDING);
                lsassert(inputinfo->detail->x86.operands[i].mem.index <= dt_X86_REG_ENDING);

                result->x86.operands[i].mem.segment = 
                    reg_map_table[inputinfo->detail->x86.operands[i].mem.segment].id;
                result->x86.operands[i].mem.default_segment = dt_X86_REG_INVALID;
                result->x86.operands[i].mem.base = 
                    reg_map_table[inputinfo->detail->x86.operands[i].mem.base].id;
                result->x86.operands[i].mem.index = 
                    reg_map_table[inputinfo->detail->x86.operands[i].mem.index].id;
                result->x86.operands[i].mem.scale = 
                    inputinfo->detail->x86.operands[i].mem.scale;
                result->x86.operands[i].mem.disp = 
                    inputinfo->detail->x86.operands[i].mem.disp;
                break;
            default:
                break;
        }

        result->x86.operands[i].size = inputinfo->detail->x86.operands[i].size;

        // Access type mapping with different control structure
        switch (inputinfo->detail->x86.operands[i].access) {
            case CS_AC_READ:
                result->x86.operands[i].access = dt_CS_AC_READ;
                break;
            case CS_AC_WRITE:
                result->x86.operands[i].access = dt_CS_AC_WRITE;
                break;
            case (CS_AC_READ | CS_AC_WRITE):
                result->x86.operands[i].access = (dt_CS_AC_READ | dt_CS_AC_WRITE);
                break;
        }

        result->x86.operands[i].avx_bcast = 
            bcast_map_table[inputinfo->detail->x86.operands[i].avx_bcast].id;
        result->x86.operands[i].avx_zero_opmask = 
            inputinfo->detail->x86.operands[i].avx_zero_opmask;
    }

    result->x86.avx_cc = avx_cc_map_table[inputinfo->detail->x86.avx_cc].id;
    result->size = inputinfo->size;
    result->address = inputinfo->address;

    return result;
}

// Modified gitcapstone_get function with different error handling approach
int gitcapstone_get(const uint8_t *code, size_t code_size,
        uint64_t address,
        size_t count, struct la_dt_insn **insn,
        int ir1_num, void *pir1_base, int mode)
{
    cs_insn *disasm_result;
    struct la_dt_insn *output_result;

    dtassert(cap_handle_storage[mode]);

    int disasm_count = latx_cs_disasm(cap_handle_storage[mode], code, code_size,
        address, count, &disasm_result, 0, temp_buffer);

    if (disasm_result == nullptr) {
        *insn = nullptr;
        qemu_log_mask(LAT_LOG_DT, "%s: can't disassemble code 0x%x\n",
            __func__, *(uint32_t *)code);
        return disasm_count;
    }

    output_result = gitcapstone_get_from_insn(disasm_result, ir1_num, pir1_base);
    *insn = output_result;

    return disasm_count;
}

