    if (cs_open(CS_ARCH_X86, CS_MODE_32, &cap_handle_storage[LATX_DT_X86]) != CS_ERR_OK) {
        fprintf(stderr, "%s %s %d error : cs_open\n",
                __FILE__, __func__, __LINE__);
        exit(-1);
    }

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &cap_handle_storage[LATX_DT_X64]) != CS_ERR_OK) {
        fprintf(stderr, "%s %s %d error : cs_open\n",
                __FILE__, __func__, __LINE__);
        exit(-1);
    }

    cs_option(cap_handle_storage[LATX_DT_X86], CS_OPT_DETAIL, CS_OPT_ON);
    cs_option(cap_handle_storage[LATX_DT_X64], CS_OPT_DETAIL, CS_OPT_ON);
}

