    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, SI);
    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, SP);

    // Segment registers
    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, CS);
    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, DS);
    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, ES);
    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, FS);
    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, GS);
    LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, SS);

    // Control registers
    for (int cr = 0; cr <= 15; ++cr) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, CR0 + cr);
    }

    // Debug registers
    for (int dr = 0; dr <= 15; ++dr) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, DR0 + dr);
    }

    // FPU registers
    for (int fp = 0; fp <= 7; ++fp) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, FP0 + fp);
    }

    // K registers
    for (int k = 0; k <= 7; ++k) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, K0 + k);
    }

    // MMX registers
    for (int mm = 0; mm <= 7; ++mm) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, MM0 + mm);
    }

    // XMM registers
    for (int xmm = 0; xmm <= 31; ++xmm) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, XMM0 + xmm);
    }

    // YMM registers
    for (int ymm = 0; ymm <= 31; ++ymm) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, YMM0 + ymm);
    }

    // ZMM registers
    for (int zmm = 0; zmm <= 31; ++zmm) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, ZMM0 + zmm);
    }

    // R registers (64-bit)
    for (int r = 0; r <= 15; ++r) {
        LA_X86_INSN_ENUM(reg_map_table, X86_REG_, X86_REG_, R0 + r);
