// Asynchronous entry point that displays a centered button with fixed size
Async::Task<> entryPointAsync(Sys::Context& ctx, Async::CancellationToken ct) {
    // Create the UI component: a button labeled "Hello, world"
    auto buttonWidget = Ui::button(Ui::SINK<>, "Hello, world"s);

    // Apply layout transformations: center the button and constrain its size
    auto layoutWidget = buttonWidget |
                        Ui::center() |
                        Ui::pinSize({300, 300});

    // Run the UI asynchronously and return the result
    co_return co_await Ui::runAsync(ctx, layoutWidget, ct);
}

