struct DummyBase {};

// Helper to reduce assertion verbosity
template<typename T, typename Expected>
bool check_same() {
    return std::is_same_v<T, Expected>;
}

// Test fixture for non-template base classes
template <typename T>
class NonTemplateBaseTests : public ::testing::Test {};

using NonTemplateTypes = ::testing::Types<BaseInterface, BaseClass, LocalProxy, RemoteProxy>;
TYPED_TEST_SUITE(NonTemplateBaseTests, NonTemplateTypes);

TYPED_TEST(NonTemplateBaseTests, AccessorDeclarationsMatchExpectedTypes)
{
    // Use helper lambda to avoid repeating long type names
    auto verify = []() {
        using T = TypeParam;
        EXPECT_TRUE(check_same<T, SenInterfaceTypeT<T>>());
        EXPECT_TRUE(check_same<T, SenBaseTypeT<T>>());
        EXPECT_TRUE(check_same<T, SenLocalProxyTypeT<T>>());
        EXPECT_TRUE(check_same<T, SenRemoteProxyTypeT<T>>());
        EXPECT_FALSE(SenClassRelation<T>::isBaseTypeTemplate);
    };
    verify();
}

// Test fixture for templated base classes
template <typename T>
class TemplateBaseTests : public ::testing::Test {};

using TemplateTypes = ::testing::Types<TemplatedBaseInterface,
                                       TemplatedBaseClass<DummyBase>,
                                       TemplatedLocalProxy,
                                       TemplatedRemoteProxy>;
TYPED_TEST_SUITE(TemplateBaseTests, TemplateTypes);

TYPED_TEST(TemplateBaseTests, AccessorDeclarationsWithTemplateParameter)
{
    using T = TypeParam;

    // Verify interface and proxy types are consistent regardless of base template
    EXPECT_TRUE(check_same<T, SenInterfaceTypeT<T>>());
    EXPECT_TRUE(check_same<T, SenLocalProxyTypeT<T>>());
    EXPECT_TRUE(check_same<T, SenRemoteProxyTypeT<T>>());

    // Check base type with explicit base parameter
    EXPECT_TRUE(check_same<T, SenBaseTypeT<T, DummyBase>>());

    // Also validate alternative base parameter yields correct mapping
    struct AnotherBase {};
    EXPECT_TRUE(check_same<T, SenBaseTypeT<T, AnotherBase>>());

    // Confirm template flag is set correctly
    EXPECT_TRUE(SenClassRelation<T>::isBaseTypeTemplate);
}

