TEST_CASE(test_channel_stats_average, "Performance") {
    ChannelStats stats;

    // Add three values: 10, 20, and 30
    stats.AddSample(10.0);
    stats.AddSample(20.0);
    stats.AddSample(30.0);

    // Verify the average is 20.0
    ASSERT_NEAR(stats.GetAverage(), 20.0, 0.001);
}

TEST_CASE(test_channel_stats_resets, "Performance") {
    ChannelStats stats;

    // First measurement interval
    stats.AddSample(10.0);
    stats.AddSample(100.0);
    ASSERT_NEAR(stats.GetCurrentMax(), 100.0, 0.001);

    // Reset current interval but preserve session-level data
    stats.ResetCurrentInterval();
    ASSERT_NEAR(stats.GetCurrentSum(), 0.0, 0.001);
    ASSERT_NEAR(stats.GetSessionPeak(), 100.0, 0.001); // Previous peak preserved

    // Second measurement interval
    stats.AddSample(20.0);
    stats.AddSample(50.0);

    ASSERT_NEAR(stats.GetCurrentSum(), 70.0, 0.001);
    ASSERT_NEAR(stats.GetSessionPeak(), 100.0, 0.001); // Still 100 from first interval

    // New maximum exceeds previous session peak
    stats.AddSample(150.0);
    ASSERT_NEAR(stats.GetSessionPeak(), 150.0, 0.001);
}

TEST_CASE(test_channel_stats_empty_reset, "Performance") {
    ChannelStats stats;
    stats.ResetCurrentInterval();
    ASSERT_NEAR(stats.GetLastAverage(), 0.0, 0.001);
}
