#include <iostream>
#include "sophus/geometry.hpp"

int main() {
  // Demonstrate composition of 3D rotations and their action on vectors
  using namespace Sophus;

  const double pi = Constants<double>::pi();

  // Construct rotation matrices for individual axis rotations
  SO3d rotX = SO3d::rotX(pi / 4.0);
  SO3d rotY = SO3d::rotY(pi / 6.0);
  SO3d rotZ = SO3d::rotZ(-pi / 3.0);

  std::cout << "Individual rotation matrices:" << std::endl;
  std::cout << "R_x(π/4):\n" << rotX.matrix() << std::endl;
  std::cout << "R_y(π/6):\n" << rotY.matrix() << std::endl;
  std::cout << "R_z(-π/3):\n" << rotZ.matrix() << std::endl;

  // Compose rotations: first Z, then Y, then X (right-to-left multiplication)
  SO3d composed = rotX * rotY * rotZ;
  std::cout << "\nComposite rotation R_x * R_y * R_z:\n" << composed.matrix() << std::endl;

  // Apply rotations to a test vector
  Eigen::Vector3d point(0.0, 0.0, 1.0);
  std::cout << "\nVector transformation examples:" << std::endl;
  std::cout << "Original vector:\n" << point << std::endl;

  Eigen::Vector3d y_transformed = rotY * point;
  std::cout << "After R_y(π/6):\n" << y_transformed << std::endl;

  Eigen::Vector3d xy_transformed = rotX * y_transformed;
  std::cout << "Then R_x(π/4):\n" << xy_transformed << std::endl;

  Eigen::Vector3d direct_composed = composed * point;
  std::cout << "Direct application of composite rotation:\n" << direct_composed << std::endl;

  // Show internal representation as unit quaternion
  std::cout << "\nSO(3) internal representation (unit quaternion):" << std::endl;
  std::cout << "R_x(π/4) as quaternion coefficients (i, j, k, w):\n"
            << rotX.unit_quaternion().coeffs() << std::endl;

  return 0;
}

