  EXPECT_EQ(TrimOws("\thello\t"), std::string_view("hello"));
  EXPECT_EQ(TrimOws(" \thello \t"), std::string_view("hello"));
}

// Verify that non-OWS whitespace like newlines are preserved
TEST(StringTrimTest, NewlinesAndOtherWhitespacePreserved) {
  EXPECT_EQ(TrimOws("\nhello\n"), std::string_view("\nhello\n"));
  EXPECT_EQ(TrimOws(" \nhello\n "), std::string_view("\nhello\n"));
}

// Edge cases: empty string and strings with only OWS
TEST(StringTrimTest, HandlesEmptyAndPureWhitespace) {
  EXPECT_EQ(TrimOws(""), std::string_view(""));
  EXPECT_EQ(TrimOws("   \t  "), std::string_view(""));
}

// Input without any OWS should remain unchanged
TEST(StringTrimTest, NoChangeWhenNoOWS) { 
  EXPECT_EQ(TrimOws("hello"), std::string_view("hello")); 
}

// Internal whitespace (including tabs) should be preserved
TEST(StringTrimTest, InternalWhitespaceRetained) {
  EXPECT_EQ(TrimOws("  hello world  "), std::string_view("hello world"));
  EXPECT_EQ(TrimOws("  hello \tworld  "), std::string_view("hello \tworld"));
}

