// Forward declarations for initialization and termination functions
weak void _init();
weak void _fini();

// Main entry point for C runtime startup
int main();

// Declaration of the core libc startup function
int __libc_start_main(int (*)(), int, char **,
	void (*)(), void(*)(), void(*)());

// C runtime startup routine - processes argument vector and delegates to libc
void _start_c(long *p)
{
	// Extract argument count from the first element
	int argc = p[0];
	// Extract argument pointer array starting after the first element
	char **argv = (void *)(p + 1);

	// Delegate actual startup to the libc implementation
	__libc_start_main(main, argc, argv, _init, _fini, 0);
}

