// Calculate area of square using side length
void computeSquareArea(int side) {
    int area = side * side;
    std::cout << "area of square = " << area << std::endl;
}

// Compute perimeter of rectangle using length and breadth
void computeRectanglePerimeter(int length, int breadth) {
    int perimeter = 2 * (length + breadth);
    std::cout << "perimeter of rectangle = " << perimeter << std::endl;
}

// Compute area of circle using radius (approximating pi as 3.14)
void computeCircleArea(int radius) {
    const float PI = 3.14f;
    float area = PI * radius * radius;
    std::cout << "area of circle = " << area << std::endl;
}

// Find maximum among three integers
int findMaxOfThree(int x, int y, int z) {
    int max = x;
    if (y > max) max = y;
    if (z > max) max = z;
    return max;
}

// Print multiplication table of a number up to 10
void printMultiplicationTable(int num) {
    std::cout << "table of " << num << ":" << std::endl;
    for (int i = 1; i <= 10; ++i) {
        std::cout << num << " x " << i << " = " << (num * i) << std::endl;
    }
}

int main() {
    int choice = 0;
    int side, length, breadth, r, n1, n2, n3;

    do {
        system("cls");

        std::cout << "1. area of square\n";
        std::cout << "2. perimeter of rectangle\n";
        std::cout << "3. area of circle\n";
        std::cout << "4. max of 3 nos\n";
        std::cout << "5. table of number\n";
        std::cout << "6. exit\n";
        std::cout << "enter your choice: ";
        std::cin >> choice;

        switch (choice) {
            case 1:
                std::cout << "enter side: ";
                std::cin >> side;
                computeSquareArea(side);
                break;

            case 2:
                std::cout << "enter length and breadth: ";
                std::cin >> length >> breadth;
                computeRectanglePerimeter(length, breadth);
                break;

            case 3:
                std::cout << "enter radius: ";
                std::cin >> r;
                computeCircleArea(r);
                break;

            case 4:
                std::cout << "enter three numbers: ";
                std::cin >> n1 >> n2 >> n3;
                int maxVal = findMaxOfThree(n1, n2, n3);
                std::cout << "max of 3 nos = " << maxVal << std::endl;
                break;

            case 5:
                std::cout << "enter number: ";
                std::cin >> side; // reusing 'side' as temporary input
                printMultiplicationTable(side);
                break;

            case 6:
                std::cout << "Exiting...\n";
                break;

            default:
                std::cout << "Invalid choice! Please try again.\n";
                break;
        }

        if (choice != 6) {
            std::cout << "\nPress Enter to continue...";
            std::cin.ignore();
            std::cin.get();
        }

    } while (choice != 6);

    return 0;
}

