#include "pch.h"
#include "Patcher.h"

void patcher::PatchAddress(void* targetAddress, const std::vector<BYTE>* patchData)
{
    DWORD previousProtection;
    VirtualProtect(targetAddress, patchData->size(), PAGE_EXECUTE_READWRITE, &previousProtection);

    // Copy the patch bytes to the target memory location
    std::memcpy(targetAddress, patchData->data(), patchData->size());

    // Restore original memory protection
    VirtualProtect(targetAddress, patchData->size(), previousProtection, &previousProtection);

    // Ensure CPU instruction cache is invalidated for the modified region
    FlushInstructionCache(GetCurrentProcess(), targetAddress, patchData->size());
}

struct la_dt_insn *laxed_get_from_insn(int64_t address,
    xed_decoded_inst_t *inputinfo,
    int ir1_num, void *pir1_base)
{
    if (!inputinfo) {
        return NULL;
    }

    struct la_dt_insn *result;
    if (pir1_base) {
        uint64_t offset_addr = (uint64_t)pir1_base + (ir1_num * sizeof(struct la_dt_insn));
        result = (void*)offset_addr;
        memset(result, 0, sizeof(struct la_dt_insn));
    } else {
        result = calloc(1, sizeof(struct la_dt_insn));
    }

    result->address = address;

#ifdef LATX_DISASSEMBLE_TRACE_DEBUG
    handle_dis_str(result, inputinfo);
#endif

    xed_iclass_enum_t insn_class = XED_ICLASS_INVALID;
    const xed_operand_values_t *op_vals = xed_decoded_inst_operands_const(inputinfo);

    if (xed_operand_values_has_real_rep(op_vals)) {
        insn_class = xed_rep_remove(xed_decoded_inst_get_iclass(inputinfo));
    } else {
        insn_class = xed_decoded_inst_get_iclass(inputinfo);
    }

    dtassert((insn_class <= XED_ICLASS_LAST) && 
        (la_xed_insn_tr[insn_class].id != dt_X86_INS_INVALID));

    result->id = la_xed_insn_tr[insn_class].id;

    handle_prefix(result, inputinfo);
    handle_opcode(result, inputinfo);

    result->size = xed_decoded_inst_get_length(inputinfo);

    int byte_idx = 0;
    while (byte_idx < result->size) {
        result->bytes[byte_idx] = xed_decoded_inst_get_byte(inputinfo, byte_idx);
        byte_idx++;
    }

    result->x86.addr_size = xed_operand_values_get_effective_address_width(
        xed_decoded_inst_operands_const(inputinfo)) / 8;

    if (dt_laxed_mode == 64) {
        xed_bits_t rex_val = xed3_operand_get_rex(inputinfo);
        result->x86.rex = (rex_val << 6);
        result->x86.rex |= (xed3_operand_get_rexb(inputinfo) << 0);
        result->x86.rex |= (xed3_operand_get_rexx(inputinfo) << 1);
        result->x86.rex |= (xed3_operand_get_rexr(inputinfo) << 2);
        result->x86.rex |= (xed3_operand_get_rexw(inputinfo) << 3);
    }

    const xed_inst_t *inst_info = xed_decoded_inst_inst(inputinfo);
    int operand_count = xed_inst_noperands(inst_info);
    int op_index = 0;
    int memory_op_indices[2] = {0};
    int mem_count = 0;

    if (insn_class == XED_ICLASS_CPUID) {
        goto process_operands;
    }

    while (op_index < operand_count) {
        const xed_operand_t *current_op = xed_inst_operand(inst_info, op_index);

        if (xed_operand_operand_visibility(current_op) == XED_OPVIS_SUPPRESSED) {
            if (!stringop_memop(inputinfo, current_op)) {
                seg_prefix_for_suppressed_operands(op_vals, current_op);
                op_index++;
                continue;
            }
        }

        xed_operand_enum_t op_type = xed_operand_name(current_op);
        result->x86.operands[mem_count].size = 
            xed_decoded_inst_operand_length_bits(inputinfo, op_index) / 8;

        switch (op_type) {
            case XED_OPERAND_AGEN:
            case XED_OPERAND_MEM0:
            case XED_OPERAND_MEM1: {
                memory_op_indices[mem_count++] = mem_count;
                result->x86.operands[mem_count++].type = dt_X86_OP_MEM;
                break;
            }
            case XED_OPERAND_PTR:
            case XED_OPERAND_RELBR: {
                lsassert(xed_decoded_inst_get_branch_displacement_width(inputinfo));
                if (xed_decoded_inst_get_branch_displacement_width(inputinfo)) {
                    result->x86.operands[mem_count].imm = 
                        result->address + 
                        xed_decoded_inst_get_branch_displacement(inputinfo);

                    if (op_type == XED_OPERAND_RELBR) {
                        result->x86.operands[mem_count].imm += result->size;

                        switch (dt_laxed_mode) {
                            case 32:
                                result->x86.operands[mem_count].size = 4;
                                break;
                            case 64:
                                result->x86.operands[mem_count].size = 8;
                                break;
                            default:
                                dtassert(0);
                        }
                    }
                    result->x86.operands[mem_count++].type = dt_X86_OP_IMM;
                }
                break;
            }
            case XED_OPERAND_IMM0: {
                xed_uint_t imm_bits = xed_decoded_inst_get_operand_width(inputinfo);
                if (xed3_operand_get_imm0signed(inputinfo)) {
                    result->x86.operands[mem_count].imm = XED_STATIC_CAST(xed_uint64_t,
                        xed_sign_extend_arbitrary_to_64(
                        xed_operand_values_get_immediate_int64(op_vals),
                        imm_bits));
                    result->x86.operands[mem_count].imm =
                        mask_value_bybit(result->x86.operands[mem_count].imm, imm_bits);
                } else {
                    result->x86.operands[mem_count].imm =
                        xed_operand_values_get_immediate_uint64(op_vals);
                }
                result->x86.operands[mem_count].size = imm_bits / 8;
                result->x86.operands[mem_count++].type = dt_X86_OP_IMM;
                break;
            }
            case XED_OPERAND_IMM1: {
                result->x86.operands[mem_count].imm = xed3_operand_get_uimm1(inputinfo);
                result->x86.operands[mem_count++].type = dt_X86_OP_IMM;
                break;
            }
            case XED_OPERAND_REG0:
            case XED_OPERAND_REG1:
            case XED_OPERAND_REG2:
            case XED_OPERAND_REG3:
            case XED_OPERAND_REG4:
            case XED_OPERAND_REG5:
            case XED_OPERAND_REG6:
            case XED_OPERAND_REG7:
            case XED_OPERAND_REG8:
            case XED_OPERAND_REG9: {
                xed_reg_enum_t reg_enum = xed_decoded_inst_get_reg(inputinfo, op_type);
                if ((reg_enum == XED_REG_STACKPOP) || (reg_enum == XED_REG_STACKPUSH)) {
                    result->x86.op_count = mem_count;
                    goto process_operands;
                }

                if ((reg_enum == XED_REG_EFLAGS) || (reg_enum == XED_REG_EIP)) {
                    op_index++;
                    continue;
                }

                result->x86.operands[mem_count].reg = la_xed_insn_reg[reg_enum].id;
                result->x86.operands[mem_count++].type = dt_X86_OP_REG;
                break;
            }
            case XED_OPERAND_BASE0:
            case XED_OPERAND_BASE1:
                op_index++;
                continue;
            default:
                lsassert(0);
        }
        op_index++;
    }

process_operands:
    result->x86.op_count = mem_count;
    dtassert(xed_decoded_inst_number_of_memory_operands(inputinfo) >= mem_count);

    int mem_idx = 0;
    while (mem_idx < mem_count) {
        int found_mem = memory_op_indices[mem_idx];
        unsigned int segment_reg;
        lsassert(found_mem <= result->x86.op_count);
        lsassert(result->x86.operands[found_mem].type == dt_X86_OP_MEM);

        result->x86.operands[found_mem].access = dt_CS_AC_INVALID;
        if (xed_decoded_inst_mem_read(inputinfo, mem_idx)) {
            result->x86.operands[found_mem].access |= dt_CS_AC_READ;
        }
        if (xed_decoded_inst_mem_written(inputinfo, mem_idx)) {
            result->x86.operands[found_mem].access |= dt_CS_AC_WRITE;
        }

        segment_reg = xed_decoded_inst_get_seg_reg(inputinfo, mem_idx);

        if (((mem_idx == 0) && (!xed3_operand_get_using_default_segment0(inputinfo))) ||
            ((mem_idx == 1) && (!xed3_operand_get_using_default_segment1(inputinfo)))) {
            result->x86.operands[found_mem].mem.segment = la_xed_insn_reg[segment_reg].id;
            result->x86.operands[found_mem].mem.default_segment = dt_X86_INS_INVALID;
        } else {
            result->x86.operands[found_mem].mem.segment = dt_X86_INS_INVALID;
            result->x86.operands[found_mem].mem.default_segment = la_xed_insn_reg[segment_reg].id;
        }

        result->x86.operands[found_mem].mem.base = 
            la_xed_insn_reg[xed_decoded_inst_get_base_reg(inputinfo, mem_idx)].id;

        if (mem_idx == 0) {
            result->x86.operands[found_mem].mem.index =
                la_xed_insn_reg[xed_decoded_inst_get_index_reg(inputinfo, mem_idx)].id;
            result->x86.operands[found_mem].mem.scale =
                xed_decoded_inst_get_scale(inputinfo, mem_idx);
        }

        result->x86.operands[found_mem].mem.disp =
            xed_decoded_inst_get_memory_displacement(inputinfo, mem_idx);

        if (!((result->x86.operands[found_mem].mem.base != dt_X86_REG_INVALID) &&
            result->x86.operands[found_mem].mem.disp < 0)) {
            xed_int_t disp_bits =
                xed_decoded_inst_get_memory_displacement_width_bits(inputinfo, mem_idx);
            result->x86.operands[found_mem].mem.disp =
                mask_value_bybit(result->x86.operands[found_mem].mem.disp, disp_bits);
        }

        result->x86.operands[found_mem].mem.disp =
            xed_imm_cast(result->x86.operands[found_mem].mem.disp, dt_laxed_mode / 8);

        mem_idx++;
    }

    return result;
}

