static void mem_barrier(void) { }

// Provide a weak alias for __vm_wait, defaulting to no-op
weak_alias(mem_barrier, __vm_wait);

// Unmap memory region starting at 'addr' with length 'size'
int __munmap(void *addr, size_t size)
{
	// Ensure any pending VM operations are completed first
	__vm_wait();
	return syscall(SYS_munmap, addr, size);
}

// Export __munmap as munmap under standard name
weak_alias(__munmap, munmap);

