// Display received data in hexadecimal format
void displayHexStream(const std::string &buffer) {
  if (!buffer.empty()) {
    std::cout << "hex stream: ";
    for (size_t idx = 0; idx < buffer.size(); ++idx) {
      std::cout << std::hex << std::setfill('0') << std::setw(2)
                << static_cast<int>(static_cast<uint8_t>(buffer[idx])) << " ";
    }
    std::cout << std::endl;
  }
}

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_parser");
  ros::NodeHandle nh;
  serial::Serial port;
  initializeSerial(&port);
  NProtocolExtracter extractor;
  linktrack::Init initializer(&extractor, &port);

  ros::Rate update_rate(1000);

  while (ros::ok()) {
    size_t bytes_available = port.available();
    std::string incoming_data;

    if (bytes_available > 0) {
      port.read(incoming_data, bytes_available);
      // displayHexStream(incoming_data);  // Optional: uncomment to see raw hex
      extractor.AddNewData(incoming_data);
    }

    ros::spinOnce();
    update_rate.sleep();
  }

  return EXIT_SUCCESS;
}

