void register_utils(nb::module_& mod) {
    // Expose Timer class to Python
    nb::class_<Timer> timer_class(mod, "Timer");
    timer_class.def(nb::init<int>(), nb::arg("timeout") = -1)
               .def("elapsed_time", &Timer::elapsed)
               .def("configure", &Timer::set, nb::arg("timeout"))
               .def("clear", &Timer::reset)
               .def("show", &Timer::print, nb::arg("label"));

    // Expose ScopedTimer class inheriting from Timer
    nb::class_<ScopedTimer, Timer> scoped_timer_class(mod, "ScopedTimer");
    scoped_timer_class.def(nb::init<std::string>(), nb::arg("identifier"));

    // Register host name utility function
    mod.def("hostname", &getHostName, nb::arg("limit"), nb::arg("separator"));
}

