#include "MasterMaterials/DatasmithRevitMaterialSelector.h"
#include "MasterMaterials/DatasmithSketchupMaterialSelector.h"

void IDatasmithTranslatorModule::StartupModule()
{
	// Initialize the master material manager singleton
	FDatasmithMasterMaterialManager::Create();

	// Register built-in material selectors for supported applications
	auto& manager = FDatasmithMasterMaterialManager::Get();

	manager.RegisterSelector(TEXT("C4D"), MakeShared<FDatasmithC4DMaterialSelector>());
	manager.RegisterSelector(TEXT("Revit"), MakeShared<FDatasmithRevitMaterialSelector>());
	manager.RegisterSelector(TEXT("SketchUp"), MakeShared<FDatasmithSketchUpMaterialSelector>());
	manager.RegisterSelector(TEXT("CityEngine"), MakeShared<FDatasmithCityEngineMaterialSelector>());
}

void IDatasmithTranslatorModule::ShutdownModule()
{
	auto& manager = FDatasmithMasterMaterialManager::Get();

	// Deregister all registered selectors in reverse order of registration
	manager.UnregisterSelector(TEXT("CityEngine"));
	manager.UnregisterSelector(TEXT("SketchUp"));
	manager.UnregisterSelector(TEXT("Revit"));
	manager.UnregisterSelector(TEXT("C4D"));

	// Clean up the master material manager instance
	FDatasmithMasterMaterialManager::Destroy();
}

