void GameOfLifeWindow::init(SurfaceRenderer& renderer)
{
    using namespace tc;

    // Initialize three floating-point buffers for computation
    m_pInputX.reset(new BufferResource<float>{ N });
    m_pInputY.reset(new BufferResource<float>{ N });
    m_pOutputZ.reset(new BufferResource<float>{ N });

    // Populate input buffers with random data in range [0, 100]
    m_pInputX->randomize(0, 100);
    m_pInputY->randomize(0, 100);

    // Set up the computation pipeline
    m_FloatAdder.A.attach(m_pInputX.get());
    m_FloatAdder.B.attach(m_pInputY.get());
    m_FloatAdder.C.attach(m_pOutputZ.get());

    // Configure GPU backend for computation
    using Backend = tc::gpu::GPUBackend;
    Backend gpuCompute;

    // Transfer buffers to GPU memory
    gpuCompute.uploadBuffer(*m_pInputX.get());
    gpuCompute.uploadBuffer(*m_pInputY.get());
    gpuCompute.uploadBuffer(*m_pOutputZ.get());

    // Load and configure the kernel
    gpuCompute.useKernel(m_FloatAdder);

    // Bind all required buffers for the operation
    gpuCompute.bindBuffer(m_FloatAdder.A);
    gpuCompute.bindBuffer(m_FloatAdder.B);
    gpuCompute.bindBuffer(m_FloatAdder.C);

    // Execute the computation kernel
    gpuCompute.execute(m_FloatAdder, tc::uvec3{ N,1,1 });

    // Retrieve results back from GPU
    gpuCompute.downloadBuffer(*m_pOutputZ.get());
}

