Licenses sLicense("system/src/math/SHA1.h", Licenses::kRequirementNotification);

// Helper macro for left rotation of 32-bit value
#define rotateLeft(val, shift) (((val) << (shift)) | ((val) >> (32 - (shift))))

// Block function definitions for message schedule
#define getBlockWord(idx) m_workspaceBuffer->words[idx]
#define expandBlockWord(idx) \
    (m_workspaceBuffer->words[(idx) & 0x0F] = \
        rotateLeft( \
            m_workspaceBuffer->words[(idx) & 0x0F] ^ \
            m_workspaceBuffer->words[((idx) + 2) & 0x0F] ^ \
            m_workspaceBuffer->words[((idx) + 8) & 0x0F] ^ \
            m_workspaceBuffer->words[((idx) + 13) & 0x0F], \
            1))

// SHA-1 round functions with different constants
#define ROUND1(a,b,c,d,e,idx) \
    e += ((b & (c ^ d)) ^ d) + getBlockWord(idx) + 0x5A827999 + rotateLeft(a, 5); \
    b = rotateLeft(b, 30);

#define ROUND2(a,b,c,d,e,idx) \
    e += ((b & (c ^ d)) ^ d) + expandBlockWord(idx) + 0x5A827999 + rotateLeft(a, 5); \
    b = rotateLeft(b, 30);

#define ROUND3(a,b,c,d,e,idx) \
    e += (b ^ c ^ d) + expandBlockWord(idx) + 0x6ED9EBA1 + rotateLeft(a, 5); \
    b = rotateLeft(b, 30);

#define ROUND4(a,b,c,d,e,idx) \
    e += (((b | c) & d) | (b & c)) + expandBlockWord(idx) + 0x8F1BBCDC + rotateLeft(a, 5); \
    b = rotateLeft(b, 30);

#define ROUND5(a,b,c,d,e,idx) \
    e += (b ^ c ^ d) + expandBlockWord(idx) + 0xCA62C1D6 + rotateLeft(a, 5); \
    b = rotateLeft(b, 30);

void CSHA1::Transform(unsigned int *stateRegisters, const unsigned char *inputBlock) {
    // Initialize working variables
    unsigned int wv1 = stateRegisters[0];
    unsigned int wv2 = stateRegisters[1];
    unsigned int wv3 = stateRegisters[2];
    unsigned int wv4 = stateRegisters[3];
    unsigned int wv5 = stateRegisters[4];

    // Copy input block to workspace buffer
    memcpy(m_workspaceBuffer->bytes, inputBlock, 64);

    // Execute first 20 rounds (0-15 direct, 16-19 expanded)
    ROUND1(wv1, wv2, wv3, wv4, wv5, 0);
    ROUND1(wv5, wv1, wv2, wv3, wv4, 1);
    ROUND1(wv4, wv5, wv1, wv2, wv3, 2);
    ROUND1(wv3, wv4, wv5, wv1, wv2, 3);
    ROUND1(wv2, wv3, wv4, wv5, wv1, 4);
    ROUND1(wv1, wv2, wv3, wv4, wv5, 5);
    ROUND1(wv5, wv1, wv2, wv3, wv4, 6);
    ROUND1(wv4, wv5, wv1, wv2, wv3, 7);
    ROUND1(wv3, wv4, wv5, wv1, wv2, 8);
    ROUND1(wv2, wv3, wv4, wv5, wv1, 9);
    ROUND1(wv1, wv2, wv3, wv4, wv5, 10);
