    ROUND4(wv4, wv5, wv1, wv2, wv3, 47);
    ROUND4(wv3, wv4, wv5, wv1, wv2, 48);
    ROUND4(wv2, wv3, wv4, wv5, wv1, 49);
    ROUND4(wv1, wv2, wv3, wv4, wv5, 50);
