    stateRegisters[0] += wv1;
    stateRegisters[1] += wv2;
    stateRegisters[2] += wv3;
    stateRegisters[3] += wv4;
    stateRegisters[4] += wv5;
}

void CSHA1::Update(const unsigned char *data, unsigned int length) {
    unsigned int processedBytes = m_byteCount[0] / 8;
    processedBytes %= 64;

    // Update bit counters (handle overflow)
    m_byteCount[0] += length * 8;
    if (m_byteCount[0] < (length * 8)) {
        m_byteCount[1]++;
    }
    m_byteCount[1] += (length >> 29);

    // Process data in 64-byte blocks
    if ((processedBytes + length) > 63) {
        unsigned int fillSize = 64 - processedBytes;
        memcpy(&m_inputBuffer[processedBytes], data, fillSize);
        Transform(m_hashState, m_inputBuffer);

        // Process complete remaining blocks
        for (unsigned int i = fillSize; i + 63 < length; i += 64) {
            Transform(m_hashState, &data[i]);
        }
        processedBytes = 0;
    } else {
        processedBytes = 0;
    }

    // Store remaining bytes
    if (length - processedBytes != 0) {
        memcpy(&m_inputBuffer[processedBytes], &data[processedBytes], length - processedBytes);
    }
}

const CSHA1::Digest &CSHA1::Final() {
    unsigned int i;
    unsigned char paddingBytes[8];
    unsigned char padByte;

    // Prepare length padding (big-endian format)
    for (i = 0; i < 8; i++) {
        paddingBytes[i] = 
            (unsigned char)((m_byteCount[(i >= 4 ? 0 : 1)] >> ((3 - (i & 3)) * 8)) & 0xFF);
    }

    // Add padding bit
    Update((const unsigned char *)"\x80", 1);

    // Add zero padding until we reach 448 bits (56 bytes) mod 512
    while ((m_byteCount[0] & 504) != 448) {
        Update((const unsigned char *)"\x00", 1);
    }

    // Append original length in bits
    Update(paddingBytes, 8);

    // Extract final hash digest
    for (i = 0; i < 20; i++) {
        m_result.digits[i] = 
            (unsigned char)((m_hashState[i >> 2] >> ((3 - (i & 3)) * 8)) & 0xFF);
    }

    // Clear sensitive data
    memset(m_inputBuffer, 0, 64);
    memset(m_hashState, 0, 20);
    memset(m_byteCount, 0, 8);
    memset(paddingBytes, 0, 8);
    Transform(m_hashState, m_inputBuffer);

    return m_result;
}

void CSHA1::Digest::Copy(unsigned char *output) const { 
    memcpy(output, this, 20); 
}

void CSHA1::Digest::ReportHash(char *output, unsigned char formatType) const {
    char tempBuffer[24];
    unsigned int index;

    if (output) {
        if (formatType == 0) {
            // Hexadecimal format
            sprintf(tempBuffer, "%02X", digits[0]);
            strcpy(output, tempBuffer);
            for (index = 1; index < 20; index++) {
                sprintf(tempBuffer, "%02X", digits[index & 0xFF]);
                strcat(output, tempBuffer);
            }
        } else if (formatType == 1) {
            // Decimal format with spaces
            sprintf(tempBuffer, "%u", digits[0]);
            strcpy(output, tempBuffer);
            for (index = 1; index < 20; index++) {
                sprintf(tempBuffer, " %u", digits[index & 0xFF]);
                strcat(output, tempBuffer);
            }
        } else {
            strcpy(output, "Error: Unknown report type!");
        }
    }
}

BinStream &operator<<(BinStream &stream, const CSHA1::Digest &digest) {
    stream.Write(digest.digits, 20);
    return stream;
}

BinStream &operator>>(BinStream &stream, CSHA1::Digest &digest) {
    stream.Read(digest.digits, 20);
    return stream;
}

CSHA1::CSHA1() {
    m_workspaceBuffer = (SHA1_WORKSPACE_BLOCK *)m_workspace;
    Reset();
}

CSHA1::~CSHA1() { 
    Reset(); 
}

