// Helper macro to reduce redundancy in exception tests
#define VERIFY_TIME_PARSE_FAILURE(code_str, expected_msg) \
    try { \
        Time::fromCString((code_str), strlen((code_str))); \
        FAIL() << "Expected ConversionException not thrown"; \
    } catch (const ConversionException& ex) { \
        EXPECT_STREQ(ex.what(), (expected_msg)); \
    } catch (...) { \
        FAIL() << "Unexpected exception type thrown"; \
    }

TEST(TimeTests, FromTimeValidation) {
    // Hour out of range
    try {
        Time::fromTime(25, 24, 32, 231321);
        FAIL();
    } catch (const ConversionException& e) {
        EXPECT_STREQ(e.what(),
            "Conversion exception: Time field value out of range: 25:24:32[.231321].");
    } catch (...) {
        FAIL();
    }

    // Minute out of range
    try {
        Time::fromTime(21, 60, 22, 212322);
        FAIL();
    } catch (const ConversionException& e) {
        EXPECT_STREQ(e.what(),
            "Conversion exception: Time field value out of range: 21:60:22[.212322].");
    } catch (...) {
        FAIL();
    }

    // Second out of range
    try {
        Time::fromTime(14, 22, 61);
        FAIL();
    } catch (const ConversionException& e) {
        EXPECT_STREQ(e.what(),
            "Conversion exception: Time field value out of range: 14:22:61[.0].");
    } catch (...) {
        FAIL();
    }

    // Microsecond out of range
    try {
        Time::fromTime(14, 22, 42, 1000001);
        FAIL();
    } catch (const ConversionException& e) {
        EXPECT_STREQ(e.what(),
            "Conversion exception: Time field value out of range: 14:22:42[.1000001].");
    } catch (...) {
        FAIL();
    }

    // Valid cases
    EXPECT_EQ(80052000000, Time::fromTime(22, 14, 12).micros);
    EXPECT_EQ(58991000024, Time::fromTime(16, 23, 11, 24).micros);
}

TEST(TimeTests, FromCStringValidation) {
    // Invalid hour values
    VERIFY_TIME_PARSE_FAILURE("25:12:00",
        "Conversion exception: Error occurred during parsing time. Given: "
        "\"25:12:00\". Expected format: (hh:mm:ss[.zzzzzz]).");

    VERIFY_TIME_PARSE_FAILURE("24:00:00",
        "Conversion exception: Error occurred during parsing time. Given: "
        "\"24:00:00\". Expected format: (hh:mm:ss[.zzzzzz]).");

    // Valid cases
    EXPECT_EQ(83531000000, Time::fromCString("23:12:11", strlen("23:12:11")).micros);
    EXPECT_EQ(46792122311, Time::fromCString("12:59:52.122311", strlen("12:59:52.122311")).micros);
    EXPECT_EQ(11561200, Time::fromCString("00:00:11.5612", strlen("00:00:11.5612")).micros);
    EXPECT_EQ(11561200, Time::fromCString(" 00:00:11.5612", strlen(" 00:00:11.5612")).micros);
}

TEST(TimeTests, ConvertToComponents) {
    dtime_t input_time{46792122311};
    int32_t hr = 0, mn = 0, sc = 0, us = 0;
    Time::convert(input_time, hr, mn, sc, us);

    EXPECT_EQ(12, hr);
    EXPECT_EQ(59, mn);
    EXPECT_EQ(52, sc);
    EXPECT_EQ(122311, us);
}

TEST(TimeTests, ToStringFormat) {
    EXPECT_EQ("21:59:00.5621", Time::toString(dtime_t(79140562100)));
    EXPECT_EQ("13:22:59",        Time::toString(dtime_t(48179000000)));
    EXPECT_EQ("00:00:00",       Time::toString(dtime_t(0)));
}

