    // Unpack single element from 32-bit to 64-bit array
    template<uint8_t DELTA, uint8_t BIT_POS>
    void unpack_single_dword_to_qword(const uint32_t* in, uint64_t* out) {
        uint64_t current_val = static_cast<uint64_t>(*in);
