            uint8_t first_part = extract_bits(current_val, bit_offset, 32 - bit_offset);
            ++in;
            uint64_t next_val = static_cast<uint64_t>(*in);
            uint8_t second_part = extract_bits(next_val, 0, DELTA - (32 - bit_offset));
            *out = first_part | (static_cast<uint64_t>(second_part) << (32 - bit_offset));
        } else {
            uint8_t first_part = extract_bits(current_val, bit_offset, 32 - bit_offset);
            ++in;
            uint64_t next_val = static_cast<uint64_t>(*in);
            uint8_t second_part = extract_bits(next_val, 0, 64 - bit_offset);
            *out = first_part | (static_cast<uint64_t>(second_part) << (32 - bit_offset));
            if (DELTA > 64 - bit_offset) {
                ++in;
                uint8_t third_part = extract_bits(*in, 0, DELTA - (64 - bit_offset));
                *out |= static_cast<uint64_t>(third_part) << (64 - bit_offset);
