    // Pack single element into byte array
    template<uint8_t DELTA, uint8_t BIT_POS>
    void pack_single_byte(const uint8_t value, uint8_t* out) {
        uint8_t bit_offset = BIT_POS % 8;
        uint8_t mask = (DELTA == 8) ? 0xFF : ((1U << DELTA) - 1);

        if (bit_offset + DELTA <= 8) {
            insert_bits(*out, value, bit_offset, DELTA);
        } else {
            uint8_t first_mask = (8 - bit_offset) == 8 ? 0xFF : ((1U << (8 - bit_offset)) - 1);
            *out |= (value & first_mask) << bit_offset;
            ++out;
            uint8_t remaining = DELTA - (8 - bit_offset);
            uint8_t second_mask = (remaining == 8) ? 0xFF : ((1U << remaining) - 1);
            *out = (value >> (8 - bit_offset)) & second_mask;
        }
    }

