        }

        static void Unpack(const uint32_t* in, uint64_t* out) {
            unpack_single_dword_to_qword<DELTA, DELTA * INDEX>(in, out + INDEX);
            Unroller32<DELTA, INDEX + 1>::Unpack(in, out);
        }

        static void Pack(const uint32_t* in, uint32_t* out) {
            pack_single_dword<DELTA, DELTA * INDEX>(in[INDEX], out);
            Unroller32<DELTA, INDEX + 1>::Pack(in, out);
        }

        static void Pack(const uint64_t* in, uint32_t* out) {
            pack_single_qword_to_dword<DELTA, DELTA * INDEX>(in[INDEX], out);
            Unroller32<DELTA, INDEX + 1>::Pack(in, out);
        }

        static void PackNoMask(const uint32_t* in, uint32_t* out) {
            uint8_t bit_pos = DELTA * INDEX;
            uint8_t bit_offset = bit_pos % 32;

            if (bit_offset + DELTA <= 32) {
                insert_bits(*out, in[INDEX], bit_offset, DELTA);
            } else {
                *out |= in[INDEX] << bit_offset;
                ++out;
                *out = in[INDEX] >> (32 - bit_offset);
