                *out = static_cast<uint32_t>(in[INDEX] >> (32 - bit_offset));
            } else {
                *out |= static_cast<uint32_t>(in[INDEX]) << bit_offset;
                ++out;
                *out = static_cast<uint32_t>(in[INDEX] >> (32 - bit_offset));
                ++out;
                if (DELTA > 64 - bit_offset) {
