using namespace AscendC;
using namespace CamMoeDispatchNormalImpl;

// Tiling identifiers for dispatch modes
constexpr uint32_t NO_QUANT_TILING_ID = 10000;
constexpr uint32_t QUANT_TILING_ID    = 10002;

extern "C" __global__ __aicore__ void cam_moe_dispatch_normal(
    GM_ADDR x,
    GM_ADDR expertIds,
    GM_ADDR send_offset,
    GM_ADDR send_token_idx,
    GM_ADDR recv_offset,
    GM_ADDR recv_count,
    GM_ADDR expert_global_offset,
    GM_ADDR srcrank_in_expert_offset,
    GM_ADDR r_in_srcrank_offset,
    GM_ADDR expandXOut,
    GM_ADDR dynamicScalesOut,
    GM_ADDR assist_info_for_combine,
    GM_ADDR waitRecvCostStatsOut,
    GM_ADDR workspaceGM,
    GM_ADDR tilingGM)
{
    // Register default tiling data structure
    REGISTER_TILING_DEFAULT(CamMoeDispatchNormalTilingData);

    TPipe pipe;

    // Determine tiling mode based on key
    uint32_t tilingKey = GET_TILING_KEY();

#if (ORIG_DTYPE_RECV_X == DT_BF16 || ORIG_DTYPE_RECV_X == DT_FLOAT16)
    if (tilingKey == NO_QUANT_TILING_ID) {
        CamMoeDispatchNormalTilingData tilingData;
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, &tilingData, tilingGM);

        using OpType = CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, false, false, false>;
        OpType op;
        op.Init(x, expertIds, send_offset, send_token_idx, recv_offset, recv_count,
                expert_global_offset, srcrank_in_expert_offset, r_in_srcrank_offset,
                expandXOut, dynamicScalesOut, assist_info_for_combine,
                waitRecvCostStatsOut, workspaceGM, &pipe, &tilingData);
        op.Process();
    }
#elif (ORIG_DTYPE_RECV_X == DT_INT8)
    if (tilingKey == QUANT_TILING_ID) {
        CamMoeDispatchNormalTilingData tilingData;
        GET_TILING_DATA_WITH_STRUCT(CamMoeDispatchNormalTilingData, &tilingData, tilingGM);

        using OpType = CamMoeDispatchNormal<DTYPE_X, DTYPE_RECV_X, true, false, false>;
        OpType op;
        op.Init(x, expertIds, send_offset, send_token_idx, recv_offset, recv_count,
                expert_global_offset, srcrank_in_expert_offset, r_in_srcrank_offset,
                expandXOut, dynamicScalesOut, assist_info_for_combine,
                waitRecvCostStatsOut, workspaceGM, &pipe, &tilingData);
        op.Process();
    }
#endif

    // Explicit return at end (optional, but clarifies control flow)
    return;
}

