TEST_CASE_MAP("load_factor", int, int) {
    auto m = map_t();

    // Check initial load factor is zero
    REQUIRE(static_cast<double>(m.load_factor()) == doctest::Approx(0.0));

    // Insert elements and verify load factor behavior
    for (int key = 0; key < 10000; ++key) {
        m.emplace(key, key);

