// Helper lambda to run expression tests with expected string output
void evaluate_and_check(SMTParser::ParserPtr& parser,
                        const std::string& expr,
                        const std::string& expected,
                        const std::string& description) {
    std::cout << "Expression: " << expr << std::endl;
    auto res = parser->mkExpr(expr);
    assert(res && "Failed to parse expression");
    std::string actual = parser->toString(res);
    std::cout << "  Result: " << actual << std::endl;
    assert(actual == expected && description + " result mismatch");
    std::cout << std::endl;
}

// Helper lambda to run boolean evaluation tests
void evaluate_bool_and_check(SMTParser::ParserPtr& parser,
                             const std::string& expr,
                             bool expected,
                             const std::string& description) {
    std::cout << "Expression: " << expr << std::endl;
    auto res = parser->mkExpr(expr);
    assert(res && "Failed to parse expression");
    std::cout << "  Result: " << parser->toString(res) << std::endl;
    assert(res->isTrue() == expected && description + " comparison failed");
    std::cout << std::endl;
}

// Test integer arithmetic operations
void test_integer_ops(SMTParser::ParserPtr& parser) {
    std::cout << "=== Testing Integer Arithmetic ===" << std::endl;

    // List of test cases: input expression and expected output string
    std::vector<std::pair<std::string, std::string>> tests = {
        {"42", "42"},
        {"-15", "-15"},
        {"(+ 10 20)", "30"},
        {"(- 50 30)", "20"},
        {"(* 6 7)", "42"},
        {"(div 20 5)", "4"},
        {"(mod 17 5)", "2"},
        {"(abs -42)", "42"}
    };

    size_t idx = 0;
    while (idx < tests.size()) {
        const auto& [input, expect] = tests[idx];
        evaluate_and_check(parser, input, expect, "integer arithmetic");
        ++idx;
    }
}

// Test real number arithmetic operations
void test_real_ops(SMTParser::ParserPtr& parser) {
    std::cout << "=== Testing Real Number Arithmetic ===" << std::endl;

    std::vector<std::pair<std::string, std::string>> tests = {
        {"3.14159", "3.14159"},
        {"-2.71828", "-2.71828"},
        {"(+ 3.5 2.7)", "6.2"},
        {"(- 10.5 4.2)", "6.3"},
        {"(* 2.5 4.0)", "10"},
        {"(/ 15.0 3.0)", "5"},
        {"(^ 2.0 3.0)", "8"},
        {"(sqrt 16.0)", "4"},
        {"(abs -9.81)", "9.81"}
    };

    size_t i = 0;
    while (i < tests.size()) {
        const auto& [expr, expected] = tests[i];
        evaluate_and_check(parser, expr, expected, "real arithmetic");
        ++i;
    }
}

// Test comparison operations
void test_comparison_ops(SMTParser::ParserPtr& parser) {
    std::cout << "=== Testing Arithmetic Comparisons ===" << std::endl;

    std::vector<std::pair<std::string, bool>> checks = {
        {"(< 5 10)", true},
        {"(<= 7 7)", true},
        {"(> 15 5)", true},
        {"(>= 12 12)", true},
        {"(= 42 42)", true},
        {"(distinct 3 5 7)", true}
    };

    size_t j = 0;
    while (j < checks.size()) {
        const auto& [expr, expected] = checks[j];
        evaluate_bool_and_check(parser, expr, expected, "comparison");
        ++j;
    }
}

// Test precision handling in floating point evaluation
void test_precision_handling(SMTParser::ParserPtr& parser) {
    std::cout << "=== Testing Precision ===" << std::endl;

    // Default precision (128 bits)
    std::cout << "=== Default Precision (128 bits) ===" << std::endl;
    auto r1 = parser->mkExpr("(+ 3.5 2.7)");
    auto r2 = parser->mkExpr("(- 10.5 4.2)");
    assert(r1 && r2);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(r1) << std::endl;
    assert(parser->toString(r1) == "6.2");
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(r2) << std::endl;
    assert(parser->toString(r2) == "6.3");

    // Switch to higher precision (256 bits)
    parser->setEvaluatePrecision(256);
    std::cout << "\n=== Higher Precision (256 bits) ===" << std::endl;
    auto r3 = parser->mkExpr("(+ 3.5 2.7)");
    auto r4 = parser->mkExpr("(- 10.5 4.2)");
    assert(r3 && r4);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(r3) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(r4) << std::endl;
    assert(parser->toString(r3) == "6.2" && parser->toString(r4) == "6.3");

    // Disable floating-point mode (use exact rational arithmetic)
    parser->setEvaluateUseFloating(false);
    std::cout << "\n=== Disable Floating Point Mode ===" << std::endl;
    auto r5 = parser->mkExpr("(+ 3.5 2.7)");
    auto r6 = parser->mkExpr("(- 10.5 4.2)");
    assert(r5 && r6);
    std::cout << "Expression: (+ 3.5 2.7)" << std::endl;
    std::cout << "  Result: " << parser->toString(r5) << std::endl;
    std::cout << "Expression: (- 10.5 4.2)" << std::endl;
    std::cout << "  Result: " << parser->toString(r6) << std::endl;
    assert(parser->toString(r5) == "6.2" && parser->toString(r6) == "6.3");
}

int main() {
    std::cout << "======= Arithmetic Operations Test =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    test_integer_ops(parser);
    test_real_ops(parser);
    test_comparison_ops(parser);
    test_precision_handling(parser);

    return 0;
}

