FAnimBlueprintCompilerHandler_PropertyAccess::FAnimBlueprintCompilerHandler_PropertyAccess(IAnimBlueprintCompilerCreationContext& CreationCtx)
{
	CreationCtx.OnStartCompilingClass().AddRaw(this, &FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationStart);
	CreationCtx.OnFinishCompilingClass().AddRaw(this, &FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationEnd);
}

int32 FAnimBlueprintCompilerHandler_PropertyAccess::AddCopy(TArrayView<FString> SourcePath, TArrayView<FString> DestPath, EPropertyAccessBatchType BatchType, UObject* TargetObject)
{
	return PropertyAccessLibraryCompiler.AddCopy(SourcePath, DestPath, BatchType, TargetObject);
}

void FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationStart(const UClass* ClassRef, IAnimBlueprintCompilationBracketContext& CompilationBracket, IAnimBlueprintGeneratedClassCompiledData& CompiledResult)
{
	PropertyAccessLibraryCompiler.Configure(ClassRef, &CompiledResult.GetPropertyAccessLibrary());
	PropertyAccessLibraryCompiler.InitiateCompilation(ClassRef);
}

void FAnimBlueprintCompilerHandler_PropertyAccess::HandleClassCompilationEnd(const UClass* ClassRef, IAnimBlueprintCompilationBracketContext& CompilationBracket, IAnimBlueprintGeneratedClassCompiledData& CompiledResult)
{
	OnPreLibraryCompiledDelegate.Broadcast();

	bool bCompilationSucceeded = PropertyAccessLibraryCompiler.CompleteCompilation();
	if (!bCompilationSucceeded)
	{
		PropertyAccessLibraryCompiler.EnumerateErrors([&CompilationBracket](const FText& ErrorMsg, UObject* ContextObj)
		{
			// Log property access issues as warnings
			if (ContextObj)
			{
				CompilationBracket.GetMessageLog().Warning(*ErrorMsg.ToString(), ContextObj);
			}
			else
			{
				CompilationBracket.GetMessageLog().Warning(*ErrorMsg.ToString());
			}
		});
	}

	OnPostLibraryCompiledDelegate.Broadcast(CompiledResult);
}

int32 FAnimBlueprintCompilerHandler_PropertyAccess::MapCopyIndex(int32 OriginalIndex) const
{
	return PropertyAccessLibraryCompiler.MapCopyIndex(OriginalIndex);
}

