namespace Karm::Fs {
export struct FsTab {
    enum struct Type {
        AUTO,
        BOOTFS,
    };
    Ref::Url device;
    Ref::Path path;
    Type type;
    Serde::Object options;
};

// Overloaded mount function that processes a table of filesystem entries
export [[clang::coro_wrapper]]
Async::Task<Rc<Node>> mountAsync(Vec<FsTab> tab) {
    for (auto& entry : tab) {
        switch (entry.type) {
            case FsTab::Type::BOOTFS:
                co_await mountBootfsAsync(entry.device);
                break;
            case FsTab::Type::AUTO:
                // For AUTO, default to bootfs for now
                co_await mountBootfsAsync(entry.device);
                break;
        }
    }
    // Return root node after mounting all entries
    co_return Rc<Node>{};
}

// Convenience overload for single URL mounting
export [[clang::coro_wrapper]]
Async::Task<Rc<Node>> mountAsync(Ref::Url url) {
    return mountBootfsAsync(url);
}
} // namespace Karm::Fs

