#include <sol/sol.hpp>

#include <iostream>
#include <functional>
#include <vector>

int main() {
    std::cout << "=== capturing Lua functions with arguments ==="
              << std::endl;

    sol::state lua;
    lua.open_libraries(sol::lib::base);

    std::function<void()> stored_callback;

    auto capture_lua_call = [&stored_callback](sol::function func, 
                                                sol::variadic_args args) {
        // Convert variadic arguments to a vector of sol::object
        std::vector<sol::object> captured_args(args.begin(), args.end());

        // Store a lambda that will invoke the function with the captured arguments
        stored_callback = [func, args = std::move(captured_args)]() mutable {
            func(sol::as_args(args));
        };
    };

    lua.set_function("capture_lua_call", capture_lua_call);

    lua.script(R"(
function greet_user(username)
    print("Hello, " .. username .. "!")
end

capture_lua_call(greet_user, "Alice")
)");
    stored_callback();

    lua.script(R"(
function display_info(count, item_name)
    print(count, "units of", item_name)
end

capture_lua_call(display_info, 15, "oranges")
)");
    stored_callback();

    std::cout << std::endl;

    return 0;
}

