    INIT_ENUM_ARRAY(next_x86_insn_avx_cc, X86_AVX_CC_, NLT);
    INIT_ENUM_ARRAY(next_x86_insn_avx_cc, X86_AVX_CC_, NLE);
    INIT_ENUM_ARRAY(next_x86_insn_avx_cc, X86_AVX_CC_, ORD);
    INIT_ENUM_ARRAY(next_x86_insn_avx_cc, X86_AVX_CC_, EQ_UQ);
    INIT_ENUM_ARRAY(next_x86_insn_avx_cc, X86_AVX_CC_, NGE);
    INIT_ENUM_ARRAY(next_x86_insn_avx_cc, X86_AVX_CC_, NGT);
