LayoutController::LayoutController() {
}

void LayoutController::init(PaneLayout* layout, ClientManager* manager, domain::Window* win) {
    m_layout = layout;

    // Register handler for new client addition
    manager->onClientAdded([=](KakouneClient* new_client) {
        // When UI options change for this client, trigger relayout
        new_client->onUIOptionsChanged([=](const domain::UIOptions&) {
            m_layout->relayout();
        });
        // Initial layout update after adding client
        m_layout->relayout();
    });

    // Register handler for client removal
    manager->onClientRemoved([=](KakouneClient*) {
        m_layout->relayout();
    });

    // Handle window resize events
    win->onResize([this, win](int w, int h) {
        // Update bounds to cover full window area
        m_layout->setBounds(domain::Rectangle{0.0f, 0.0f, static_cast<float>(w), static_cast<float>(h)});
        // Trigger layout recalculation
        m_layout->relayout();
        // Request redraw
        win->requestRedraw();
    });
}

