void OreRecipies::_init()
{
    // Initialize the recipe mapping array
    map = new vector<Object*>[MAX_ORE_RECIPES];

    // Populate the mapping with ore block to ingot conversions
    int idx = 0;
    ADD_OBJECT(map[idx], Tile::goldBlock);
    ADD_OBJECT(map[idx++], new ItemInstance(Item::goldIngot, 9));

    ADD_OBJECT(map[idx], Tile::ironBlock);
    ADD_OBJECT(map[idx++], new ItemInstance(Item::ironIngot, 9));

    ADD_OBJECT(map[idx], Tile::diamondBlock);
    ADD_OBJECT(map[idx++], new ItemInstance(Item::diamond, 9));

    ADD_OBJECT(map[idx], Tile::emeraldBlock);
    ADD_OBJECT(map[idx++], new ItemInstance(Item::emerald, 9));

    ADD_OBJECT(map[idx], Tile::lapisBlock);
    ADD_OBJECT(map[idx++], new ItemInstance(Item::dye_powder, 9, DyePowderItem::BLUE));
}

void OreRecipies::addRecipes(Recipes* r)
{
    // Iterate through all registered ore recipes
    for (int counter = 0; counter < MAX_ORE_RECIPES; ++counter)
    {
        // Extract source tile and target item instance
        Tile* inputBlock = static_cast<Tile*>(map[counter][0]->tile);
        ItemInstance* outputItem = static_cast<ItemInstance*>(map[counter][1]->iteminstance);

        // Add crafting recipe: Block -> 9 Ingots (3x3 shape)
        r->addShapedRecipy(
            new ItemInstance(inputBlock),
            L"sssczg",
            L"###", 
            L"###", 
            L"###", 
            L'#', outputItem,
            L'D'
        );

        // Add smelting/crafting recipe: 1 Ingot -> Block (single item input)
        r->addShapedRecipy(
            outputItem,
            L"sctg",
            L"#", 
            L'#', inputBlock,
            L'D'
        );
    }
}

