#include "yaml-cpp/node/node.h"
#include "nodebuilder.h"
#include "nodeevents.h"

namespace YAML {

// Create a deep copy of the given node using event-based construction
Node Clone(const Node& sourceNode) {
  // Generate events from the source node
  NodeEvents eventGenerator(sourceNode);

  // Construct a new node using the builder pattern
  NodeBuilder nodeConstructor;

  // Emit all events to rebuild the node structure
  eventGenerator.Emit(nodeConstructor);

  // Return the root of the newly constructed node
  return nodeConstructor.Root();
}

}

