/// @test
/// Check creation of a matrix
/// @requirements(SEN-1059)
TEST(Matrix, Creation)
{
  Mat3f matrix {};
  matrix.setElement(1, 2, 4.66f);
  EXPECT_FLOAT_EQ(4.66f, matrix.getElement(1, 2));
  EXPECT_FLOAT_EQ(0.0f, matrix.getElement(0, 0));
}

/// @test
/// Check initialization of a matrix
/// @requirements(SEN-1059)
TEST(Matrix, InitializerList)
{
  Mat3f matrix {{3, 5, 4}, {2, 2, 2}, {1, 3, 4}};
  EXPECT_FLOAT_EQ(3.0f, matrix.getElement(0, 0));
  EXPECT_FLOAT_EQ(5.0f, matrix.getElement(0, 1));
  EXPECT_FLOAT_EQ(4.0f, matrix.getElement(0, 2));
  EXPECT_FLOAT_EQ(2.0f, matrix.getElement(1, 0));
  EXPECT_FLOAT_EQ(2.0f, matrix.getElement(1, 1));
  EXPECT_FLOAT_EQ(2.0f, matrix.getElement(1, 2));
  EXPECT_FLOAT_EQ(1.0f, matrix.getElement(2, 0));
  EXPECT_FLOAT_EQ(3.0f, matrix.getElement(2, 1));
  EXPECT_FLOAT_EQ(4.0f, matrix.getElement(2, 2));
}

/// @test
/// Check the copy of a matrix
/// @requirements(SEN-1059)
TEST(Matrix, copyMatrix)
{
  Mat3f source {{3, 5, 4}, {2, 2, 2}, {1, 3, 4}};
  Mat3f destination = source;
  EXPECT_FLOAT_EQ(2.0f, destination.getElement(1, 1));
}

/// @test
/// Check the correct creation of an identity matrix
/// @requirements(SEN-1059)
TEST(Matrix, identity)
{
  auto generated = Mat3f::makeIdentity();
  Mat3f expected {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};

  u32 row = 0U;
  while (row < 3U)
  {
    u32 col = 0U;
    while (col < 3U)
    {
      EXPECT_EQ(expected.getElement(row, col), generated.getElement(row, col));
      ++col;
    }
    ++row;
  }
}

/// @test
/// Check transpose function for a matrix
/// @requirements(SEN-1059)
TEST(Matrix, transpose)
{
  Mat3f input {{2, 3, 4}, {4, 5, 6}, {88, 6, 6}};
  Mat3f expected {{2, 4, 88}, {3, 5, 6}, {4, 6, 6}};
  Mat3f output {};

  output.transpose(input);

  u32 i = 0U;
  do
  {
    u32 j = 0U;
    do
    {
      EXPECT_EQ(expected.getElement(i, j), output.getElement(i, j));
      ++j;
    } while (j < 3U);
    ++i;
  } while (i < 3U);

  // Transpose again to recover original
  output.transpose(output);
  i = 0U;
  do
  {
    u32 j = 0U;
    do
    {
      EXPECT_EQ(input.getElement(i, j), output.getElement(i, j));
      ++j;
    } while (j < 3U);
    ++i;
  } while (i < 3U);
}

/// @test
/// Check multiplication function for two given matrices storing the result in the current instance
/// @requirements(SEN-1059)
TEST(Matrix, mult)
{
  Mat3f result {};
  Mat3f left {{1, 2, 3}, {3, 2, 1}, {1, 2, 3}};
  Mat3f right {{4, 5, 6}, {6, 5, 4}, {4, 6, 5}};
  Mat3f target {{28, 33, 29}, {28, 31, 31}, {28, 33, 29}};

  result.mult(left, right);

  for (u32 idx = 0U; idx < 9U; ++idx)
  {
    u32 r = idx / 3U;
    u32 c = idx % 3U;
    EXPECT_EQ(target.getElement(r, c), result.getElement(r, c));
  }
}

/// @test
/// Check pre-multiplication function for a given matrix to the current instance
/// @requirements(SEN-1059)
TEST(Matrix, preMult)
{
  Mat3f accumulator {{4, 5, 6}, {6, 5, 4}, {4, 6, 5}};
  Mat3f factor {{1, 2, 3}, {3, 2, 1}, {1, 2, 3}};
  Mat3f expected {{28, 33, 29}, {28, 31, 31}, {28, 33, 29}};

  accumulator.preMult(factor);

  u32 k = 0U;
  while (k < 9U)
  {
    u32 row = k / 3U;
    u32 col = k % 3U;
    EXPECT_EQ(expected.getElement(row, col), accumulator.getElement(row, col));
    ++k;
  }
}

/// @test
/// Check post-multiplication function for a given matrix to the current instance
/// @requirements(SEN-1059)
TEST(Matrix, postMult)
{
  Mat3f base {{1, 2, 3}, {3, 2, 1}, {1, 2, 3}};
  Mat3f multiplier {{4, 5, 6}, {6, 5, 4}, {4, 6, 5}};
  Mat3f expected {{28, 33, 29}, {28, 31, 31}, {28, 33, 29}};

  base.postMult(multiplier);

  for (u32 pos = 0U; pos < 9U; ++pos)
  {
    u32 r = pos / 3U;
    u32 c = pos % 3U;
    EXPECT_EQ(expected.getElement(r, c), base.getElement(r, c));
  }
}

/// @test
/// Check post-multiplication function for a given matrix and store the result in a vector
/// @requirements(SEN-1059)
TEST(Matrix, postMultVec)
{
  Mat3f matrix {{1, 2, 3}, {3, 2, 1}, {1, 2, 3}};
  Vec3f vector {4.6f, 55.0f, 6.7f};
  Vec3f expected {134.7f, 130.5f, 134.7f};

  Vec3f outcome = matrix.postMult(vector);
  EXPECT_EQ(expected, outcome);
}

/// @test
/// Check pre-multiplication function for a given matrix and store the result in a vector
/// @requirements(SEN-1059)
TEST(Matrix, preMultVec)
{
  Mat3f matrix {{1, 2, 3}, {3, 2, 1}, {1, 2, 3}};
  Vec3f vector {4.6f, 55.0f, 6.7f};
  Vec3f expected {176.3f, 132.6f, 88.9f};

  Vec3f computed = matrix.preMult(vector);
  EXPECT_FLOAT_EQ(expected.getX(), computed.getX());
  EXPECT_FLOAT_EQ(expected.getY(), computed.getY());
  EXPECT_FLOAT_EQ(expected.getZ(), computed.getZ());
}
