// Helper class for layout construction
class LayoutBuilder {
public:
  explicit LayoutBuilder(MLIRContext* ctx) : context(ctx) {}

  BlockedEncodingAttr createBlocked(ArrayRef<unsigned> sp, ArrayRef<unsigned> tpb,
                                    ArrayRef<unsigned> wpb, ArrayRef<unsigned> cpg,
                                    ArrayRef<unsigned> csp, ArrayRef<unsigned> ord,
                                    ArrayRef<unsigned> cord) {
    return BlockedEncodingAttr::get(
        context, sp, tpb, wpb, ord, CTALayoutAttr::get(context, cpg, csp, cord));
  }

  NvidiaMmaEncodingAttr createMMA(unsigned maj, unsigned min, ArrayRef<unsigned> shape,
                                  ArrayRef<unsigned> wbp, ArrayRef<unsigned> cpg,
                                  ArrayRef<unsigned> csp, ArrayRef<unsigned> cord) {
    return NvidiaMmaEncodingAttr::get(
        context, maj, min, wbp, CTALayoutAttr::get(context, cpg, csp, cord), shape);
  }

  DotOperandEncodingAttr createDotMMAv2(int operand, int width, ArrayRef<unsigned> warps,
                                        ArrayRef<unsigned> order) {
    auto mmaLayout = createMMA(2, 0, {16, 8}, warps, {1, 1}, {1, 1}, order);
    return DotOperandEncodingAttr::get(context, operand, mmaLayout, /*kWidth=*/width);
  }

  AMDMfmaEncodingAttr createMFMA(ArrayRef<unsigned> warps, unsigned mDim,
                                 unsigned nDim, bool isTransposed) {
    SmallVector<unsigned> cpg(warps.size(), 1u);
    SmallVector<unsigned> csp(warps.size(), 1u);
    SmallVector<unsigned> cord(warps.size());
    std::iota(cord.begin(), cord.end(), 0);
    return AMDMfmaEncodingAttr::get(
        context, /*versionMajor=*/2, /*versionMinor=*/0, warps, mDim, nDim,
        isTransposed, CTALayoutAttr::get(context, cpg, csp, cord));
  }

  DotOperandEncodingAttr createMFMAdot(AMDMfmaEncodingAttr mfma, unsigned opIdx,
                                       unsigned kWidth) {
    return DotOperandEncodingAttr::get(context, opIdx, mfma, kWidth);
  }

  AMDWmmaEncodingAttr createWMMA(ArrayRef<unsigned> warps) {
    SmallVector<unsigned> cpg(warps.size(), 1u);
    SmallVector<unsigned> csp(warps.size(), 1u);
    SmallVector<unsigned> cord(warps.size());
    std::iota(cord.begin(), cord.end(), 0);
    return AMDWmmaEncodingAttr::get(
        context, /*version=*/1, warps,
        CTALayoutAttr::get(context, cpg, csp, cord));
  }

  SliceEncodingAttr createSlice(Attribute parent, int dim) {
    return SliceEncodingAttr::get(context, dim, parent);
  }

  SharedEncodingAttr createShared(unsigned vec, unsigned perPhase, unsigned maxPhase,
                                  bool hasLeadingOffset, ArrayRef<unsigned> cpg,
                                  ArrayRef<unsigned> csp, ArrayRef<unsigned> ord,
                                  ArrayRef<unsigned> cord) {
    return SharedEncodingAttr::get(context, vec, perPhase, maxPhase, ord,
                                   CTALayoutAttr::get(context, cpg, csp, cord),
                                   hasLeadingOffset);
  }

  StringAttr makeString(StringRef str) { return StringAttr::get(context, str); }

private:
  MLIRContext* context;
};

class LinearLayoutConversionsTest : public ::testing::Test {
public:
  void SetUp() override { 
    ctx.getOrLoadDialect<TritonGPUDialect>(); 
    builder = std::make_unique<LayoutBuilder>(&ctx);
  }

  ~LinearLayoutConversionsTest() override = default;

protected:
  MLIRContext ctx;
  std::unique_ptr<LayoutBuilder> builder;

  // Convenience wrappers using the builder
  BlockedEncodingAttr blocked(ArrayRef<unsigned> spt, ArrayRef<unsigned> tpw,
                              ArrayRef<unsigned> wpb, ArrayRef<unsigned> cpg,
                              ArrayRef<unsigned> cSplit, ArrayRef<unsigned> ord,
                              ArrayRef<unsigned> cOrd) {
    return builder->createBlocked(spt, tpw, wpb, cpg, cSplit, ord, cOrd);
  }

  NvidiaMmaEncodingAttr mma(unsigned versionMaj, unsigned versionMin,
                            ArrayRef<unsigned> instrShape,
                            ArrayRef<unsigned> wbp, ArrayRef<unsigned> cpg,
                            ArrayRef<unsigned> cSplit,
                            ArrayRef<unsigned> cOrd) {
    return builder->createMMA(versionMaj, versionMin, instrShape, wbp, cpg, cSplit, cOrd);
  }

  DotOperandEncodingAttr dotMMAv2(int idx, int kWidth, ArrayRef<unsigned> warps,
                                  ArrayRef<unsigned> order) {
    return builder->createDotMMAv2(idx, kWidth, warps, order);
  }

  AMDMfmaEncodingAttr mfma(ArrayRef<unsigned> warps, unsigned mDim,
                           unsigned nDim, bool isTransposed) {
    return builder->createMFMA(warps, mDim, nDim, isTransposed);
  }

  DotOperandEncodingAttr mfmaDotOp(AMDMfmaEncodingAttr mfma, unsigned opIdx,
                                   unsigned kWidth) {
    return builder->createMFMAdot(mfma, opIdx, kWidth);
  }

  AMDWmmaEncodingAttr wmma(ArrayRef<unsigned> warps) {
    return builder->createWMMA(warps);
  }

  SliceEncodingAttr slice(Attribute parent, int dim) {
    return builder->createSlice(parent, dim);
  }

  SharedEncodingAttr shared(unsigned vec, unsigned perPhase, unsigned maxPhase,
                            bool hasLeadingOffset, ArrayRef<unsigned> cpg,
                            ArrayRef<unsigned> cSplit, ArrayRef<unsigned> ord,
                            ArrayRef<unsigned> cOrd) {
    return builder->createShared(vec, perPhase, maxPhase, hasLeadingOffset, cpg, cSplit, ord, cOrd);
  }

  StringAttr S(StringRef str) { return builder->makeString(str); }
};

