#include "m3_api_tracer.h"
#include "m3_env.h"
#include "m3_exception.h"

#if defined(d_m3HasTracer)

static FILE* tracer_file = nullptr;

// Helper to format and write trace lines
static void WriteTraceLine(const char* prefix, uint32_t id, const char* fmt, ...) {
    if (!tracer_file) return;
    fprintf(tracer_file, "%s;%u;", prefix, id);
    va_list args;
    va_start(args, fmt);
    vfprintf(tracer_file, fmt, args);
    va_end(args);
    fputc('\n', tracer_file);
}

// Execution tracing functions
m3ApiRawFunction(m3_env_log_execution) {
    m3ApiGetArg(uint32_t, execution_id)
    WriteTraceLine("exec", execution_id, "%d", execution_id);
    m3ApiSuccess();
}

m3ApiRawFunction(m3_env_log_exec_enter) {
    m3ApiGetArg(uint32_t, execution_id)
    m3ApiGetArg(uint32_t, function_index)
    WriteTraceLine("enter", execution_id, "%d", function_index);
    m3ApiSuccess();
}

m3ApiRawFunction(m3_env_log_exec_exit) {
    m3ApiGetArg(uint32_t, execution_id)
    m3ApiGetArg(uint32_t, function_index)
    WriteTraceLine("exit", execution_id, "%d", function_index);
    m3ApiSuccess();
}

m3ApiRawFunction(m3_env_log_exec_loop) {
    m3ApiGetArg(uint32_t, execution_id)
    WriteTraceLine("loop", execution_id, "%d", execution_id);
    m3ApiSuccess();
}

// Pointer load/store tracing
m3ApiRawFunction(m3_env_load_ptr) {
    m3ApiReturnType(uint32_t)
    m3ApiGetArg(uint32_t, execution_id)
    m3ApiGetArg(uint32_t, alignment)
    m3ApiGetArg(uint32_t, offset)
    m3ApiGetArg(uint32_t, address)
    WriteTraceLine("load ptr", execution_id, "%d;%d;%d", alignment, offset, address);
    m3ApiReturn(address);
}

m3ApiRawFunction(m3_env_store_ptr) {
    m3ApiReturnType(uint32_t)
    m3ApiGetArg(uint32_t, execution_id)
    m3ApiGetArg(uint32_t, alignment)
    m3ApiGetArg(uint32_t, offset)
    m3ApiGetArg(uint32_t, address)
    WriteTraceLine("store ptr", execution_id, "%d;%d;%d", alignment, offset, address);
    m3ApiReturn(address);
}

// Generic value tracing macros restructured as inline functions
#define DEFINE_VALUE_TRACER(FUNC_NAME, PREFIX, TYPE, FMT_SPEC) \
m3ApiRawFunction(m3_env_##FUNC_NAME) { \
    m3ApiReturnType(TYPE) \
    m3ApiGetArg(uint32_t, execution_id) \
    m3ApiGetArg(TYPE, value) \
    WriteTraceLine(PREFIX, execution_id, FMT_SPEC, value); \
    m3ApiReturn(value); \
}

DEFINE_VALUE_TRACER(load_val_i32, "load i32", int32_t, "%" PRIi32)
DEFINE_VALUE_TRACER(store_val_i32, "store i32", int32_t, "%" PRIi32)
DEFINE_VALUE_TRACER(load_val_i64, "load i64", int64_t, "%" PRIi64)
DEFINE_VALUE_TRACER(store_val_i64, "store i64", int64_t, "%" PRIi64)
DEFINE_VALUE_TRACER(load_val_f32, "load f32", float, "%" PRIf32)
DEFINE_VALUE_TRACER(store_val_f32, "store f32", float, "%" PRIf32)
DEFINE_VALUE_TRACER(load_val_f64, "load f64", double, "%" PRIf64)
DEFINE_VALUE_TRACER(store_val_f64, "store f64", double, "%" PRIf64)

// Local variable access tracing
#define DEFINE_LOCAL_TRACER(GET_SET, TYPE, FMT_SPEC) \
m3ApiRawFunction(m3_env_##GET_SET##_##TYPE) { \
    m3ApiReturnType(TYPE) \
    m3ApiGetArg(uint32_t, execution_id) \
    m3ApiGetArg(uint32_t, local_index) \
    m3ApiGetArg(TYPE, value) \
    WriteTraceLine("get " #TYPE, execution_id, "%d;" FMT_SPEC, local_index, value); \
    m3ApiReturn(value); \
} \
m3ApiRawFunction(m3_env_set_##TYPE) { \
    m3ApiReturnType(TYPE) \
    m3ApiGetArg(uint32_t, execution_id) \
    m3ApiGetArg(uint32_t, local_index) \
    m3ApiGetArg(TYPE, value) \
    WriteTraceLine("set " #TYPE, execution_id, "%d;" FMT_SPEC, local_index, value); \
    m3ApiReturn(value); \
}

DEFINE_LOCAL_TRACER(get, i32, "%" PRIi32)
DEFINE_LOCAL_TRACER(set, i32, "%" PRIi32)
DEFINE_LOCAL_TRACER(get, i64, "%" PRIi64)
DEFINE_LOCAL_TRACER(set, i64, "%" PRIi64)
DEFINE_LOCAL_TRACER(get, f32, "%" PRIf32)
DEFINE_LOCAL_TRACER(set, f32, "%" PRIf32)
DEFINE_LOCAL_TRACER(get, f64, "%" PRIf64)
DEFINE_LOCAL_TRACER(set, f64, "%" PRIf64)

// Modified error suppression logic
static M3Result SuppressLookupFailure(M3Result result) {
    if (result == m3Err_none) {
        // Initialize trace file only once on success
        if (!tracer_file) {
            tracer_file = fopen("wasm3_trace.csv", "w");
        }
    } else if (result == m3Err_functionLookupFailed) {
        result = m3Err_none;  // Ignore missing functions silently
    }
    return result;
}

M3Result m3_LinkTracer(IM3Module module) {
    M3Result result = m3Err_none;
    const char* env_namespace = "env";

    // Link all tracer functions
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "log_execution",
                                               "v(i)", &m3_env_log_execution)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "log_exec_enter",
                                               "v(ii)", &m3_env_log_exec_enter)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "log_exec_exit",
                                               "v(ii)", &m3_env_log_exec_exit)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "log_exec_loop",
                                               "v(i)", &m3_env_log_exec_loop)));

    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "load_ptr",
                                               "i(iiii)", &m3_env_load_ptr)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "store_ptr",
                                               "i(iiii)", &m3_env_store_ptr)));

    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "load_val_i32",
                                               "i(ii)", &m3_env_load_val_i32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "load_val_i64",
                                               "I(iI)", &m3_env_load_val_i64)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "load_val_f32",
                                               "f(if)", &m3_env_load_val_f32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "load_val_f64",
                                               "F(iF)", &m3_env_load_val_f64)));

    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "store_val_i32",
                                               "i(ii)", &m3_env_store_val_i32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "store_val_i64",
                                               "I(iI)", &m3_env_store_val_i64)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "store_val_f32",
                                               "f(if)", &m3_env_store_val_f32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "store_val_f64",
                                               "F(iF)", &m3_env_store_val_f64)));

    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "get_i32",
                                               "i(iii)", &m3_env_get_i32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "get_i64",
                                               "I(iiI)", &m3_env_get_i64)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "get_f32",
                                               "f(iif)", &m3_env_get_f32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "get_f64",
                                               "F(iiF)", &m3_env_get_f64)));

    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "set_i32",
                                               "i(iii)", &m3_env_set_i32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "set_i64",
                                               "I(iiI)", &m3_env_set_i64)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "set_f32",
                                               "f(iif)", &m3_env_set_f32)));
    _(SuppressLookupFailure(m3_LinkRawFunction(module, env_namespace, "set_f64",
                                               "F(iiF)", &m3_env_set_f64)));

_catch:
    return result;
}

