/* Stub for calling setenv */
void
x_cgo_setenv(char **arg)
{
	_cgo_tsan_acquire();
	char *env_str = (char*)malloc(strlen(arg[0]) + strlen(arg[1]) + 2);
	if (env_str != NULL) {
		sprintf(env_str, "%s=%s", arg[0], arg[1]);
		putenv(env_str);
		// Note: putenv takes ownership of the string, so we don't free it
	}
	_cgo_tsan_release();
}
/* Stub for calling unsetenv */
void
x_cgo_unsetenv(char **arg)
{
	_cgo_tsan_acquire();
	// Alternative approach using putenv with empty value to unset
	char *env_str = (char*)malloc(strlen(arg[0]) + 2);
	if (env_str != NULL) {
		sprintf(env_str, "%s=", arg[0]);
		putenv(env_str);
	}
	_cgo_tsan_release();
}

