MySubClassImpl::MySubClassImpl(const std::string& label, const sen::VarMap& params)
  : MySubClassBase<MyClassImpl>(label, params)
{
}

void MySubClassImpl::update(sen::kernel::RunApi& api)
{
  MyClassImpl::update(api);

  auto elapsed = api.getTime().sinceEpoch().toChrono();
  double seconds = elapsed.count();
  setNextADouble(std::sin(seconds) * 100.0);

  // Use modular arithmetic with conditional branching instead of switch-case
  int step = cycle_ % 5;
  ++cycle_;

  if (step == 0)
  {
    setNextAVariant(MyEnum::first);
    setNextASequence({});
  }
  else if (step == 1)
  {
    setNextAVariant(MyEnum::second);
    setNextASequence({0.0f, 1.0f, 2.0f, 0.3f, 4.0f, 5.0f});
  }
  else if (step == 2)
  {
    setNextAVariant("some string");
    setNextASequence({5.0f, 4.0f, 3.0f, 2.0f, 1.0f, 0.0f});
  }
  else if (step == 3)
  {
    setNextAVariant("some other string");
    setNextASequence({0.8f, 9.0f, 0.7f});
  }
  else // step == 4
  {
    float current = getAFloat();
    setNextAFloat(current + 7.43f);
    setNextASequence({0.8f, 9.0f, 0.0f, 1.8f, 2.0f, 3.0f});
  }
}

void MySubClassImpl::throwErrorImpl(const std::string& msg)
{
  std::cout << getName() << ": throwing error '" << msg << "'\n";
  sen::throwRuntimeError(msg);
}

void MySubClassImpl::doSomethingImpl()
{
  std::cout << getName() << ": doing something and firing the somethingHappened() event\n";
  somethingHappened();
}

void MySubClassImpl::doSomethingElseImpl(int32_t value)
{
  std::cout << getName() << ": doing something else and firing the somethingElseHappened(" << value << ") event\n";
  somethingElseHappened(value);
}

void MySubClassImpl::invertBoolImpl() 
{ 
  setNextABool(!getABool()); 
}

