    ((CPlusPlus)  (0x01))
    ((Golang)     (0x02))
    ((RustLang)   (0x04))
    ((Pythonic)   (0x08))
    ((JS)         (0x10))
    ((CppGoCombo) (0x03))
    ((AllLangs)   (0x1f))
    ((NotKnown)   (0x20))
);

DEFINE_ENUM_UNKNOWN_VALUE(EProgrammingLanguages, NotKnown);
DEFINE_ENUM(EColorsUnknown,
    ((Crimson)   (0))
    ((Emerald)   (1))
    ((NotKnown)  (2))
);
DEFINE_ENUM_UNKNOWN_VALUE(EColorsUnknown, NotKnown);

TEST(TCastTest, TryCheckedEnumCast_Variant)
{
    EXPECT_EQ((TryCheckedEnumCast<EDirection, char>(2)), EDirection::Right);
    EXPECT_EQ((TryCheckedEnumCast<EDirection, int>(3)), EDirection::Down);
    EXPECT_FALSE((TryCheckedEnumCast<EDirection, char>(100)));
    EXPECT_FALSE((TryCheckedEnumCast<EDirection, int>(300)));
    EXPECT_EQ((TryCheckedEnumCast<EAttributes, ui8>(0)), EAttributes::Empty);
    EXPECT_EQ((TryCheckedEnumCast<EAttributes, ui8>(ToUnderlying(EAttributes::AttributeA))), EAttributes::AttributeA);
    EXPECT_EQ((TryCheckedEnumCast<EAttributes, ui8>(ToUnderlying(EAttributes::AttributeB))), EAttributes::AttributeB);
    EXPECT_EQ((TryCheckedEnumCast<EAttributes, int>(ToUnderlying(EAttributes::AttributeA))), EAttributes::AttributeA);
    EXPECT_EQ((TryCheckedEnumCast<EAttributes, ui8>(ToUnderlying(EAttributes::AttributeA | EAttributes::AttributeB))), EAttributes::AttributeA | EAttributes::AttributeB);
    EXPECT_FALSE((TryCheckedEnumCast<EAttributes, ui8>(0x10)));
    EXPECT_FALSE(TryCheckedEnumCast<EColorsUnknown>(3));
    EXPECT_EQ(TryCheckedEnumCast<EColorsUnknown>(3, /*enableUnknown*/ true), EColorsUnknown::NotKnown);
    EXPECT_FALSE(TryCheckedEnumCast<EProgrammingLanguages>(0x40));
    EXPECT_EQ(TryCheckedEnumCast<EProgrammingLanguages>(0x40, /*enableUnknown*/ true), EProgrammingLanguages::NotKnown);
    EXPECT_EQ(TryCheckedEnumCast<EProgrammingLanguages>(0x41, /*enableUnknown*/ true), EProgrammingLanguages::NotKnown | EProgrammingLanguages::CPlusPlus);
}

TEST(TCastTest, CheckedEnumCast_Variant)
{
    EXPECT_EQ((CheckedEnumCast<EDirection, char>(2)), EDirection::Right);
    EXPECT_EQ((CheckedEnumCast<EDirection, int>(3)), EDirection::Down);
    EXPECT_THROW((CheckedEnumCast<EDirection, char>(100)), TSimpleException);
    EXPECT_THROW((CheckedEnumCast<EDirection, int>(300)), TSimpleException);
    EXPECT_EQ((CheckedEnumCast<EAttributes, ui8>(0)), EAttributes::Empty);
    EXPECT_EQ((CheckedEnumCast<EAttributes, ui8>(ToUnderlying(EAttributes::AttributeA))), EAttributes::AttributeA);
    EXPECT_EQ((CheckedEnumCast<EAttributes, ui8>(ToUnderlying(EAttributes::AttributeB))), EAttributes::AttributeB);
    EXPECT_EQ((CheckedEnumCast<EAttributes, int>(ToUnderlying(EAttributes::AttributeA))), EAttributes::AttributeA);
    EXPECT_EQ((CheckedEnumCast<EAttributes, ui8>(ToUnderlying(EAttributes::AttributeA | EAttributes::AttributeB))), EAttributes::AttributeA | EAttributes::AttributeB);
    EXPECT_THROW((CheckedEnumCast<EAttributes, ui8>(0x10)), TSimpleException);
    EXPECT_EQ(CheckedEnumCast<EColorsUnknown>(3), EColorsUnknown::NotKnown);
    EXPECT_EQ(CheckedEnumCast<EProgrammingLanguages>(0x40), EProgrammingLanguages::NotKnown);
    EXPECT_EQ(CheckedEnumCast<EProgrammingLanguages>(0x41), EProgrammingLanguages::NotKnown | EProgrammingLanguages::CPlusPlus);
}

TEST(TCastTest, IntegralCasts_Variant)
{
    static_assert(CanFitSubtype<i64, i32>());
    static_assert(CanFitSubtype<ui64, ui32>());
    static_assert(CanFitSubtype<ui64, ui64>());
    static_assert(!CanFitSubtype<ui64, i32>());
    static_assert(!CanFitSubtype<i32, i64>());
    static_assert(IsInIntegralRange<ui32>(0));
    static_assert(IsInIntegralRange<ui32>(1ull));
    static_assert(!IsInIntegralRange<ui32>(-1));
    static_assert(!IsInIntegralRange<i32>(std::numeric_limits<i64>::max()));
    static_assert(IsInIntegralRange<i32>(1ull));
    static_assert(IsInIntegralRange<i32>(-1));
    static_assert(!IsInIntegralRange<ui32>(-1));
    static_assert(!IsInIntegralRange<ui32>(std::numeric_limits<i64>::max()));
    static_assert(IsInIntegralRange<ui64>(std::numeric_limits<i64>::max()));
}

