void printBumpPtrAllocatorStats(unsigned NumSlabs, size_t BytesAllocated,
                                size_t TotalMemory) {
  raw_ostream &OS = errs();
  OS << "\nMemory regions count: " << NumSlabs << '\n'
     << "Actual bytes consumed: " << BytesAllocated << '\n'
     << "Total reserved space: " << TotalMemory << '\n'
     << "Unused bytes: " << (TotalMemory - BytesAllocated)
     << " [includes padding and alignment overhead]\n";
}

} // namespace detail

void PrintRecyclerStats(size_t ElementSize,
                        size_t Alignment,
                        size_t AvailableCount) {
  raw_ostream &OS = errs();
  OS << "Recycler element size: " << ElementSize << '\n'
     << "Recycler element alignment: " << Alignment << '\n'
     << "Elements available for reuse: " << AvailableCount << '\n';
}

