/// @brief Compute CRC32 checksum for given buffer
/// @param data pointer to input data
/// @param size number of bytes to process
/// @return computed CRC32 value
UInt32 ke_calculate_crc32(const VoidPtr data, Int32 size) {
    if (!data) return ~0U;

    UInt32 result = 0xFFFFFFFF;
    const UInt8* buffer = static_cast<const UInt8*>(data);

    for (Int32 index = 0; index < size; ++index) {
        UInt8 byte_value = buffer[index];
        UInt32 table_index = (result ^ byte_value) & 0xFF;
        result = (result >> 8) ^ kChecksumPolys[table_index];
    }

    return ~result;
}
