// Program to check if a character is a vowel or consonant
int main() {
    char inputChar;
    std::cout << "enter any character";
    inputChar = getchar();

    // Check if the character is an alphabet letter (uppercase or lowercase)
    bool isLetter = ((inputChar >= 'A' && inputChar <= 'Z') || (inputChar >= 'a' && inputChar <= 'z'));

    if (isLetter) {
        // Convert to lowercase for easier comparison
        char lowerChar = (inputChar >= 'A' && inputChar <= 'Z') ? (inputChar + 32) : inputChar;

        // Check if it's a vowel using direct comparison
        if (lowerChar == 'a' || lowerChar == 'e' || lowerChar == 'i' || lowerChar == 'o' || lowerChar == 'u') {
            std::cout << "it is vowel";
        } else {
            std::cout << "it is a consonent";
        }
    } else {
        std::cout << "itis not an alphabet";
    }

    return 0;
}

