// Helper lambda to format table creation SQL with escaped identifiers
static QString buildCreateStatement(const QString& tableName) {
    QString fmt = "CREATE TABLE IF NOT EXISTS `%1`( "
                  "`%2` NCHAR(256) NOT NULL, "
                  "`%3` INT DEFAULT 0, "
                  "`%4` INT, "
                  "`%5` CHAR(64) DEFAULT '', "
                  "`%6` NCHAR(256) NOT NULL, "
                  "PRIMARY KEY (`%2`, `%6`) "
                  ");";
    return fmt.arg(tableName)
               .arg(ENUM_2_STR(Name))
               .arg(ENUM_2_STR(Size))
               .arg(ENUM_2_STR(DateModified))
               .arg(ENUM_2_STR(MD5))
               .arg(ENUM_2_STR(PrePath));
}

// Helper lambda to construct REPLACE INTO statement with named placeholders
static QString buildReplaceStatement(const QString& tableName) {
    QString sql = R"(REPLACE INTO `%1` 
(`%2`, `%3`, `%4`, `%5`, `%6`)
VALUES(:%7, :%8, :%9, :%10, :%11);)";

    return sql.arg(tableName)
              .arg(ENUM_2_STR(Name))
              .arg(ENUM_2_STR(Size))
              .arg(ENUM_2_STR(DateModified))
              .arg(ENUM_2_STR(MD5))
              .arg(ENUM_2_STR(PrePath))
              .arg(ENUM_2_STR(Name))
              .arg(ENUM_2_STR(Size))
              .arg(ENUM_2_STR(DateModified))
              .arg(ENUM_2_STR(MD5))
              .arg(ENUM_2_STR(PrePath));
}

