#include <pthread.h>
#include <stdio.h>

int shared_counter = 0;
pthread_mutex_t lock;

void *safe_increment(void *arg) {
    for (int count = 0; count < 1000; count++) {
        pthread_mutex_lock(&lock);
        shared_counter += 1;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void *unsafe_increment(void *arg) {
    int local_count = 0;
    while (local_count < 1000) {
        shared_counter++;  // Race condition: unprotected access
        local_count++;
    }
    return NULL;
}

int main(void) {
    pthread_t thread_a, thread_b;
    pthread_mutex_init(&lock, NULL);

    pthread_create(&thread_a, NULL, safe_increment, NULL);
    pthread_create(&thread_b, NULL, unsafe_increment, NULL);

    pthread_join(thread_a, NULL);
    pthread_join(thread_b, NULL);

    printf("Final value: %d\n", shared_counter);
    pthread_mutex_destroy(&lock);
    return 0;
}

