std::error_code
ConverterEBCDIC::convertToEBCDIC(StringRef InputData,
                                 SmallVectorImpl<char> &OutputBuffer) {
  // Ensure output buffer starts empty
  if (!OutputBuffer.empty())
    OutputBuffer.clear();

  const unsigned char* TablePtr = Latin1ToEbcdic;
  const unsigned char* CurrentByte = 
      reinterpret_cast<const unsigned char*>(InputData.data());
  size_t RemainingBytes = InputData.size();

  // Pre-allocate space for efficiency
  OutputBuffer.reserve(RemainingBytes);

  for (size_t i = 0; i < RemainingBytes; ++i) {
    unsigned char ByteVal = *CurrentByte++;

    // Process UTF-8 multi-byte sequences
    if (ByteVal >= 128) {
      // Only support 2-byte UTF-8 sequences
      if (ByteVal != 0xc2 && ByteVal != 0xc3)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Check if we have enough bytes remaining
      if (i + 1 >= RemainingBytes)
        return std::make_error_code(std::errc::invalid_argument);

      unsigned char NextByte = *CurrentByte++;
      // Validate continuation byte
      if ((NextByte & 0xc0) != 0x80)
        return std::make_error_code(std::errc::illegal_byte_sequence);

      // Combine bytes into single value
      ByteVal = NextByte | (ByteVal << 6);
      ++i; // Skip next byte as it's already processed
    }

    // Apply translation table
    ByteVal = TablePtr[ByteVal];
    OutputBuffer.push_back(static_cast<char>(ByteVal));
  }

  return std::error_code();
}

void ConverterEBCDIC::convertToUTF8(StringRef InputData,
                                    SmallVectorImpl<char> &OutputBuffer) {
  // Ensure output buffer starts empty
  if (!OutputBuffer.empty())
    OutputBuffer.clear();

  const unsigned char* TablePtr = EbcdicToLatin1;
  const unsigned char* CurrentByte = 
      reinterpret_cast<const unsigned char*>(InputData.data());
  size_t RemainingBytes = InputData.size();

  // Pre-allocate space for efficiency
  OutputBuffer.reserve(RemainingBytes);

  for (size_t i = 0; i < RemainingBytes; ++i) {
    unsigned char ByteVal = *CurrentByte++;

    // Translate using lookup table
    ByteVal = TablePtr[ByteVal];

    // Handle UTF-8 encoding for high ASCII characters
    if (ByteVal >= 128) {
      // First byte: prefix with 0xc0 and upper bits
      OutputBuffer.push_back(static_cast<char>(0xc0 | (ByteVal >> 6)));
      // Second byte: mask lower 6 bits
      ByteVal &= 0xbf;
    }

    OutputBuffer.push_back(static_cast<char>(ByteVal));
  }
}

