#include <Alembic/AbcMaterial/MaterialFlatten.h>
#include "PrintMaterial.h"

namespace Abc = Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;

void createMaterials()
{
    // Open archive for writing using Ogawa backend
    Abc::OArchive outArchive(
        Alembic::AbcCoreOgawa::WriteArchive(),
        "FlattenMaterial.abc"
    );

    Abc::OObject topObj(outArchive, Abc::kTop);
    Abc::OObject matContainer(topObj, "materials");

    // Create parent material
    Mat::OMaterial parentMat(matContainer, "parentMaterial");
    auto& parentSchema = parentMat.getSchema();

    parentSchema.setShader("prman", "surface", "paintedplastic");
    parentSchema.setShader("prman", "displacement", "knobby");

    // Set surface shader parameters
    {
        Abc::OFloatProperty kdProp(
            parentSchema.getShaderParameters("prman", "surface"),
            "Kd"
        );
        kdProp.set(0.5f);
    }

    {
        Abc::OStringProperty texNameProp(
            parentSchema.getShaderParameters("prman", "surface"),
            "texname"
        );
        texNameProp.set("taco");
    }

    // Set displacement shader parameters
    {
        Abc::OFloatProperty heightProp(
            parentSchema.getShaderParameters("prman", "displacement"),
            "height"
        );
        heightProp.set(0.75f);
    }

    // Create child material inheriting from parent
    Mat::OMaterial childMat(parentMat, "childMaterial");
    auto& childSchema = childMat.getSchema();

    childSchema.setShader("prman", "surface", "betterpaintedplastic");

    {
        Abc::OStringProperty texNameProp(
            childSchema.getShaderParameters("prman", "surface"),
            "texname"
        );
        texNameProp.set("cheese");
    }
}

void inspectMaterials()
{
    Abc::IArchive inArchive(
        Alembic::AbcCoreOgawa::ReadArchive(),
        "FlattenMaterial.abc"
    );

    Abc::IObject root = inArchive.getTop();
    Abc::IObject matGroup(root, "materials");

    Mat::IMaterial parentMat(matGroup, "parentMaterial");
    Mat::IMaterial childMat(parentMat, "childMaterial");

    std::cout << "----------------------------------------\n";
    std::cout << "LOCAL\n";
    std::cout << "---------------------------\n";
    std::cout << "Local parent material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(parentMat.getSchema());

    std::cout << "---------------------------\n";
    std::cout << "Local child material\n";
    std::cout << "---------------------------\n";
    printMaterialSchema(childMat.getSchema());

    std::cout << "----------------------------------------\n";
    std::cout << "FLATTENED\n";
    printFlattenedMaterial(parentMat);
    printFlattenedMaterial(childMat);
}

int main(int /*argc*/, char* /*argv*/[])
{
    createMaterials();
    inspectMaterials();
    return 0;
}

