// External function declaration remains unchanged
extern void UNSAFE_BUFACCESS(void *buffer, int size);

int main() {
    // Initialize buffer with a shorter string to allow more space for concatenation
    char buffer[10] = "H";
    char input[20];

    printf("Enter a string: ");
    scanf("%19s", input);

    // Use snprintf to safely concatenate and prevent buffer overflow
    // This ensures we never exceed the buffer size (10 characters including null terminator)
    size_t current_len = strlen(buffer);
    if (current_len < sizeof(buffer) - 1) {
        size_t remaining_space = sizeof(buffer) - 1 - current_len;
        strncat(buffer, input, remaining_space);
    }

    UNSAFE_BUFACCESS(buffer, strlen(buffer));
    printf("Buffer: %s\n", buffer);
    return 0;
}

