static void mapAuxExcept(IO &IO, XCOFFYAML::ExcpetionAuxEnt &ASE) {
  IO.mapOptional("OffsetToExceptionTbl", ASE.OffsetToExceptionTbl);
  IO.mapOptional("SizeOfFunction", ASE.SizeOfFunction);
  IO.mapOptional("SymIdxOfNextBeyond", ASE.SymIdxOfNextBeyond);
}

static void mapAuxFcn(IO &IO, XCOFFYAML::FunctionAuxEnt &ASE, bool Is64) {
  if (!Is64)
    IO.mapOptional("OffsetToExceptionTbl", ASE.OffsetToExceptionTbl);
  IO.mapOptional("SizeOfFunction", ASE.SizeOfFunction);
  IO.mapOptional("SymIdxOfNextBeyond", ASE.SymIdxOfNextBeyond);
  IO.mapOptional("PtrToLineNum", ASE.PtrToLineNum);
}

static void mapAuxBlock(IO &IO, XCOFFYAML::BlockAuxEnt &ASE, bool Is64) {
  if (Is64) {
    IO.mapOptional("LineNum", ASE.LineNum);
  } else {
    IO.mapOptional("LineNumHi", ASE.LineNumHi);
    IO.mapOptional("LineNumLo", ASE.LineNumLo);
  }
}

static void mapAuxFile(IO &IO, XCOFFYAML::FileAuxEnt &ASE) {
  IO.mapOptional("FileNameOrString", ASE.FileNameOrString);
  IO.mapOptional("FileStringType", ASE.FileStringType);
}

static void mapAuxCsect(IO &IO, XCOFFYAML::CsectAuxEnt &ASE, bool Is64) {
  IO.mapOptional("ParameterHashIndex", ASE.ParameterHashIndex);
  IO.mapOptional("TypeChkSectNum", ASE.TypeChkSectNum);
  IO.mapOptional("SymbolAlignmentAndType", ASE.SymbolAlignmentAndType);
  IO.mapOptional("StorageMappingClass", ASE.StorageMappingClass);
  if (Is64) {
    IO.mapOptional("SectionOrLengthLo", ASE.SectionOrLengthLo);
    IO.mapOptional("SectionOrLengthHi", ASE.SectionOrLengthHi);
  } else {
    IO.mapOptional("SectionOrLength", ASE.SectionOrLength);
    IO.mapOptional("StabInfoIndex", ASE.StabInfoIndex);
    IO.mapOptional("StabSectNum", ASE.StabSectNum);
  }
}

static void mapAuxDwarf(IO &IO, XCOFFYAML::SectAuxEntForDWARF &ASE) {
  IO.mapOptional("LengthOfSectionPortion", ASE.LengthOfSectionPortion);
  IO.mapOptional("NumberOfRelocEnt", ASE.NumberOfRelocEnt);
}

static void mapAuxStat(IO &IO, XCOFFYAML::SectAuxEntForStat &ASE) {
  IO.mapOptional("SectionLength", ASE.SectionLength);
  IO.mapOptional("NumberOfRelocEnt", ASE.NumberOfRelocEnt);
  IO.mapOptional("NumberOfLineNum", ASE.NumberOfLineNum);
}

template <typename T>
static void resetAuxSym(IO &IO,
                        std::unique_ptr<XCOFFYAML::AuxSymbolEnt> &ASE) {
  if (!IO.outputting())
    ASE.reset(new T());
}

void MappingTraits<std::unique_ptr<XCOFFYAML::AuxSymbolEnt>>::mapping(
    IO &IO, std::unique_ptr<XCOFFYAML::AuxSymbolEnt> &ASE) {
  const auto *Obj = static_cast<XCOFFYAML::Object *>(IO.getContext());
  const bool Is64 = Obj->Header.Magic == (llvm::yaml::Hex16)XCOFF::XCOFF64;

  XCOFFYAML::AuxSymbolType AuxType;
  if (IO.outputting())
    AuxType = ASE.get()->Type;
  IO.mapRequired("Type", AuxType);

  switch (AuxType) {
  case XCOFFYAML::AUX_EXCEPT:
    if (!Is64) {
      IO.setError("aux symbol type AUX_EXCEPT not allowed in XCOFF32");
      return;
    }
    resetAuxSym<XCOFFYAML::ExcpetionAuxEnt>(IO, ASE);
    mapAuxExcept(IO, *cast<XCOFFYAML::ExcpetionAuxEnt>(ASE.get()));
    break;
  case XCOFFYAML::AUX_FCN:
    resetAuxSym<XCOFFYAML::FunctionAuxEnt>(IO, ASE);
    mapAuxFcn(IO, *cast<XCOFFYAML::FunctionAuxEnt>(ASE.get()), Is64);
    break;
  case XCOFFYAML::AUX_SYM:
    resetAuxSym<XCOFFYAML::BlockAuxEnt>(IO, ASE);
    mapAuxBlock(IO, *cast<XCOFFYAML::BlockAuxEnt>(ASE.get()), Is64);
    break;
  case XCOFFYAML::AUX_FILE:
    resetAuxSym<XCOFFYAML::FileAuxEnt>(IO, ASE);
    mapAuxFile(IO, *cast<XCOFFYAML::FileAuxEnt>(ASE.get()));
    break;
  case XCOFFYAML::AUX_CSECT:
    resetAuxSym<XCOFFYAML::CsectAuxEnt>(IO, ASE);
    mapAuxCsect(IO, *cast<XCOFFYAML::CsectAuxEnt>(ASE.get()), Is64);
    break;
  case XCOFFYAML::AUX_SECT:
    resetAuxSym<XCOFFYAML::SectAuxEntForDWARF>(IO, ASE);
    mapAuxDwarf(IO, *cast<XCOFFYAML::SectAuxEntForDWARF>(ASE.get()));
    break;
  case XCOFFYAML::AUX_STAT:
    if (Is64) {
      IO.setError("aux symbol type AUX_STAT not allowed in XCOFF64");
      return;
    }
    resetAuxSym<XCOFFYAML::SectAuxEntForStat>(IO, ASE);
    mapAuxStat(IO, *cast<XCOFFYAML::SectAuxEntForStat>(ASE.get()));
    break;
  }
}

void MappingTraits<XCOFFYAML::Symbol>::mapping(
    IO &IO, XCOFFYAML::Symbol &Sym) {
  IO.mapOptional("Name", Sym.SymbolName);
  IO.mapOptional("Value", Sym.Value);
  IO.mapOptional("Section", Sym.SectionName);
  IO.mapOptional("SectionIndex", Sym.SectionIndex);
  IO.mapOptional("Type", Sym.Type);
  IO.mapOptional("StorageClass", Sym.StorageClass);
  IO.mapOptional("NumberOfAuxEntries", Sym.NumberOfAuxEntries);
  IO.mapOptional("AuxEntries", Sym.AuxEntries);
}

void MappingTraits<XCOFFYAML::StringTable>::mapping(
    IO &IO, XCOFFYAML::StringTable &Str) {
  IO.mapOptional("ContentSize", Str.ContentSize);
  IO.mapOptional("Length", Str.Length);
  IO.mapOptional("Strings", Str.Strings);
  IO.mapOptional("RawContent", Str.RawContent);
}

void MappingTraits<XCOFFYAML::Object>::mapping(
    IO &IO, XCOFFYAML::Object &Obj) {
  IO.setContext(&Obj);
  IO.mapTag("!XCOFF", true);
  IO.mapRequired("FileHeader", Obj.Header);
  IO.mapOptional("AuxiliaryHeader", Obj.AuxHeader);
  IO.mapOptional("Sections", Obj.Sections);
  IO.mapOptional("Symbols", Obj.Symbols);
  IO.mapOptional("StringTable", Obj.StrTbl);
  IO.setContext(nullptr);
}

