#include "messagereceiver.h"

int main(int argc, char *argv[])
{
    // Initialize application allowing multiple instances
    SingleApplication app(argc, argv, true);
    MessageReceiver receiver;

    // Check if this is a secondary instance
    if (app.isSecondary()) {
        // Send current arguments to primary instance
        QString message = app.arguments().join(" ");
        app.sendMessage(message.toUtf8());

        qDebug() << "Another instance is already running.";
        qDebug() << "Primary process ID:" << app.primaryPid();
        qDebug() << "User running primary instance:" << app.primaryUser();

        return 0;
    } else {
        // Connect signal for receiving messages from other instances
        QObject::connect(
            &app,
            &SingleApplication::receivedMessage,
            &receiver,
            &MessageReceiver::handleReceivedMessage
        );
    }

    return app.exec();
}

#include "bounding_box_diagonal.h"
#include "mat_max.h"
#include "mat_min.h"
#include <cmath>

IGL_INLINE double igl::bounding_box_diagonal(
  const Eigen::MatrixXd & V)
{
  using namespace Eigen;

  // Compute the diagonal length of the bounding box
  VectorXd min_vals, max_vals;
  VectorXi min_idx, max_idx;

  // Find minimum and maximum values along rows (dimension-wise)
  mat_min(V, 1, min_vals, min_idx);
  mat_max(V, 1, max_vals, max_idx);

  // Calculate Euclidean distance between min and max corners
  VectorXd diff = max_vals - min_vals;
  double diagonal = std::sqrt((diff.array() * diff.array()).sum());

  return diagonal;
}
