    // Process each input file provided as command-line argument
    for (int idx = 1; idx < argc; ++idx) {
        std::ifstream file_stream(argv[idx]);
        assert(file_stream.is_open());

        // Seek to the end to determine file size
        file_stream.seekg(0, std::ios::end);
        auto file_size_pos = file_stream.tellg();
        assert(file_size_pos >= 0);

        // Reset to beginning of file
        file_stream.seekg(0, std::ios::beg);

        // Read entire file content into buffer
        std::vector<char> buffer(static_cast<size_t>(file_size_pos));
        file_stream.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
