namespace aeronet::http {

// Verify that standard reserved response headers are correctly identified
TEST(ReservedHeadersTest, StandardResponseHeadersRecognized) {
  EXPECT_TRUE(IsReservedResponseHeader("content-length"));
  EXPECT_TRUE(IsReservedResponseHeader("date"));
  EXPECT_TRUE(IsReservedResponseHeader(http::Connection));
  EXPECT_TRUE(IsReservedResponseHeader("transfer-encoding"));
  EXPECT_TRUE(IsReservedResponseHeader("te"));
  EXPECT_TRUE(IsReservedResponseHeader("trailer"));
  EXPECT_TRUE(IsReservedResponseHeader("upgrade"));
}

// Confirm case-insensitive matching for reserved response headers
TEST(ReservedHeadersTest, CaseInsensitiveMatchingForResponseHeaders) {
  EXPECT_TRUE(IsReservedResponseHeader("Content-Length"));
  EXPECT_TRUE(IsReservedResponseHeader("DaTe"));
  EXPECT_TRUE(IsReservedResponseHeader("TrAnSfEr-EnCoDiNg"));
}

// Ensure non-reserved or modified headers are properly rejected
TEST(ReservedHeadersTest, NonReservedHeadersCorrectlyRejected) {
  EXPECT_FALSE(IsReservedResponseHeader("x-custom-header"));
  EXPECT_FALSE(IsReservedResponseHeader("content-length-extra"));
  EXPECT_FALSE(IsReservedResponseHeader("datex"));
}

// Test edge cases: empty string and overly long header names
TEST(ReservedHeadersTest, EdgeCasesForResponseHeaders) {
  EXPECT_FALSE(IsReservedResponseHeader(""));
  // Headers exceeding maximum allowed length should be rejected
  std::string excessiveName(256, 'a');
  EXPECT_FALSE(IsReservedResponseHeader(excessiveName));
}

// Validate that certain headers are forbidden in trailers
TEST(ForbiddenTrailersTest, CoreForbiddenTrailersIdentified) {
  EXPECT_TRUE(IsForbiddenTrailerHeader("transfer-encoding"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("content-length"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("host"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("trailer"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("te"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("set-cookie"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("authorization"));
}

// Verify case-insensitive behavior for forbidden trailer headers
TEST(ForbiddenTrailersTest, CaseInsensitivityForTrailers) {
  EXPECT_TRUE(IsForbiddenTrailerHeader("Transfer-Encoding"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("Content-Length"));
  EXPECT_TRUE(IsForbiddenTrailerHeader("SET-COOKIE"));
}

// Ensure non-forbidden trailer headers are not mistakenly flagged
TEST(ForbiddenTrailersTest, SafeTrailersCorrectlyAllowed) {
  EXPECT_FALSE(IsForbiddenTrailerHeader("x-trailer-safe"));
  EXPECT_FALSE(IsForbiddenTrailerHeader("content-typex"));
  EXPECT_FALSE(IsForbiddenTrailerHeader("cached"));
}

// Test boundary conditions for forbidden trailer headers
TEST(ForbiddenTrailersTest, BoundaryConditionsForTrailers) {
  EXPECT_FALSE(IsForbiddenTrailerHeader(""));
  std::string lengthyName(512, 'Z');
  EXPECT_FALSE(IsForbiddenTrailerHeader(lengthyName));
}

// Prevent false positives from prefix-based matching
TEST(ReservedHeadersTest, PrefixesMustNotTriggerMatches) {
  // Short strings that are prefixes of reserved names must not match
  EXPECT_FALSE(IsReservedResponseHeader("con"));
  EXPECT_FALSE(IsForbiddenTrailerHeader("transf"));
}

