using namespace ckernel;
using namespace ckernel::sfpu;

void run_kernel(const volatile struct RuntimeParams* params)
{
    // Copy source A to destination register
#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(4, formats.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(4, formats.math);
#endif

    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(formats.math, formats.math);
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    std::uint32_t tile_idx = 0u;
    const std::uint32_t max_tiles = get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>();
    while (tile_idx < params->TILE_CNT)
    {
        LLK_ASSERT(tile_idx < max_tiles, "Block tile index exceeds maximum destination tiles");
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tile_idx, formats.math, formats.math);
        ++tile_idx;
    }

    _llk_math_eltwise_unary_sfpu_init_<SfpuType::reduce>();
    ckernel::sfpu::_init_reduce_<POOL_TYPE, static_cast<DataFormat>(formats.math)>();

    if (REDUCE_DIM == ReduceDim::REDUCE_COL)
    {
        tile_idx = 0u;
        while (tile_idx < params->TILE_CNT)
        {
            LLK_ASSERT(tile_idx < max_tiles, "Block tile index exceeds maximum destination tiles");
            _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(tile_idx);
            ckernel::sfpu::_calculate_reduce_<POOL_TYPE, REDUCE_DIM, static_cast<DataFormat>(formats.math)>();
            ++tile_idx;
        }
    }
    else if (REDUCE_DIM == ReduceDim::REDUCE_ROW)
    {
        _llk_math_eltwise_unary_sfpu_start_<DstSync::SyncHalf>(0);
        ckernel::sfpu::_calculate_reduce_<POOL_TYPE, REDUCE_DIM, static_cast<DataFormat>(formats.math)>(
            BLOCK_CT_DIM, BLOCK_RT_DIM);
    }

#ifdef ADD_TOP_ROW
    _llk_math_eltwise_binary_sfpu_init_<SfpuType::add_top_row>();
    _llk_math_eltwise_binary_sfpu_start_<DstSync::SyncHalf>(0);
    ckernel::sfpu::_init_add_top_row_();

    std::uint32_t row_tile_idx = 1u;
    while (row_tile_idx < params->TILE_CNT)
    {
        LLK_ASSERT(row_tile_idx < max_tiles, "Block tile index exceeds maximum destination tiles");
        ckernel::sfpu::_calculate_add_top_row_<static_cast<DataFormat>(formats.math)>(0, row_tile_idx, 0);
        ++row_tile_idx;
    }
#endif

    _llk_math_eltwise_unary_sfpu_done_();
    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

