static u64 EncodeInstruction(DecMode mode, DecParam dest, DecParam src, shilop operation, u32 extra = 0)
{
    return (((u64)extra) << 32) | ((u64)mode << 24) | ((u64)dest << 16) | ((u64)src << 8) | (u64)operation;
}

