#define QUAD_PRECISION
#include "fp_lib.h"
#include "int_lib.h"
#if defined(CRT_HAS_TF_MODE)
#define SRC_U128
#define DST_QUAD
#include "int_to_fp_impl.inc"

// Converts an unsigned 128-bit integer to a quad-precision floating-point value
// using round-to-nearest, ties-to-even rounding mode.
// Precondition: fp_t represents IEEE 754 binary128 format (128-bit float)
//               tu_int is a 128-bit unsigned integer type
// Bit layout:
// s[0] | e[15:0] | m[111:0]
// where s is sign bit, e is 15-bit exponent with bias 16383, and m is 112-bit mantissa
COMPILER_RT_ABI fp_t __floatuntitf(tu_int operand) {
    return __floatXiYf__(operand);
}
#endif

#include "tree/phylotree.h"
#include "tree/tinatree.h"
#include "parsmultistate.h"
#include "alignment/alignment.h"
#include "tree/parstree.h"

void doParsMultiState(Params &params) {
    Alignment seq_data(params.aln_file, params.sequence_type, params.intype, "");
    seq_data.orderPatternByNumChars(PAT_VARIANT);

    ParsTree phylo_tree;
    phylo_tree.readTree(params.user_file, params.is_rooted);

    if (phylo_tree.rooted)
        phylo_tree.convertToUnrooted();

    phylo_tree.setAlignment(&seq_data);
    phylo_tree.initCostMatrix(CM_LINEAR);
    phylo_tree.setParsimonyKernel(params.SSE);
    phylo_tree.initializeAllPartialPars();

    int total_cost = phylo_tree.computeParsimony();
    std::cout << "total length: " << total_cost << std::endl;

    phylo_tree.initCostMatrix(CM_UNIFORM);
    int score_value = phylo_tree.computeParsimony();

    std::cout.unsetf(std::ios::fixed);
    std::cout.precision(6);
    std::cout << "mean length: " << static_cast<double>(total_cost) / score_value << std::endl;
    std::cout << "Parsimony score is: " << score_value << std::endl;
}

