// Wrapper function to retrieve random data using the getrandom syscall
// Ensures MemorySanitizer does not flag uninitialized memory usage
ssize_t getrandom(void *buffer, size_t length, unsigned int options)
{
#if defined(__has_feature)
    #if __has_feature(memory_sanitizer)
        // Inform MemorySanitizer that the buffer is now initialized
        __msan_unpoison(buffer, length);
    #endif
#endif
    // Invoke the kernel's getrandom syscall with provided arguments
    return syscall(SYS_getrandom, buffer, length, options);
}

#include <fenv.h>

// Re-establish floating-point exception flags based on provided mask
int fesetexceptflag(const fexcept_t *flag_ptr, int exception_mask)
{
    // Clear exceptions not present in the flag but requested by mask
    feclearexcept(exception_mask & ~(*flag_ptr));

    // Raise exceptions present in the flag and requested by mask
    feraiseexcept(exception_mask & (*flag_ptr));

    return 0;
}

