namespace autolink {

using autolink::proto::Param;
using autolink::proto::ParamType;

class ParameterTest : public ::testing::Test {
 protected:
  virtual void SetUp() override {
    // Initialize various parameter types for testing
    bool_param_ = std::make_unique<Parameter>("flag", true);
    int_param_ = std::make_unique<Parameter>("count", 100);
    double_param_ = std::make_unique<Parameter>("rate", 0.0f);
    string_param_ = std::make_unique<Parameter>("label", "sample");

    Param proto_obj;
    proto_obj.set_name("descriptor");
    std::string serialized_data;
    proto_obj.SerializeToString(&serialized_data);

    std::string description;
    message::GetDescriptorString(proto_obj, &description);

    std::string full_type_name = Param::descriptor()->full_name();
    protobuf_param_ = std::make_unique<Parameter>(
        "message", serialized_data, full_type_name, description);
  }

  virtual void TearDown() override {
    bool_param_.reset();
    int_param_.reset();
    double_param_.reset();
    string_param_.reset();
    protobuf_param_.reset();
  }

 protected:
  std::unique_ptr<Parameter> bool_param_;
  std::unique_ptr<Parameter> int_param_;
  std::unique_ptr<Parameter> double_param_;
  std::unique_ptr<Parameter> string_param_;
  std::unique_ptr<Parameter> protobuf_param_;
};

// Test default constructor and copy constructor
TEST_F(ParameterTest, constructors) {
  Parameter p1("identifier");
  EXPECT_EQ(ParamType::NOT_SET, p1.Type());

  Parameter p2(p1);
  EXPECT_EQ(ParamType::NOT_SET, p2.Type());
}

// Test deserialization from Protobuf message
TEST_F(ParameterTest, from_pb) {
  Param pb_msg;
  pb_msg.set_name("int_test");
  pb_msg.set_type(ParamType::INT);
  pb_msg.set_int_value(100);

  Parameter pv;
  pv.FromProtoParam(pb_msg);
  EXPECT_EQ("int_test", pv.Name());
  EXPECT_EQ(ParamType::INT, pv.Type());
  EXPECT_EQ(100, pv.AsInt64());

  pb_msg.set_name("bool_test");
  pb_msg.set_type(ParamType::BOOL);
  pb_msg.set_bool_value(true);
  pv.FromProtoParam(pb_msg);
  EXPECT_TRUE(pv.AsBool());

  pb_msg.set_name("double_test");
  pb_msg.set_type(ParamType::DOUBLE);
  pb_msg.set_double_value(10.0);
  pv.FromProtoParam(pb_msg);
  EXPECT_EQ(ParamType::DOUBLE, pv.Type());

  pb_msg.set_name("string_test");
  pb_msg.set_type(ParamType::STRING);
  pb_msg.set_string_value("hello_world");
  pv.FromProtoParam(pb_msg);
  EXPECT_EQ("hello_world", pv.AsString());
}

// Test serialization to Protobuf message
TEST_F(ParameterTest, to_pb) {
  Param result = int_param_->ToProtoParam();
  EXPECT_EQ("int", result.name());
  EXPECT_EQ(ParamType::INT, result.type());
  EXPECT_EQ(100, result.int_value());
}

// Verify type detection for each stored parameter
TEST_F(ParameterTest, type) {
  EXPECT_EQ(ParamType::BOOL, bool_param_->Type());
  EXPECT_EQ(ParamType::INT, int_param_->Type());
  EXPECT_EQ(ParamType::DOUBLE, double_param_->Type());
  EXPECT_EQ(ParamType::STRING, string_param_->Type());
  EXPECT_EQ(ParamType::PROTOBUF, protobuf_param_->Type());
}

// Check human-readable type names
TEST_F(ParameterTest, type_name) {
  EXPECT_EQ("BOOL", bool_param_->TypeName());
  EXPECT_EQ("INT", int_param_->TypeName());
  EXPECT_EQ("DOUBLE", double_param_->TypeName());
  EXPECT_EQ("STRING", string_param_->TypeName());
  EXPECT_EQ("autolink.proto.Param", protobuf_param_->TypeName());
}

// Validate parameter names
TEST_F(ParameterTest, name) {
  EXPECT_EQ("flag", bool_param_->Name());
  EXPECT_EQ("count", int_param_->Name());
  EXPECT_EQ("rate", double_param_->Name());
  EXPECT_EQ("label", string_param_->Name());
  EXPECT_EQ("message", protobuf_param_->Name());
}

// Boolean value extraction tests
TEST_F(ParameterTest, as_bool) {
  EXPECT_TRUE(bool_param_->AsBool());
  EXPECT_FALSE(Parameter("flag", false).AsBool());
}

// Integer value extraction tests
TEST_F(ParameterTest, as_int) { EXPECT_EQ(100, int_param_->AsInt64()); }

// Floating-point value extraction tests
TEST_F(ParameterTest, as_double) { EXPECT_EQ(0.0, double_param_->AsDouble()); }

// String value extraction tests
TEST_F(ParameterTest, AsString) { EXPECT_EQ("sample", string_param_->AsString()); }

// Generic value access via template method
TEST_F(ParameterTest, value) {
  EXPECT_TRUE(bool_param_->value<bool>());
  EXPECT_EQ("", bool_param_->value<std::string>());

  EXPECT_EQ(100, int_param_->value<uint8_t>());
  EXPECT_EQ(100, int_param_->value<uint32_t>());
  EXPECT_EQ(100, int_param_->value<int64_t>());
  EXPECT_EQ(100, int_param_->value<int>());
  EXPECT_EQ("", int_param_->value<std::string>());

  EXPECT_EQ(0.0, double_param_->value<float>());
  EXPECT_EQ(0.0, double_param_->value<double>());
  EXPECT_EQ("", double_param_->value<std::string>());

  EXPECT_EQ("sample", string_param_->value<std::string>());

  // Invalid conversions should return default values
  string_param_->value<int>();

  auto msg_val = protobuf_param_->value<Param>();
  EXPECT_EQ("message", protobuf_param_->Name());
  EXPECT_EQ("autolink.proto.Param", protobuf_param_->TypeName());

  std::string serialized_back;
  msg_val.SerializeToString(&serialized_back);
  EXPECT_EQ(serialized_back, protobuf_param_->value<std::string>());

  protobuf_param_->value<int>();
}

// Debug string formatting verification
TEST_F(ParameterTest, debug_string) {
  EXPECT_EQ("{name: \"flag\", type: \"BOOL\", value: true}", bool_param_->DebugString());
  EXPECT_EQ("{name: \"count\", type: \"INT\", value: 100}", int_param_->DebugString());
  EXPECT_EQ("{name: \"rate\", type: \"DOUBLE\", value: 0.000000}", double_param_->DebugString());
  EXPECT_EQ("{name: \"label\", type: \"STRING\", value: \"sample\"}", string_param_->DebugString());
  EXPECT_EQ(
      "{name: \"message\", type: \"autolink.proto.Param\", value: "
      "\"name: \"descriptor\"\"}",
      protobuf_param_->DebugString());
}

