extern std::size_t totalMemory;
extern "C" void main() {
    // Initialize C++ constructors and low-level subsystems
    utils::cxx::init_constructors();
    bootloader::init();

    // Terminal initialization: basic then full
    utils::flanterm::init();
    utils::flanterm::fullinit();

    // Memory management setup
    pmm::init();
    paging::init();
    kheap::init();

    // Print memory info
    klibc::printf("PMM: Total usable memory: %zu bytes\r\n", totalMemory);
    klibc::printf("Paging: Enabled kernel root with %d-level paging\r\n", arch::level_paging());
    klibc::printf("KHeap: Available memory %zu bytes\r\n", KHEAP_SIZE);

    // ACPI and architecture initialization phases
    acpi::init_tables();
    arch::init(ARCH_INIT_EARLY);
    acpi::full_init();
    arch::init(ARCH_INIT_COMMON);

    // Mark that early boot is complete
    extern int bootPhase;
    bootPhase = 0;

    // Time-based diagnostics before triggering page fault
    const auto nowNs = time::timer->current_nano();
    const auto seconds = static_cast<std::uint64_t>(nowNs / (1'000'000'000ULL));
    klibc::printf("Boot completed. Waiting 2 seconds before page fault test...\r\n");
    klibc::printf("Current time: %llu seconds\r\n", static_cast<unsigned long long>(seconds));

    // Trigger TLB flush and deliberate page fault
    constexpr std::uintptr_t faultAddr = 0x47AFE710;
    arch::tlb_flush(0x47AFE000, PAGE_SIZE);
    *reinterpret_cast<int*>(faultAddr) = 0;

    // Halt CPU on fatal error
    arch::hcf();
}

#include "Alias/Dynamic/LogPrinter.h"
