#include <iostream>

namespace dynamic {

LogPrinter::LogPrinter(const char *fileName, std::ostream &outputStream)
    : LogProcessor(fileName), os(outputStream) {}

/// Outputs a memory allocation event in readable form
void LogPrinter::visitAllocRecord(const AllocRecord &allocInfo) {
  os << "[ALLOC] ";

  switch (allocInfo.type) {
  case AllocType::Global:
    os << "Global ";
    break;
  case AllocType::Stack:
    os << "Stack ";
    break;
  case AllocType::Heap:
    os << "Heap ";
    break;
  default:
    std::cerr << "Invalid allocation type. Corrupted log file detected.\n";
    std::exit(-1);
  }

  os << "Ptr# " << allocInfo.id << " = " << allocInfo.address << '\n';
}

/// Outputs a pointer assignment event
void LogPrinter::visitPointerRecord(const PointerRecord &ptrInfo) {
  os << "[POINTER] Ptr# " << ptrInfo.id << " = " << ptrInfo.address << '\n';
}

/// Outputs a function entry event
void LogPrinter::visitEnterRecord(const EnterRecord &enterInfo) {
  os << "[ENTER] Function# " << enterInfo.id << '\n';
}

/// Outputs a function exit event
void LogPrinter::visitExitRecord(const ExitRecord &exitInfo) {
  os << "[EXIT] Function# " << exitInfo.id << '\n';
}

/// Outputs a function call event
void LogPrinter::visitCallRecord(const CallRecord &callInfo) {
  os << "[CALL] Inst# " << callInfo.id << '\n';
}

} // namespace dynamic

