class TFileListTest : public TTestBase {
    UNIT_TEST_SUITE(TFileListTest);
    UNIT_TEST(TestBasicScenario);
    UNIT_TEST(TestFilteringByPrefix);
    UNIT_TEST_SUITE_END();

public:
    void TestBasicScenario();
    void TestFilteringByPrefix();
};

void TFileListTest::TestBasicScenario() {
    TTempDir tempPath("nonexistingdir");
    const TString subDirPath = tempPath() + LOCSLASH_S "subdir";
    MakeDirIfNotExist(subDirPath.data());

    const TString filePath = subDirPath + LOCSLASH_S "file";
    TFile(filePath.data(), CreateAlways);

    TFileList dirEntries;
    dirEntries.Fill(tempPath().data(), "", "", 1000);

    TString firstEntry(dirEntries.Next());
    UNIT_ASSERT_EQUAL(firstEntry, "subdir" LOCSLASH_S "file");
    UNIT_ASSERT_EQUAL(dirEntries.Next(), nullptr);
}

void TFileListTest::TestFilteringByPrefix() {
    TTempDir tempPath("nonexistingdir");

    const TString good1 = tempPath() + LOCSLASH_S "good_file1";
    const TString good2 = tempPath() + LOCSLASH_S "good_file2";
    const TString bad1  = tempPath() + LOCSLASH_S "bad_file1";
    const TString bad2  = tempPath() + LOCSLASH_S "bad_file2";

    TFile(good1.data(), CreateAlways);
    TFile(good2.data(), CreateAlways);
    TFile(bad1.data(), CreateAlways);
    TFile(bad2.data(), CreateAlways);

    const bool ENABLE_SORTING = true;

    TFileList dirEntries;

    // First test: filter files starting with "good_file"
    {
        dirEntries.Fill(tempPath().data(), "good_file", ENABLE_SORTING);
        UNIT_ASSERT_EQUAL(TString(dirEntries.Next()), "good_file1");
        UNIT_ASSERT_EQUAL(TString(dirEntries.Next()), "good_file2");
        UNIT_ASSERT_EQUAL(dirEntries.Next(), nullptr);
    }

    // Second test: filter files starting with "bad_file"
    {
        dirEntries.Fill(tempPath().data(), "bad_file", ENABLE_SORTING);
        UNIT_ASSERT_EQUAL(TString(dirEntries.Next()), "bad_file1");
        UNIT_ASSERT_EQUAL(TString(dirEntries.Next()), "bad_file2");
        UNIT_ASSERT_EQUAL(dirEntries.Next(), nullptr);
    }
}

UNIT_TEST_SUITE_REGISTRATION(TFileListTest);

