#ifdef LLK_TRISC_UNPACK
#include "llk_unpack_A.h"
#include "llk_unpack_common.h"

void run_kernel(const volatile struct RuntimeParams* pParams)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = pParams->formats;
#endif

    // Configure unpack hardware with face dimensions and count
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmts.unpack_A_src, fmts.unpack_B_src, fmts.unpack_A_dst, fmts.unpack_B_dst, FACE_R_DIM, FACE_R_DIM, pParams->num_faces, pParams->num_faces);

    // Initialize A-unpack operation
    _llk_unpack_A_init_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
        pParams->UNPACK_TRANSPOSE_FACES, 0, FACE_R_DIM, pParams->num_faces, fmts.unpack_A_src, fmts.unpack_A_dst);

    // Process each tile via A-unpack
    int tileIdx = 0;
    do {
        _llk_unpack_A_<BroadcastType::NONE, false, EltwiseBinaryReuseDestType::NONE, unpack_to_dest>(
            L1_ADDRESS(pParams->buffer_A[tileIdx]), fmts.unpack_A_src, fmts.unpack_A_dst);
        ++tileIdx;
    } while (tileIdx < pParams->TILE_CNT);

    // Signal dummy valid for source B across all tiles
    int dummyIter = 0;
    do {
        _llk_unpack_set_srcb_dummy_valid_();
        ++dummyIter;
    } while (dummyIter < pParams->TILE_CNT);
}
#endif

#ifdef LLK_TRISC_MATH
#include "llk_math_common.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "llk_math_transpose_dest.h"

using namespace ckernel;

void run_kernel(const volatile struct RuntimeParams* pParams)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = pParams->formats;
#endif

    constexpr bool is32bitMode = is_fp32_dest_acc_en;

#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, false>(pParams->num_faces, fmts.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false>(pParams->num_faces, fmts.math);
#endif

    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);
    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    // Perform data copy per tile
    int tIdx = 0;
    do {
        LLK_ASSERT(
            (tIdx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()), 
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tIdx, fmts.math, fmts.math);
#else
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, unpack_to_dest>(
            tIdx, fmts.math, fmts.math);
#endif
        ++tIdx;
    } while (tIdx < pParams->TILE_CNT);

    // Setup transpose destination
    _llk_math_transpose_dest_init_<MATH_TRANSPOSE_FACES, is32bitMode>();

    // Execute transpose per tile
    tIdx = 0;
    do {
        LLK_ASSERT(
            (tIdx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()), 
            "Block tile index exceeds maximum destination tiles");

#ifdef ARCH_BLACKHOLE
        _llk_math_transpose_dest_<is_fp32_dest_acc_en, MATH_TRANSPOSE_FACES, is32bitMode>(tIdx);
#else
        _llk_math_transpose_dest_<MATH_TRANSPOSE_FACES, is32bitMode>(tIdx);
#endif
        ++tIdx;
    } while (tIdx < pParams->TILE_CNT);

    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"

void run_kernel(const volatile struct RuntimeParams* pParams)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = pParams->formats;
#endif

#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false, false>(fmts.pack_src, fmts.pack_dst, 16 * 16 * 4, FACE_R_DIM, TILE_C_DIM, pParams->num_faces);
    _llk_pack_init_<false, false, false>(fmts.pack_dst, FACE_R_DIM, TILE_C_DIM, pParams->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, false>(fmts.pack_src, fmts.pack_dst, 16 * 16 * 4, FACE_R_DIM, pParams->num_faces);
    _llk_pack_init_<false, false>(fmts.pack_dst, FACE_R_DIM, pParams->num_faces);
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>();
#endif

    _llk_packer_wait_for_math_done_();

    int pIdx = 0;
    do {
        LLK_ASSERT(
            (pIdx < get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>()), 
            "Block tile index exceeds maximum destination tiles");
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(pIdx, L1_ADDRESS(pParams->buffer_Res[pIdx]));
        ++pIdx;
    } while (pIdx < pParams->TILE_CNT);

    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

