XmlPolarWriter::XmlPolarWriter(QFile &XFile) : XflXmlWriter(XFile)
{
}

void XmlPolarWriter::writeXMLPolar(Polar *pPolar)
{
    if (!pPolar) return;

    writeHeader();
    writeStartElement("Polar");

    // Write basic identification fields
    writeTextElement("Foil_Name",  pPolar->foilName());
    writeTextElement("Polar_Name", pPolar->name());
    writeTextElement("Type",       objects::polarType(pPolar->type()));

    // Write method information
    QString methodStr = "XFoil"; // default
    switch (pPolar->BLMethod())
    {
        case BL::XFOIL:
            methodStr = "XFoil";
            break;
        // Additional cases could be added here in the future
    }
    writeTextElement("Method", methodStr);

    // Write simulation parameters for non-control polars
    if (!pPolar->isControlPolar())
    {
        writeTextElement("Fixed_Reynolds",     QString::number(pPolar->Reynolds(), 'f', 0));
        writeTextElement("Fixed_AOA",          QString::number(pPolar->aoaSpec(), 'f', 3));
        writeTextElement("Mach",               QString::number(pPolar->Mach(), 'f', 2));
        writeTextElement("ReType",             QString::number(pPolar->ReType()));
        writeTextElement("MaType",             QString::number(pPolar->MaType()));
        writeTextElement("NCrit",              QString::number(pPolar->NCrit(), 'f', 1));
        writeTextElement("Forced_Top_Transition",    QString::number(pPolar->XTripTop(), 'f', 2));
        writeTextElement("Forced_Bottom_Transition", QString::number(pPolar->XTripBot(), 'f', 2));
    }

    writeEndElement();
    writeEndDocument();
}

void XmlPolarWriter::writeHeader()
{
    setAutoFormatting(true);
    writeStartDocument();
    writeDTD("<!DOCTYPE flow5>");
    writeStartElement("Foil_Polar");
    writeAttribute("version", "1.0");
}

#include <bpf/bpf.h>

// Tracepoint structure for scheduler switch event
struct sched_switch_event {
    u64 reserved;
    char prev_task_name[16];
    u32 prev_process_id;
    u32 prev_priority;
    u64 prev_state_info;
    char next_task_name[16];
    u32 next_process_id;
    u32 next_priority;
};

// Data container for storing large entries
struct data_container {
    u8 storage[1024];
};

BTF_EXPORT(struct data_container);

// Define a BPF array map with 400K entries of data_container
BPF_MAP_STRUCT(large_array_map, BPF_MAP_TYPE_ARRAY, u32, struct data_container, 400 * 1024, 0);

// Nested map: array of maps where each entry is a large_array_map
struct {
    BPF_MAP_DEF_UINT(type, BPF_MAP_TYPE_ARRAY_OF_MAPS);
    BPF_MAP_DEF_UINT(key_size, sizeof(u32));
    BPF_MAP_DEF_UINT(max_entries, 1024);
    BPF_MAP_DEF_ARRAY(entries, struct large_array_map);
} multi_gigabyte_storage SEC(BPF_SEC_BTF_MAPS);

// Tracepoint handler for scheduler context switches
SEC("tracepoint/sched/sched_switch")
int handle_sched_switch(struct sched_switch_event* event) {
    BPF_PRINTK("Scheduler switch: %d -> %d\n", event->prev_process_id, event->next_process_id);
    return 0;
}

