class EnumIntActionTest : public PlainTestSuite {
  Q_OBJECT

 public:
  template <typename T>
  void verifyEnumIntAction(T enumA, T enumB, T invalidEnum, QActionGroup::ExclusionPolicy policy) {
    QAction action1{"ascii b large"};
    action1.setCheckable(true);
    QAction action2{"ascii a less"};
    QVERIFY(action1.text() > action2.text());

    action2.setCheckable(true);
    QVERIFY(enumA < enumB);

    if (policy == QActionGroup::ExclusionPolicy::Exclusive) {
      action2.setChecked(true);
    }

    EnumIntAction<T> tester;
    QCOMPARE(tester, false);

    tester.init({{&action1, enumA}, {&action2, enumB}}, invalidEnum, policy);
    QCOMPARE(tester, true);

    QCOMPARE(tester.defVal(), invalidEnum);

    if (policy == QActionGroup::ExclusionPolicy::Exclusive) {
      QCOMPARE(tester.curVal(), enumB);
    } else {
      QCOMPARE(tester.curVal(), invalidEnum);
    }

    auto* grp = tester.getActionGroup();
    QVERIFY(grp != nullptr);
    QCOMPARE(grp->actions().size(), 2);

    QList<QAction*> expectedAscEnumOrder = {&action1, &action2};
    QList<QAction*> expectedAscNameOrder = {&action2, &action1};

    QCOMPARE(tester.getActionEnumAscendingList(), expectedAscEnumOrder);
    QCOMPARE(tester.getActionNameAscendingList(), expectedAscNameOrder);

    QCOMPARE(tester.act2Enum(&action1), enumA);
    QCOMPARE(tester.act2Enum(static_cast<const QAction*>(&action1)), enumA);
    QCOMPARE(tester.intVal2Enum(static_cast<int>(enumA)), enumA);

    QCOMPARE(tester.act2Enum(&action2), enumB);
    QCOMPARE(tester.act2Enum(static_cast<const QAction*>(&action2)), enumB);
    QCOMPARE(tester.intVal2Enum(static_cast<int>(enumB)), enumB);

    QCOMPARE(tester.setCheckedIfActionExist(static_cast<int>(enumB)), &action2);
    QCOMPARE(tester.setCheckedIfActionExist(enumB), &action2);

    if (policy != QActionGroup::ExclusionPolicy::None) {
      QCOMPARE(tester.curVal(), enumB);
    }
  }

 private slots:
  void enum_in_action_exclusive() {
    verifyEnumIntAction<ViewTypeTool::ViewType>(
        ViewTypeTool::ViewType::TABLE,
        ViewTypeTool::ViewType::SEARCH,
        ViewTypeTool::DEFAULT_VIEW_TYPE,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<Style::StyleE>(
        Style::StyleE::STYLE_WINDOWS_VISTA,
        Style::StyleE::STYLE_FUSION,
        Style::StyleE::STYLE_WINDOWS_VISTA,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<Style::StyleSheetE>(
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        Style::StyleSheetE::STYLESHEET_DARK_THEME_MOON_FOG,
        Style::StyleSheetE::STYLESHEET_DEFAULT_LIGHT,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<SearchTools::SearchModeE>(
        SearchTools::SearchModeE::REGEX,
        SearchTools::SearchModeE::FILE_CONTENTS,
        SearchTools::DEFAULT_SEARCH_MODE,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<BytesRangeTool::BytesRangeE>(
        BytesRangeTool::BytesRangeE::FIRST_16_BYTES,
        BytesRangeTool::BytesRangeE::ENTIRE_FILE,
        BytesRangeTool::DEFAULT_BYTE_RANGE,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<QCryptographicHash::Algorithm>(
        QCryptographicHash::Algorithm::Md5,
        QCryptographicHash::Algorithm::Sha256,
        QCryptographicHash::Algorithm::Md5,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<DuplicateImageDetectionCriteria::DICriteriaE>(
        DuplicateImageDetectionCriteria::DICriteriaE::LIBRARY,
        DuplicateImageDetectionCriteria::DICriteriaE::MD5,
        DuplicateImageDetectionCriteria::DEFAULT_DI_CRITERIA_E,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<FileStructurePolicy::FileStuctureModeE>(
        FileStructurePolicy::FileStuctureModeE::PRESERVE,
        FileStructurePolicy::FileStuctureModeE::FLATTEN,
        FileStructurePolicy::FileStuctureModeE::QUERY,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<SceneSortOrderHelper::SortDimE>(
        SceneSortOrderHelper::SortDimE::MOVIE_PATH,
        SceneSortOrderHelper::SortDimE::MOVIE_SIZE,
        SceneSortOrderHelper::DEFAULT_SCENE_SORT_ORDER,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<Qt::TextElideMode>(
        Qt::TextElideMode::ElideLeft,
        Qt::TextElideMode::ElideRight,
        Qt::TextElideMode::ElideNone,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<QHeaderView::ResizeMode>(
        QHeaderView::ResizeMode::Interactive,
        QHeaderView::ResizeMode::Stretch,
        QHeaderView::ResizeMode::Interactive,
        QActionGroup::ExclusionPolicy::Exclusive);

    verifyEnumIntAction<Qt::ScrollBarPolicy>(
        Qt::ScrollBarPolicy::ScrollBarAsNeeded,
        Qt::ScrollBarPolicy::ScrollBarAlwaysOff,
        Qt::ScrollBarPolicy::ScrollBarAsNeeded,
        QActionGroup::ExclusionPolicy::Exclusive);
  }

  void enum_in_action_exclusive_optional() {
    verifyEnumIntAction<PreviewTypeTool::PREVIEW_TYPE_E>(
        PreviewTypeTool::PREVIEW_TYPE_E::CATEGORY,
        PreviewTypeTool::PREVIEW_TYPE_E::PROGRESSIVE_LOAD,
