// NOTE: It might be possible to track net objects through their raw pointer values instead of NetObjIDs, as the NetObjID is just reassigned when moved, and it isn't reallocated.
bool UndoManager::can_undo() {
    return !undoQueue.empty();
}

bool UndoManager::can_redo() {
    return !redoQueue.empty();
}

void UndoManager::push(const UndoRedoPair& undoRedoPair) {
    store_for_undo(undoRedoPair);
    flush_redo_history();
}

void UndoManager::store_for_undo(const UndoRedoPair& undoRedoPair) {
    if (undoQueue.size() >= queueLimit) {
        undoQueue.pop_front();
    }
    undoQueue.push_back(undoRedoPair);
}

void UndoManager::flush_redo_history() {
    redoQueue.clear();
}

void UndoManager::push_redo(const UndoRedoPair& undoRedoPair) {
    if (redoQueue.size() >= queueLimit) {
        redoQueue.pop_front();
    }
    redoQueue.push_back(undoRedoPair);
}

void UndoManager::undo() {
    if (undoQueue.empty()) {
        return;
    }

    if (!undoQueue.back().perform_undo()) {
        reset_all();
    } else {
        save_for_redo(undoQueue.back());
        undoQueue.pop_back();
    }
}

void UndoManager::redo() {
    if (redoQueue.empty()) {
        return;
    }

    if (!redoQueue.back().perform_redo()) {
        reset_all();
    } else {
        save_for_undo(redoQueue.back());
        redoQueue.pop_back();
    }
}

void UndoManager::reset_all() {
    redoQueue.clear();
    undoQueue.clear();
}

