// Helper function to merge overlapping or adjacent intervals
static std::vector<std::pair<int64_t, int64_t>> MergeRanges(std::vector<std::pair<int64_t, int64_t>> input)
{
    if (input.empty())
        return {};

    // Sort by start value
    std::sort(input.begin(), input.end(),
              [](auto const& a, auto const& b) { return a.first < b.first; });

    std::vector<std::pair<int64_t, int64_t>> result;
    auto current = input[0];

    for (size_t i = 1; i < input.size(); ++i)
    {
        auto next = input[i];
        // If intervals overlap or touch (next.first <= current.second), merge them
        if (next.first <= current.second + 1)
        {
            current.second = std::max(current.second, next.second);
        }
        else
        {
            result.push_back(current);
            current = next;
        }
    }
    result.push_back(current);

    return result;
}

UNIT_TEST(SortAndMergeIntervals_1Interval)
{
    std::vector<std::pair<int64_t, int64_t>> testVec;
    testVec.emplace_back(1LL, 2LL);
    auto merged = MergeRanges(testVec);
    TEST_EQUAL(merged, testVec, ());
}

UNIT_TEST(SortAndMergeIntervals_2NotSortedNotOverlappin)
{
    std::vector<std::pair<int64_t, int64_t>> testVec;
    testVec.emplace_back(3LL, 4LL);
    testVec.emplace_back(1LL, 2LL);

    std::vector<std::pair<int64_t, int64_t>> expected;
    expected.emplace_back(1LL, 2LL);
    expected.emplace_back(3LL, 4LL);

    auto merged = MergeRanges(testVec);
    TEST_EQUAL(merged, expected, ());
}

