// Constructor: initializes audio settings UI scene
UIScene_SettingsAudioMenu::UIScene_SettingsAudioMenu(int playerIndex, void* /*initData*/, UILayer* layerParent)
    : UIScene(playerIndex, layerParent)
{
    initialiseMovie();

    // Prepare localized slider labels with current volume values
    wchar_t buffer[256];

    int musicVol = app.GetGameSettings(playerIndex, eGameSetting_MusicVolume);
    swprintf(buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), musicVol);
    m_sliderMusic.init(buffer, eControl_Music, 0, 100, musicVol);

    int soundVol = app.GetGameSettings(playerIndex, eGameSetting_SoundFXVolume);
    swprintf(buffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), soundVol);
    m_sliderSound.init(buffer, eControl_Sound, 0, 100, soundVol);

    doHorizontalResizeCheck();

    if (app.GetLocalPlayerCount() > 1)
    {
#if TO_BE_IMPLEMENTED
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, playerIndex);
#endif
    }
}

// Destructor
UIScene_SettingsAudioMenu::~UIScene_SettingsAudioMenu() = default;

// Returns appropriate movie path based on player count
std::wstring UIScene_SettingsAudioMenu::getMoviePath() const
{
    return (app.GetLocalPlayerCount() > 1) ? L"SettingsAudioMenuSplit" : L"SettingsAudioMenu";
}

// Update tooltip strings for accessibility
void UIScene_SettingsAudioMenu::updateTooltips()
{
    ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

// Adjust visible UI components depending on game state and player count
void UIScene_SettingsAudioMenu::updateComponents()
{
    bool const inLevel = (Minecraft::GetInstance()->level != nullptr);

    if (!inLevel)
    {
        m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, true);
        m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, true);
    }
    else
    {
        m_parentLayer->showComponent(m_iPad, eUIComponent_Panorama, false);
        bool const showLogo = (app.GetLocalPlayerCount() == 1);
        m_parentLayer->showComponent(m_iPad, eUIComponent_Logo, showLogo);
    }
}

// Input handling logic — routes key presses appropriately
void UIScene_SettingsAudioMenu::handleInput(int playerIdx, int keyCode, bool isRepeat, bool isDown, bool isUp, bool& consumed)
{
    ui.AnimateKeyPress(playerIdx, keyCode, isRepeat, isDown, isUp);
    switch (keyCode)
    {
    case ACTION_MENU_CANCEL:
        if (isDown)
            navigateBack();
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        break;

    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        break;
    }
}

// Callback when a slider value changes — syncs setting and updates label
void UIScene_SettingsAudioMenu::handleSliderMove(F64 sliderId, F64 newValue)
{
    wchar_t labelBuffer[256];
    int const val = static_cast<int>(newValue);

    switch (static_cast<int>(sliderId))
    {
    case eControl_Music:
        m_sliderMusic.handleSliderMove(val);
        app.SetGameSettings(m_iPad, eGameSetting_MusicVolume, val);
        swprintf(labelBuffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_MUSIC), val);
        m_sliderMusic.setLabel(labelBuffer);
        break;

    case eControl_Sound:
        m_sliderSound.handleSliderMove(val);
        app.SetGameSettings(m_iPad, eGameSetting_SoundFXVolume, val);
        swprintf(labelBuffer, 256, L"%ls: %d%%", app.GetString(IDS_SLIDER_SOUND), val);
        m_sliderSound.setLabel(labelBuffer);
        break;
    }
}

