namespace efsw {

// Constructor: initializes watcher with given parameters
WatcherGeneric::WatcherGeneric(WatchID watchId, const std::string& dirPath, FileWatchListener* listener,
                               FileWatcherImpl* impl, bool isRecursive) :
    Watcher(watchId, dirPath, listener, isRecursive),
    WatcherImpl(impl),
    directoryMonitor(nullptr) {

    // Ensure directory path ends with a slash
    std::string normalizedDir = dirPath;
    FileSystem::dirAddSlashAtEnd(normalizedDir);
    Directory = normalizedDir;

    // Create underlying directory watcher
    directoryMonitor = new DirWatcherGeneric(nullptr, this, Directory, isRecursive, false);
    directoryMonitor->enumerateExistingFiles(false);
}

// Destructor: safely release resources
WatcherGeneric::~WatcherGeneric() {
    delete directoryMonitor;
    directoryMonitor = nullptr;
}

// Start watching the directory
void WatcherGeneric::startObserving() {
    directoryMonitor->beginWatching();
}

// Add a subdirectory to be watched
void WatcherGeneric::monitorDirectory(std::string subDir) {
    directoryMonitor->addDirectory(subDir);
}

// Check if a given path is being monitored
bool WatcherGeneric::isPathTracked(std::string filePath) {
    return directoryMonitor->containsPath(filePath);
}

