void LCFlushQueue() {
    union {
        u32 val;
        struct {
            u32 lcAddr : 27;
            u32 dmaLd : 1;
            u32 dmaLenL : 2;
            u32 dmaTrigger : 1;
            u32 dmaFlush : 1;
        } f;
    } dmaL;
    dmaL.val = 0;
    dmaL.f.dmaFlush = 1;
    PPCMtdmaU(0);
    PPCMtdmaL(dmaL.val);
    PPCSync();
}

static void L2Init(void) {
    u32 oldMSR;
    oldMSR = PPCMfmsr();
    __sync();
    PPCMtmsr(MSR_IR | MSR_DR);
    __sync();
    L2Disable();
    L2GlobalInvalidate();
    PPCMtmsr(oldMSR);
}

void L2Enable(void) { 
    PPCMtl2cr((PPCMfl2cr() | L2CR_L2E) & ~L2CR_L2I);
}

void L2Disable(void) {
    __sync();
    PPCMtl2cr(PPCMfl2cr() & ~0x80000000);
    __sync();
}

void L2GlobalInvalidate(void) {
    L2Disable();
    PPCMtl2cr(PPCMfl2cr() | 0x00200000);
    while (PPCMfl2cr() & 0x00000001u);
    PPCMtl2cr(PPCMfl2cr() & ~0x00200000);
    while (PPCMfl2cr() & 0x00000001u) {
        DBPrintf(">>> L2 INVALIDATE : SHOULD NEVER HAPPEN\n");
    }
}

void L2SetDataOnly(BOOL dataOnly) {
    if (dataOnly) {
        PPCMtl2cr(PPCMfl2cr() | 0x400000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFBFFFFF);
}

void L2SetWriteThrough(BOOL writeThrough) {
    if (writeThrough) {
        PPCMtl2cr(PPCMfl2cr() | 0x80000);
        return;
    }
    PPCMtl2cr(PPCMfl2cr() & 0xFFF7FFFF);
}

void DMAErrorHandler(OSError error, OSContext* context, ...) {
    u32 hid2 = PPCMfhid2();
    OSReport("Machine check received\n");
    OSReport("HID2 = 0x%x   SRR1 = 0x%x\n", hid2, context->srr1);
    if (!(hid2 & (HID2_DCHERR | HID2_DNCERR | HID2_DCMERR | HID2_DQOERR)) || !(context->srr1 & SRR1_DMA_BIT)) {
        OSReport("Machine check was not DMA/locked cache related\n");
        OSDumpContext(context);
        PPCHalt();
    }
    OSReport("DMAErrorHandler(): An error occurred while processing DMA.\n");
    OSReport("The following errors have been detected and cleared :\n");
    if (hid2 & HID2_DCHERR) {
        OSReport("\t- Requested a locked cache tag that was already in the cache\n");
    }
    if (hid2 & HID2_DNCERR) {
        OSReport("\t- DMA attempted to access normal cache\n");
    }
    if (hid2 & HID2_DCMERR) {
        OSReport("\t- DMA missed in data cache\n");
    }
    if (hid2 & HID2_DQOERR) {
        OSReport("\t- DMA queue overflowed\n");
    }
    // write hid2 back to clear the error bits
    PPCMthid2(hid2);
}

void __OSCacheInit() {
    if (!(PPCMfhid0() & HID0_ICE)) {
        ICEnable();
        DBPrintf("L1 i-caches initialized\n");
    }
    if (!(PPCMfhid0() & HID0_DCE)) {
        DCEnable();
        DBPrintf("L1 d-caches initialized\n");
    }
    if (!(PPCMfl2cr() & L2CR_L2E)) {
        L2Init();
        L2Enable();
        DBPrintf("L2 cache initialized\n");
    }
    OSSetErrorHandler(OS_ERROR_MACHINE_CHECK, DMAErrorHandler);
    DBPrintf("Locked cache machine check handler installed\n");
}

#include "valdi_core/cpp/Utils/PathUtils.hpp"
#include "gtest/gtest.h"
#include <iostream>

using namespace Valdi;

namespace ValdiTest {

// Helper lambda to reduce repetition in path string comparisons
inline std::string normalize_and_get(const Path& p) {
    return p.normalize().toString();
}

TEST(PathUtils, isAbsolutePathAcceptance) {
    EXPECT_TRUE(Path("/").isAbsolute());
    EXPECT_FALSE(Path("").isAbsolute());
    EXPECT_TRUE(Path("/test/dir").isAbsolute());
    EXPECT_FALSE(Path("test/dir").isAbsolute());
}

TEST(PathUtils, normalizePathAcceptance) {
    // Empty and root cases
    EXPECT_EQ(normalize_and_get(Path("")), "");
    EXPECT_EQ(normalize_and_get(Path("/")), "/");

    // Trailing slash removal
    EXPECT_EQ(normalize_and_get(Path("/test/")), "/test");
    EXPECT_EQ(normalize_and_get(Path("test")), "test");

    // Multiple slashes consolidation
    EXPECT_EQ(normalize_and_get(Path("test///dir")), "test/dir");

    // Single dot handling
    EXPECT_EQ(normalize_and_get(Path("./")), "");
    EXPECT_EQ(normalize_and_get(Path("/./")), "/");
    EXPECT_EQ(normalize_and_get(Path("././test")), "test");
    EXPECT_EQ(normalize_and_get(Path("/test/./././dir/.")), "/test/dir");

    // Double dot handling
    EXPECT_EQ(normalize_and_get(Path("/test/../dir")), "/dir");
    EXPECT_EQ(normalize_and_get(Path("/test/../../dir")), "/dir");
    EXPECT_EQ(normalize_and_get(Path("test/../../dir")), "../dir");
    EXPECT_EQ(normalize_and_get(Path("/test/dir/..")), "/test");
    EXPECT_EQ(normalize_and_get(Path("test/dir/../..")), "");
    EXPECT_EQ(normalize_and_get(Path("/../../test/dir/../..")), "/");
    EXPECT_EQ(normalize_and_get(Path("../test/dir/../..")), "..");
    EXPECT_EQ(normalize_and_get(Path("../test/dir/..")), "../test");
}

TEST(PathUtils, removeComponentAcceptance) {
    EXPECT_EQ(Path("").removeLastComponent().toString(), "");
    EXPECT_EQ(Path("/").removeLastComponent().toString(), "");
    EXPECT_EQ(Path("test").removeLastComponent().toString(), "");
    EXPECT_EQ(Path("/test").removeLastComponent().toString(), "/");
    EXPECT_EQ(Path("test/dir").removeLastComponent().toString(), "test");
    EXPECT_EQ(Path("/test/dir").removeLastComponent().toString(), "/test");
}

TEST(PathUtils, appendPathAcceptance) {
    EXPECT_EQ(Path("").append("").toString(), "");
    EXPECT_EQ(Path("/").append("").toString(), "/");
    EXPECT_EQ(Path("").append("/").toString(), "/");
    EXPECT_EQ(Path("/").append("test").toString(), "/test");
    EXPECT_EQ(Path("./").append("/test").normalize().toString(), "test");
    EXPECT_EQ(Path("test").append("dir").toString(), "test/dir");
    EXPECT_EQ(Path("/test").append("dir").toString(), "/test/dir");
    EXPECT_EQ(Path("/test/dir").append("/path").toString(), "/test/dir/path");
    EXPECT_EQ(Path("test/dir").append("/path").toString(), "test/dir/path");
    EXPECT_EQ(Path("test/dir").append("../path").normalize().toString(), "test/path");
}

TEST(PathUtils, removeFileExtensionAcceptance) {
    EXPECT_EQ(Path("").removeFileExtension().toString(), "");
    EXPECT_EQ(Path("/").removeFileExtension().toString(), "/");
    EXPECT_EQ(Path("/test").removeFileExtension().toString(), "/test");
    EXPECT_EQ(Path("./test").removeFileExtension().toString(), "./test");
    EXPECT_EQ(Path("/test/").removeFileExtension().toString(), "/test");
    EXPECT_EQ(Path("./test/").removeFileExtension().toString(), "./test");
    EXPECT_EQ(Path("/test.foo").removeFileExtension().toString(), "/test");
    EXPECT_EQ(Path("./test.foo").removeFileExtension().toString(), "./test");
}

TEST(PathUtils, appendFileExtensionAcceptance) {
    EXPECT_EQ(Path("").appendFileExtension("bar").toString(), "");
    EXPECT_EQ(Path("/").appendFileExtension("bar").toString(), "/.bar");
    EXPECT_EQ(Path("/test").appendFileExtension("bar").toString(), "/test.bar");
    EXPECT_EQ(Path("./test").appendFileExtension("bar").toString(), "./test.bar");
    EXPECT_EQ(Path("/test/").appendFileExtension("bar").toString(), "/test.bar");
    EXPECT_EQ(Path("./test/").appendFileExtension("bar").toString(), "./test.bar");
    EXPECT_EQ(Path("/test.foo").appendFileExtension("bar").toString(), "/test.foo.bar");
    EXPECT_EQ(Path("./test.foo").appendFileExtension("bar").toString(), "./test.foo.bar");
}

TEST(PathUtils, startsWithAcceptance) {
    EXPECT_TRUE(Path("").startsWith(Path("")));
    EXPECT_TRUE(Path("/").startsWith(Path("")));
    EXPECT_TRUE(Path("/").startsWith(Path("/")));
    EXPECT_FALSE(Path("/").startsWith(Path("/hello")));
    EXPECT_TRUE(Path("/hello").startsWith(Path("/")));
    EXPECT_FALSE(Path("hello").startsWith(Path("/")));
    EXPECT_FALSE(Path("hello/boy").startsWith(Path("/")));
    EXPECT_FALSE(Path("hello/boy").startsWith(Path("h")));
    EXPECT_TRUE(Path("hello/boy").startsWith(Path("hello")));
    EXPECT_TRUE(Path("hello/boy").startsWith(Path("hello/boy")));
    EXPECT_FALSE(Path("hello/boy").startsWith(Path("hello/boy/nein")));
}

TEST(PathUtils, getFileExtensionAcceptable) {
    EXPECT_EQ("", Path("").getFileExtension());
    EXPECT_EQ("", Path("hello").getFileExtension());
    EXPECT_EQ("txt", Path("hello.txt").getFileExtension());
    EXPECT_EQ("png", Path("nice/bro/hello.png").getFileExtension());
    EXPECT_EQ("jpg", Path("/nice/bro/hello.jpg").getFileExtension());
}

