  void HybridRunAnywhereCoreSpec::loadHybridMethods() {
    // Delegate base method loading first
    HybridObject::loadHybridMethods();

    // Prepare registration context using a lambda that configures the prototype
    registerHybrids(this, [](Prototype& proto) {
      // Helper alias for brevity and readability
      using RegFn = void (HybridRunAnywhereCoreSpec::*)();
      auto reg = [&proto](const char* name, RegFn method) {
        proto.registerHybridMethod(name, method);
      };

      // Core lifecycle
      reg("initialize", &HybridRunAnywhereCoreSpec::initialize);
      reg("destroy", &HybridRunAnywhereCoreSpec::destroy);
      reg("isInitialized", &HybridRunAnywhereCoreSpec::isInitialized);

      // Authentication & identity
      reg("getBackendInfo", &HybridRunAnywhereCoreSpec::getBackendInfo);
      reg("authenticate", &HybridRunAnywhereCoreSpec::authenticate);
      reg("isAuthenticated", &HybridRunAnywhereCoreSpec::isAuthenticated);
      reg("getUserId", &HybridRunAnywhereCoreSpec::getUserId);
      reg("getOrganizationId", &HybridRunAnywhereCoreSpec::getOrganizationId);
      reg("setAuthTokens", &HybridRunAnywhereCoreSpec::setAuthTokens);

      // Device management
      reg("registerDevice", &HybridRunAnywhereCoreSpec::registerDevice);
      reg("isDeviceRegistered", &HybridRunAnywhereCoreSpec::isDeviceRegistered);
      reg("clearDeviceRegistration", &HybridRunAnywhereCoreSpec::clearDeviceRegistration);
      reg("getDeviceId", &HybridRunAnywhereCoreSpec::getDeviceId);

      // Model handling
      reg("getAvailableModels", &HybridRunAnywhereCoreSpec::getAvailableModels);
      reg("getModelInfo", &HybridRunAnywhereCoreSpec::getModelInfo);
      reg("isModelDownloaded", &HybridRunAnywhereCoreSpec::isModelDownloaded);
      reg("getModelPath", &HybridRunAnywhereCoreSpec::getModelPath);
      reg("registerModel", &HybridRunAnywhereCoreSpec::registerModel);
      reg("checkCompatibility", &HybridRunAnywhereCoreSpec::checkCompatibility);
      reg("downloadModel", &HybridRunAnywhereCoreSpec::downloadModel);
      reg("cancelDownload", &HybridRunAnywhereCoreSpec::cancelDownload);
      reg("getDownloadProgress", &HybridRunAnywhereCoreSpec::getDownloadProgress);
      reg("getStorageInfo", &HybridRunAnywhereCoreSpec::getStorageInfo);
      reg("clearCache", &HybridRunAnywhereCoreSpec::clearCache);
      reg("deleteModel", &HybridRunAnywhereCoreSpec::deleteModel);

      // Event system
      reg("emitEvent", &HybridRunAnywhereCoreSpec::emitEvent);
