#include <vector>
using namespace std;

class Solution {
public:
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> result;
        if (numRows == 0) return result;

        result.push_back({1});
        for (int row = 1; row < numRows; ++row) {
            vector<int> currentRow;
            currentRow.push_back(1); // First element is always 1

            // Generate middle elements by summing adjacent elements from previous row
            for (int col = 1; col < result.back().size(); ++col) {
                currentRow.push_back(result.back()[col - 1] + result.back()[col]);
            }

            currentRow.push_back(1); // Last element is always 1
            result.push_back(currentRow);
        }
        return result;
    }
};

