// Top-level PDB object mapping
void MappingTraits<PdbObject>::mapping(IO &io, PdbObject &obj) {
  io.mapOptional("MSF", obj.Headers);
  io.mapOptional("StreamSizes", obj.StreamSizes);
  io.mapOptional("StreamMap", obj.StreamMap);
  io.mapOptional("StringTable", obj.StringTable);
  io.mapOptional("PdbStream", obj.PdbStream);
  io.mapOptional("DbiStream", obj.DbiStream);
  io.mapOptional("TpiStream", obj.TpiStream);
  io.mapOptional("IpiStream", obj.IpiStream);
  io.mapOptional("PublicsStream", obj.PublicsStream);
}

// MSF header mapping
void MappingTraits<MSFHeaders>::mapping(IO &io, MSFHeaders &headers) {
  io.mapOptional("SuperBlock", headers.SuperBlock);
  io.mapOptional("NumDirectoryBlocks", headers.NumDirectoryBlocks);
  io.mapOptional("DirectoryBlocks", headers.DirectoryBlocks);
  io.mapOptional("NumStreams", headers.NumStreams);
  io.mapOptional("FileSize", headers.FileSize);
}

// Super block mapping with magic initialization
void MappingTraits<msf::SuperBlock>::mapping(IO &io, msf::SuperBlock &sb) {
  if (io.outputting()) {
    // No need to set magic on output; it's already present in memory
  } else {
    ::memcpy(sb.MagicBytes, msf::Magic, sizeof(msf::Magic));
  }

  using u32 = support::ulittle32_t;
  io.mapOptional("BlockSize", sb.BlockSize, u32(4096U));
  io.mapOptional("FreeBlockMap", sb.FreeBlockMapBlock, u32(0U));
  io.mapOptional("NumBlocks", sb.NumBlocks, u32(0U));
  io.mapOptional("NumDirectoryBytes", sb.NumDirectoryBytes, u32(0U));
  io.mapOptional("Unknown1", sb.Unknown1, u32(0U));
  io.mapOptional("BlockMapAddr", sb.BlockMapAddr, u32(0U));
}

// Stream block list mapping
void MappingTraits<StreamBlockList>::mapping(IO &io, StreamBlockList &list) {
  io.mapRequired("Stream", list.Blocks);
}

// PDB info stream mapping
void MappingTraits<PdbInfoStream>::mapping(IO &io, PdbInfoStream &info) {
  io.mapOptional("Age", info.Age, 1U);
  io.mapOptional("Guid", info.Guid);
  io.mapOptional("Signature", info.Signature, 0U);
  io.mapOptional("Features", info.Features);
  io.mapOptional("Version", info.Version, PdbImplVC70);
}

// Dbi stream mapping
void MappingTraits<PdbDbiStream>::mapping(IO &io, PdbDbiStream &dbi) {
  io.mapOptional("VerHeader", dbi.VerHeader, PdbDbiV70);
  io.mapOptional("Age", dbi.Age, 1U);
  io.mapOptional("BuildNumber", dbi.BuildNumber, uint16_t(0U));
  io.mapOptional("PdbDllVersion", dbi.PdbDllVersion, 0U);
  io.mapOptional("PdbDllRbld", dbi.PdbDllRbld, uint16_t(0U));
  io.mapOptional("Flags", dbi.Flags, uint16_t(1U));
  io.mapOptional("MachineType", dbi.MachineType, PDB_Machine::x86);
  io.mapOptional("Modules", dbi.ModInfos);
}

// Tpi stream mapping
void MappingTraits<PdbTpiStream>::mapping(IO &io, pdb::yaml::PdbTpiStream &tpi) {
  io.mapOptional("Version", tpi.Version, PdbTpiV80);
  io.mapRequired("Records", tpi.Records);
}

// Publics stream mapping
void MappingTraits<PdbPublicsStream>::mapping(
    IO &io, pdb::yaml::PdbPublicsStream &pubs) {
  io.mapRequired("Records", pubs.PubSyms);
}

// Named stream mapping
void MappingTraits<NamedStreamMapping>::mapping(IO &io, NamedStreamMapping &ns) {
  io.mapRequired("Name", ns.StreamName);
  io.mapRequired("StreamNum", ns.StreamNumber);
}

// Modi stream mapping
void MappingTraits<PdbModiStream>::mapping(IO &io, PdbModiStream &modi) {
  io.mapOptional("Signature", modi.Signature, 4U);
  io.mapRequired("Records", modi.Symbols);
}

// Dbi module info mapping
void MappingTraits<PdbDbiModuleInfo>::mapping(IO &io, PdbDbiModuleInfo &modInfo) {
  io.mapRequired("Module", modInfo.Mod);
  io.mapOptional("ObjFile", modInfo.Obj, modInfo.Mod);
  io.mapOptional("SourceFiles", modInfo.SourceFiles);
  io.mapOptional("Subsections", modInfo.Subsections);
  io.mapOptional("Modi", modInfo.Modi);
}

