LevelGenerators::LevelGenerators() {
}

void LevelGenerators::addLevelGenerator(const std::wstring& name, LevelGenerationOptions* generator) {
    if (!name.empty()) {
        generator->setDisplayName(name);
    }
    m_levelGenerators.push_back(generator);
}

void LevelGenerators::removeLevelGenerator(LevelGenerationOptions* generator) {
    auto it = std::find(m_levelGenerators.begin(), m_levelGenerators.end(), generator);
    while (it != m_levelGenerators.end()) {
        m_levelGenerators.erase(it);
        it = std::find(m_levelGenerators.begin(), m_levelGenerators.end(), generator);
    }
}

