void initialize_os_key_map(bimap<key_code, int>& key_map)
{
    key_map.clear();
    int32_t code = static_cast<int32_t>(os::key::code::unknown);
    while (code < static_cast<int32_t>(os::key::code::count))
    {
        key_map.map(static_cast<key_code>(code), code);
        ++code;
    }
}
