#include <iostream>

// Check if a number is prime
int main() {
    int number;
    std::cout << "enter your no u betichod" << std::endl;
    std::cin >> number;

    bool isPrime = true;

    if (number <= 1) {
        std::cout << "it is not prime" << std::endl;
    } else {
        for (int divisor = 2; divisor * divisor <= number; ++divisor) {
            if (number % divisor == 0) {
                isPrime = false;
                break;
            }
        }

        if (isPrime) {
            std::cout << "it is prime" << std::endl;
        } else {
            std::cout << "it is not prime" << std::endl;
        }
    }

    return 0;
}

#include <iostream>
using namespace std;

class Distance {
private:
    int feet, inches;
public:
    void input();
    void display();
    Distance combine(Distance d);
};

void Distance::input() {
    cout << "Enter feet and inches: ";
    cin >> feet >> inches;
}

void Distance::display() {
    cout << feet << " feet " << inches << " inches" << endl;
}

Distance Distance::combine(Distance d) {
    Distance temp;
    temp.feet = feet + d.feet;
    temp.inches = inches + d.inches;

    if (temp.inches >= 12) {
        temp.feet += temp.inches / 12;
        temp.inches = temp.inches % 12;
    }

    return temp;
}

int main() {
    Distance d1, d2, result;

    d1.input();
    d2.input();

    d1.display();
    d2.display();

    result = d1.combine(d2);
    result.display();

    return 0;
}

