    // Helper lambda to reduce repetition in attribute registration
    auto make_attr = [](std::string_view n, std::string_view p) {
        return entt::attributes{entt::attribute{"name", n}, entt::attribute{"pretty_name", p}};
    };

    auto make_numeric_attr = [](std::string_view n, std::string_view p, float min_val, float step_val, std::optional<float> max_val = std::nullopt, std::string_view tooltip = "") {
        entt::attributes attrs{
            entt::attribute{"name", n},
            entt::attribute{"pretty_name", p},
            entt::attribute{"min", min_val},
            entt::attribute{"step", step_val}
        };
        if (max_val.has_value()) attrs.emplace_back(entt::attribute{"max", max_val.value()});
        if (!tooltip.empty()) attrs.emplace_back(entt::attribute{"tooltip", tooltip});
        return attrs;
    };

    REFLECT_INLINE(bloom_pass::settings)
    {
        using Settings = bloom_pass::settings;

        entt::meta_factory<Settings>{}
            .type("bloom_settings"_hs)
            .custom(make_attr("bloom_settings", "Bloom Settings"))

            .data<&Settings::threshold>("threshold"_hs)
            .custom(make_numeric_attr("threshold", "Threshold", 0.0f, 0.1f))

            .data<&Settings::soft_knee>("soft_knee"_hs)
            .custom(make_numeric_attr("soft_knee", "Soft Knee", 0.0f, 0.05f, 1.0f,
                "Smooth transition around threshold. 0 = hard cutoff, 1 = soft. Reduces specular flicker."))

            .data<&Settings::clamp>("clamp"_hs)
            .custom(make_numeric_attr("clamp", "Clamp", 0.0f, 1.0f, std::nullopt,
                "Max value before threshold. Limits firefly exaggeration. 0 = no clamp."))

            .data<&Settings::intensity>("intensity"_hs)
            .custom(make_numeric_attr("intensity", "Intensity", 0.0f, 0.1f))

            .data<&Settings::mip_count>("mip_count"_hs)
            .custom(entt::attributes{
                entt::attribute{"name", "mip_count"},
                entt::attribute{"pretty_name", "Mip Count"},
                entt::attribute{"min", 2},
                entt::attribute{"max", 10}
            });
    }

    // Serialization helpers
    template<typename Archive>
    void serialize_settings(Archive& ar, bloom_pass::settings& obj)
    {
        try_save(ar, ser20::make_nvp("threshold", obj.threshold));
        try_save(ar, ser20::make_nvp("soft_knee", obj.soft_knee));
        try_save(ar, ser20::make_nvp("clamp", obj.clamp));
        try_save(ar, ser20::make_nvp("intensity", obj.intensity));
        try_save(ar, ser20::make_nvp("mip_count", obj.mip_count));
    }

    template<typename Archive>
    void deserialize_settings(Archive& ar, bloom_pass::settings& obj)
    {
        try_load(ar, ser20::make_nvp("threshold", obj.threshold));
        try_load(ar, ser20::make_nvp("soft_knee", obj.soft_knee));
        try_load(ar, ser20::make_nvp("clamp", obj.clamp));
        try_load(ar, ser20::make_nvp("intensity", obj.intensity));
        try_load(ar, ser20::make_nvp("mip_count", obj.mip_count));
    }

    SAVE_INLINE(bloom_pass::settings)
    {
        serialize_settings(ar, obj);
    }
    SAVE_INSTANTIATE(bloom_pass::settings, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(bloom_pass::settings, ser20::oarchive_binary_t);

    LOAD_INLINE(bloom_pass::settings)
    {
        deserialize_settings(ar, obj);
    }
    LOAD_INSTANTIATE(bloom_pass::settings, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(bloom_pass::settings, ser20::iarchive_binary_t);


    // Bloom component reflection & serialization
    REFLECT(bloom_component)
    {
        using Component = bloom_component;

        entt::meta_factory<Component>{}
            .type("bloom_component"_hs)
            .custom(make_attr("bloom_component", "Bloom"))
            .custom(entt::attributes{
                entt::attribute{"category", "RENDERING"}
            })

            .func<&component_meta<Component>::exists>("component_exists"_hs)
            .func<&component_meta<Component>::add>("component_add"_hs)
            .func<&component_meta<Component>::remove>("component_remove"_hs)
            .func<&component_meta<Component>::save>("component_save"_hs)
            .func<&component_meta<Component>::load>("component_load"_hs)

            .data<&Component::enabled>("enabled"_hs)
            .custom(make_attr("enabled", "Enabled"))
            .custom(entt::attributes{
                entt::attribute{"tooltip", "Enable/disable bloom post-processing"}
            })

            .data<&Component::settings>("settings"_hs)
            .custom(make_attr("settings", "Settings"))
            .custom(entt::attributes{
                entt::attribute{"flattable", true}
            });
    }

    template<typename Archive>
    void serialize_bloom_component(Archive& ar, bloom_component& obj)
    {
        try_save(ar, ser20::make_nvp("enabled", obj.enabled));
        try_save(ar, ser20::make_nvp("settings", obj.settings));
    }

    template<typename Archive>
    void deserialize_bloom_component(Archive& ar, bloom_component& obj)
    {
        try_load(ar, ser20::make_nvp("enabled", obj.enabled));
        try_load(ar, ser20::make_nvp("settings", obj.settings));
    }

    SAVE(bloom_component)
    {
        serialize_bloom_component(ar, obj);
    }
    SAVE_INSTANTIATE(bloom_component, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(bloom_component, ser20::oarchive_binary_t);

    LOAD(bloom_component)
    {
        deserialize_bloom_component(ar, obj);
    }
    LOAD_INSTANTIATE(bloom_component, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(bloom_component, ser20::iarchive_binary_t);
} // namespace unravel

