RayTracerWindow::RayTracerWindow(GLuint width, GLuint height)
	: m_pCameraRaysImage{ nullptr }
{
}

RayTracerWindow::~RayTracerWindow()
{
}

void RayTracerWindow::init(SurfaceRenderer& renderer)
{
	tc::ivec2 size{ renderer.getWidth(), renderer.getHeight() };
	tc::gpu::GPUBackend gpuBackend;

	m_pCameraRaysImage = new tc::BufferResource<tc::cpu::RGBA8, tc::Dim::D2>{ size };
	gpuBackend.uploadImage<tc::InternalFormat::RGBA32F>(*m_pCameraRaysImage);

	m_RayTracerKernel.outData.bind(m_pCameraRaysImage);
	m_VisualizeRaysKernel.inData.bind(m_pCameraRaysImage);
	m_VisualizeRaysKernel.outData.bind(renderer.getRenderBuffer());
}

void RayTracerWindow::compute(SurfaceRenderer& renderer)
{
	tc::gpu::GPUBackend gpuBackend;

	tc::ivec2 resolution{ renderer.getWidth(), renderer.getHeight() };

	gpuBackend.activateKernel(m_RayTracerKernel);
	gpuBackend.bindStorageImage(m_RayTracerKernel.outData);
	gpuBackend.bindConstant(m_RayTracerKernel.fieldOfView);
	gpuBackend.launch(m_RayTracerKernel, tc::uvec3{ resolution.x, resolution.y, 1 });

	gpuBackend.activateKernel(m_VisualizeRaysKernel);
	gpuBackend.bindStorageImage(m_VisualizeRaysKernel.inData);
	gpuBackend.bindStorageImage(m_VisualizeRaysKernel.outData);
	gpuBackend.launch(m_VisualizeRaysKernel, tc::uvec3{ resolution.x, resolution.y, 1 });
}

