/// Send an IR command to a Sherwood device.
/// Status: STABLE / Known working.
/// @param[in] data The message to be sent.
/// @param[in] nbits The number of bits of message to be sent.
/// @param[in] repeat The number of times the command is to be repeated.
/// @note Sherwood remote codes appear to be NEC codes with a mandatory repeat
///   code. i.e. repeat should be >= kSherwoodMinRepeat (1).
void IRsend::sendSherwood(uint64_t data, uint16_t nbits, uint16_t repeat) {
  // Ensure minimum repeat count is enforced for Sherwood compatibility
  uint16_t effective_repeat = repeat;
  if (repeat < kSherwoodMinRepeat) {
    effective_repeat = kSherwoodMinRepeat;
  }
  sendNEC(data, nbits, effective_repeat);
}
#endif  // SEND_SHERWOOD

