#define DEBUG_TYPE "instcount"

STATISTIC(TotalInstructions, "Total number of instructions encountered");
STATISTIC(TotalBasicBlocks, "Total number of basic blocks processed");
STATISTIC(TotalFunctions, "Total number of non-external functions analyzed");

// Define per-instruction counters using the instruction definition file
#define HANDLE_INST(N, OPCODE, CLASS)                                          \
  STATISTIC(Count##OPCODE, "Count of " #OPCODE " instructions");
#include "llvm/IR/Instruction.def"

namespace {
class InstructionCounter : public InstVisitor<InstructionCounter> {
  friend class InstVisitor<InstructionCounter>;

  // Count each function visited (excluding external declarations)
  void visitFunction(Function &F) { 
    ++TotalFunctions; 
  }

  // Count each basic block encountered
  void visitBasicBlock(BasicBlock &BB) { 
    ++TotalBasicBlocks; 
  }

  // Handle specific instruction types
#define HANDLE_INST(N, OPCODE, CLASS)                                          \
  void visit##OPCODE(CLASS &I) {                                               \
    ++Count##OPCODE;                                                           \
    ++TotalInstructions;                                                       \
  }
#include "llvm/IR/Instruction.def"

  // Fallback for unknown or unhandled instructions
  void visitInstruction(Instruction &I) {
    errs() << "WARNING: InstructionCounter does not recognize: " << I << "\n";
    llvm_unreachable("Unrecognized instruction type in InstCount pass");
  }
};
} // namespace

PreservedAnalyses InstCountPass::run(Function &F,
                                     FunctionAnalysisManager &FAM) {
  LLVM_DEBUG(dbgs() << "INSTCOUNT: analyzing function '" << F.getName() 
                    << "'\n");

  InstructionCounter counter;
  counter.visit(F);

  return PreservedAnalyses::all();
}

