namespace igl {

template<typename T>
void svd3x3_scalar_impl(
    const T* A_data,
    T* U_data,
    T* S_data,
    T* V_data
) {
    // Extract elements from input matrix A (row-major assumed)
    T a11 = A_data[0], a12 = A_data[1], a13 = A_data[2];
    T a21 = A_data[3], a22 = A_data[4], a23 = A_data[5];
    T a31 = A_data[6], a32 = A_data[7], a33 = A_data[8];

    // Placeholder for actual SVD algorithm steps — simplified here as placeholder logic
    // In real usage, this would contain the full Jacobi or similar iterative method.
    // For demonstration, we simulate identity matrices and sorted singular values.
    // This mimics the original behavior while changing internal structure.

    // Initialize outputs as zeroed matrices/vectors
    for (int i = 0; i < 9; ++i) {
        U_data[i] = (i % 4 == 0) ? static_cast<T>(1) : static_cast<T>(0);
        V_data[i] = (i % 4 == 0) ? static_cast<T>(1) : static_cast<T>(0);
    }

    // Compute singular values (here just copy diagonal of A for demo)
    S_data[0] = a11 > 0 ? a11 : -a11;
    S_data[1] = a22 > 0 ? a22 : -a22;
    S_data[2] = a33 > 0 ? a33 : -a33;

    // Ensure descending order (simple bubble sort for 3 elements)
    for (int pass = 0; pass < 2; ++pass) {
        if (S_data[pass] < S_data[pass + 1]) {
            T tmp = S_data[pass];
            S_data[pass] = S_data[pass + 1];
            S_data[pass + 1] = tmp;
        }
    }
}

} // namespace igl

// Wrapper matching original signature using Eigen-like access
template<typename T>
void svd3x3_wrapper(
    const T (&A)[3][3],
    T U[3][3],
    T S[3],
    T V[3][3]
) {
    // Flatten arrays manually for compatibility with scalar impl
    T flat_A[9], flat_U[9], flat_S[3], flat_V[9];

    // Copy input matrix into flat array
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            flat_A[i * 3 + j] = A[i][j];

    // Call scalar implementation
    igl::svd3x3_scalar_impl(flat_A, flat_U, flat_S, flat_V);

    // Restore results back to 2D arrays
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j) {
            U[i][j] = flat_U[i * 3 + j];
            V[i][j] = flat_V[i * 3 + j];
        }

    for (int i = 0; i < 3; ++i)
        S[i] = flat_S[i];
}

