VarDecl* VarDecl::create(CypherAST* ast,
                         DeclContext* declContext,
                         std::string_view identifier,
                         EvaluatedType varType) {
    // Instantiate the variable declaration object
    VarDecl* newDecl = new VarDecl(varType, identifier);

