#include <ocs2_sqp/SqpMpc.h>
// #include <ocs2_ddp/GaussNewtonDDP_MPC.h>
#include <ocs2_ros_interfaces/mpc/MPC_ROS_Interface.h>
#include <ocs2_ros_interfaces/synchronized_module/RosReferenceManager.h>
#include <humanoid_wheel_interface/HumanoidWheelInterface.h>

int main(int argc, char** argv) {
  // Initialize ROS with a node name derived from the robot type
  const std::string robotType = "mobile_manipulator";
  ros::init(argc, argv, robotType + "_mpc_node");
  ros::NodeHandle nh;

  // Retrieve configuration parameters from the parameter server
  std::string taskConfigPath, libraryPath, robotDescriptionPath;
  nh.getParam("/taskFile", taskConfigPath);
  nh.getParam("/libFolder", libraryPath);
  nh.getParam("/urdfFile", robotDescriptionPath);

  // Log loaded paths for debugging
  std::cerr << "[INFO] Task config file: " << taskConfigPath << std::endl;
  std::cerr << "[INFO] Library directory: " << libraryPath << std::endl;
  std::cerr << "[INFO] URDF path: " << robotDescriptionPath << std::endl;

  // Construct the system interface using loaded files
  humanoid_wheel_interface::HumanoidWheelInterface systemInterface(
      taskConfigPath, libraryPath, robotDescriptionPath);

  // Set up ROS-based reference manager
  auto refManagerPtr = std::make_shared<ocs2::RosReferenceManager>(
      robotType, systemInterface.getReferenceManagerPtr());
  refManagerPtr->subscribe(nh);

  // Build the SQP-MPC solver instance
  ocs2::SqpMpc mpcSolver(
      systemInterface.mpcSettings(),
      systemInterface.sqpSettings(),
      systemInterface.getOptimalControlProblem(),
      systemInterface.getInitializer());

  // Attach the reference manager to the solver
  mpcSolver.getSolverPtr()->setReferenceManager(refManagerPtr);

  // Launch ROS interfaces for MPC
  ocs2::MPC_ROS_Interface mpcRosNode(mpcSolver, robotType);
  mpcRosNode.launchNodes(nh);

  return 0;
}

#include <GetBulkProfileDataProcessor.h>
#include <BulkProfileDataMessage.pb.h>
#include <ProfileData.pb.h>
#include <PlayerDatabase.h>

GetBulkProfileDataProcessor::GetBulkProfileDataProcessor(SpectreRpcType rpcType) 
    : WebsocketPacketProcessor(rpcType) {
}

void GetBulkProfileDataProcessor::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock) {
    std::unique_ptr<GetBulkProfileDataMessage> request = packet.GetPayloadAsMessage<GetBulkProfileDataMessage>();
    BulkProfileDataResponse response;

    int count = request->playerids_size();
    for (int index = 0; index < count; ++index) {
        const std::string& playerId = request->playerids(index);
        ProfileData* profileData = PlayerDatabase::Get().GetField<ProfileData>(FieldKey::PROFILE_DATA, playerId);

        if (profileData != nullptr) {
            ProfileData* newEntry = response.add_bulkprofiledata();
            newEntry->CopyFrom(*profileData);
        }
    }

    sock.SendPacket(response, packet.GetResponseType(), packet.GetRequestId());
}

