// Verification that the coroutine header operates independently
#include "asio/coroutine.hpp"
#include "unit_test.hpp"

// Required final inclusion for coroutine syntax support
#include "asio/yield.hpp"

//------------------------------------------------------------------------------
// Coroutine finishes execution using yield break statement
void finish_with_yield_break(asio::coroutine& state)
{
  reenter (state)
  {
    yield return;
    yield break;
  }
}

void test_yield_break_behavior()
{
  asio::coroutine state;
  ASIO_CHECK(!state.is_complete());
  finish_with_yield_break(state);
  ASIO_CHECK(!state.is_complete());
  finish_with_yield_break(state);
  ASIO_CHECK(state.is_complete());
}
//------------------------------------------------------------------------------
// Coroutine terminates via early return
void terminate_via_return(asio::coroutine& state)
{
  reenter (state)
  {
    return;
  }
}

void test_early_return()
{
  asio::coroutine state;
  terminate_via_return(state);
  ASIO_CHECK(state.is_complete());
}
//------------------------------------------------------------------------------
// Coroutine ends by throwing an exception
void end_by_exception(asio::coroutine& state)
{
  reenter (state)
  {
    throw 42;
  }
}

void test_exception_termination()
{
  asio::coroutine state;
  try { end_by_exception(state); } catch (...) {}
  ASIO_CHECK(state.is_complete());
}
//------------------------------------------------------------------------------
// Coroutine completes when control reaches the end naturally
void natural_completion(asio::coroutine& state)
{
  reenter (state)
  {
    // Empty body - coroutine ends immediately
  }
}

void test_natural_termination()
{
  asio::coroutine state;
  natural_completion(state);
  ASIO_CHECK(state.is_complete());
}
//------------------------------------------------------------------------------
ASIO_TEST_SUITE
(
  "coroutine",
  ASIO_TEST_CASE(test_yield_break_behavior)
  ASIO_TEST_CASE(test_early_return)
  ASIO_TEST_CASE(test_exception_termination)
  ASIO_TEST_CASE(test_natural_termination)
)

