#include <llvm/Support/SourceMgr.h>
#include <llvm/Support/ToolOutputFile.h>

using namespace llvm;

static cl::opt<std::string> InputFile(cl::Positional, 
                                      cl::desc("<input file>"),
                                      cl::init("-"));
static cl::opt<std::string> OutputFile("o", 
                                       cl::desc("Specify output filename"),
                                       cl::value_desc("filename"), 
                                       cl::Required);

int main(int argc, char **argv) {
  cl::ParseCommandLineOptions(argc, argv);

  LLVMContext llvmContext;
  SMDiagnostic diag;
  auto irModule = parseIRFile(InputFile, diag, llvmContext);

  if (!irModule) {
    diag.print(InputFile.data(), errs());
    return -1;
  }

  dynamic::MemoryInstrument memPass;
  memPass.runOnModule(*irModule);

  std::error_code err;
  ToolOutputFile outStream(OutputFile, err, sys::fs::OF_None);
  if (err) {
    errs() << "Error opening output file: " << err.message() << "\n";
    return -1;
  }

  outStream.keep();
  WriteBitcodeToFile(*irModule, outStream.os());

  return 0;
}

#include <QtCore/QCommandLineParser>
#include <QtGui/QGuiApplication>
#include <QtMcpServer/QMcpServer>
#include "tools.h"

int main(int argc, char *argv[])
{
    QGuiApplication applicationInstance{argc, argv};

    // Configure application metadata
    applicationInstance.setApplicationName("Qt Mcp Example Window Server");
    applicationInstance.setApplicationVersion("1.0");
    applicationInstance.setOrganizationName("Signal Slot Inc.");
    applicationInstance.setOrganizationDomain("signal-slot.co.jp");

    // Command-line parsing setup
    QCommandLineParser cliParser;
    cliParser.setApplicationDescription(applicationInstance.applicationName());
    cliParser.addHelpOption();
    cliParser.addVersionOption();

    // Define backend selection option
    QCommandLineOption backendChoice(
        {"b", "backend"},
        "Backend to use (stdio/sse).",
        "backend",
        "stdio"
    );
    cliParser.addOption(backendChoice);

    // Define network address option
    QCommandLineOption listenAddress(
        {"a", "address"},
        "Address to listen on (host:port).",
        "address",
        "127.0.0.1:8000"
    );
    cliParser.addOption(listenAddress);

    // Process command-line arguments
    cliParser.process(applicationInstance);

    // Extract parsed values
    QString selectedBackend = cliParser.value(backendChoice);
    QString endpointAddress = cliParser.value(listenAddress);

    // Initialize MCP server with chosen backend
    QMcpServer mcpServer{selectedBackend};

    // Register tool set with descriptive metadata
    Tools* toolsInstance = new Tools(&mcpServer);
    mcpServer.registerToolSet(toolsInstance,
        {
            { "screenShot", "Take screen shot of whole screen" },
            { "moveCursor", "Move cursor to specified position" },
            { "moveCursor/x", "X coordinate of cursor" },
            { "moveCursor/y", "Y coordinate of cursor" }
        });

    // Connect server termination signal to app quit slot
    QObject::connect(&mcpServer, &QMcpServer::finished,
                     &applicationInstance, &QCoreApplication::quit);

    // Start server on specified address
    mcpServer.start(endpointAddress);

    // Enter event loop
    return applicationInstance.exec();
}

