#include "TuyaDatapoints.h"

/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandBool(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_identifier,
  bool dp_data, bool is_synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  // Convert boolean value to 1/0 and populate payload
  makeTuyaDPBool(tuya_payload, dp_identifier, dp_data ? 1 : 0);

  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET,
    TUYA_DP_ZCL_PAYLOAD_8, reinterpret_cast<uint8_t*>(&tuya_payload), is_synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandEnum8(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_identifier,
  uint8_t dp_data, bool is_synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPEnum8(tuya_payload, dp_identifier, dp_data);

  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET,
    TUYA_DP_ZCL_PAYLOAD_8, reinterpret_cast<uint8_t*>(&tuya_payload), is_synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandValue32(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_identifier,
  uint32_t dp_data, bool is_synchronous, uint8_t tuya_command) {
  Tuya_dp_zcl_payload_t tuya_payload;

  makeTuyaDPValue32(tuya_payload, dp_identifier, dp_data);

  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, tuya_command, ESP_ZB_ZCL_ATTR_TYPE_SET,
    TUYA_DP_ZCL_PAYLOAD_32, reinterpret_cast<uint8_t*>(&tuya_payload), is_synchronous);
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaCommandByType(
  ZigbeeGateway *gateway, zbg_device_params_t *device, uint8_t dp_identifier,
  uint8_t dp_format, uint32_t dp_data, bool is_synchronous, uint8_t tuya_command) {
  switch (dp_format) {
    case TUYA_DP_TYPE_BOOL:
      return transmitTuyaCommandBool(
        gateway, device, dp_identifier, static_cast<bool>(dp_data), 
        is_synchronous, tuya_command);

    case TUYA_DP_TYPE_VALUE:
      return transmitTuyaCommandValue32(
        gateway, device, dp_identifier, dp_data, 
        is_synchronous, tuya_command);

    case TUYA_DP_TYPE_ENUM:
      return transmitTuyaCommandEnum8(
        gateway, device, dp_identifier, static_cast<uint8_t>(dp_data), 
        is_synchronous, tuya_command);

    default:
      log_e("unsupported Tuya datapoint %02x format %02x", dp_identifier, dp_format);
      break;
  }
  return false;
}
/*---------------------------------------------------------------------------*/
bool transmitTuyaQueryRequest(
  ZigbeeGateway *gateway, zbg_device_params_t *device, bool is_synchronous) {
  return gateway->sendCustomClusterCmd(
    device, TUYA_PRIVATE_CLUSTER_EF00, TUYA_QUERY_CMD,
    ESP_ZB_ZCL_ATTR_TYPE_NULL, TUYA_DP_ZCL_PAYLOAD_0, nullptr, is_synchronous);
}

