class Level;
class Random;

MineShaftStart::MineShaftStart(
    Level*  level,
    Random* random,
    int     chunkX,
    int     chunkZ
) {
    // Create initial mine shaft room at offset position within the chunk
    MineShaftPieces::MineShaftRoom* initialRoom =
        new MineShaftPieces::MineShaftRoom(
            0,
            random,
            (chunkX << 4) + 2,
            (chunkZ << 4) + 2
        );

    // Add the starting room to the list of pieces
    pieces.emplace_back(initialRoom);

    // Generate additional shaft segments by extending from the initial room
    initialRoom->addChildren(initialRoom, &pieces, random);

    // Adjust bounding box based on all generated pieces
    calculateBoundingBox();

    // Ensure the structure is positioned below sea level
    moveBelowSeaLevel(level, random, 10);
}

