using namespace testing;

// Test iteration over values in const associative containers
TEST(IterateValues, ConstMappingIteration) {
    // Test with std::map: ordered key-value pairs
    const std::map<int, int> squares{
        {1, 1},
        {2, 4},
        {3, 9},
    };

    // Extract values and verify they match expected sequence
    std::vector<int> extractedSquares;
    for (const auto& val : IterateValues(squares)) {
        extractedSquares.push_back(val);
    }
    EXPECT_EQ(extractedSquares, (std::vector<int>{1, 4, 9}));

    // Test with std::unordered_map: unordered key-value pairs
    const std::unordered_map<int, int> roots{
        {49, 7},
        {36, 6},
        {25, 5},
    };

    std::vector<int> extractedRoots;
    for (const auto& val : IterateValues(roots)) {
        extractedRoots.push_back(val);
    }
    EXPECT_THAT(extractedRoots, UnorderedElementsAre(5, 6, 7));

    // Test string concatenation using accumulate
    const std::map<int, std::string> translations{
        {1, "one"},
        {2, "two"},
        {3, "three"},
    };

    std::string concatenated;
    for (const auto& val : IterateValues(translations)) {
        concatenated += val;
    }
    EXPECT_EQ(concatenated, "onetwothree");
}

// Test modification of values through non-const mapping iteration
TEST(IterateValues, NonConstMappingIteration) {
    std::map<int, int> squares{
        {1, 1},
        {2, 4},
        {3, 9},
    };

    // Square each value in the map
    for (auto& val : IterateValues(squares)) {
        val = val * val;
    }

    // Verify results after modification
    std::vector<int> modifiedValues;
    for (const auto& val : IterateValues(squares)) {
        modifiedValues.push_back(val);
    }
    EXPECT_EQ(modifiedValues, (std::vector<int>{1, 16, 81}));
}

// Test iteration over multimap with duplicate keys (const)
TEST(IterateValues, ConstMultiMappingIteration) {
    const std::multimap<int, int> primesBelow{
        {2, 2},
        {5, 3},
        {5, 5},
        {11, 7},
        {11, 11},
        {23, 13},
        {23, 17},
        {23, 23},
    };

    // Collect all values from multimap
    std::vector<int> allValues;
    for (const auto& val : IterateValues(primesBelow)) {
        allValues.push_back(val);
    }
    EXPECT_EQ(allValues, (std::vector<int>{2, 3, 5, 7, 11, 13, 17, 23}));

    // Check equal_range behavior for key 11
    auto [begin, end] = primesBelow.equal_range(11);
    EXPECT_EQ(std::distance(begin, end), 2);

    // Extract values from range [begin, end)
    std::vector<int> rangeValues;
    for (auto it = begin; it != end; ++it) {
        rangeValues.push_back(it->second);
    }
    EXPECT_EQ(rangeValues, (std::vector<int>{7, 11}));
}

// Test iteration over unordered_multimap with duplicate keys (const)
TEST(IterateValues, ConstUnorderedMultiMappingIteration) {
    const std::unordered_multimap<int, int> primesBelow{
        {2, 2},
        {5, 3},
        {5, 5},
        {11, 7},
        {11, 11},
        {23, 13},
        {23, 17},
        {23, 23},
    };

    // Collect all values from unordered_multimap
    std::vector<int> allValues;
    for (const auto& val : IterateValues(primesBelow)) {
        allValues.push_back(val);
    }
    EXPECT_THAT(allValues, UnorderedElementsAre(2, 3, 5, 7, 11, 13, 17, 23));

    // Check equal_range behavior for key 11
    auto [begin, end] = primesBelow.equal_range(11);
    EXPECT_EQ(std::distance(begin, end), 2);

    // Extract values from range [begin, end)
    std::vector<int> rangeValues;
    for (auto it = begin; it != end; ++it) {
        rangeValues.push_back(it->second);
    }
    EXPECT_THAT(rangeValues, UnorderedElementsAre(7, 11));
}

