// Function to handle triangular solve operations based on TRANS parameter
int CNAME(blas_arg_t *params, BLASLONG *range_m, BLASLONG *range_n, FLOAT *scratch_a, FLOAT *scratch_b, BLASLONG thread_id) {
#if TRANS == 1
    // Forward LASWP with positive increment for TRANS=1 case
    LASWP_PLUS(params->n, 1, params->m, ZERO, ZERO, params->b, params->ldb, NULL, 0, params->c, 1);
    // Solve lower triangular system - no unit diagonal
    TRSM_LNLU(params, range_m, range_n, scratch_a, scratch_b, 0);
    // Solve lower triangular system - unit diagonal
    TRSM_LNUN(params, range_m, range_n, scratch_a, scratch_b, 0); 
#elif TRANS == 2
    // Solve upper triangular system - unit diagonal first
    TRSM_LTUN(params, range_m, range_n, scratch_a, scratch_b, 0);
    // Solve upper triangular system - no unit diagonal
    TRSM_LTLU(params, range_m, range_n, scratch_a, scratch_b, 0);

    // Backward LASWP with negative increment for TRANS=2 case
    LASWP_MINUS(params->n, 1, params->m, ZERO, ZERO, params->b, params->ldb, NULL, 0, params->c, -1);
#elif TRANS == 3
    // Forward LASWP with positive increment for TRANS=3 case
    LASWP_PLUS(params->n, 1, params->m, ZERO, ZERO, params->b, params->ldb, NULL, 0, params->c, 1);
    // Solve upper triangular system - no unit diagonal
    TRSM_LRLU(params, range_m, range_n, scratch_a, scratch_b, 0);
    // Solve upper triangular system - unit diagonal
    TRSM_LRUN(params, range_m, range_n, scratch_a, scratch_b, 0);
#else
    // Default case: conjugate transpose operations
    // Solve lower triangular system - conjugate, no unit diagonal
    TRSM_LCUN(params, range_m, range_n, scratch_a, scratch_b, 0);
    // Solve lower triangular system - conjugate, unit diagonal
    TRSM_LCLU(params, range_m, range_n, scratch_a, scratch_b, 0);
    // Backward LASWP with negative increment
    LASWP_MINUS(params->n, 1, params->m, ZERO, ZERO, params->b, params->ldb, NULL, 0, params->c, -1);
#endif
   return 0;
}

