#include <string>
#include <unordered_map>

class Solution {
public:
    bool isIsomorphic(std::string s, std::string t) {
        // Check if lengths differ (though problem likely assumes equal length)
        if (s.length() != t.length()) return false;

        std::unordered_map<char, char> forwardMap;  // maps characters from s to t
        std::unordered_map<char, char> backwardMap; // maps characters from t to s

        for (size_t i = 0; i < s.length(); ++i) {
            char charS = s[i];
            char charT = t[i];

            // If mapping already exists, verify consistency
            if (forwardMap.find(charS) != forwardMap.end() && 
                forwardMap[charS] != charT) {
                return false;
            }
            if (backwardMap.find(charT) != backwardMap.end() && 
                backwardMap[charT] != charS) {
                return false;
            }

            // Create new mappings
            forwardMap[charS] = charT;
            backwardMap[charT] = charS;
        }

        return true;
    }
};

