#include <algorithm>

RateContinuousGamma::RateContinuousGamma() : RateHeterogeneity(), gamma_shape(1.0) {}

RateContinuousGamma::RateContinuousGamma(double shape) : RateHeterogeneity(), gamma_shape(shape) {}

void RateContinuousGamma::startCheckpoint() {
    checkpoint->startStruct("RateContinuousGamma");
}

void RateContinuousGamma::saveCheckpoint() {
    startCheckpoint();
    CKP_SAVE(gamma_shape);
    checkpoint->endStruct();
}

void RateContinuousGamma::restoreCheckpoint() {
    startCheckpoint();
    CKP_RESTORE(gamma_shape);
    checkpoint->endStruct();
}

void RateContinuousGamma::setGammaShape(double gs) {
    gamma_shape = gs;
}

void RateContinuousGamma::getSiteSpecificRates(std::vector<double>& site_rates, int seq_len, std::default_random_engine& rng) {
    // Use a lambda to generate gamma-distributed values
    std::gamma_distribution<double> dist(gamma_shape, 1.0 / gamma_shape);

    auto gen_gamma = [&dist, &rng]() { return dist(rng); };

    std::generate(site_rates.begin(), site_rates.end(), gen_gamma);
}

void RateContinuousGamma::writeInfo(std::ostream& out) {
    out << "Gamma shape parameter (α): " << gamma_shape << '\n';
}

void RateContinuousGamma::writeParameters(std::ostream& out) {
    out << "\t" << gamma_shape;
}

