#include <library/cpp/getopt/last_getopt.h>
#include <library/cpp/getopt/modchooser.h>
#include <library/cpp/getopt/small/last_getopt_opts.h>
#include <library/cpp/getopt/small/last_getopt_parse_result.h>
#include <library/cpp/logger/global/global.h>
#include <perforator/symbolizer/lib/symbolize/symbolizer.h>
#include <util/folder/path.h>
#include <util/stream/file.h>
#include <util/stream/zlib.h>

int main(int argc, const char* argv[]) {
    // Initialize logging to console
    InitGlobalLog2Console();

    // Declare paths and option parser
    TFsPath inputProfile;
    TFsPath resultPath;  // renamed from outputPath for clarity
    NLastGetopt::TOpts cliOpts;

    // Configure command-line interface
    cliOpts
        .AddLongOption('p', "profile-path", "Path to input profiling data")
        .Required()
        .StoreResult(&inputProfile);

    cliOpts
        .AddLongOption('o', "output-profile", "Path where processed profile will be saved")
        .Optional()
        .StoreResult(&resultPath);

    // Parse arguments
    NLastGetopt::TOptsParseResult parseResult(&cliOpts, argc, argv);

    // Default output path if not specified
    if (resultPath.Empty()) {
        resultPath = inputProfile;
    }

    // Open input file stream
    TFileInput inputStream(inputProfile);
    NPerforator::NProto::NPProf::Profile profileData;

    // Determine compression type and deserialize accordingly
    TString filePathStr{inputProfile};
    if (filePathStr.EndsWith(".tar.gz")) {
        TZLibDecompress decompressor(&inputStream);
        profileData.ParseFromArcadiaStream(&decompressor);
    } else {
        profileData.ParseFromArcadiaStream(&inputStream);
    }

    // Perform symbolization
    NPerforator::NSymbolize::TProfileSymbolizer profilerSymbolizer;
    profilerSymbolizer.Symbolize(profileData);

    // Serialize to output with optional compression
    TFileOutput outputStream(resultPath);
    TZLibCompress compressedOutput(&outputStream, ZLib::GZip, 1);
    profileData.SerializeToArcadiaStream(&compressedOutput);

    return 0;
}

