void FDMXProtocolArtNetPacketReply::Serialize(FArchive& Ar)
{
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(ID)), ARTNET_STRING_SIZE);
	Ar << OpCode;
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(Ip)), sizeof(Ip));
	Ar << Port;
	Ar << Version;
	Ar << NetAddress;
	Ar << SubnetAddress;
	Ar << Oem;
	Ar << Ubea;
	Ar << Status1;
	Ar << EstaId;
