	Ar.Serialize(const_cast<void*>(static_cast<const void*>(LongName)), ARTNET_LONG_NAME_LENGTH);
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(NodeReport)), ARTNET_REPORT_LENGTH);
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(NumberPorts)), sizeof(NumberPorts));
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(PortTypes)), ARTNET_MAX_PORTS);
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(GoodInput)), ARTNET_MAX_PORTS);
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(GoodOutput)), ARTNET_MAX_PORTS);
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(SwIn)), ARTNET_MAX_PORTS);
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(SwOut)), ARTNET_MAX_PORTS);
	Ar << SwVideo;
	Ar << SwMacro;
	Ar << SwRemote;
	Ar << Spare1;
	Ar << Spare2;
	Ar << Spare3;
	Ar << Style;
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(Mac)), sizeof(Mac));
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(BindIp)), sizeof(BindIp));
	Ar << BindIndex;
	Ar << Status2;
	Ar.Serialize(const_cast<void*>(static_cast<const void*>(Filler)), sizeof(Filler));
}

