// Helper function to check if a string contains only whitespace and comment characters
bool IsCommentOrWhitespace(const std::string& str) {
    bool hasNonComment = false;
    for (size_t i = 0; i < str.length(); ++i) {
        char c = str[i];
        if (c == '#') break;
        if (!isspace(c)) hasNonComment = true;
    }
    return !hasNonComment;
}

