#include "chan.h"
#include "gmock/gmock.h"
#include "gtest/gtest.h"
#include <thread>

// Test case for channel operations: put, take, and close
TEST(ChanTest, PutTakeClose) {
  dap::Chan<int> channel;

  // Launch a producer thread to send values and close the channel
  auto producer = std::thread([&] {
    channel.put(10);
    channel.put(20);
    channel.put(30);
    channel.close();
  });

  // Consume values from the channel in the main thread
  EXPECT_EQ(channel.take(), dap::optional<int>(10));
  EXPECT_EQ(channel.take(), dap::optional<int>(20));
  EXPECT_EQ(channel.take(), dap::optional<int>(30));
  EXPECT_EQ(channel.take(), dap::optional<int>());

  // Ensure the producer thread completes before test ends
  producer.join();
}

#include <iostream>

int main() {
    int choice;

    std::cout << "Choose an option:\n";
    std::cout << "1. Sum of two numbers\n";
    std::cout << "2. Difference of two numbers\n";
    std::cout << "3. Square of a number\n";
    std::cout << "4. Cube of a number\n";
    std::cout << "5. Division of a number by 2\n";
    std::cout << "Enter your choice: ";
    std::cin >> choice;

    switch (choice) {
        case 1: {
            int num1, num2, result;
            std::cout << "Enter two numbers: ";
            std::cin >> num1 >> num2;
            result = num1 + num2;
            std::cout << "Sum = " << result << std::endl;
            break;
        }

        case 2: {
            int num1, num2, result;
            std::cout << "Enter two numbers: ";
            std::cin >> num1 >> num2;
            result = num1 - num2;
            std::cout << "Difference = " << result << std::endl;
            break;
        }

        case 3: {
            int number, result;
            std::cout << "Enter a number: ";
            std::cin >> number;
            result = number * number;
            std::cout << "Square = " << result << std::endl;
            break;
        }

        case 4: {
            int number, result;
            std::cout << "Enter a number: ";
            std::cin >> number;
            result = number * number * number;
            std::cout << "Cube = " << result << std::endl;
            break;
        }

        case 5: {
            int number, result;
            std::cout << "Enter a number: ";
            std::cin >> number;
            result = number / 2;
            std::cout << "Result (number divided by 2) = " << result << std::endl;
            break;
        }

        default:
            std::cout << "Invalid option!" << std::endl;
            break;
    }

    return 0;
}

