// Custom timing utility for logging execution duration
namespace Slic3r {

Timer::Timer(const std::string &label) 
    : m_label(label), 
      m_start_time(std::chrono::steady_clock::now()) {}

Timer::~Timer()
{
    auto now = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(now - m_start_time).count();
    BOOST_LOG_TRIVIAL(debug) << "Timer '" << m_label << "' spent "
                             << elapsed << "ms";
}

} // namespace Slic3r

namespace Slic3r::Timing {

void TimeLimitAlarm::report_time_exceeded() const
{
    BOOST_LOG_TRIVIAL(error) << "Time limit exceeded for " << m_limit_exceeded_message << ": "
                             << m_timer.elapsed_seconds() << "s";
}

