// Verify handling of root path URL with no parameters
TEST(HttpRequestTest, testEmptyUrl) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("/");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("/", req.fullUrl());
  EXPECT_EQ("/", req.requestUrl());
  EXPECT_TRUE(req.values().empty());
}

// Check parsing of simple hierarchical path
TEST(HttpRequestTest, testPathOnlyUrl) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("/a/foo/bar");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("/a/foo/bar", req.fullUrl());
  EXPECT_EQ("/a/foo/bar", req.requestUrl());
  EXPECT_TRUE(req.values().empty());
}

// Ensure multiple consecutive slashes are normalized to single ones
TEST(HttpRequestTest, testDuplicateForwardSlashesInUrl) {
  ConnectionInfo conn;
  HttpRequest req(conn, 1);
  std::string_view path("//a//foo//bar");
  req.parseUrl(path.data(), path.size());

  EXPECT_EQ("/a/foo/bar", req.fullUrl());
  EXPECT_EQ("/a/foo/bar", req.requestUrl());
  EXPECT_TRUE(req.values().empty());
}

